package com.osrsindex;

import java.util.function.BiPredicate;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * What the plugin does with each destination the socket delivers: route it with {@link RouteDispatcher}, tell the player in
 * chat, then {@code ack} it with what became of it. Every destination whose id can be acked is acked, routed or not, so
 * the site stops sending it again and its map can say why nothing happened. Run it on the client thread, where the
 * dispatcher posts its {@code PluginMessage}.
 */
final class DestinationReceiver
{
	private final RouteDispatcher dispatcher;
	private final Supplier<RouteWith> routeWith;
	private final Consumer<String> chat;
	/** Sends one ack: the destination's id, and the result the site's contract names. */
	private final BiPredicate<String, String> ack;

	DestinationReceiver(RouteDispatcher dispatcher, Supplier<RouteWith> routeWith, Consumer<String> chat,
		BiPredicate<String, String> ack)
	{
		this.dispatcher = dispatcher;
		this.routeWith = routeWith;
		this.chat = chat;
		this.ack = ack;
	}

	RouteDispatcher.Result accept(Destination destination)
	{
		RouteDispatcher.Result result = dispatcher.dispatch(destination, routeWith.get());
		if (result.chatMessage != null)
		{
			chat.accept(result.chatMessage);
		}
		if (result.ackId != null)
		{
			ack.test(result.ackId, result.kind.ackResult);
		}
		return result;
	}
}

package com.osrsindex;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.Random;
import java.util.function.Consumer;

/**
 * The WebSocket osrsindex.com pushes map places down. It holds one socket to the relay while the player is linked, logged in <b>and</b> has
 * turned on "Receive destinations", and none otherwise.
 *
 * <p>The contract's rules, as this class keeps them:
 * <ul>
 *   <li>Reconnect after 15 s, doubling to 5 minutes, with ±20 % jitter, honouring {@code Retry-After}.</li>
 *   <li>Listen only once the relay has said {@code hello} with protocol 1. A hello naming another protocol,
 *   or none within 10 s of the upgrade, closes the socket and backs off, as an unknown subprotocol does.</li>
 *   <li>After {@code 401} or close {@code 4401} (revoked), stay closed until the token changes: only a
 *   fresh link re-opens it.</li>
 *   <li>After close {@code 4409} (a newer socket from this token replaced this one), stay closed until
 *   the player logs in again, re-enables the setting or relinks.</li>
 *   <li>Ignore a frame of a type it does not know.</li>
 * </ul>
 *
 * <p>The socket itself is behind {@link Connector}, so the state machine is tested without a network.
 * Every {@link Connection} callback names its connection, and one that is no longer current is ignored,
 * so a late event from a replaced socket cannot touch the live one.
 */
final class DestinationSocket
{
	static final String SUBPROTOCOL = "osrsindex.destinations.v1";
	static final int PROTOCOL = 1;

	static final long FIRST_RETRY_MILLIS = 15_000;
	static final long MAX_RETRY_MILLIS = 300_000;
	static final double JITTER = 0.20;

	/** How long the relay has, after the upgrade, to send its {@code hello}. */
	static final long HELLO_TIMEOUT_MILLIS = 10_000;

	/**
	 * A coordinate a {@code destination} frame did not carry as a whole number. It is below every range, so the
	 * place is never valid, but it is still handed on to be acked {@code invalid}.
	 */
	static final int UNREADABLE = -1;

	/** The contract's close codes. */
	static final int CLOSE_NORMAL = 1000;
	static final int CLOSE_REVOKED = 4401;
	static final int CLOSE_REPLACED = 4409;

	/** What the player sees in the panel. */
	enum Status
	{
		/** Not wanted: the setting is off, the client is not linked, or nobody is logged in. */
		OFF,
		/** Opening the socket, or open and waiting for the relay's {@code hello}. */
		CONNECTING,
		/** The relay said {@code hello}: places it sends are handed on. */
		LISTENING,
		/** Closed unexpectedly; the next attempt is scheduled. */
		RETRYING,
		/** The site revoked this link. Only a new link re-opens the socket. */
		REVOKED,
		/** Another client with this link took over the socket. */
		REPLACED,
	}

	/** Opens a socket. The production one is OkHttp (see {@link OkHttpConnector}). */
	interface Connector
	{
		Connection open(String token, Events events);
	}

	/** One open, or opening, socket. */
	interface Connection
	{
		boolean send(String text);

		void close(int code, String reason);
	}

	/** What a {@link Connection} reports, from any thread. */
	interface Events
	{
		/** The upgrade succeeded; {@code protocol} is the server's {@code Sec-WebSocket-Protocol}. */
		void opened(Connection connection, String protocol);

		void text(Connection connection, String text);

		/** The socket closed with this code (the server's, or 1006 when it simply dropped). */
		void closed(Connection connection, int code);

		/**
		 * The upgrade was refused or the socket failed. {@code httpStatus} is the refusal's status, or 0
		 * for a network failure; {@code retryAfterSeconds} is its {@code Retry-After}, or -1.
		 */
		void failed(Connection connection, int httpStatus, long retryAfterSeconds);
	}

	/** Runs a task later. The production one is RuneLite's shared executor. */
	interface Scheduler
	{
		Cancellable schedule(Runnable task, long delayMillis);
	}

	interface Cancellable
	{
		void cancel();
	}

	private final Connector connector;
	private final Scheduler scheduler;
	private final Random random;
	private final Consumer<Destination> onDestination;
	private final Consumer<Status> onStatus;
	private final Events events = new ConnectionEvents();

	/** What the plugin last asked for. */
	private boolean wanted;
	private String token = "";

	private Connection connection;
	private Cancellable retry;
	/** Closes {@link #connection} if its {@code hello} has not come; null before the upgrade and after the hello. */
	private Cancellable helloDeadline;
	private int failures;
	/** The reconnect waits: the site config may change them ({@link #retryWaits}). */
	private long firstRetryMillis = FIRST_RETRY_MILLIS;
	private long maxRetryMillis = MAX_RETRY_MILLIS;
	private Status status = Status.OFF;
	/** The token the site revoked, or that another client took over; null when neither happened. */
	private String stoppedToken;
	/** Why {@link #stoppedToken} stopped: {@link Status#REVOKED} or {@link Status#REPLACED}. */
	private Status stoppedReason;

	DestinationSocket(Connector connector, Scheduler scheduler, Random random, Consumer<Destination> onDestination,
		Consumer<Status> onStatus)
	{
		this.connector = connector;
		this.scheduler = scheduler;
		this.random = random;
		this.onDestination = onDestination;
		this.onStatus = onStatus;
	}

	/**
	 * Whether a socket may be open at all: the contract opens none unless the player opted in, the client
	 * holds a token, and someone is logged in.
	 */
	static boolean shouldListen(boolean optedIn, String token, boolean loggedIn)
	{
		return optedIn && loggedIn && Tokens.wellFormed(token);
	}

	/**
	 * Apply the plugin's current state. Safe to call on every change: it opens, closes or leaves the
	 * socket as the state asks.
	 *
	 * @param fresh true when the player acted (logged in, turned the setting on, relinked), which lifts a
	 *              "replaced" stop; a revoked token stays stopped until the token itself changes
	 */
	synchronized void update(boolean optedIn, String newToken, boolean loggedIn, boolean fresh)
	{
		String next = newToken == null ? "" : newToken.trim();
		boolean shouldListen = shouldListen(optedIn, next, loggedIn);
		boolean tokenChanged = !next.equals(token);
		token = next;
		wanted = shouldListen;

		if (tokenChanged || (fresh && stoppedReason == Status.REPLACED))
		{
			stoppedToken = null;
			stoppedReason = null;
		}
		if (!wanted)
		{
			disconnect(Status.OFF);
			return;
		}
		if (token.equals(stoppedToken))
		{
			setStatus(stoppedReason);
			return;
		}
		if (tokenChanged)
		{
			// The old socket belongs to the old token.
			disconnect(Status.OFF);
		}
		if (connection == null && retry == null)
		{
			failures = 0;
			connect();
		}
	}

	/** The reconnect waits from the site config. The next retry uses them; one already scheduled keeps its wait. */
	synchronized void retryWaits(long firstMillis, long maxMillis)
	{
		firstRetryMillis = firstMillis;
		maxRetryMillis = Math.max(firstMillis, maxMillis);
	}

	/** Close for good: the plugin is shutting down. */
	synchronized void stop()
	{
		wanted = false;
		disconnect(Status.OFF);
	}

	/**
	 * Acknowledge a destination with what became of it: {@code result} is {@code routed},
	 * {@code no_pathing_plugin}, {@code expired} or {@code invalid}. Any ack stops the site sending that place
	 * again, and only {@code routed} makes its map say the place was received. False when there is no socket
	 * to send it on.
	 */
	synchronized boolean ack(String id, String result)
	{
		if (connection == null || status != Status.LISTENING)
		{
			return false;
		}
		JsonObject frame = new JsonObject();
		frame.addProperty("type", "ack");
		frame.addProperty("id", id);
		frame.addProperty("result", result);
		return connection.send(frame.toString());
	}

	synchronized Status status()
	{
		return status;
	}

	// --- internals ---------------------------------------------------------

	private void connect()
	{
		setStatus(failures == 0 ? Status.CONNECTING : Status.RETRYING);
		connection = connector.open(token, events);
	}

	private void disconnect(Status next)
	{
		if (retry != null)
		{
			retry.cancel();
			retry = null;
		}
		cancelHelloDeadline();
		if (connection != null)
		{
			Connection closing = connection;
			connection = null;
			closing.close(CLOSE_NORMAL, "closing");
		}
		setStatus(next);
	}

	/** The socket is gone; try again later unless it should stay down. */
	private void scheduleRetry(long retryAfterSeconds)
	{
		connection = null;
		cancelHelloDeadline();
		if (!wanted || token.equals(stoppedToken))
		{
			return;
		}
		long delay = retryDelayMillis(failures, retryAfterSeconds, random, firstRetryMillis, maxRetryMillis);
		failures++;
		setStatus(Status.RETRYING);
		retry = scheduler.schedule(this::retryNow, delay);
	}

	private synchronized void retryNow()
	{
		retry = null;
		if (wanted && connection == null && !token.equals(stoppedToken))
		{
			connect();
		}
	}

	private void stopFor(Status reason)
	{
		connection = null;
		cancelHelloDeadline();
		stoppedToken = token;
		stoppedReason = reason;
		if (retry != null)
		{
			retry.cancel();
			retry = null;
		}
		setStatus(reason);
	}

	/**
	 * Give up on a socket whose relay does not speak this contract (wrong subprotocol, wrong hello, or no
	 * hello at all), and back off as after any other failure. The backoff keeps growing, because only a
	 * hello resets it.
	 */
	private void refuse(Connection from, String reason)
	{
		connection = null;
		from.close(CLOSE_NORMAL, reason);
		scheduleRetry(-1);
	}

	/**
	 * A frame from {@code from} before its hello. A protocol 1 hello starts listening; a hello of any other
	 * protocol refuses the socket. Anything else is not acted on: the contract puts the hello first, and a
	 * place the plugin does not ack is delivered again on the next socket.
	 */
	private void beforeHello(Connection from, String text)
	{
		if (isHello(text))
		{
			cancelHelloDeadline();
			failures = 0;
			setStatus(Status.LISTENING);
		}
		else if (isAnyHello(text))
		{
			refuse(from, "unsupported protocol");
		}
	}

	/** The relay upgraded {@code from} but has not said hello in time. */
	private synchronized void helloTimedOut(Connection from)
	{
		// A deadline whose cancel lost the race with the hello, or with a close, finds nothing to do.
		if (from == connection && status != Status.LISTENING)
		{
			helloDeadline = null;
			refuse(from, "no hello");
		}
	}

	private void cancelHelloDeadline()
	{
		if (helloDeadline != null)
		{
			helloDeadline.cancel();
			helloDeadline = null;
		}
	}

	private void setStatus(Status next)
	{
		if (status != next)
		{
			status = next;
			onStatus.accept(next);
		}
	}

	/**
	 * How long to wait before attempt {@code failures + 1}: 15 s doubling to 5 minutes, ±20 %, and never
	 * less than the server's {@code Retry-After}.
	 */
	static long retryDelayMillis(int failures, long retryAfterSeconds, Random random)
	{
		return retryDelayMillis(failures, retryAfterSeconds, random, FIRST_RETRY_MILLIS, MAX_RETRY_MILLIS);
	}

	/** As above, from {@code firstMillis} doubling to {@code maxMillis}: the site config's waits. */
	static long retryDelayMillis(int failures, long retryAfterSeconds, Random random, long firstMillis, long maxMillis)
	{
		long base = firstMillis;
		for (int i = 0; i < failures && base < maxMillis; i++)
		{
			base *= 2;
		}
		base = Math.min(base, maxMillis);
		double factor = 1 - JITTER + random.nextDouble() * 2 * JITTER;
		long delay = Math.round(base * factor);
		return retryAfterSeconds > 0 ? Math.max(delay, retryAfterSeconds * 1_000L) : delay;
	}

	/**
	 * A {@code destination} frame as a {@link Destination}, or null for any other frame, or one with no
	 * string {@code id}. A frame with an id is always handed on, so it can be acked: a field that is missing
	 * or of the wrong shape becomes {@link #UNREADABLE} or null, which {@link RouteDispatcher} finds invalid.
	 */
	static Destination parseDestination(String text)
	{
		JsonObject frame = object(text);
		if (frame == null || !"destination".equals(string(frame, "type")))
		{
			return null;
		}
		String id = string(frame, "id");
		if (id == null)
		{
			return null;
		}
		return new Destination(id, orUnreadable(integer(frame, "x")), orUnreadable(integer(frame, "y")),
			orUnreadable(integer(frame, "plane")), string(frame, "label"), instant(string(frame, "expires_at")));
	}

	private static int orUnreadable(Integer value)
	{
		return value == null ? UNREADABLE : value;
	}

	private static Instant instant(String text)
	{
		try
		{
			return text == null ? null : Instant.parse(text);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	/** True for the {@code hello} frame of protocol 1. */
	static boolean isHello(String text)
	{
		JsonObject frame = object(text);
		Integer protocol = frame == null ? null : integer(frame, "protocol");
		return frame != null && "hello".equals(string(frame, "type")) && protocol != null && protocol == PROTOCOL;
	}

	/** True for a {@code hello} frame of any protocol, or of none, so one this plugin does not speak is caught. */
	static boolean isAnyHello(String text)
	{
		JsonObject frame = object(text);
		return frame != null && "hello".equals(string(frame, "type"));
	}

	private static JsonObject object(String text)
	{
		try
		{
			JsonElement element = new JsonParser().parse(text);
			return element.isJsonObject() ? element.getAsJsonObject() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static String string(JsonObject frame, String name)
	{
		JsonElement value = frame.get(name);
		return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()
			? value.getAsString() : null;
	}

	private static Integer integer(JsonObject frame, String name)
	{
		JsonElement value = frame.get(name);
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		JsonPrimitive number = value.getAsJsonPrimitive();
		double asDouble = number.getAsDouble();
		return asDouble == Math.rint(asDouble) && Math.abs(asDouble) <= Integer.MAX_VALUE ? (int) asDouble : null;
	}

	private final class ConnectionEvents implements Events
	{
		@Override
		public void opened(Connection from, String protocol)
		{
			synchronized (DestinationSocket.this)
			{
				if (from != connection)
				{
					return;
				}
				if (!SUBPROTOCOL.equals(protocol))
				{
					// A relay that does not speak this contract: give up on this socket and back off.
					refuse(from, "unsupported protocol");
					return;
				}
				// Upgraded, but the relay speaks first: the status stays as it is, and the backoff is not
				// reset, until its hello arrives.
				cancelHelloDeadline();
				helloDeadline = scheduler.schedule(() -> helloTimedOut(from), HELLO_TIMEOUT_MILLIS);
			}
		}

		@Override
		public void text(Connection from, String text)
		{
			Destination destination;
			synchronized (DestinationSocket.this)
			{
				if (from != connection)
				{
					return;
				}
				// Only the current socket's hello sets LISTENING, so anything else means it has not come yet.
				if (status != Status.LISTENING)
				{
					beforeHello(from, text);
					return;
				}
				destination = parseDestination(text);
			}
			// Outside the lock: the plugin hands it to the client thread, which may ack it.
			if (destination != null)
			{
				onDestination.accept(destination);
			}
		}

		@Override
		public void closed(Connection from, int code)
		{
			synchronized (DestinationSocket.this)
			{
				if (from != connection)
				{
					return;
				}
				if (code == CLOSE_REVOKED)
				{
					stopFor(Status.REVOKED);
				}
				else if (code == CLOSE_REPLACED)
				{
					stopFor(Status.REPLACED);
				}
				else
				{
					scheduleRetry(-1);
				}
			}
		}

		@Override
		public void failed(Connection from, int httpStatus, long retryAfterSeconds)
		{
			synchronized (DestinationSocket.this)
			{
				if (from != connection)
				{
					return;
				}
				if (httpStatus == 401)
				{
					stopFor(Status.REVOKED);
				}
				else
				{
					scheduleRetry(retryAfterSeconds);
				}
			}
		}
	}
}

package com.osrsindex;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.regex.Pattern;

/**
 * Where the site is. Production unless `-Dosrsindex.origin=http://localhost:5173` points it at a local
 * copy (`gradlew run -Posrsindex.origin=…`). The destinations relay is a service of its own, so it has its
 * own override: `-Dosrsindex.relay=ws://localhost:8787` for a local relay.
 */
final class Endpoints
{
	static final String DEFAULT_ORIGIN = "https://osrsindex.com";
	static final String DEFAULT_RELAY = "wss://relay.osrsindex.com";

	private Endpoints()
	{
	}

	static String origin()
	{
		return override("osrsindex.origin", DEFAULT_ORIGIN, "https://", "http://");
	}

	/**
	 * A development override, or {@code fallback}. The token goes to it, so it must be encrypted ({@code secure}) or
	 * this computer ({@code plain} to localhost); anything else is ignored.
	 */
	static String override(String property, String fallback, String secure, String plain)
	{
		String value = System.getProperty(property, fallback).trim();
		while (value.endsWith("/"))
		{
			value = value.substring(0, value.length() - 1);
		}
		boolean local = LOCAL.matcher(value).matches() && value.startsWith(plain);
		boolean encrypted = value.startsWith(secure) && value.length() > secure.length();
		return encrypted || local ? value : fallback;
	}

	/** {@code http://localhost}, {@code 127.0.0.1} or {@code [::1]}, with a port or none. */
	private static final Pattern LOCAL = Pattern.compile("[a-z]+://(localhost|127\\.0\\.0\\.1|\\[::1])(:\\d{1,5})?");

	static String sync()
	{
		return origin() + "/api/v1/tracker/sync";
	}

	static String linkStart()
	{
		return origin() + "/api/v1/tracker/link/start";
	}

	static String linkPoll()
	{
		return origin() + "/api/v1/tracker/link/poll";
	}

	/** What the site asks of this client: a {@code GET} with the token as a bearer (docs/site-config.md). */
	static String pluginConfig()
	{
		return origin() + "/api/v1/tracker/plugin-config";
	}

	/** Every guide the site offers in game: a public {@code GET} (docs/guides.md). */
	static String guides()
	{
		return origin() + "/api/v1/guides";
	}

	/** One guide, whole: a public {@code GET}. {@code id} is a slug ({@link GuideParser#GUIDE_ID}). */
	static String guide(String id)
	{
		return guides() + "/" + encode(id);
	}

	/** Where Unlink revokes this client's token: a {@code DELETE} with the token as a bearer. */
	static String revokeToken()
	{
		return origin() + "/api/v1/tracker/token";
	}

	/** The WebSocket the site pushes map places down. */
	static String destinations()
	{
		return override("osrsindex.relay", DEFAULT_RELAY, "wss://", "ws://") + "/v1/destinations";
	}

	/** The page a player opens to approve a link code. */
	static String linkPage()
	{
		return origin() + "/link";
	}

	/** The approval page with the code in it (the site's {@code verification_url_complete}). */
	static String linkApproval(String userCode)
	{
		return linkPage() + "?code=" + encode(userCode);
	}

	/** The signed-in player's character page, where everything this plugin sends is shown. */
	static String tracker()
	{
		return origin() + "/tracker";
	}

	/**
	 * One character's page. An account can hold several, and without {@code ?character=} the site shows
	 * the first it lists. The name goes as the site stores it, hard spaces read as spaces, or the site would
	 * not find it. With no name, the plain page.
	 */
	static String tracker(String character)
	{
		String name = character == null ? "" : character.replace('\u00A0', ' ').trim();
		return name.isEmpty() ? tracker() : tracker() + "?character=" + encode(name);
	}

	/** The RuneLite section of the account page: linked clients, Revoke, and deleting what was sent. */
	static String account()
	{
		return origin() + "/account#runelite";
	}

	/** The site's world map, marking one tile. */
	static String map(int x, int y, int plane)
	{
		return origin() + "/map?x=" + x + "&y=" + y + "&plane=" + plane;
	}

	/** The site's world map. */
	static String map()
	{
		return origin() + "/map";
	}

	private static String encode(String value)
	{
		return URLEncoder.encode(value == null ? "" : value, StandardCharsets.UTF_8).replace("+", "%20");
	}
}

package com.osrsindex;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;
import java.util.function.ToIntFunction;

/**
 * One osrsindex.com guide, as {@code GET /api/v1/guides/{id}} serves it (docs/guides.md): its sections, and in each
 * the steps in the site's order. {@link GuideParser} builds it, and everything here has been checked and made safe
 * to show: text is plain, coordinates are in range, and an optional field the site left out is null or empty.
 */
final class Guide
{
	/** The {@code version} of the guide routes this plugin reads. Any other is "update the plugin". */
	static final int VERSION = 1;

	final String id;
	final String title;
	final String summary;
	/** Who the guide adapts, shown under its title, or null. */
	final String attribution;
	/** Changes whenever anything in the guide changes, so a cached copy is kept until it does. */
	final String revision;
	/** The account types the guide is written for, or null for any. */
	final List<String> modes;
	final List<Section> sections;
	/** Every step, in order. */
	final List<Step> steps;

	Guide(String id, String title, String summary, String attribution, String revision, List<String> modes,
		List<Section> sections)
	{
		this.id = id;
		this.title = title;
		this.summary = summary;
		this.attribution = attribution;
		this.revision = revision;
		this.modes = modes == null ? null : Collections.unmodifiableList(modes);
		this.sections = Collections.unmodifiableList(sections);
		List<Step> all = new ArrayList<>();
		for (Section section : sections)
		{
			all.addAll(section.steps);
		}
		this.steps = Collections.unmodifiableList(all);
	}

	/** {@link #withItemFacts} with no item known to be untradeable. */
	Guide withItemIds(ToIntFunction<String> lookup)
	{
		return withItemFacts(lookup, id -> false);
	}

	/**
	 * This guide with what the game knows about its items: the ids the site left out, filled in by name from
	 * {@code lookup} (the game's id, or -1 when it knows none), and which items cannot be traded, from
	 * {@code untradeable}. An id the site gave is kept. Returns this guide when nothing changes.
	 */
	Guide withItemFacts(ToIntFunction<String> nameLookup, IntPredicate untradeableLookup)
	{
		// Each name and id is looked up once: a guide can name the same item hundreds of times, and this runs on the
		// client thread.
		Map<String, Integer> ids = new HashMap<>();
		Map<Integer, Boolean> bound = new HashMap<>();
		ToIntFunction<String> lookup = name -> ids.computeIfAbsent(name, nameLookup::applyAsInt);
		IntPredicate untradeable = id -> bound.computeIfAbsent(id, untradeableLookup::test);
		boolean changed = false;
		List<Section> filled = new ArrayList<>();
		for (Section section : sections)
		{
			List<Step> steps = new ArrayList<>();
			for (Step step : section.steps)
			{
				List<Item> bring = items(step.bring, lookup, untradeable);
				List<Collect> collect = new ArrayList<>();
				for (Collect entry : step.collect)
				{
					Item item = item(entry.item, lookup, untradeable);
					collect.add(item == entry.item ? entry : new Collect(item, entry.forQuests, entry.from));
				}
				Rewards rewards = step.rewards;
				if (rewards != null)
				{
					List<Item> items = items(rewards.items, lookup, untradeable);
					rewards = items == rewards.items ? rewards
						: new Rewards(rewards.xp, rewards.questPoints, rewards.coins, items, rewards.unlocks);
				}
				boolean same = bring == step.bring && rewards == step.rewards;
				for (int i = 0; same && i < collect.size(); i++)
				{
					same = collect.get(i) == step.collect.get(i);
				}
				changed |= !same;
				steps.add(same ? step : new Step(step.id, step.title, step.minutes, step.url, step.text, step.how, step.tip,
					step.ironman, step.tags, step.quests, step.places, step.travel, bring, collect, step.requires,
					step.completes, rewards));
			}
			filled.add(new Section(section.id, section.title, section.summary, steps));
		}
		return changed ? new Guide(id, title, summary, attribution, revision, modes, filled) : this;
	}

	/** The same list when no item in it changes. */
	private static List<Item> items(List<Item> items, ToIntFunction<String> lookup, IntPredicate untradeable)
	{
		List<Item> out = new ArrayList<>();
		boolean changed = false;
		for (Item item : items)
		{
			Item filled = item(item, lookup, untradeable);
			changed |= filled != item;
			out.add(filled);
		}
		return changed ? out : items;
	}

	private static Item item(Item item, ToIntFunction<String> lookup, IntPredicate untradeable)
	{
		int id = item.id >= 0 ? item.id : lookup.applyAsInt(item.name);
		boolean bound = id >= 0 && untradeable.test(id);
		return id == item.id && bound == item.untradeable ? item : new Item(item.name, id, item.qty, bound);
	}

	Step step(String stepId)
	{
		for (Step step : steps)
		{
			if (step.id.equals(stepId))
			{
				return step;
			}
		}
		return null;
	}

	static final class Section
	{
		final String id;
		final String title;
		final String summary;
		final List<Step> steps;

		Section(String id, String title, String summary, List<Step> steps)
		{
			this.id = id;
			this.title = title;
			this.summary = summary;
			this.steps = Collections.unmodifiableList(steps);
		}
	}

	static final class Step
	{
		/** The site's stable tick key: progress is kept by it. */
		final String id;
		final String title;
		/** About how long it takes, or -1. */
		final int minutes;
		/** The step's page on osrsindex.com, or null. */
		final String url;
		final String text;
		final List<String> how;
		final String tip;
		/** What an Ironman does instead, when it differs, or null. */
		final String ironman;
		/** {@code risk}, {@code solo}, {@code optional}, and any the plugin does not know yet. */
		final Set<String> tags;
		/** The game's names of the quests this step is, for Quest Helper. */
		final List<String> quests;
		final List<Place> places;
		final List<Place> travel;
		final List<Item> bring;
		final List<Collect> collect;
		final List<Requirement> requires;
		/** What ticks the step by itself once the character meets all of it. */
		final List<Requirement> completes;
		/** Null when the step names none. */
		final Rewards rewards;

		Step(String id, String title, int minutes, String url, String text, List<String> how, String tip,
			String ironman, Set<String> tags, List<String> quests, List<Place> places, List<Place> travel,
			List<Item> bring, List<Collect> collect, List<Requirement> requires, List<Requirement> completes,
			Rewards rewards)
		{
			this.id = id;
			this.title = title;
			this.minutes = minutes;
			this.url = url;
			this.text = text;
			this.how = Collections.unmodifiableList(how);
			this.tip = tip;
			this.ironman = ironman;
			this.tags = Collections.unmodifiableSet(tags);
			this.quests = Collections.unmodifiableList(quests);
			this.places = Collections.unmodifiableList(places);
			this.travel = Collections.unmodifiableList(travel);
			this.bring = Collections.unmodifiableList(bring);
			this.collect = Collections.unmodifiableList(collect);
			this.requires = Collections.unmodifiableList(requires);
			this.completes = Collections.unmodifiableList(completes);
			this.rewards = rewards;
		}

		/** The first place with a tile, which the map point, the minimap arrow and Walk there use, or null. */
		Place point()
		{
			for (Place place : places)
			{
				if (place.hasPoint())
				{
					return place;
				}
			}
			return null;
		}
	}

	/** A place, or a way to travel ({@code by}). Some have only a label: the site knows no tile for them yet. */
	static final class Place
	{
		final String label;
		/** How to travel there, such as {@code teleport}, for a travel entry; null for a place. */
		final String by;
		final int x;
		final int y;
		final int plane;

		Place(String label, String by, int x, int y, int plane)
		{
			this.label = label;
			this.by = by;
			this.x = x;
			this.y = y;
			this.plane = plane;
		}

		boolean hasPoint()
		{
			return x >= 0 && y >= 0 && plane >= 0;
		}
	}

	static final class Item
	{
		final String name;
		/** The game's item id, or -1 when the site gives none: the item is then shown by name only. */
		final int id;
		final int qty;
		/** The game says it cannot be traded, so owning it shows the player did what gives it. */
		final boolean untradeable;

		Item(String name, int id, int qty)
		{
			this(name, id, qty, false);
		}

		Item(String name, int id, int qty, boolean untradeable)
		{
			this.name = name;
			this.id = id;
			this.qty = qty;
			this.untradeable = untradeable;
		}
	}

	/** An item to gather on the way, for the quests in {@code forQuests}, and where it comes from. */
	static final class Collect
	{
		final Item item;
		final List<String> forQuests;
		final String from;

		Collect(Item item, List<String> forQuests, String from)
		{
			this.item = item;
			this.forQuests = Collections.unmodifiableList(forQuests);
			this.from = from;
		}
	}

	/**
	 * One requirement, or one condition of {@code completes}. Beside levels, quests, quest points and account type, the
	 * site can name the game's own state, so a new kind of step needs no plugin update: a game variable (a varbit or a
	 * varp, which hold quest stages, diaries, unlocks and minigame progress), items held, or something that happens in
	 * the game (standing in an area, talking to someone, killing something).
	 */
	static final class Requirement
	{
		enum Kind
		{
			SKILL,
			QUEST,
			QUEST_POINTS,
			MODE,
			/** A varbit compared with {@link #value} by {@link #op}. */
			VARBIT,
			/** A varp compared with {@link #value} by {@link #op}. */
			VARP,
			/** Every item in {@link #items}, carried ({@link #op} {@code carried}) or owned, banked included. */
			ITEMS,
			/** Standing within {@link #value} tiles of {@link #place}. */
			AREA,
			/** A dialogue with the NPC named {@link #npc}. */
			TALK,
			/** {@link #value} kills of the NPC named {@link #npc}. */
			KILL,
			/** A kind this version does not know: never met, never missing. */
			UNKNOWN;

			/** Shown by something happening in the game, not by a state the plugin can read at any time. */
			boolean event()
			{
				return this == AREA || this == TALK || this == KILL;
			}

			/** A state the plugin can read at any time. */
			boolean state()
			{
				return !event() && this != UNKNOWN;
			}
		}

		final Kind kind;
		/** The site's lower-case skill name, for {@link Kind#SKILL}. */
		final String skill;
		final int level;
		/** A temporary boost counts, within 5 levels, as on the site. */
		final boolean boostable;
		final String quest;
		final int points;
		final List<String> modes;
		/** The varbit or varp id. */
		final int varId;
		/**
		 * How a variable compares with {@link #value}: {@code ==}, {@code !=}, {@code >=}, {@code >}, {@code <=} or
		 * {@code <}; for {@link Kind#ITEMS}, {@code carried} or {@code owned}.
		 */
		final String op;
		/** The variable's value to compare with, the kills to make, or the area's reach in tiles. */
		final int value;
		final List<Item> items;
		/** The area's centre, with a tile. */
		final Place place;
		final String npc;
		/** What the site calls the condition, shown to the player, or null. */
		final String label;

		Requirement(Kind kind, String skill, int level, boolean boostable, String quest, int points, List<String> modes)
		{
			this(kind, skill, level, boostable, quest, points, modes, -1, null, 0, Collections.<Item>emptyList(), null, null,
				null);
		}

		Requirement(Kind kind, String skill, int level, boolean boostable, String quest, int points, List<String> modes,
			int varId, String op, int value, List<Item> items, Place place, String npc, String label)
		{
			this.kind = kind;
			this.skill = skill;
			this.level = level;
			this.boostable = boostable;
			this.quest = quest;
			this.points = points;
			this.modes = Collections.unmodifiableList(modes);
			this.varId = varId;
			this.op = op;
			this.value = value;
			this.items = Collections.unmodifiableList(items);
			this.place = place;
			this.npc = npc;
			this.label = label;
		}

		/** One of the kinds the site describes with game state or events, built by the parser. */
		static Requirement of(Kind kind, int varId, String op, int value, List<Item> items, Place place, String npc,
			String label)
		{
			return new Requirement(kind, null, 0, false, null, 0, Collections.<String>emptyList(), varId, op, value, items,
				place, npc, label);
		}
	}

	static final class Rewards
	{
		final List<Xp> xp;
		final int questPoints;
		final long coins;
		final List<Item> items;
		final List<String> unlocks;

		Rewards(List<Xp> xp, int questPoints, long coins, List<Item> items, List<String> unlocks)
		{
			this.xp = Collections.unmodifiableList(xp);
			this.questPoints = questPoints;
			this.coins = coins;
			this.items = Collections.unmodifiableList(items);
			this.unlocks = Collections.unmodifiableList(unlocks);
		}

		boolean isEmpty()
		{
			return xp.isEmpty() && questPoints == 0 && coins == 0 && items.isEmpty() && unlocks.isEmpty();
		}
	}

	static final class Xp
	{
		final String skill;
		final long amount;

		Xp(String skill, long amount)
		{
			this.skill = skill;
			this.amount = amount;
		}
	}

	/** {@code GET /api/v1/guides}: every guide the site offers in game. */
	static final class Listing
	{
		final List<Summary> guides;

		Listing(List<Summary> guides)
		{
			this.guides = Collections.unmodifiableList(guides);
		}

		Summary find(String guideId)
		{
			for (Summary summary : guides)
			{
				if (summary.id.equals(guideId))
				{
					return summary;
				}
			}
			return null;
		}
	}

	/** One guide in the list. */
	static final class Summary
	{
		final String id;
		final String title;
		final String summary;
		/** {@code free} or {@code members}, or null. */
		final String membership;
		final List<String> modes;
		/** How many steps it has, or -1. */
		final int steps;
		final int minutes;
		final String revision;

		Summary(String id, String title, String summary, String membership, List<String> modes, int steps, int minutes,
			String revision)
		{
			this.id = id;
			this.title = title;
			this.summary = summary;
			this.membership = membership;
			this.modes = modes == null ? null : Collections.unmodifiableList(modes);
			this.steps = steps;
			this.minutes = minutes;
			this.revision = revision;
		}
	}
}

package com.osrsindex;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * What the live client knows about the character, for a guide's requirements, its {@code completes} and its items:
 * a snapshot taken on the client thread, immutable, so the panel can read it on the Swing thread. Anything the
 * client could not read is unknown, never assumed: a requirement on it is shown as unknown, and it ticks nothing.
 */
final class GuideFacts
{
	/** Logged out, or nothing read yet. */
	static final GuideFacts UNKNOWN = new Builder().build();

	private final Map<String, Integer> realLevels;
	private final Map<String, Integer> boostedLevels;
	private final Map<String, QuestState> quests;
	/** Quest points, or -1. */
	final int questPoints;
	/** The account type in the site's words ({@link CharacterReader#ACCOUNT_TYPES}), or null. */
	final String accountType;
	/** Inventory and worn items, by item id. */
	private final Map<Integer, Integer> carried;
	private final Map<Integer, Integer> banked;
	/** The bank was open at least once since login, so {@link #banked} is what it held then. */
	final boolean bankSeen;
	/** The game variables a guide's conditions name, by id, as last read. */
	private final Map<Integer, Integer> varbits;
	private final Map<Integer, Integer> varps;

	private GuideFacts(Builder builder)
	{
		realLevels = Collections.unmodifiableMap(new HashMap<>(builder.realLevels));
		boostedLevels = Collections.unmodifiableMap(new HashMap<>(builder.boostedLevels));
		quests = Collections.unmodifiableMap(new HashMap<>(builder.quests));
		questPoints = builder.questPoints;
		accountType = builder.accountType;
		carried = Collections.unmodifiableMap(new HashMap<>(builder.carried));
		banked = Collections.unmodifiableMap(new HashMap<>(builder.banked));
		bankSeen = builder.bankSeen;
		varbits = Collections.unmodifiableMap(new HashMap<>(builder.varbits));
		varps = Collections.unmodifiableMap(new HashMap<>(builder.varps));
	}

	/**
	 * The client's {@link Skill} for the site's lower-case skill name, or null. The site writes {@code runecraft} as
	 * the game does; {@code runecrafting} is read too.
	 */
	static Skill skill(String name)
	{
		if (name == null)
		{
			return null;
		}
		String upper = name.trim().toUpperCase(Locale.ROOT);
		if ("RUNECRAFTING".equals(upper))
		{
			upper = "RUNECRAFT";
		}
		if ("OVERALL".equals(upper))
		{
			return null;
		}
		try
		{
			return Skill.valueOf(upper);
		}
		catch (IllegalArgumentException unknown)
		{
			return null;
		}
	}

	/** The real (unboosted) level, or null when unknown. */
	Integer realLevel(String skill)
	{
		Skill known = skill(skill);
		return known == null ? null : realLevels.get(known.name());
	}

	Integer boostedLevel(String skill)
	{
		Skill known = skill(skill);
		return known == null ? null : boostedLevels.get(known.name());
	}

	/** The quest's state by the game's name, or null when it was not read or is not a quest. */
	QuestState quest(String name)
	{
		return name == null ? null : quests.get(name);
	}

	int carried(int itemId)
	{
		Integer count = carried.get(itemId);
		return count == null ? 0 : count;
	}

	int banked(int itemId)
	{
		Integer count = banked.get(itemId);
		return count == null ? 0 : count;
	}

	/** A varbit's value, or null when it was not read. */
	Integer varbit(int id)
	{
		return varbits.get(id);
	}

	/** A varp's value, or null when it was not read. */
	Integer varp(int id)
	{
		return varps.get(id);
	}

	/** Any Ironman type, group ones included: the step's Ironman text is for them. */
	boolean ironman()
	{
		return accountType != null && !"normal".equals(accountType);
	}

	Builder toBuilder()
	{
		Builder builder = new Builder();
		builder.realLevels.putAll(realLevels);
		builder.boostedLevels.putAll(boostedLevels);
		builder.quests.putAll(quests);
		builder.questPoints = questPoints;
		builder.accountType = accountType;
		builder.carried.putAll(carried);
		builder.banked.putAll(banked);
		builder.bankSeen = bankSeen;
		builder.varbits.putAll(varbits);
		builder.varps.putAll(varps);
		return builder;
	}

	static final class Builder
	{
		private final Map<String, Integer> realLevels = new HashMap<>();
		private final Map<String, Integer> boostedLevels = new HashMap<>();
		private final Map<String, QuestState> quests = new HashMap<>();
		private int questPoints = -1;
		private String accountType;
		private final Map<Integer, Integer> carried = new HashMap<>();
		private final Map<Integer, Integer> banked = new HashMap<>();
		private boolean bankSeen;
		private final Map<Integer, Integer> varbits = new HashMap<>();
		private final Map<Integer, Integer> varps = new HashMap<>();

		Builder varbit(int id, int value)
		{
			varbits.put(id, value);
			return this;
		}

		Builder varp(int id, int value)
		{
			varps.put(id, value);
			return this;
		}

		Builder level(Skill skill, int real, int boosted)
		{
			realLevels.put(skill.name(), real);
			boostedLevels.put(skill.name(), boosted);
			return this;
		}

		Builder quest(String name, QuestState state)
		{
			quests.put(name, state);
			return this;
		}

		Builder questPoints(int points)
		{
			questPoints = points;
			return this;
		}

		Builder accountType(String type)
		{
			accountType = type;
			return this;
		}

		/** Replace the carried items: inventory and worn, by id. */
		Builder carried(Map<Integer, Integer> items)
		{
			carried.clear();
			carried.putAll(items);
			return this;
		}

		Builder banked(Map<Integer, Integer> items)
		{
			banked.clear();
			banked.putAll(items);
			bankSeen = true;
			return this;
		}

		GuideFacts build()
		{
			return new GuideFacts(this);
		}
	}
}

package com.osrsindex;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

/**
 * Downloads osrsindex.com's guides (docs/guides.md), only when the player asks: the list when they open the Guides
 * view, and a guide when they open it. Guides are public, so a request carries no token, and works unlinked. It
 * goes through the plugin's site client, so it names the plugin's version, and that is all it says.
 *
 * <p>Answers are kept in memory: the list for an hour, and each guide until the list gives it a new
 * {@code revision}. A request after that sends {@code If-None-Match}, so an unchanged answer costs a {@code 304}.
 * Nothing is fetched on a timer, and a failure is asked again only when the player opens the view again or clicks
 * Try again.
 */
final class GuideFetcher
{
	/** One {@code GET}, with {@code If-None-Match} when {@code etag} is not null, answered with the status (-1 for none). */
	interface Transport
	{
		void get(String url, String etag, Handler handler);
	}

	interface Handler
	{
		void handle(int status, String body, String etag);
	}

	enum Status
	{
		OK,
		/** {@code 404}: a site without the guides routes, or a guide it no longer offers. */
		NOT_SERVED,
		/** A {@code version} this plugin does not read. */
		UPDATE_PLUGIN,
		/** Anything else, or no answer. */
		FAILED
	}

	static final class Answer<T>
	{
		final Status status;
		/** The value for {@link Status#OK}, else null. */
		final T value;

		Answer(Status status, T value)
		{
			this.status = status;
			this.value = value;
		}
	}

	/** The list is asked for at most once an hour. */
	static final long LIST_MAX_AGE_MILLIS = 3_600_000;
	/** A site without the routes is asked again after this, when the player opens the view. */
	static final long NOT_SERVED_MAX_AGE_MILLIS = 900_000;
	/** After a failure, Try again asks at once, but never sooner than this after the last ask. */
	static final long RETRY_MILLIS = 10_000;
	/** The largest body read, in bytes. A long guide is a few hundred kilobytes. */
	static final int MAX_BODY_BYTES = 1_500_000;
	/** Guides kept in memory at once. */
	static final int CACHED_GUIDES = 4;

	private final Transport transport;
	private final LongSupplier clock;

	private Answer<Guide.Listing> listing;
	private String listingEtag;
	private long listingAt;
	private long listingMaxAge;
	private boolean listingInFlight;
	private final List<Consumer<Answer<Guide.Listing>>> listingWaiters = new ArrayList<>();

	private final Map<String, Cached> guides = new LinkedHashMap<String, Cached>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Cached> eldest)
		{
			return size() > CACHED_GUIDES;
		}
	};
	private final Map<String, List<Consumer<Answer<Guide>>>> guideWaiters = new HashMap<>();
	private final Map<String, Long> guideFailedAt = new HashMap<>();

	private static final class Cached
	{
		final Guide guide;
		final String etag;

		Cached(Guide guide, String etag)
		{
			this.guide = guide;
			this.etag = etag;
		}
	}

	GuideFetcher(OkHttpClient http)
	{
		this(okHttp(http), System::currentTimeMillis);
	}

	GuideFetcher(Transport transport, LongSupplier clock)
	{
		this.transport = transport;
		this.clock = clock;
	}

	/**
	 * The guide list, for the player opening the Guides view. A list from the last hour is answered at once, on this
	 * thread; otherwise it is asked for, and answered on the thread that gets the response.
	 */
	void listing(Consumer<Answer<Guide.Listing>> done)
	{
		Answer<Guide.Listing> known;
		String etag;
		synchronized (this)
		{
			long now = clock.getAsLong();
			known = listing != null && now - listingAt < listingMaxAge ? listing : null;
			if (known == null)
			{
				listingWaiters.add(done);
				if (listingInFlight)
				{
					return;
				}
				listingInFlight = true;
				listingAt = now;
			}
			etag = listing != null && listing.value != null ? listingEtag : null;
		}
		if (known != null)
		{
			done.accept(known);
			return;
		}
		transport.get(Endpoints.guides(), etag, this::listingAnswered);
	}

	private void listingAnswered(int status, String body, String etag)
	{
		Answer<Guide.Listing> answer;
		List<Consumer<Answer<Guide.Listing>>> waiting;
		synchronized (this)
		{
			listingInFlight = false;
			long maxAge = RETRY_MILLIS;
			if (status == 304 && listing != null && listing.value != null)
			{
				answer = listing;
				maxAge = LIST_MAX_AGE_MILLIS;
			}
			else if (status == 200)
			{
				GuideParser.Result<Guide.Listing> parsed = GuideParser.listing(body);
				answer = answer(parsed);
				if (answer.status == Status.OK)
				{
					listingEtag = etag;
				}
				maxAge = answer.status == Status.FAILED ? RETRY_MILLIS : LIST_MAX_AGE_MILLIS;
			}
			else if (status == 404)
			{
				answer = new Answer<>(Status.NOT_SERVED, null);
				maxAge = NOT_SERVED_MAX_AGE_MILLIS;
			}
			else
			{
				answer = new Answer<>(Status.FAILED, null);
			}
			if (answer.status == Status.OK || listing == null || listing.value == null)
			{
				listing = answer;
				listingMaxAge = maxAge;
			}
			else
			{
				// A failed refresh keeps the list it has, and asks again on the next open after a short wait.
				answer = listing;
				listingMaxAge = RETRY_MILLIS;
			}
			waiting = new ArrayList<>(listingWaiters);
			listingWaiters.clear();
		}
		for (Consumer<Answer<Guide.Listing>> done : waiting)
		{
			done.accept(answer);
		}
	}

	/** Try again after a failure: the next {@link #listing} asks, unless it asked moments ago. */
	synchronized void forgetFailures()
	{
		if (listing != null && listing.status != Status.OK)
		{
			listingMaxAge = Math.min(listingMaxAge, RETRY_MILLIS);
		}
		guideFailedAt.clear();
	}

	/**
	 * One guide, for the player opening it. The copy in memory is answered at once when {@code revision} is null or
	 * its own; otherwise the guide is asked for, with {@code If-None-Match}.
	 */
	void guide(String id, String revision, Consumer<Answer<Guide>> done)
	{
		Cached cached;
		boolean ask;
		synchronized (this)
		{
			cached = guides.get(id);
			if (cached != null && (revision == null || revision.equals(cached.guide.revision)))
			{
				ask = false;
			}
			else
			{
				Long failedAt = guideFailedAt.get(id);
				if (failedAt != null && clock.getAsLong() - failedAt < RETRY_MILLIS)
				{
					cached = null;
					ask = false;
				}
				else
				{
					List<Consumer<Answer<Guide>>> waiting = guideWaiters.get(id);
					if (waiting != null)
					{
						waiting.add(done);
						return;
					}
					waiting = new ArrayList<>();
					waiting.add(done);
					guideWaiters.put(id, waiting);
					ask = true;
				}
			}
		}
		if (!ask)
		{
			done.accept(cached != null ? new Answer<>(Status.OK, cached.guide) : new Answer<>(Status.FAILED, null));
			return;
		}
		String etag = cached == null ? null : cached.etag;
		transport.get(Endpoints.guide(id), etag, (status, body, newEtag) -> guideAnswered(id, status, body, newEtag));
	}

	private void guideAnswered(String id, int status, String body, String etag)
	{
		Answer<Guide> answer;
		List<Consumer<Answer<Guide>>> waiting;
		synchronized (this)
		{
			Cached cached = guides.get(id);
			if (status == 304 && cached != null)
			{
				answer = new Answer<>(Status.OK, cached.guide);
			}
			else if (status == 200)
			{
				answer = answer(GuideParser.guide(body));
				if (answer.status == Status.OK && !id.equals(answer.value.id))
				{
					answer = new Answer<>(Status.FAILED, null);
				}
				if (answer.status == Status.OK)
				{
					guides.put(id, new Cached(answer.value, etag));
				}
			}
			else if (status == 404)
			{
				guides.remove(id);
				answer = new Answer<>(Status.NOT_SERVED, null);
			}
			else
			{
				answer = new Answer<>(Status.FAILED, null);
			}
			if (answer.status == Status.FAILED)
			{
				guideFailedAt.put(id, clock.getAsLong());
			}
			else
			{
				guideFailedAt.remove(id);
			}
			waiting = guideWaiters.remove(id);
		}
		if (waiting != null)
		{
			for (Consumer<Answer<Guide>> done : waiting)
			{
				done.accept(answer);
			}
		}
	}

	private static <T> Answer<T> answer(GuideParser.Result<T> parsed)
	{
		switch (parsed.problem)
		{
			case NONE:
				return new Answer<>(Status.OK, parsed.value);
			case UPDATE_PLUGIN:
				return new Answer<>(Status.UPDATE_PLUGIN, null);
			case UNREADABLE:
			default:
				return new Answer<>(Status.FAILED, null);
		}
	}

	/** The plugin's own {@code GET}: through {@code http}, which names the plugin's version, and with no token. */
	static Transport okHttp(OkHttpClient http)
	{
		return (url, etag, handler) -> http.newCall(request(url, etag)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				handler.handle(-1, "", null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				int status = response.code();
				String body;
				try (ResponseBody responseBody = response.body())
				{
					body = responseBody == null ? "" : bounded(responseBody);
				}
				catch (IOException e)
				{
					body = null;
				}
				if (body == null)
				{
					handler.handle(-1, "", null);
					return;
				}
				handler.handle(status, body, response.header("ETag"));
			}
		});
	}

	static Request request(String url, String etag)
	{
		Request.Builder request = new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.get();
		// Printable ASCII only: OkHttp refuses any other header value by throwing, which would leave the fetch waiting.
		if (etag != null && !etag.isEmpty() && etag.length() <= 200 && etag.chars().allMatch(c -> c >= 0x20 && c <= 0x7e))
		{
			request.header("If-None-Match", etag);
		}
		return request.build();
	}

	/** The body as text, or null when it is larger than {@link #MAX_BODY_BYTES}; never read whole when it is. */
	static String bounded(ResponseBody body) throws IOException
	{
		if (body.contentLength() > MAX_BODY_BYTES)
		{
			return null;
		}
		BufferedSource source = body.source();
		if (source.request(MAX_BODY_BYTES + 1L))
		{
			return null;
		}
		return source.getBuffer().readString(StandardCharsets.UTF_8);
	}
}

package com.osrsindex;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.swing.Icon;
import net.runelite.client.ui.ColorScheme;

/**
 * The small marks the Guides view draws, painted rather than loaded, so they stay sharp at any scale: a status dot,
 * a map pin, a bag for a step's items, and fold and back arrows. The route's nodes are drawn by the view itself.
 */
final class GuideIcons
{
	/** The green of a done step, a met requirement and a carried item, calmer than RuneLite's progress green. */
	static final Color DONE = new Color(46, 160, 67);
	static final Color INK = new Color(20, 20, 20);

	private GuideIcons()
	{
	}

	/** A status dot, set on the first line of the text beside it. */
	static Icon dot(Color colour, int lineHeight)
	{
		return new Painted(8, lineHeight, g ->
		{
			g.setColor(colour);
			int y = Math.max(0, (Math.min(lineHeight, 16) - 7) / 2);
			g.fillOval(0, y, 7, 7);
		});
	}

	/** A map pin, filled when the place has a map point and hollow when it has only a label. */
	static Icon pin(boolean hasPoint, int lineHeight)
	{
		Color colour = hasPoint ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR;
		return new Painted(8, lineHeight, g ->
		{
			int y = Math.max(0, (Math.min(lineHeight, 16) - 11) / 2);
			Path2D pin = new Path2D.Float();
			pin.moveTo(4, y + 11);
			pin.curveTo(0, y + 6, 0, y + 4, 0, y + 4);
			pin.curveTo(0, y + 1.5, 1.8, y, 4, y);
			pin.curveTo(6.2, y, 8, y + 1.5, 8, y + 4);
			pin.curveTo(8, y + 4, 8, y + 6, 4, y + 11);
			pin.closePath();
			g.setColor(colour);
			if (hasPoint)
			{
				g.fill(pin);
				g.setColor(INK);
				g.fillOval(3, y + 3, 2, 2);
			}
			else
			{
				g.setStroke(new BasicStroke(1.2f));
				g.draw(pin);
			}
		});
	}

	/** A fold arrow: pointing right when folded, down when open. */
	static Icon chevron(boolean open, Color colour)
	{
		return new Painted(8, 8, g ->
		{
			g.setColor(colour);
			Path2D arrow = new Path2D.Float();
			if (open)
			{
				arrow.moveTo(0, 2);
				arrow.lineTo(8, 2);
				arrow.lineTo(4, 7);
			}
			else
			{
				arrow.moveTo(2, 0);
				arrow.lineTo(7, 4);
				arrow.lineTo(2, 8);
			}
			arrow.closePath();
			g.fill(arrow);
		});
	}

	/** A sack, for the items a step needs: coloured by whether you carry them. */
	static Icon bag(Color colour)
	{
		return new Painted(12, 12, g ->
		{
			Path2D sack = new Path2D.Float();
			sack.moveTo(4, 3);
			sack.curveTo(0.5, 5, 0.5, 11.5, 6, 11.5);
			sack.curveTo(11.5, 11.5, 11.5, 5, 8, 3);
			sack.closePath();
			g.setColor(colour);
			g.fill(sack);
			g.fillRect(4, 1, 4, 2);
			g.setColor(INK);
			g.drawLine(4, 3, 8, 3);
		});
	}

	/** "Back": an arrow pointing left. */
	static Icon back(Color colour)
	{
		return new Painted(8, 8, g ->
		{
			g.setColor(colour);
			Path2D arrow = new Path2D.Float();
			arrow.moveTo(6, 0);
			arrow.lineTo(1, 4);
			arrow.lineTo(6, 8);
			arrow.closePath();
			g.fill(arrow);
		});
	}

	private interface Paint
	{
		void paint(Graphics2D g);
	}

	private static final class Painted implements Icon
	{
		private final int width;
		private final int height;
		private final Paint paint;

		Painted(int width, int height, Paint paint)
		{
			this.width = width;
			this.height = height;
			this.paint = paint;
		}

		@Override
		public void paintIcon(Component c, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.translate(x, y);
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
				paint.paint(g);
			}
			finally
			{
				g.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return width;
		}

		@Override
		public int getIconHeight()
		{
			return height;
		}
	}
}

package com.osrsindex;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * The minimap arrow toward the current guide step's place: a dot on the place once it is on the minimap, and an
 * arrow at the minimap's edge pointing to it before then. Only on the place's floor, and not in an instance, whose
 * tiles are not the world's.
 */
final class GuideMinimapOverlay extends Overlay
{
	static final Color COLOR = new Color(0xD9, 0xB9, 0x8C);
	/** Within this many tiles the place itself is drawn; the minimap shows about 19 around the player. */
	static final int DOT_RANGE_TILES = 15;
	/** How far from the minimap's centre the arrow sits, in pixels. */
	private static final int ARROW_RADIUS = 58;

	private final Client client;
	private volatile WorldPoint target;

	GuideMinimapOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** The place to point to, or null for none. */
	void target(WorldPoint place)
	{
		target = place;
	}

	WorldPoint target()
	{
		return target;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldPoint place = target;
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (place == null || player == null || view == null || view.isInstance())
		{
			return null;
		}
		WorldPoint here = player.getWorldLocation();
		LocalPoint local = player.getLocalLocation();
		if (here == null || local == null || here.getPlane() != place.getPlane())
		{
			return null;
		}
		int dx = place.getX() - here.getX();
		int dy = place.getY() - here.getY();
		double distance = Math.hypot(dx, dy);
		if (distance <= DOT_RANGE_TILES)
		{
			LocalPoint placeLocal = LocalPoint.fromWorld(view, place);
			Point dot = placeLocal == null ? null : Perspective.localToMinimap(client, placeLocal);
			if (dot != null)
			{
				OverlayUtil.renderMinimapLocation(graphics, dot, COLOR);
			}
			return null;
		}
		// A tile a few steps toward the place: the minimap's own projection then gives the direction, with its
		// rotation and zoom.
		Point centre = Perspective.localToMinimap(client, local);
		LocalPoint toward = new LocalPoint(local.getX() + (int) Math.round(dx / distance * 4 * Perspective.LOCAL_TILE_SIZE),
			local.getY() + (int) Math.round(dy / distance * 4 * Perspective.LOCAL_TILE_SIZE), local.getWorldView());
		Point ahead = Perspective.localToMinimap(client, toward);
		if (centre == null || ahead == null)
		{
			return null;
		}
		double angle = Math.atan2(ahead.getY() - centre.getY(), ahead.getX() - centre.getX());
		drawArrow(graphics, centre.getX() + ARROW_RADIUS * Math.cos(angle), centre.getY() + ARROW_RADIUS * Math.sin(angle),
			angle);
		return null;
	}

	private static void drawArrow(Graphics2D graphics, double x, double y, double angle)
	{
		double length = 10;
		double half = 6;
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		Polygon arrow = new Polygon();
		arrow.addPoint((int) Math.round(x + cos * length / 2), (int) Math.round(y + sin * length / 2));
		arrow.addPoint((int) Math.round(x - cos * length / 2 - sin * half), (int) Math.round(y - sin * length / 2 + cos * half));
		arrow.addPoint((int) Math.round(x - cos * length / 2 + sin * half), (int) Math.round(y - sin * length / 2 - cos * half));
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(COLOR);
		graphics.fillPolygon(arrow);
		graphics.setColor(Color.BLACK);
		graphics.setStroke(new BasicStroke(1));
		graphics.drawPolygon(arrow);
	}
}

package com.osrsindex;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Reads the site's guide routes (docs/guides.md) into {@link Guide}. Fields it does not know are ignored, so the
 * site can add one without a plugin release. A {@code version} other than {@link Guide#VERSION} is
 * {@link Problem#UPDATE_PLUGIN}: the site bumps it when it removes, renames or changes a field, and the plugin then
 * shows nothing of the guide rather than guess.
 *
 * <p>Everything kept is made safe to show: text is plain, without control characters, and bounded; a tile outside
 * the game's ranges is dropped, leaving the label; a link off the site is dropped. A step without an id cannot keep
 * progress, so it is left out, as is a second step with an id already used.
 */
final class GuideParser
{
	enum Problem
	{
		NONE,
		/** A {@code version} this plugin does not read. */
		UPDATE_PLUGIN,
		/** Not a guide, or not a list: not JSON, or missing what the plugin needs. */
		UNREADABLE
	}

	static final class Result<T>
	{
		final T value;
		final Problem problem;

		private Result(T value, Problem problem)
		{
			this.value = value;
			this.problem = problem;
		}

		static <T> Result<T> ok(T value)
		{
			return new Result<>(value, Problem.NONE);
		}

		static <T> Result<T> failed(Problem problem)
		{
			return new Result<>(null, problem);
		}
	}

	/** A guide id: the site's slugs. It is also part of a config key and a URL path, so nothing else is taken. */
	static final Pattern GUIDE_ID = Pattern.compile("[a-z0-9][a-z0-9_-]{0,63}");
	static final int MAX_STEP_ID = 100;
	static final int MAX_REVISION = 128;
	static final int MAX_TITLE = 200;
	static final int MAX_SUMMARY = 1_000;
	static final int MAX_TEXT = 4_000;
	static final int MAX_LINE = 1_000;
	static final int MAX_GUIDES = 200;
	static final int MAX_SECTIONS = 200;
	static final int MAX_STEPS = 3_000;
	static final int MAX_LIST = 50;
	/**
	 * Items in one list: a step's bring, collect or rewards. A shopping step stocks up for many quests at once: the
	 * site's quest route sends 108 on one, so 50 was too few.
	 */
	static final int MAX_ITEMS = 500;
	static final int MAX_ITEM_ID = 65_535;
	/** Above any varbit or varp the game has. */
	static final int MAX_VAR_ID = 50_000;
	/** An area wider than this is not a place. */
	static final int MAX_AREA_RADIUS = 50;
	static final java.util.Set<String> VAR_OPS = new java.util.HashSet<>(java.util.Arrays.asList("==", "!=", ">=", ">",
		"<=", "<"));

	private GuideParser()
	{
	}

	static Result<Guide.Listing> listing(String body)
	{
		JsonObject json = object(body);
		if (json == null)
		{
			return Result.failed(Problem.UNREADABLE);
		}
		Problem version = version(json);
		if (version != Problem.NONE)
		{
			return Result.failed(version);
		}
		JsonArray array = array(json, "guides");
		if (array == null)
		{
			return Result.failed(Problem.UNREADABLE);
		}
		List<Guide.Summary> guides = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (JsonObject entry : objects(array, MAX_GUIDES))
		{
			String id = guideId(entry);
			String title = text(entry, "title", MAX_TITLE);
			if (id == null || title == null || !seen.add(id))
			{
				continue;
			}
			guides.add(new Guide.Summary(id, title, text(entry, "summary", MAX_SUMMARY), word(entry, "membership"),
				modes(entry), (int) number(entry, "steps", -1, 0, MAX_STEPS), (int) number(entry, "minutes", -1, 0, 1_000_000),
				revision(entry)));
		}
		return Result.ok(new Guide.Listing(guides));
	}

	static Result<Guide> guide(String body)
	{
		JsonObject json = object(body);
		if (json == null)
		{
			return Result.failed(Problem.UNREADABLE);
		}
		Problem version = version(json);
		if (version != Problem.NONE)
		{
			return Result.failed(version);
		}
		String id = guideId(json);
		String title = text(json, "title", MAX_TITLE);
		JsonArray sectionArray = array(json, "sections");
		if (id == null || title == null || sectionArray == null)
		{
			return Result.failed(Problem.UNREADABLE);
		}
		List<Guide.Section> sections = new ArrayList<>();
		Set<String> stepIds = new HashSet<>();
		for (JsonObject section : objects(sectionArray, MAX_SECTIONS))
		{
			List<Guide.Step> steps = new ArrayList<>();
			for (JsonObject step : objects(array(section, "steps"), MAX_STEPS - stepIds.size()))
			{
				Guide.Step parsed = step(step);
				if (parsed != null && stepIds.add(parsed.id))
				{
					steps.add(parsed);
				}
			}
			if (!steps.isEmpty())
			{
				String sectionTitle = text(section, "title", MAX_TITLE);
				sections.add(new Guide.Section(orEmpty(text(section, "id", MAX_STEP_ID)), sectionTitle == null ? "" : sectionTitle,
					text(section, "summary", MAX_SUMMARY), steps));
			}
		}
		return Result.ok(new Guide(id, title, text(json, "summary", MAX_SUMMARY), text(json, "attribution", MAX_SUMMARY),
			revision(json), modes(json), sections));
	}

	private static Guide.Step step(JsonObject json)
	{
		String id = text(json, "id", MAX_STEP_ID);
		if (id == null)
		{
			return null;
		}
		String title = text(json, "title", MAX_TITLE);
		Set<String> tags = new LinkedHashSet<>();
		for (String tag : strings(json, "tags", 30))
		{
			tags.add(tag.toLowerCase(Locale.ROOT));
		}
		List<Guide.Place> travel = new ArrayList<>();
		for (JsonObject entry : objects(array(json, "travel"), MAX_LIST))
		{
			Guide.Place place = place(entry, text(entry, "by", 30));
			if (place != null)
			{
				travel.add(place);
			}
		}
		List<Guide.Place> places = new ArrayList<>();
		for (JsonObject entry : objects(array(json, "places"), MAX_LIST))
		{
			Guide.Place place = place(entry, null);
			if (place != null)
			{
				places.add(place);
			}
		}
		List<Guide.Collect> collect = new ArrayList<>();
		for (JsonObject entry : objects(array(json, "collect"), MAX_ITEMS))
		{
			JsonObject item = object(entry, "item");
			Guide.Item parsed = item == null ? null : item(item);
			if (parsed != null)
			{
				collect.add(new Guide.Collect(parsed, strings(entry, "for", MAX_TITLE), text(entry, "from", MAX_TITLE)));
			}
		}
		JsonObject rewards = object(json, "rewards");
		return new Guide.Step(id, title == null ? id : title, (int) number(json, "minutes", -1, 0, 1_000_000),
			SiteConfig.siteUrl(SiteConfig.string(json, "url")), text(json, "text", MAX_TEXT), strings(json, "how", MAX_LINE),
			text(json, "tip", MAX_TEXT), text(json, "ironman", MAX_TEXT), tags, strings(json, "quests", MAX_TITLE), places,
			travel, items(array(json, "bring")), collect, requirements(array(json, "requires")),
			requirements(array(json, "completes")), rewards == null ? null : rewards(rewards));
	}

	/** A place or a travel entry. Without a label it says nothing, so it is dropped; a bad tile leaves the label. */
	private static Guide.Place place(JsonObject json, String by)
	{
		String label = text(json, "label", RouteDispatcher.MAX_LABEL_CODE_POINTS);
		if (label == null)
		{
			return null;
		}
		Integer x = wholeNumber(json.get("x"));
		Integer y = wholeNumber(json.get("y"));
		JsonElement planeValue = json.get("plane");
		Integer plane = planeValue == null ? Integer.valueOf(0) : wholeNumber(planeValue);
		boolean tile = x != null && y != null && plane != null && inRange(x, RouteDispatcher.MAX_COORDINATE)
			&& inRange(y, RouteDispatcher.MAX_COORDINATE) && inRange(plane, RouteDispatcher.MAX_PLANE);
		return tile ? new Guide.Place(label, by, x, y, plane) : new Guide.Place(label, by, -1, -1, -1);
	}

	private static List<Guide.Item> items(JsonArray array)
	{
		List<Guide.Item> out = new ArrayList<>();
		for (JsonObject entry : objects(array, MAX_ITEMS))
		{
			Guide.Item item = item(entry);
			if (item != null)
			{
				out.add(item);
			}
		}
		return out;
	}

	/** An item: a name always, and the game's id when the site knows it. An id of 0 or less is no id. */
	private static Guide.Item item(JsonObject json)
	{
		String name = text(json, "name", MAX_TITLE);
		if (name == null)
		{
			return null;
		}
		Integer id = wholeNumber(json.get("id"));
		return new Guide.Item(name, id == null || id <= 0 || id > MAX_ITEM_ID ? -1 : id,
			(int) number(json, "qty", 1, 1, Integer.MAX_VALUE));
	}

	private static List<Guide.Requirement> requirements(JsonArray array)
	{
		List<Guide.Requirement> out = new ArrayList<>();
		for (JsonObject entry : objects(array, MAX_LIST))
		{
			out.add(requirement(entry));
		}
		return out;
	}

	/** One requirement. One this version cannot read is kept as {@link Guide.Requirement.Kind#UNKNOWN}. */
	static Guide.Requirement requirement(JsonObject json)
	{
		String kind = word(json, "kind");
		Guide.Requirement unknown = new Guide.Requirement(Guide.Requirement.Kind.UNKNOWN, null, 0, false, null, 0,
			Collections.<String>emptyList());
		if (kind == null)
		{
			return unknown;
		}
		switch (kind)
		{
			case "skill":
			{
				String skill = word(json, "skill");
				Integer level = wholeNumber(json.get("level"));
				if (skill == null || level == null || level < 1 || level > 99)
				{
					return unknown;
				}
				JsonElement boostable = json.get("boostable");
				return new Guide.Requirement(Guide.Requirement.Kind.SKILL, skill, level, boostable != null
					&& boostable.isJsonPrimitive() && boostable.getAsJsonPrimitive().isBoolean() && boostable.getAsBoolean(),
					null, 0, Collections.<String>emptyList());
			}
			case "quest":
			{
				String quest = text(json, "quest", MAX_TITLE);
				return quest == null ? unknown : new Guide.Requirement(Guide.Requirement.Kind.QUEST, null, 0, false, quest, 0,
					Collections.<String>emptyList());
			}
			case "quest_points":
			{
				Integer points = wholeNumber(json.get("points"));
				return points == null || points < 0 || points > 1_000 ? unknown
					: new Guide.Requirement(Guide.Requirement.Kind.QUEST_POINTS, null, 0, false, null, points,
					Collections.<String>emptyList());
			}
			case "mode":
			{
				List<String> modes = modes(json);
				return modes == null || modes.isEmpty() ? unknown
					: new Guide.Requirement(Guide.Requirement.Kind.MODE, null, 0, false, null, 0, modes);
			}
			case "varbit":
			case "varp":
			{
				Integer id = wholeNumber(json.get("id"));
				Integer value = wholeNumber(json.get("value"));
				String op = json.has("op") ? SiteConfig.string(json, "op") : ">=";
				if (id == null || id < 0 || id > MAX_VAR_ID || value == null || op == null || !VAR_OPS.contains(op))
				{
					return unknown;
				}
				return Guide.Requirement.of(kind.equals("varbit") ? Guide.Requirement.Kind.VARBIT : Guide.Requirement.Kind.VARP,
					id, op, value, Collections.<Guide.Item>emptyList(), null, null, text(json, "label", MAX_TITLE));
			}
			case "items":
			{
				List<Guide.Item> items = items(array(json, "items"));
				String where = json.has("where") ? word(json, "where") : "owned";
				if (items.isEmpty() || !("owned".equals(where) || "carried".equals(where)))
				{
					return unknown;
				}
				return Guide.Requirement.of(Guide.Requirement.Kind.ITEMS, -1, where, 0, items, null, null,
					text(json, "label", MAX_TITLE));
			}
			case "area":
			{
				String label = text(json, "label", RouteDispatcher.MAX_LABEL_CODE_POINTS);
				JsonObject centre = json.deepCopy();
				if (label == null)
				{
					centre.addProperty("label", "the place");
				}
				Guide.Place place = place(centre, null);
				int radius = (int) number(json, "radius", GuideSigns.REACH_TILES, 0, MAX_AREA_RADIUS);
				return place == null || !place.hasPoint() ? unknown : Guide.Requirement.of(Guide.Requirement.Kind.AREA, -1,
					null, radius, Collections.<Guide.Item>emptyList(), place, null, label);
			}
			case "talk":
			case "kill":
			{
				String npc = text(json, "npc", MAX_TITLE);
				int count = (int) number(json, "count", 1, 1, 1_000);
				return npc == null ? unknown : Guide.Requirement.of(kind.equals("talk") ? Guide.Requirement.Kind.TALK
					: Guide.Requirement.Kind.KILL, -1, null, count, Collections.<Guide.Item>emptyList(), null, npc,
					text(json, "label", MAX_TITLE));
			}
			default:
				return unknown;
		}
	}

	private static Guide.Rewards rewards(JsonObject json)
	{
		List<Guide.Xp> xp = new ArrayList<>();
		for (JsonObject entry : objects(array(json, "xp"), MAX_LIST))
		{
			String skill = word(entry, "skill");
			long amount = number(entry, "amount", 0, 0, 200_000_000);
			if (skill != null && amount > 0)
			{
				xp.add(new Guide.Xp(skill, amount));
			}
		}
		return new Guide.Rewards(xp, (int) number(json, "quest_points", 0, 0, 1_000),
			number(json, "coins", 0, 0, Integer.MAX_VALUE), items(array(json, "items")), strings(json, "unlocks", MAX_LINE));
	}

	// --- reading the body ----------------------------------------------------

	private static JsonObject object(String body)
	{
		try
		{
			JsonElement parsed = body == null ? null : new JsonParser().parse(body);
			return parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
		}
		catch (RuntimeException notJson)
		{
			return null;
		}
	}

	private static Problem version(JsonObject json)
	{
		Integer version = wholeNumber(json.get("version"));
		if (version == null)
		{
			return json.has("version") ? Problem.UPDATE_PLUGIN : Problem.UNREADABLE;
		}
		return version == Guide.VERSION ? Problem.NONE : Problem.UPDATE_PLUGIN;
	}

	private static String guideId(JsonObject json)
	{
		String id = SiteConfig.string(json, "id");
		return id != null && GUIDE_ID.matcher(id).matches() ? id : null;
	}

	private static String revision(JsonObject json)
	{
		String revision = SiteConfig.string(json, "revision");
		return revision != null && !revision.isEmpty() && revision.length() <= MAX_REVISION
			&& revision.chars().allMatch(c -> c > ' ' && c < 0x7F) ? revision : null;
	}

	/** The account types listed, lower case, or null when the field is absent or not a list (any type). */
	private static List<String> modes(JsonObject json)
	{
		if (array(json, "modes") == null)
		{
			return null;
		}
		List<String> out = new ArrayList<>();
		for (String mode : strings(json, "modes", 40))
		{
			out.add(mode.toLowerCase(Locale.ROOT));
		}
		return out;
	}

	/** A short lower-case word such as a kind or a skill: letters, digits and underscores only, or null. */
	private static String word(JsonObject json, String key)
	{
		String value = SiteConfig.string(json, key);
		if (value == null)
		{
			return null;
		}
		String lower = value.toLowerCase(Locale.ROOT);
		return lower.matches("[a-z0-9_]{1,40}") ? lower : null;
	}

	private static JsonObject object(JsonObject json, String key)
	{
		JsonElement value = json.get(key);
		return value != null && value.isJsonObject() ? value.getAsJsonObject() : null;
	}

	private static JsonArray array(JsonObject json, String key)
	{
		JsonElement value = json == null ? null : json.get(key);
		return value != null && value.isJsonArray() ? value.getAsJsonArray() : null;
	}

	/** The objects in {@code array}, at most {@code limit}; anything else in it is skipped. */
	private static List<JsonObject> objects(JsonArray array, int limit)
	{
		List<JsonObject> out = new ArrayList<>();
		if (array == null)
		{
			return out;
		}
		for (JsonElement element : array)
		{
			if (out.size() >= limit)
			{
				break;
			}
			if (element != null && element.isJsonObject())
			{
				out.add(element.getAsJsonObject());
			}
		}
		return out;
	}

	/** The plain strings in the list {@code key}, each made safe ({@link #text(String, int)}), at most {@link #MAX_LIST}. */
	private static List<String> strings(JsonObject json, String key, int max)
	{
		List<String> out = new ArrayList<>();
		JsonArray array = array(json, key);
		if (array == null)
		{
			return out;
		}
		for (JsonElement element : array)
		{
			if (out.size() >= MAX_LIST)
			{
				break;
			}
			if (element != null && element.isJsonPrimitive() && element.getAsJsonPrimitive().isString())
			{
				String text = text(element.getAsString(), max);
				if (text != null)
				{
					out.add(text);
				}
			}
		}
		return out;
	}

	private static String text(JsonObject json, String key, int max)
	{
		return text(SiteConfig.string(json, key), max);
	}

	/**
	 * Text made safe to show: control characters dropped, runs of whitespace made one space, at most {@code max} code
	 * points. Null when nothing is left. Markup stays text: the panel and chat each escape it where they show it.
	 */
	static String text(String raw, int max)
	{
		if (raw == null)
		{
			return null;
		}
		StringBuilder out = new StringBuilder();
		int[] count = {0};
		raw.codePoints()
			.map(codePoint -> Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint) ? ' ' : codePoint)
			.filter(codePoint -> !Character.isISOControl(codePoint) && Character.getType(codePoint) != Character.FORMAT)
			.forEach(codePoint ->
			{
				boolean space = codePoint == ' ';
				if (count[0] < max && !(space && (out.length() == 0 || out.charAt(out.length() - 1) == ' ')))
				{
					out.appendCodePoint(codePoint);
					count[0]++;
				}
			});
		String text = out.toString().trim();
		return text.isEmpty() ? null : text;
	}

	private static String orEmpty(String value)
	{
		return value == null ? "" : value;
	}

	/** A number field clamped to {@code min}..{@code max}, or {@code fallback} when absent or not a number. */
	private static long number(JsonObject json, String key, long fallback, long min, long max)
	{
		JsonElement value = json.get(key);
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return fallback;
		}
		double number = value.getAsDouble();
		if (Double.isNaN(number))
		{
			return fallback;
		}
		return (long) Math.max(min, Math.min(max, number));
	}

	/** A JSON number with no fraction that fits an int, or null. */
	private static Integer wholeNumber(JsonElement value)
	{
		if (value == null || !value.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive primitive = value.getAsJsonPrimitive();
		if (!primitive.isNumber())
		{
			return null;
		}
		double number = primitive.getAsDouble();
		return number == Math.rint(number) && number >= Integer.MIN_VALUE && number <= Integer.MAX_VALUE ? (int) number : null;
	}

	private static boolean inRange(int value, int max)
	{
		return value >= 0 && value <= max;
	}
}

package com.osrsindex;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Which steps of one guide the player marked, kept in the RuneLite profile, so per character, by the site's stable
 * step id. A step is done, skipped, not done ("open", said by the player, so a later done step does not count it as
 * passed), or unmarked. The player may also name the step they start from, with Start here. Marks for step ids the guide no longer has are kept, not
 * reset: they are ignored while the guide lacks the step, and count again if it comes back.
 *
 * <p>Stored as a JSON object of step id to {@code "done"}, {@code "skipped"} or {@code "open"}, with the start step
 * under {@code "@start"} (no step id starts with {@code @}). Not thread-safe: the plugin uses
 * it on the client thread, and the panel gets a {@link #copy()}.
 */
final class GuideProgress
{
	enum Mark
	{
		DONE("done"),
		SKIPPED("skipped"),
		/** Not done, in the player's words: a step with nothing to check, which a later done step would count as passed. */
		OPEN("open");

		final String key;

		Mark(String key)
		{
			this.key = key;
		}

		static Mark of(String key)
		{
			for (Mark mark : values())
			{
				if (mark.key.equals(key))
				{
					return mark;
				}
			}
			return null;
		}
	}

	/** More marks than any guide has steps: a profile value past this is not ours to grow. */
	static final int MAX_MARKS = 5_000;

	/** Where the start step is kept in the stored object. */
	static final String START_KEY = "@start";

	private final Map<String, Mark> marks = new LinkedHashMap<>();
	/** The step the player said they start from, or null. */
	private String start;

	Mark mark(String stepId)
	{
		return marks.get(stepId);
	}

	/** Mark a step, or clear its mark with null. True when that changed anything. */
	boolean set(String stepId, Mark mark)
	{
		if (mark == null)
		{
			return marks.remove(stepId) != null;
		}
		if (marks.size() >= MAX_MARKS && !marks.containsKey(stepId))
		{
			return false;
		}
		return marks.put(stepId, mark) != mark;
	}

	/** The step the player said they start from (Start here), or null. */
	String start()
	{
		return start;
	}

	/** Name the step the player starts from, or clear it with null. True when that changed anything. */
	boolean start(String stepId)
	{
		if (stepId != null && stepId.length() > GuideParser.MAX_STEP_ID * 2)
		{
			return false;
		}
		boolean changed = stepId == null ? start != null : !stepId.equals(start);
		start = stepId;
		return changed;
	}

	int size()
	{
		return marks.size();
	}

	GuideProgress copy()
	{
		GuideProgress copy = new GuideProgress();
		copy.marks.putAll(marks);
		copy.start = start;
		return copy;
	}

	/** The marks saved in the profile; anything unreadable in it is left out. */
	static GuideProgress load(String saved)
	{
		GuideProgress progress = new GuideProgress();
		if (saved == null || saved.isEmpty())
		{
			return progress;
		}
		try
		{
			JsonElement parsed = new JsonParser().parse(saved);
			if (parsed == null || !parsed.isJsonObject())
			{
				return progress;
			}
			for (Map.Entry<String, JsonElement> entry : parsed.getAsJsonObject().entrySet())
			{
				JsonElement value = entry.getValue();
				if (START_KEY.equals(entry.getKey()))
				{
					if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isString())
					{
						progress.start(value.getAsString());
					}
					continue;
				}
				Mark mark = value.isJsonPrimitive() && value.getAsJsonPrimitive().isString() ? Mark.of(value.getAsString())
					: null;
				if (mark != null && entry.getKey().length() <= GuideParser.MAX_STEP_ID * 2)
				{
					progress.set(entry.getKey(), mark);
				}
			}
		}
		catch (RuntimeException unreadable)
		{
			// A damaged value: start this guide afresh rather than fail.
		}
		return progress;
	}

	JsonObject toJson()
	{
		JsonObject out = new JsonObject();
		for (Map.Entry<String, Mark> entry : marks.entrySet())
		{
			out.addProperty(entry.getKey(), entry.getValue().key);
		}
		if (start != null)
		{
			out.addProperty(START_KEY, start);
		}
		return out;
	}
}

package com.osrsindex;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.QuestState;

/**
 * The guide rules, kept apart from the client so they can be tested: whether a requirement is met, when a step ticks
 * itself, a step's status, the "N/total" count and the current step, and whether the player has an item. Each reads
 * only a {@link GuideFacts} snapshot and the player's marks.
 *
 * <p>Where the player is in a guide ({@link #standing}) goes past the site's evaluator, so an account that is not new
 * does not start at step one: the player's place is the end of the sections they have mostly finished, and an
 * earlier step that nothing in the game can show done or not counts as passed. An earlier step the game shows is
 * not done stays behind the player, listed, rather than becoming the current step. A step done far ahead, such as a
 * quest done out of the guide's order, does not move the place.
 */
final class GuideRules
{
	/** A boostable skill requirement is met this many levels short, as on the site. */
	static final int BOOST_ALLOWANCE = 5;
	/** A section is finished, for the player's place, once this share of the steps the game can check in it is done. */
	static final double SECTION_FINISHED = 0.8;

	enum Met
	{
		MET,
		/** Short, but within {@link #BOOST_ALLOWANCE} of a boostable level: shown as met, with "boost". */
		BOOST,
		MISSING,
		/** The client cannot tell: logged out, not read yet, or a kind this version does not know. */
		UNKNOWN;

		boolean met()
		{
			return this == MET || this == BOOST;
		}
	}

	enum Status
	{
		OPEN,
		DONE,
		SKIPPED,
		/** Before the player's place, and nothing in the game shows it done or not: counted as done. */
		PASSED,
		/** Before the player's place, and the game shows it is not done, or the player said so. */
		BEHIND
	}

	/** Where an item to bring is: carried (inventory or worn), in the bank, or neither. */
	enum Have
	{
		CARRIED,
		BANKED,
		MISSING,
		/** Not carried, and the bank has not been open since login. */
		BANK_UNSEEN,
		/** The site gives no item id, so it is shown by name only. */
		NO_ID
	}

	/** The guide's "N/total": done steps over every step not skipped, and the current step, or null when none is open. */
	static final class Count
	{
		final int done;
		final int total;
		final Guide.Step current;

		Count(int done, int total, Guide.Step current)
		{
			this.done = done;
			this.total = total;
			this.current = current;
		}

		@Override
		public String toString()
		{
			return done + "/" + total;
		}
	}

	private GuideRules()
	{
	}

	static Met requirement(Guide.Requirement requirement, GuideFacts facts)
	{
		switch (requirement.kind)
		{
			case SKILL:
			{
				Integer level = facts.realLevel(requirement.skill);
				if (level == null)
				{
					return Met.UNKNOWN;
				}
				if (level >= requirement.level)
				{
					return Met.MET;
				}
				return requirement.boostable && level + BOOST_ALLOWANCE >= requirement.level ? Met.BOOST : Met.MISSING;
			}
			case QUEST:
			{
				QuestState state = facts.quest(requirement.quest);
				return state == null ? Met.UNKNOWN : state == QuestState.FINISHED ? Met.MET : Met.MISSING;
			}
			case QUEST_POINTS:
				return facts.questPoints < 0 ? Met.UNKNOWN : facts.questPoints >= requirement.points ? Met.MET : Met.MISSING;
			case MODE:
				return facts.accountType == null ? Met.UNKNOWN
					: requirement.modes.contains(facts.accountType) ? Met.MET : Met.MISSING;
			case VARBIT:
			case VARP:
			{
				Integer value = requirement.kind == Guide.Requirement.Kind.VARBIT ? facts.varbit(requirement.varId)
					: facts.varp(requirement.varId);
				return value == null ? Met.UNKNOWN : compare(value, requirement.op, requirement.value) ? Met.MET : Met.MISSING;
			}
			case ITEMS:
			{
				boolean unknown = false;
				for (Guide.Item item : requirement.items)
				{
					if (item.id < 0)
					{
						unknown = true;
						continue;
					}
					if (facts.carried(item.id) >= item.qty)
					{
						continue;
					}
					if ("carried".equals(requirement.op))
					{
						return Met.MISSING;
					}
					if (!facts.bankSeen)
					{
						unknown = true;
						continue;
					}
					if (facts.carried(item.id) + facts.banked(item.id) < item.qty)
					{
						return Met.MISSING;
					}
				}
				return unknown ? Met.UNKNOWN : Met.MET;
			}
			case AREA:
			case TALK:
			case KILL:
			case UNKNOWN:
			default:
				// Something that happens, not a state: the tracker sees it when it does ({@link GuideSigns}).
				return Met.UNKNOWN;
		}
	}

	static boolean compare(int value, String op, int target)
	{
		switch (op == null ? ">=" : op)
		{
			case "==":
				return value == target;
			case "!=":
				return value != target;
			case ">":
				return value > target;
			case "<=":
				return value <= target;
			case "<":
				return value < target;
			case ">=":
			default:
				return value >= target;
		}
	}

	/**
	 * Whether the character has done the step, from the live client: every {@code completes} entry met, with a skill
	 * at its real level (a boost does not finish a step). A quest step with no {@code completes} is done when all its
	 * quests are finished, so the guide moves on when Quest Helper's quest ends. A step with neither that picks items
	 * up is done when every quest those items are for is finished (they were fetched and used), or when the player owns
	 * an untradeable item it picks up, carried or banked (only that step gives it). Unknown is never done.
	 */
	static boolean completed(Guide.Step step, GuideFacts facts)
	{
		if (!step.completes.isEmpty())
		{
			// With something that happens among them (an area, a talk, a kill), the step is done when it happens, with
			// the states met then: the tracker marks it ({@link GuideSigns}).
			for (Guide.Requirement entry : step.completes)
			{
				if (entry.kind.event() || requirement(entry, facts) != Met.MET)
				{
					return false;
				}
			}
			return true;
		}
		if (step.quests.isEmpty())
		{
			return pickedUp(step, facts);
		}
		for (String quest : step.quests)
		{
			if (facts.quest(quest) != QuestState.FINISHED)
			{
				return false;
			}
		}
		return true;
	}

	private static boolean pickedUp(Guide.Step step, GuideFacts facts)
	{
		boolean anyFor = false;
		boolean allFinished = true;
		for (Guide.Collect collect : step.collect)
		{
			if (collect.item.untradeable && owned(collect.item, facts))
			{
				return true;
			}
			for (String quest : collect.forQuests)
			{
				anyFor = true;
				allFinished &= facts.quest(quest) == QuestState.FINISHED;
			}
			allFinished &= !collect.forQuests.isEmpty();
		}
		return anyFor && allFinished;
	}

	/** At least one carried or, once the bank has been seen, banked. */
	static boolean owned(Guide.Item item, GuideFacts facts)
	{
		return item.id >= 0 && facts.carried(item.id) + (facts.bankSeen ? facts.banked(item.id) : 0) >= 1;
	}

	/** Skipped wins over done: a skipped step stays out of the count until the player reopens it. */
	static Status status(Guide.Step step, GuideProgress progress, GuideFacts facts)
	{
		GuideProgress.Mark mark = progress.mark(step.id);
		if (mark == GuideProgress.Mark.SKIPPED)
		{
			return Status.SKIPPED;
		}
		return mark == GuideProgress.Mark.DONE || completed(step, facts) ? Status.DONE : Status.OPEN;
	}

	/** Every step's status where it sits in the guide, the count, and the steps left behind the player's place. */
	static final class Standing
	{
		private final Map<String, Status> statuses;
		final Count count;
		/** Steps before the player's place that are not done, in guide order. */
		final List<Guide.Step> behind;

		Standing(Map<String, Status> statuses, Count count, List<Guide.Step> behind)
		{
			this.statuses = statuses;
			this.count = count;
			this.behind = Collections.unmodifiableList(behind);
		}

		Status of(Guide.Step step)
		{
			Status status = statuses.get(step.id);
			return status == null ? Status.OPEN : status;
		}
	}

	/**
	 * Something the plugin can read at any time shows the step done or not: a state in its {@code completes}, or its
	 * quests.
	 */
	static boolean checkable(Guide.Step step)
	{
		if (!step.quests.isEmpty())
		{
			return true;
		}
		for (Guide.Requirement entry : step.completes)
		{
			if (entry.kind.state())
			{
				return true;
			}
		}
		return false;
	}

	/** Every state in the step's {@code completes} is met: what an event needs as well, to tick it. */
	static boolean statesMet(Guide.Step step, GuideFacts facts)
	{
		for (Guide.Requirement entry : step.completes)
		{
			if (entry.kind.state() && requirement(entry, facts) != Met.MET)
			{
				return false;
			}
		}
		return true;
	}

	/** The varbit ids the guide's conditions name, to read. */
	static Set<Integer> varbits(Guide guide)
	{
		return vars(guide, Guide.Requirement.Kind.VARBIT);
	}

	/** The varp ids the guide's conditions name, to read. */
	static Set<Integer> varps(Guide guide)
	{
		return vars(guide, Guide.Requirement.Kind.VARP);
	}

	private static Set<Integer> vars(Guide guide, Guide.Requirement.Kind kind)
	{
		Set<Integer> out = new LinkedHashSet<>();
		for (Guide.Step step : guide.steps)
		{
			for (List<Guide.Requirement> list : java.util.Arrays.asList(step.requires, step.completes))
			{
				for (Guide.Requirement entry : list)
				{
					if (entry.kind == kind)
					{
						out.add(entry.varId);
					}
				}
			}
		}
		return out;
	}

	/**
	 * Where the player is. Their place is found by sections: the first section whose checkable steps are less than
	 * {@link #SECTION_FINISHED} done is where they are, and their place is the last done step before its first open
	 * checkable step, in it or earlier. When every section is mostly done, it is the furthest
	 * done step. Start here moves it on to the step before the one named. An open step at or before the place is passed
	 * when nothing in the game can show it either way, and behind when the game shows it is not done or the player
	 * said so. The current step is the first open one after the place; when there is none, the first one behind. A
	 * player with nothing done starts at the first step, and a step done far ahead does not move the place.
	 */
	static Standing standing(Guide guide, GuideProgress progress, GuideFacts facts)
	{
		List<Guide.Step> steps = guide.steps;
		Status[] base = new Status[steps.size()];
		int furthest = -1;
		for (int i = 0; i < steps.size(); i++)
		{
			base[i] = status(steps.get(i), progress, facts);
			if (base[i] == Status.DONE)
			{
				furthest = i;
			}
		}
		int place = furthest;
		int first = 0;
		int lastDone = -1;
		for (Guide.Section section : guide.sections)
		{
			int checkable = 0;
			int done = 0;
			for (int i = first; i < first + section.steps.size(); i++)
			{
				if (checkable(steps.get(i)) && base[i] != Status.SKIPPED)
				{
					checkable++;
					done += base[i] == Status.DONE ? 1 : 0;
				}
			}
			if (checkable > 0 && done < SECTION_FINISHED * checkable)
			{
				// The player is in this section: their place is the last done step before its first open checkable one.
				place = lastDone;
				for (int i = first; i < first + section.steps.size(); i++)
				{
					if (base[i] == Status.DONE)
					{
						place = i;
					}
					else if (base[i] == Status.OPEN && checkable(steps.get(i)))
					{
						break;
					}
				}
				break;
			}
			for (int i = first; i < first + section.steps.size(); i++)
			{
				if (base[i] == Status.DONE)
				{
					lastDone = i;
				}
			}
			first += section.steps.size();
		}
		String start = progress.start();
		if (start != null)
		{
			for (int i = 0; i < steps.size(); i++)
			{
				if (steps.get(i).id.equals(start))
				{
					place = Math.max(place, i - 1);
					break;
				}
			}
		}
		Map<String, Status> statuses = new HashMap<>();
		List<Guide.Step> behind = new ArrayList<>();
		int done = 0;
		int total = 0;
		Guide.Step current = null;
		for (int i = 0; i < steps.size(); i++)
		{
			Guide.Step step = steps.get(i);
			Status status = base[i];
			if (status == Status.OPEN && i <= place)
			{
				status = checkable(step) || progress.mark(step.id) == GuideProgress.Mark.OPEN ? Status.BEHIND : Status.PASSED;
			}
			statuses.put(step.id, status);
			if (status == Status.SKIPPED)
			{
				continue;
			}
			total++;
			if (status == Status.DONE || status == Status.PASSED)
			{
				done++;
			}
			else if (status == Status.BEHIND)
			{
				behind.add(step);
			}
			else if (current == null)
			{
				current = step;
			}
		}
		if (current == null && !behind.isEmpty())
		{
			current = behind.get(0);
		}
		return new Standing(statuses, new Count(done, total, current), behind);
	}

	/** Done, ticked and passed steps, out of every step that is not skipped, and the current step ({@link #standing}). */
	static Count count(Guide guide, GuideProgress progress, GuideFacts facts)
	{
		return standing(guide, progress, facts).count;
	}

	/**
	 * Mark every open step the character has completed as done, so it stays done in the profile. True when any
	 * changed. A step the player skipped is left skipped.
	 */
	static boolean tickCompleted(Guide guide, GuideProgress progress, GuideFacts facts)
	{
		boolean changed = false;
		for (Guide.Step step : guide.steps)
		{
			if (progress.mark(step.id) == null && completed(step, facts))
			{
				changed |= progress.set(step.id, GuideProgress.Mark.DONE);
			}
		}
		return changed;
	}

	static Have item(Guide.Item item, GuideFacts facts)
	{
		if (item.id < 0)
		{
			return Have.NO_ID;
		}
		if (facts.carried(item.id) >= item.qty)
		{
			return Have.CARRIED;
		}
		if (!facts.bankSeen)
		{
			return Have.BANK_UNSEEN;
		}
		return facts.carried(item.id) + facts.banked(item.id) >= item.qty ? Have.BANKED : Have.MISSING;
	}

	/** Every quest the guide names, in its requirements, its {@code completes} and its quest steps: what to read. */
	static Set<String> quests(Guide guide)
	{
		Set<String> out = new LinkedHashSet<>();
		for (Guide.Step step : guide.steps)
		{
			out.addAll(quests(step));
		}
		return out;
	}

	static Set<String> quests(Guide.Step step)
	{
		Set<String> out = new LinkedHashSet<>(step.quests);
		for (Guide.Requirement requirement : step.requires)
		{
			if (requirement.kind == Guide.Requirement.Kind.QUEST)
			{
				out.add(requirement.quest);
			}
		}
		for (Guide.Requirement requirement : step.completes)
		{
			if (requirement.kind == Guide.Requirement.Kind.QUEST)
			{
				out.add(requirement.quest);
			}
		}
		for (Guide.Collect collect : step.collect)
		{
			out.addAll(collect.forQuests);
		}
		return out;
	}
}

package com.osrsindex;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the game can show happening that ticks a step. The site names it in {@code completes}, as an {@code area}, a
 * {@code talk} or a {@code kill}; for a step with no {@code completes} and no quests, it is read from the title and
 * the step's fields instead: talking to the person it names ("Meet the Mining Instructor"), killing what it names
 * ("Kill a goblin", "Kill 5 cows"), reaching the place it sends you to ("Go to Draynor Village"), or holding the items
 * it tells you to get ("Buy a hammer"). A step whose title matches none of these has no signs, and is ticked by hand.
 *
 * <p>The site's own {@code completes} always wins; these are only for steps it has not described yet. They are
 * checked against the current step alone, so talking to someone a later step names ticks nothing early.
 */
final class GuideSigns
{
	/** How near the place counts as reaching it, in tiles, on its plane. */
	static final int REACH_TILES = 6;

	static final GuideSigns NONE = new GuideSigns(Collections.emptySet(), Collections.emptySet(), 0, null, REACH_TILES,
		Collections.emptyList());

	private static final Pattern TALK = Pattern.compile("^(?:talk to|speak to|speak with|meet|ask)\\s+(.+)$");
	static final Pattern KILL = Pattern.compile("^(?:kill|defeat|slay)\\s+(?:(\\d{1,4})\\s+)?(.+)$");
	private static final Pattern REACH = Pattern.compile(
		"^(?:go to|walk to|run to|travel to|head to|teleport to|return to|go back to)\\s+.+$");
	private static final Pattern GET = Pattern.compile("^(?:get|buy|collect|pick up|gather|grab|take)\\s+.+$");

	/** Names a dialogue may show for the person to talk to, normalised. */
	final Set<String> talk;
	/** Names of what to kill, normalised. */
	final Set<String> kill;
	/** How many kills tick the step: 1 unless the title counts them. */
	final int kills;
	/** The place to reach, with a tile, or null. */
	final Guide.Place reach;
	/** How near the place counts, in tiles. */
	final int reachTiles;
	/** Items to hold, each with an id. */
	final List<Guide.Item> get;

	private GuideSigns(Set<String> talk, Set<String> kill, int kills, Guide.Place reach, int reachTiles,
		List<Guide.Item> get)
	{
		this.talk = talk;
		this.kill = kill;
		this.kills = kills;
		this.reach = reach;
		this.reachTiles = reachTiles;
		this.get = get;
	}

	static GuideSigns of(Guide.Step step)
	{
		if (!step.quests.isEmpty())
		{
			return NONE;
		}
		Set<String> talkNames = new LinkedHashSet<>();
		Set<String> killNames = new LinkedHashSet<>();
		int killCount = 1;
		Guide.Place area = null;
		int tiles = REACH_TILES;
		for (Guide.Requirement entry : step.completes)
		{
			switch (entry.kind)
			{
				case TALK:
					talkNames.add(name(entry.npc));
					break;
				case KILL:
					killNames.add(name(entry.npc));
					killCount = Math.max(killCount, entry.value);
					break;
				case AREA:
					if (area == null)
					{
						area = entry.place;
						tiles = entry.value;
					}
					break;
				default:
					break;
			}
		}
		if (!talkNames.isEmpty() || !killNames.isEmpty() || area != null)
		{
			// The site said what happens: that, and no guessing.
			return new GuideSigns(Collections.unmodifiableSet(talkNames), Collections.unmodifiableSet(killNames),
				killNames.isEmpty() ? 0 : killCount, area, tiles, Collections.emptyList());
		}
		if (!step.completes.isEmpty())
		{
			return NONE;
		}
		String title = step.title.trim().toLowerCase(Locale.ROOT);
		Matcher talk = TALK.matcher(title);
		if (talk.matches())
		{
			Set<String> names = new LinkedHashSet<>();
			names.add(name(talk.group(1)));
			for (Guide.Place place : step.places)
			{
				names.add(name(place.label));
			}
			return new GuideSigns(Collections.unmodifiableSet(names), Collections.emptySet(), 0, null, REACH_TILES,
				Collections.emptyList());
		}
		Matcher kill = KILL.matcher(title);
		if (kill.matches())
		{
			Set<String> names = new LinkedHashSet<>();
			names.add(name(kill.group(2)));
			for (Guide.Place place : step.places)
			{
				names.add(name(place.label));
			}
			int count = kill.group(1) == null ? 1 : Math.max(1, Math.min(1000, Integer.parseInt(kill.group(1))));
			return new GuideSigns(Collections.emptySet(), Collections.unmodifiableSet(names), count, null, REACH_TILES,
				Collections.emptyList());
		}
		if (REACH.matcher(title).matches() && step.point() != null)
		{
			return new GuideSigns(Collections.emptySet(), Collections.emptySet(), 0, step.point(), REACH_TILES,
				Collections.emptyList());
		}
		if (GET.matcher(title).matches())
		{
			List<Guide.Item> items = new ArrayList<>();
			for (Guide.Item item : step.bring)
			{
				if (item.id >= 0)
				{
					items.add(item);
				}
			}
			for (Guide.Collect collect : step.collect)
			{
				if (collect.item.id >= 0)
				{
					items.add(collect.item);
				}
			}
			if (!items.isEmpty() && items.size() == step.bring.size() + step.collect.size())
			{
				return new GuideSigns(Collections.emptySet(), Collections.emptySet(), 0, null, REACH_TILES,
					Collections.unmodifiableList(items));
			}
		}
		return NONE;
	}

	boolean none()
	{
		return talk.isEmpty() && kill.isEmpty() && reach == null && get.isEmpty();
	}

	/** A dialogue opened with someone of this name. */
	boolean talkedTo(String npc)
	{
		return npc != null && talk.contains(name(npc));
	}

	/** Something of this name died fighting the player. */
	boolean isKill(String npc)
	{
		return npc != null && kill.contains(name(npc));
	}

	boolean reached(int x, int y, int plane)
	{
		return reach != null && plane == reach.plane && Math.abs(x - reach.x) <= reachTiles
			&& Math.abs(y - reach.y) <= reachTiles;
	}

	/** Every item to get is carried, inventory or worn, in the numbers asked. Unknown is never held. */
	boolean held(GuideFacts facts)
	{
		if (get.isEmpty())
		{
			return false;
		}
		for (Guide.Item item : get)
		{
			if (GuideRules.item(item, facts) != GuideRules.Have.CARRIED)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * A name as the signs compare it: lower case, without a leading article or count, and without a plural ending,
	 * so "the Mining Instructor", "Mining Instructor", "a goblin" and "Goblins" meet their game names.
	 */
	static String name(String text)
	{
		String out = text.trim().toLowerCase(Locale.ROOT).replaceAll("<[^>]*>", "").replaceAll("\\s+", " ");
		out = out.replaceFirst("^(?:the|a|an|some|\\d+)\\s+", "");
		if (out.endsWith("es") && (out.endsWith("ches") || out.endsWith("shes") || out.endsWith("xes")))
		{
			out = out.substring(0, out.length() - 2);
		}
		else if (out.endsWith("s") && !out.endsWith("ss") && out.length() > 3)
		{
			out = out.substring(0, out.length() - 1);
		}
		return out;
	}
}

package com.osrsindex;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.util.Text;

/**
 * The current guide step in a box on the game screen, as Quest Helper shows its current step: the guide and its
 * count, the step's title and text, where it is, and what to bring that the player is not carrying. It shows nothing
 * while Quest Helper guides the step's quest, so the two boxes never show at once.
 */
final class GuideStepOverlay extends OverlayPanel
{
	/** The longest text the box shows, in characters; the panel has the rest. */
	static final int MAX_TEXT = 300;
	/** Lines of items still to bring; the rest are counted, and listed in the panel. */
	static final int MAX_BRING_LINES = 6;
	private static final int WIDTH = 200;

	/** What the box shows: plain text, made at the client thread's last check. */
	static final class Box
	{
		final String guide;
		final String count;
		final String step;
		final String text;
		/** Where the step is, or null. */
		final String where;
		/** Items to bring the player is not carrying. */
		final List<String> missing;
		/** A line about Quest Helper, before the quest starts, or null. */
		final String questHelper;

		Box(String guide, String count, String step, String text, String where, List<String> missing,
			String questHelper)
		{
			// The overlay draws RuneLite's colour tags, and these come from the site: shown as plain text.
			this.guide = plain(guide);
			this.count = plain(count);
			this.step = plain(step);
			this.text = plain(text);
			this.where = plain(where);
			List<String> plainMissing = new ArrayList<>();
			for (String item : missing)
			{
				plainMissing.add(plain(item));
			}
			this.missing = Collections.unmodifiableList(plainMissing);
			this.questHelper = plain(questHelper);
		}
	}

	private static String plain(String text)
	{
		return text == null ? null : Text.removeTags(text);
	}

	private volatile Box box;

	GuideStepOverlay()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** The box to show, or null for none. */
	void show(Box next)
	{
		box = next;
	}

	Box shown()
	{
		return box;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Box current = box;
		if (current == null)
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		panelComponent.getChildren().add(LineComponent.builder()
			.left(current.guide)
			.leftColor(Color.WHITE)
			.right(current.count)
			.rightColor(ColorScheme.LIGHT_GRAY_COLOR)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left(current.step)
			.leftColor(ColorScheme.BRAND_ORANGE)
			.build());
		if (current.questHelper != null)
		{
			line(current.questHelper, ColorScheme.BRAND_ORANGE);
		}
		if (current.text != null)
		{
			line(current.text, Color.WHITE);
		}
		if (current.where != null)
		{
			line("Where: " + current.where, ColorScheme.LIGHT_GRAY_COLOR);
		}
		for (String item : bringLines(current.missing))
		{
			line(item, ColorScheme.PROGRESS_ERROR_COLOR);
		}
		return super.render(graphics);
	}

	/** The box's Bring lines: at most {@link #MAX_BRING_LINES} items, then how many more the panel lists. */
	static List<String> bringLines(List<String> missing)
	{
		List<String> out = new ArrayList<>();
		for (String item : missing)
		{
			if (out.size() == MAX_BRING_LINES && missing.size() > MAX_BRING_LINES + 1)
			{
				out.add("Bring: and " + (missing.size() - MAX_BRING_LINES) + " more, in the panel");
				break;
			}
			out.add("Bring: " + item);
		}
		return out;
	}

	private void line(String text, Color colour)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(text).leftColor(colour).build());
	}

	/** The step's text for the box: the Ironman text for an Ironman, cut to {@link #MAX_TEXT}. */
	static String text(Guide.Step step, boolean ironman)
	{
		String text = ironman && step.ironman != null ? step.ironman : step.text;
		if (text == null || text.length() <= MAX_TEXT)
		{
			return text;
		}
		int cut = text.lastIndexOf(' ', MAX_TEXT - 1);
		return text.substring(0, cut > MAX_TEXT / 2 ? cut : MAX_TEXT - 1) + "...";
	}
}

package com.osrsindex;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Outlines the current guide step's tile in the game world once it is in view, as Quest Helper marks where to go.
 * Only on the tile's floor, and not in an instance, whose tiles are not the world's.
 */
final class GuideTileOverlay extends Overlay
{
	private static final Color FILL = new Color(0xD9, 0xB9, 0x8C, 40);
	private static final BasicStroke STROKE = new BasicStroke(2);

	private final Client client;
	private volatile WorldPoint target;

	GuideTileOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/** The tile to outline, or null for none. */
	void target(WorldPoint place)
	{
		target = place;
	}

	WorldPoint target()
	{
		return target;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldPoint place = target;
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (place == null || player == null || view == null || view.isInstance() || view.getPlane() != place.getPlane())
		{
			return null;
		}
		LocalPoint local = LocalPoint.fromWorld(view, place);
		Polygon tile = local == null ? null : Perspective.getCanvasTilePoly(client, local);
		if (tile != null)
		{
			OverlayUtil.renderPolygon(graphics, tile, GuideMinimapOverlay.COLOR, FILL, STROKE);
		}
		return null;
	}
}

