			return null;
		}
	}

	/**
	 * A label whose text may come from the site, or be built from it: always shown as text. Swing would otherwise draw
	 * a text that starts with {@code <html>} as HTML, and load any picture it names from any server.
	 */
	private static JLabel plain(JLabel label)
	{
		label.putClientProperty("html.disable", Boolean.TRUE);
		return label;
	}

	/** A tooltip for text that may come from the site: escaped inside the plugin's own HTML, so it shows as text. */
	static String tip(String text)
	{
		return text == null || text.isEmpty() ? null : "<html>" + OsrsIndexPanel.escape(text) + "</html>";
	}

	/**
	 * Wrapped text {@code width} pixels wide. Swing's HTML reads a CSS pixel as 4/3 of a screen pixel, so the width
	 * is given in CSS as three quarters of it.
	 */
	private static JLabel html(String html, Font font, Color colour, int width)
	{
		JLabel label = new JLabel("<html><body style='width: " + (width * 3 / 4) + "px'>" + html + "</body></html>");
		label.setFont(font);
		label.setForeground(colour);
		label.setVerticalAlignment(SwingConstants.TOP);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel text(String text, Font font, Color colour, int width)
	{
		return html(OsrsIndexPanel.escape(text), font, colour, width);
	}

	/** A coloured word after a name on the same line: "Anvils  no map point yet". */
	private static String status(String word, Color colour)
	{
		return "&nbsp; <font color='" + hex(colour) + "'>" + OsrsIndexPanel.escape(word) + "</font>";
	}

	private static String hex(Color colour)
	{
		return String.format(Locale.ROOT, "#%02x%02x%02x", colour.getRed(), colour.getGreen(), colour.getBlue());
	}

	/** A part's heading in a step's card, with an optional tally after it: "BRING  1 of 2 with you". */
	private static JComponent heading(String label, String tally, Color tallyColour)
	{
		JPanel out = column();
		out.add(gap(9));
		out.add(html(OsrsIndexPanel.escape(label) + (tally == null ? "" : "&nbsp; <font color='" + hex(tallyColour) + "'>"
			+ OsrsIndexPanel.escape(tally) + "</font>"), small(), FAINT, CARD_TEXT));
		out.add(gap(4));
		return fit(out);
	}

	/** A small capitalised tag on a tinted ground: "SOLO", "OPTIONAL", "FOLLOWING". */
	private static JLabel chip(String text, Color colour, Color ground)
	{
		JLabel chip = plain(new JLabel(text));
		chip.setFont(small());
		chip.setForeground(colour);
		chip.setOpaque(true);
		chip.setBackground(blend(colour, ground, 0.16));
		chip.setBorder(BorderFactory.createEmptyBorder(1, 5, 1, 5));
		return chip;
	}

	/** A requirement as a chip with its dot: green met, orange met with a boost, red not yet, grey unknown. */
	private static JLabel dotChip(String text, Color dot)
	{
		JLabel chip = plain(new JLabel(text, GuideIcons.dot(dot, 12), SwingConstants.LEFT));
		chip.setIconTextGap(4);
		chip.setFont(small());
		chip.setForeground(TEXT);
		chip.setOpaque(true);
		chip.setBackground(new Color(46, 46, 46));
		chip.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 6));
		return chip;
	}

	/** Chips laid out in rows that fit {@code width}, since a flow layout would not report its wrapped height. */
	private static JComponent chipRows(List<JLabel> chips, int width)
	{
		JPanel out = column();
		JPanel line = null;
		int used = 0;
		for (JLabel chip : chips)
		{
			int w = Math.min(chip.getPreferredSize().width, width);
			if (line == null || used + 4 + w > width)
			{
				if (line != null)
				{
					out.add(fit(line));
					out.add(gap(4));
				}
				line = new JPanel();
				line.setLayout(new BoxLayout(line, BoxLayout.X_AXIS));
				line.setOpaque(false);
				used = 0;
			}
			else
			{
				line.add(Box.createRigidArea(new Dimension(4, 0)));
				used += 4;
			}
			line.add(chip);
			used += w;
		}
		if (line != null)
		{
			out.add(fit(line));
		}
		return fit(out);
	}

	/** An icon, then a component beside it, the icon on the first line. */
	private static JComponent row(Icon icon, JComponent beside)
	{
		return beside(new JLabel(icon), beside);
	}

	private static JComponent beside(JComponent left, JComponent right)
	{
		JPanel row = new JPanel(new BorderLayout(7, 0));
		row.setOpaque(false);
		row.add(top(left), BorderLayout.WEST);
		row.add(right, BorderLayout.CENTER);
		return fit(row);
	}

	/** "1" and the text, hanging. */
	private static JComponent numbered(int number, String text)
	{
		JPanel row = new JPanel(new BorderLayout(5, 0));
		row.setOpaque(false);
		JLabel mark = new JLabel(Integer.toString(number));
		mark.setFont(regular());
		mark.setForeground(ORANGE);
		mark.setPreferredSize(new Dimension(9, mark.getPreferredSize().height));
		row.add(top(mark), BorderLayout.WEST);
		row.add(text(text, regular(), TEXT, CARD_TEXT - 14), BorderLayout.CENTER);
		return fit(row);
	}

	/** A note set off by a coloured bar: "TIP", "IRONMAN", "DONE", "GUIDE COMPLETE". */
	private static JPanel callout(String label, Color colour, String text, int width)
	{
		JPanel out = column();
		out.setOpaque(true);
		out.setBackground(CALLOUT);
		out.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 2, 0, 0, colour),
			BorderFactory.createEmptyBorder(5, 7, 6, 6)));
		JLabel heading = text(label, small(), colour, width);
		if (label.equals("IRONMAN") && IRONMAN_ICON != null)
		{
			out.add(row(new ImageIcon(IRONMAN_ICON), text(label, small(), colour, width - 20)));
		}
		else
		{
			out.add(heading);
		}
		out.add(gap(2));
		out.add(text(text, regular(), TEXT, width));
		return (JPanel) fit(out);
	}

	private static Color blend(Color top, Color ground, double amount)
	{
		return new Color(
			(int) Math.round(ground.getRed() + (top.getRed() - ground.getRed()) * amount),
			(int) Math.round(ground.getGreen() + (top.getGreen() - ground.getGreen()) * amount),
			(int) Math.round(ground.getBlue() + (top.getBlue() - ground.getBlue()) * amount));
	}

	/** A panel that reacts to the mouse as a button does: it lights on hover and acts on a left click. */
	private static JPanel clickable(Color ground, Color hover, Runnable action)
	{
		JPanel panel = new JPanel();
		panel.setOpaque(true);
		panel.setBackground(ground);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		panel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				panel.setBackground(hover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				panel.setBackground(ground);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && panel.contains(e.getPoint()))
				{
					action.run();
				}
			}
		});
		return panel;
	}

	/** A small text link: {@code colour}, lit to {@code hover} under the mouse. */
	private static JComponent link(String text, Color colour, Color hover, Runnable action)
	{
		JLabel label = plain(new JLabel(text));
		label.setFont(small());
		label.setForeground(colour);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setForeground(hover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setForeground(colour);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && label.contains(e.getPoint()))
				{
					action.run();
				}
			}
		});
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JButton button(String text, Runnable action)
	{
		JButton button = new JButton(text);
		button.putClientProperty("html.disable", Boolean.TRUE);
		button.addActionListener(e -> action.run());
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		// Narrow margins, so two buttons side by side in a card keep their whole labels.
		button.setMargin(new Insets(2, 4, 2, 4));
		button.setFocusPainted(false);
		return button;
	}

	private static JPanel column()
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/** Holds a component at the top of a border layout's side, so it lines up with the first line of text. */
	private static JComponent top(JComponent component)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.add(component, BorderLayout.NORTH);
		return holder;
	}

	/** Left-aligned, as wide as the column, and no taller than it wants to be. */
	private static JComponent fit(JComponent component)
	{
		return fit(component, component.getPreferredSize().height);
	}

	private static JComponent fit(JComponent component, int height)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return component;
	}

	private static Component gap(int height)
	{
		JComponent gap = (JComponent) Box.createRigidArea(new Dimension(0, height));
		gap.setAlignmentX(Component.LEFT_ALIGNMENT);
		return gap;
	}
}

package com.osrsindex;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Boss and activity counts, gathered from the game's own chat lines. No var holds them. Kept in the
 * RuneLite profile so they accumulate across sessions.
 */
final class KillCountTracker
{
	static final int MAX_ENTRIES = 500;
	static final int MAX_NAME_LENGTH = 60;
	static final int MAX_COUNT = 10_000_000;

	/**
	 * "Your Vorkath kill count is: 123.", "Your completed Theatre of Blood count is: 5.",
	 * "Your Barrows chest count is: 50.", "Your Gauntlet completion count is: 10.",
	 * "Your subdued Wintertodt count is: 7.", "Your Canifis Rooftop lap count is: 40."
	 */
	private static final Pattern COUNT = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?) (?:kill |chest |completion |harvest |lap |success |reward |rift search )?count is: ([\\d,]+)\\.?$");

	private final Map<String, Integer> counts = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);

	/** Record a count from a chat line with its tags already removed. Returns true when a count changed. */
	boolean offer(String message)
	{
		if (message == null)
		{
			return false;
		}
		Matcher matcher = COUNT.matcher(message.replace(' ', ' ').trim());
		if (!matcher.matches())
		{
			return false;
		}
		String name = matcher.group(1).trim();
		int count;
		try
		{
			count = Integer.parseInt(matcher.group(2).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return false;
		}
		return record(name, count);
	}

	boolean record(String name, int count)
	{
		if (name.isEmpty() || name.length() > MAX_NAME_LENGTH || count < 0 || count > MAX_COUNT)
		{
			return false;
		}
		Integer previous = counts.get(name);
		if (previous != null && previous == count)
		{
			return false;
		}
		if (previous == null && counts.size() >= MAX_ENTRIES)
		{
			return false;
		}
		counts.put(name, count);
		return true;
	}

	int size()
	{
		return counts.size();
	}

	Integer get(String name)
	{
		return counts.get(name);
	}

	void clear()
	{
		counts.clear();
	}

	JsonObject toJson()
	{
		JsonObject out = new JsonObject();
		counts.forEach(out::addProperty);
		return out;
	}

	void load(String saved)
	{
		counts.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		try
		{
			JsonElement parsed = new JsonParser().parse(saved);
			if (!parsed.isJsonObject())
			{
				return;
			}
			for (Map.Entry<String, JsonElement> entry : parsed.getAsJsonObject().entrySet())
			{
				try
				{
					record(entry.getKey(), entry.getValue().getAsInt());
				}
				catch (RuntimeException ignored)
				{
					// Skip a malformed entry.
				}
			}
		}
		catch (RuntimeException ignored)
		{
			// A malformed profile value loads as empty.
		}
	}
}

package com.osrsindex;

import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/**
 * Opens the destinations socket with OkHttp, as the contract asks: the relay's URL, the link token as a
 * bearer, the {@code osrsindex.destinations.v1} subprotocol, and a WebSocket ping every 30 s. The plugin
 * passes its {@link SiteHttp} client, and {@code newBuilder()} keeps its interceptor, so the upgrade request
 * names the plugin's version too.
 */
final class OkHttpConnector implements DestinationSocket.Connector
{
	/** The longest relay frame read, in characters. */
	static final int MAX_FRAME_CHARS = 16_384;
	/** WebSocket close code 1009: a message too big to process. */
	static final int CLOSE_TOO_BIG = 1009;
	static final long MAX_RETRY_AFTER_SECONDS = 3_600;

	static final long PING_SECONDS = 30;

	private final OkHttpClient client;
	private final Supplier<String> url;

	OkHttpConnector(OkHttpClient base, Supplier<String> url)
	{
		this.client = base.newBuilder().pingInterval(PING_SECONDS, TimeUnit.SECONDS).build();
		this.url = url;
	}

	@Override
	public DestinationSocket.Connection open(String token, DestinationSocket.Events events)
	{
		Request request = new Request.Builder()
			.url(url.get())
			.header("Authorization", "Bearer " + token)
			.header("Sec-WebSocket-Protocol", DestinationSocket.SUBPROTOCOL)
			.build();
		OkHttpConnection connection = new OkHttpConnection();
		connection.socket = client.newWebSocket(request, new WebSocketListener()
		{
			@Override
			public void onOpen(WebSocket webSocket, Response response)
			{
				events.opened(connection, response.header("Sec-WebSocket-Protocol"));
			}

			@Override
			public void onMessage(WebSocket webSocket, String text)
			{
				// A frame is a few hundred bytes. A far larger one is not a frame this plugin reads: drop the socket,
				// which reconnects as after any drop.
				if (text.length() > MAX_FRAME_CHARS)
				{
					webSocket.close(CLOSE_TOO_BIG, null);
					return;
				}
				events.text(connection, text);
			}

			@Override
			public void onClosing(WebSocket webSocket, int code, String reason)
			{
				// Answer the server's close, so onClosed follows with its code.
				webSocket.close(DestinationSocket.CLOSE_NORMAL, null);
			}

			@Override
			public void onClosed(WebSocket webSocket, int code, String reason)
			{
				events.closed(connection, code);
			}

			@Override
			public void onFailure(WebSocket webSocket, Throwable failure, Response response)
			{
				events.failed(connection, response == null ? 0 : response.code(), retryAfterSeconds(response));
			}
		});
		return connection;
	}

	/** A numeric {@code Retry-After}, or -1. */
	static long retryAfterSeconds(Response response)
	{
		String header = response == null ? null : response.header("Retry-After");
		if (header == null)
		{
			return -1;
		}
		try
		{
			// At most an hour, as for a sync: a wait of years would leave Walk here off until the next login.
			return Math.min(MAX_RETRY_AFTER_SECONDS, Math.max(0, Long.parseLong(header.trim())));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private static final class OkHttpConnection implements DestinationSocket.Connection
	{
		private volatile WebSocket socket;

		@Override
		public boolean send(String text)
		{
			WebSocket current = socket;
			return current != null && current.send(text);
		}

		@Override
		public void close(int code, String reason)
		{
			WebSocket current = socket;
			if (current != null)
			{
				current.close(code, reason);
			}
		}
	}
}

