	/** Back from approving in the browser: collect the token now rather than at the next 15 s poll. */
	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		if (event.isFocused() && linker != null)
		{
			linker.pollSoon();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_LOG_DRAW_ITEM_SCRIPT || event.getScriptEvent() == null
			|| !viewingOwnCollectionLog())
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		recordCollectionLogItem((Integer) args[1], (Integer) args[2]);
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (ticksSinceLogin < 0 || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticksSinceLogin++;
		if (ticksSinceLogin < LOGIN_SETTLE_TICKS)
		{
			return;
		}
		if (ticksSinceLogin == LOGIN_SETTLE_TICKS)
		{
			onOwnWorld = ownWorld();
			if (onOwnWorld)
			{
				loadProfile();
				markAllDirty();
			}
			panelCharacter = reader.characterName();
			refreshPanel();
			guideTracker.loggedIn();
		}
		else
		{
			checkWorldKind();
		}

		guideTracker.tick();
		readGuideSigns();
		maybeOfferLink();
		linker.tick();
		siteConfigFetcher.tick(token());
		readOpenCollectionLogPage();
		tickCount++;
		SiteConfig site = siteConfig;
		if (tickCount % site.timing.pollTicks == 0)
		{
			pollForChanges();
		}
		if (tickCount % site.timing.pollVarsTicks == 0)
		{
			poll(Part.VARS, reader.vars(sendSchema(), site.vars));
		}
		if (profileUnsaved && tickCount % 100 == 0)
		{
			saveProfile();
		}
		maybeSend();
	}

	/** What the guide's current step may be waiting for: who the player is talking to, and where they stand. */
	private void readGuideSigns()
	{
		Widget name = client.getWidget(InterfaceID.ChatLeft.NAME);
		String talking = name == null || name.isHidden() ? null : Text.removeTags(name.getText());
		if (talking != null && !talking.equals(lastDialogueName))
		{
			guideTracker.npcTalkedTo(talking);
		}
		lastDialogueName = talking;
		Player player = client.getLocalPlayer();
		if (player != null)
		{
			WorldPoint at = player.getWorldLocation();
			guideTracker.playerAt(at.getX(), at.getY(), at.getPlane());
		}
	}

	/** Something died: the guide hears of it when it was fighting the player, for a step to kill it. */
	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		Player player = client.getLocalPlayer();
		if (actor instanceof NPC && player != null && (player.getInteracting() == actor || actor.getInteracting() == player))
		{
			guideTracker.npcKilled(actor.getName());
		}
	}

	/** RuneLite's tradeable items by lower-case name, built once from its item prices, for {@link #itemIdByName}. */
	private Map<String, Integer> itemIdsByName = Collections.emptyMap();

	/**
	 * A tradeable item's id by its exact name, from RuneLite's item prices, or -1: for guide items with no id. One
	 * lookup in a map built once, not a search of every price per item: a guide can name thousands of items.
	 */
	private int itemIdByName(String name)
	{
		if (itemIdsByName.isEmpty())
		{
			Map<String, Integer> byName = new HashMap<>();
			for (ItemPrice price : itemManager.search(""))
			{
				byName.putIfAbsent(price.getName().toLowerCase(Locale.ROOT), price.getId());
			}
			itemIdsByName = byName;
		}
		Integer id = itemIdsByName.get(name.toLowerCase(Locale.ROOT));
		return id == null ? -1 : id;
	}

	// --- change tracking ---------------------------------------------------

	private void markDirty(Part part)
	{
		dirty.put(part, ++stamp);
	}

	private void markAllDirty()
	{
		lastSeen.clear();
		for (Part part : Part.values())
		{
			if (part != Part.BANK || capturedBank != null)
			{
				markDirty(part);
			}
		}
	}

	/** Mark a polled part dirty when its value moved since it was last seen. */
	private void pollForChanges()
	{
		poll(Part.LOCATION, reader.location());
		poll(Part.ACCOUNT, reader.account());
		poll(Part.DIARIES, reader.diaries());
		poll(Part.COMBAT_ACHIEVEMENTS, reader.combatAchievements());
		// The log's counters are not read while another player's log is open, in case they show theirs.
		if (!viewingAnotherCollectionLog())
		{
			poll(Part.COLLECTION_LOG, reader.collectionLog(collectionLog));
		}
	}

	/** True while a collection log is open that is not known to be the player's own. */
	private boolean viewingAnotherCollectionLog()
	{
		Widget frame = client.getWidget(InterfaceID.Collection.FRAME);
		return frame != null && !frame.isHidden() && !viewingOwnCollectionLog();
	}

	private void poll(Part part, JsonElement value)
	{
		if (value != null && !value.equals(lastSeen.get(part)))
		{
			lastSeen.put(part, value);
			markDirty(part);
		}
	}

	/** The player has the part on, and the site has not paused it: the site can only ever pause more. */
	private boolean enabled(Part part)
	{
		return siteConfig.allows(part) && playerEnabled(part);
	}

	private boolean playerEnabled(Part part)
	{
		switch (part)
		{
			case EQUIPMENT:
			case INVENTORY:
				return config.syncGear();
			case BANK:
			case STORAGE:
			case GRAND_EXCHANGE:
				return config.syncBank();
			case ACCOUNT:
			case SKILLS:
			case QUESTS:
			case DIARIES:
			case COMBAT_ACHIEVEMENTS:
			case KILL_COUNTS:
			case VARS:
				return config.syncProgress();
			case COLLECTION_LOG:
				return config.syncCollectionLog();
			case LOCATION:
				return config.syncLocation();
			default:
				return false;
		}
	}

	private JsonElement read(Part part, int sendSchema)
	{
		switch (part)
		{
			case EQUIPMENT:
				return reader.equipment();
			case INVENTORY:
				return reader.inventory();
			case BANK:
				return capturedBank;
			case ACCOUNT:
				return reader.account();
			case SKILLS:
				return reader.skills();
			case QUESTS:
				return reader.quests();
			case DIARIES:
				return reader.diaries();
			case COMBAT_ACHIEVEMENTS:
				return reader.combatAchievements();
			case COLLECTION_LOG:
				return viewingAnotherCollectionLog() ? null : reader.collectionLog(collectionLog);
			case LOCATION:
				return reader.location();
			case VARS:
				return reader.vars(sendSchema, siteConfig.vars);
			case STORAGE:
				return storage.size() == 0 ? null : storage.toJson();
			case KILL_COUNTS:
				return killCounts.size() == 0 ? null : killCounts.toJson();
			case GRAND_EXCHANGE:
				return reader.grandExchange();
			default:
				return null;
		}
	}

	// --- collection log ----------------------------------------------------

	private void recordCollectionLogItem(int id, int quantity)
	{
		if (profileLoaded && collectionLog.record(id, quantity))
		{
			profileUnsaved = true;
			markDirty(Part.COLLECTION_LOG);
		}
	}

	/** Read the items of the log page on screen: an obtained item is drawn fully opaque. */
	private void readOpenCollectionLogPage()
	{
		if (!viewingOwnCollectionLog())
		{
			return;
		}
		Widget items = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (items == null || items.isHidden() || items.getDynamicChildren() == null)
		{
			return;
		}
		for (Widget item : items.getDynamicChildren())
		{
			if (item != null && item.getItemId() > 0 && item.getOpacity() == 0)
			{
				recordCollectionLogItem(item.getItemId(), Math.max(1, item.getItemQuantity()));
			}
		}
	}

	/**
	 * True while the player's own collection log is open. The POH Adventure Log shows another player's
	 * log in the same interface, with that player's name in the header, and those items are not ours.
	 * When the header or the player's name cannot be read, the log is not taken as ours: an item missed
	 * is read again on the next visit, but another player's item would be kept and sent as the player's.
	 */
	private boolean viewingOwnCollectionLog()
	{
		Widget frame = client.getWidget(InterfaceID.Collection.FRAME);
		if (frame == null || frame.isHidden() || !onOwnWorld)
		{
			return false;
		}
		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		String name = reader.characterName();
		if (header == null || name == null)
		{
			return false;
		}
		String title = Text.removeTags(header.getText() == null ? "" : header.getText()).replace(' ', ' ');
		int dash = title.indexOf(" - ");
		return dash < 0 || title.substring(dash + 3).trim().equalsIgnoreCase(name.replace(' ', ' '));
	}

	// --- profile persistence -----------------------------------------------

	/** Whether this world keeps the account's own progress: a standard profile, and none of {@link #SEPARATE_WORLDS}. */
	private boolean ownWorld()
	{
		return RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD
			&& Collections.disjoint(client.getWorldType(), SEPARATE_WORLDS);
	}

	/**
	 * A hop to or from a world that keeps other progress. Leaving the account's own world drops everything queued and
	 * stops keeping data; coming back reads the account's own profile again and resends everything. The profile was
	 * saved when the hop began, under the world being left.
	 */
	private void checkWorldKind()
	{
		boolean own = ownWorld();
		if (own == onOwnWorld)
		{
			return;
		}
		onOwnWorld = own;
		if (own)
		{
			loadProfile();
			markAllDirty();
		}
		else
		{
			dirty.clear();
			capturedBank = null;
			profileLoaded = false;
			profileUnsaved = false;
		}
	}

	private void loadProfile()
	{
		if (!profileLoaded)
		{
			collectionLog.load(configManager.getRSProfileConfiguration(OsrsIndexConfig.GROUP, CLOG_ITEMS_KEY));
			killCounts.load(configManager.getRSProfileConfiguration(OsrsIndexConfig.GROUP, KILL_COUNTS_KEY));
			storage.load(configManager.getRSProfileConfiguration(OsrsIndexConfig.GROUP, STORAGE_KEY));
			partTimes.load(configManager.getRSProfileConfiguration(OsrsIndexConfig.GROUP, PART_TIMES_KEY));
			profileLoaded = true;
		}
	}

	private void saveProfile()
	{
		if (profileLoaded && profileUnsaved)
		{
			configManager.setRSProfileConfiguration(OsrsIndexConfig.GROUP, CLOG_ITEMS_KEY, gson.toJson(collectionLog.toJson()));
			configManager.setRSProfileConfiguration(OsrsIndexConfig.GROUP, KILL_COUNTS_KEY, gson.toJson(killCounts.toJson()));
			configManager.setRSProfileConfiguration(OsrsIndexConfig.GROUP, STORAGE_KEY, gson.toJson(storage.toJson()));
			configManager.setRSProfileConfiguration(OsrsIndexConfig.GROUP, PART_TIMES_KEY, gson.toJson(partTimes.toJson()));
			profileUnsaved = false;
		}
	}

	// --- sending -----------------------------------------------------------

	private void maybeSend()
	{
		String token = token();
		if (inFlight || dirty.isEmpty() || token.isEmpty() || token.equals(rejectedToken) || !onOwnWorld
			|| System.currentTimeMillis() < nextSendAtMillis)
		{
			return;
		}
		if (!Tokens.wellFormed(token))
		{
			// Never sent: OkHttp would refuse it as a header, and log the whole value in the refusal.
			rejectedToken = token;
			chat("That token does not look like one from osrsindex.com/account (it should start with "
				+ TOKEN_PREFIX + ").");
			return;
		}
		String character = reader.characterName();
		if (character == null || siteConfigFetcher.awaitingFirstAnswer() || siteConfig != siteConfigFetcher.current())
		{
			// The first sync waits briefly for the site's config, so a part it paused does not go out first. A config
			// that has come but is not applied yet is applied on this thread before the next tick.
			return;
		}

		int sendSchema = sendSchema();
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		Map<Part, Long> stamps = new EnumMap<>(Part.class);
		for (Map.Entry<Part, Long> entry : dirty.entrySet())
		{
			Part part = entry.getKey();
			if (!enabled(part) || part.minSchema > sendSchema)
			{
				continue;
			}
			JsonElement value = read(part, sendSchema);
			if (value != null)
			{
				pending.put(part, value);
				stamps.put(part, entry.getValue());
			}
		}
		String capturedAt = Instant.now().truncatedTo(ChronoUnit.SECONDS).toString();
		Map<Part, Instant> times = sendPartTimes ? partTimes.asMap() : Collections.<Part, Instant>emptyMap();
		PayloadPacker.Packed packed = PayloadPacker.pack(gson, sendSchema, character, capturedAt, pending, times,
			budgetBytes);
		if (packed == null)
		{
			return;
		}

		inFlight = true;
		post(token, packed, stamps, sendSchema);
	}

	/** The schema to send: the highest the site has not refused, and no higher than its config allows. */
	private int sendSchema()
	{
		return Math.min(schema, siteConfig.maxSchema);
	}

	/** One sync: the body to the sync endpoint, with the token as a bearer. {@link #siteHttp} adds the version. */
	static Request syncRequest(String token, String json)
	{
		return new Request.Builder()
			.url(Endpoints.sync())
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, json))
			.build();
	}

	private void post(String token, PayloadPacker.Packed packed, Map<Part, Long> stamps, int sentSchema)
	{
		Request request = syncRequest(token, packed.json);
		SiteConfig.Timing timing = siteConfig.timing;
		siteHttp.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("OSRS Index sync failed to send", e);
				clientThread.invoke(() -> settle(SyncOutcome.networkFailure(timing), token, packed.parts, stamps,
					sentSchema));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				SyncOutcome outcome;
				try (ResponseBody body = response.body())
				{
					// A sync answer is a few hundred bytes: a larger one is not read, and its status decides.
					String text = body == null ? "" : SiteHttp.bounded(body, 65_536);
					outcome = SyncOutcome.of(response.code(), text == null ? "" : text, response.header("Retry-After"), timing);
				}
				catch (IOException e)
				{
					outcome = SyncOutcome.networkFailure(timing);
				}
				SyncOutcome settled = outcome;
				clientThread.invoke(() -> settle(settled, token, packed.parts, stamps, sentSchema));
			}
		});
	}

	/** Apply a response on the client thread. */
	private void settle(SyncOutcome outcome, String token, Set<Part> parts, Map<Part, Long> stamps, int sentSchema)
	{
		inFlight = false;
		long now = System.currentTimeMillis();
		switch (outcome.kind)
		{
			case STORED:
				for (Part part : parts)
				{
					dirty.remove(part, stamps.get(part));
				}
				nextSendAtMillis = now + outcome.waitSeconds * 1_000L;
				if (!announcedFirstSync)
				{
					announcedFirstSync = true;
					chat("Synced to your osrsindex.com account.");
				}
				lastWaitMessage = null;
				lastSync = syncSummary(LocalTime.now(), parts);
				refreshPanel();
				if (outcome.configVersion >= 0)
				{
					siteConfigFetcher.changed(outcome.configVersion);
				}
				break;
			case OLD_SERVER:
				// Step down one schema at a time: a site on schema 2 still takes every schema 2 section.
				if (sentSchema > 1)
				{
					// The config may have capped what was sent below schema: step down from what was sent.
					if (schema >= sentSchema)
					{
						schema = sentSchema - 1;
						log.info("OSRS Index: the site does not accept schema {} yet; trying {}", sentSchema, schema);
					}
					break;
				}
				// Schema 1 has nowhere lower to go: this is a real contract break.
				// fall through
			case PART_TIMES_REFUSED:
				if (outcome.kind == SyncOutcome.Kind.PART_TIMES_REFUSED && sendPartTimes)
				{
					// The site refused the times, not the parts: they stay dirty and go out again at once, undated,
					// for the rest of the session. A refusal does not start the site's floor.
					sendPartTimes = false;
					log.warn("OSRS Index: the site refused the part times in a sync of {}; sending without them", parts);
					break;
				}
				// The body already carried no times, so the refusal is about something else.
				// fall through
			case REJECTED:
				// When the site names the part it refused, only that part waits for its next change. The
				// others stay dirty and go out after the floor: a part that keeps changing and keeps being
				// refused, such as the location, would otherwise be posted every few seconds.
				Set<Part> dropped = outcome.dropped(parts);
				for (Part part : dropped)
				{
					dirty.remove(part, stamps.get(part));
				}
				nextSendAtMillis = now + siteConfig.timing.syncFloorSeconds * 1_000L;
				String refusal = SyncOutcome.plainCode(outcome.code);
				log.warn("OSRS Index refused a sync of {}: {}; dropped {}", parts, refusal, dropped);
				// Once per refusal a session, so a refusal that repeats does not fill the chat.
				if (chattedRefusals.add(refusal))
				{
					chat(outcome.playerMessage != null ? RouteDispatcher.chatSafe(outcome.playerMessage)
						: "The site refused part of a sync (" + refusal + "). It will try again when that data changes.");
				}
				break;
			case BAD_TOKEN:
				if (!token.equals(token()))
				{
					// The player unlinked while this sync was out, and Unlink revoked the token it carried; or
					// they have linked again since. Either way the refusal is not about the current link.
					break;
				}
				rejectedToken = token;
				chat(outcome.playerMessage != null ? RouteDispatcher.chatSafe(outcome.playerMessage)
					: "osrsindex.com did not accept this client's link. Open the OSRS Index panel to link it again.");
				configManager.unsetConfiguration(OsrsIndexConfig.GROUP, "token");
				linkOfferedThisSession = false;
				break;
			case TOO_LARGE:
				nextSendAtMillis = now + outcome.waitSeconds * 1_000L;
				Part tooLarge = PayloadPacker.tooLargeAlone(parts);
				if (tooLarge == null)
				{
					budgetBytes = PayloadPacker.halved(budgetBytes);
					if (outcome.playerMessage != null)
					{
						lastSync = siteWait(outcome.playerMessage);
						refreshPanel();
					}
					break;
				}
				// A smaller budget cannot help a lone part: drop it as a refused part is, until it changes.
				dirty.remove(tooLarge, stamps.get(tooLarge));
				if (warnedTooLarge.add(tooLarge))
				{
					log.warn("OSRS Index: the site refused {} as too large; it is sent again when it changes",
						tooLarge.key);
				}
				lastSync = outcome.playerMessage != null ? siteWait(outcome.playerMessage) : tooLargeLine(LocalTime.now(),
					tooLarge);
				refreshPanel();
				break;
			case ACCOUNT_FULL:
				// Nothing was stored. Keep the changes, and ask again rarely: the player may free a slot.
				nextSendAtMillis = now + outcome.waitSeconds * 1_000L;
				if (!announcedAccountFull)
				{
					announcedAccountFull = true;
					chat(outcome.playerMessage != null ? RouteDispatcher.chatSafe(outcome.playerMessage)
						: "Your osrsindex.com account already tracks the most characters it can, so this one was not"
						+ " synced. Delete tracker data at osrsindex.com/account to make room.");
				}
				lastSync = outcome.playerMessage != null ? OsrsIndexPanel.escape(outcome.playerMessage) : ACCOUNT_FULL_LINE;
				refreshPanel();
				break;
			case RETRY:
			default:
				nextSendAtMillis = now + outcome.waitSeconds * 1_000L;
				if (outcome.playerMessage != null)
				{
					lastSync = siteWait(outcome.playerMessage);
					refreshPanel();
				}
				break;
		}
	}

	/**
	 * The panel's line for a wait the site explained, "Not synced at 14:02: <its message>", escaped for the panel.
	 * Chat gets the message too, once for each different one, so a maintenance notice is seen but not repeated.
	 */
	private String siteWait(String message)
	{
		if (!message.equals(lastWaitMessage))
		{
			lastWaitMessage = message;
			chat(RouteDispatcher.chatSafe(message));
		}
		return OsrsIndexPanel.escape(waitLine(LocalTime.now(), message));
	}

	/** "Not synced at 14:02: " and the site's message about why. */
	static String waitLine(LocalTime at, String message)
	{
		return "Not synced at " + at.format(DateTimeFormatter.ofPattern("HH:mm")) + ": " + message;
	}

	// --- site config -------------------------------------------------------

	/** Use what the site asks of this client now. On the client thread. */
	private void applySiteConfig(SiteConfig next)
	{
		SiteConfigFetcher fetcher = siteConfigFetcher;
		if (fetcher == null || next != fetcher.current())
		{
			// Overtaken by a later answer, or from a fetcher before the plugin restarted: that one applies instead.
			return;
		}
		SiteConfig previous = siteConfig;
		siteConfig = next;
		if (next.timing.budgetBytes != previous.timing.budgetBytes)
		{
			budgetBytes = next.timing.budgetBytes;
		}
		// A part the site un-paused sends its current state, as one the player switches back on does.
		for (Part part : previous.paused)
		{
			if (!next.paused.contains(part) && (part != Part.BANK || capturedBank != null))
			{
				markDirty(part);
			}
		}
		if (!next.vars.sameAs(previous.vars))
		{
			lastSeen.remove(Part.VARS);
			markDirty(Part.VARS);
		}
		DestinationSocket socket = destinationSocket;
		if (socket != null)
		{
			socket.retryWaits(next.timing.relayRetryMillis, next.timing.relayRetryMaxMillis);
			if (next.destinations != previous.destinations)
			{
				updateDestinations(false);
				showDestinationStatus(socket.status());
			}
		}
		if (panel != null)
		{
			panel.showNotice(next.notice);
		}
		if (next.notice != null && next.notice.chat && chattedNotices.add(next.notice.id))
		{
			chat(RouteDispatcher.chatSafe(next.notice.text));
		}
	}

	private void resetSession()
	{
		dirty.clear();
		lastSeen.clear();
		capturedBank = null;
		collectionLog.clear();
		killCounts.clear();
		storage.clear();
		partTimes.clear();
		profileLoaded = false;
		profileUnsaved = false;
		ticksSinceLogin = -1;
		schema = Part.LATEST_SCHEMA;
		budgetBytes = siteConfig.timing.budgetBytes;
		sendPartTimes = true;
		lastWaitMessage = null;
		reader.forgetUnreadableVars();
		warnedTooLarge.clear();
		chattedRefusals.clear();
		announcedFirstSync = false;
		announcedAccountFull = false;
		linkOfferedThisSession = false;
	}

	/** The panel's line while the account has no room for this character. */
	static final String ACCOUNT_FULL_LINE = "Not synced: your account already tracks the most characters it can.";

	/** The panel's last-sync line: "Last sync at 14:02: location, skills and bank." in the contract's order. */
	static String syncSummary(LocalTime at, Set<Part> parts)
	{
		List<String> names = new ArrayList<>();
		for (Part part : Part.values())
		{
			if (parts.contains(part))
			{
				names.add(part.key.replace('_', ' '));
			}
		}
		String when = "Last sync at " + at.format(DateTimeFormatter.ofPattern("HH:mm"));
		if (names.isEmpty())
		{
			return when + ".";
		}
		String last = names.remove(names.size() - 1);
		return when + ": " + (names.isEmpty() ? last : String.join(", ", names) + " and " + last) + ".";
	}

	/**
	 * The panel's line after the site refused a lone part as too large:
	 * "Not synced at 14:02: vars was too large for the site. It is sent again when it changes."
	 */
	static String tooLargeLine(LocalTime at, Part part)
	{
		return "Not synced at " + at.format(DateTimeFormatter.ofPattern("HH:mm")) + ": " + part.key.replace('_', ' ')
			+ " was too large for the site. It is sent again when it changes.";
	}

	private void chat(String message)
	{
		gameMessage("OSRS Index: " + message);
	}

	/** A line in game chat, as given. A destination's line names osrsindex.com itself. */
	private void gameMessage(String message)
	{
		clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
	}

	// --- destinations ------------------------------------------------------

	private void updateDestinations(boolean fresh)
	{
		DestinationSocket socket = destinationSocket;
		if (socket != null)
		{
			socket.update(config.receiveDestinations() && siteConfig.destinations, token(), loggedIn, fresh);
		}
	}

	private DestinationSocket.Cancellable schedule(Runnable task, long delayMillis)
	{
		ScheduledFuture<?> future = executor.schedule(task, delayMillis, TimeUnit.MILLISECONDS);
		return () -> future.cancel(false);
	}

	private void showDestinationStatus(DestinationSocket.Status status)
	{
		if (panel != null)
		{
			panel.showDestinations(destinationStatusText(status, config.receiveDestinations(), !token().isEmpty(),
				loggedIn, !siteConfig.destinations));
		}
	}

	/** The panel's status line for the destinations socket. {@code sitePaused}: the site config turned it off. */
	static String destinationStatusText(DestinationSocket.Status status, boolean optedIn, boolean linked,
		boolean loggedIn, boolean sitePaused)
	{
		switch (status)
		{
			case LISTENING:
				return "Listening for osrsindex.com destinations.";
			case CONNECTING:
				return "Not listening yet: connecting to osrsindex.com...";
			case RETRYING:
				return "Not listening: the connection dropped. Reconnecting shortly.";
			case REVOKED:
				return "Not listening: osrsindex.com revoked this link. Link again to receive places.";
			case REPLACED:
				return "Not listening: another RuneLite client with this link is listening instead.";
			case OFF:
			default:
				if (!optedIn)
				{
					return "Not listening: \"Receive destinations\" is off in this plugin's settings.";
				}
				if (!linked)
				{
					return "Not listening: link this client first.";
				}
				if (sitePaused)
				{
					return "Not listening: osrsindex.com has paused destinations for now.";
				}
				return loggedIn ? "Not listening." : "Not listening: log in to the game first.";
		}
	}

	/** The compass rose from osrsindex.com's favicon, drawn by hand at 16 px. */
	private static BufferedImage icon()
	{
		return ImageUtil.loadImageResource(OsrsIndexPlugin.class, "sidebar.png");
	}
}

package com.osrsindex;

/**
 * One container or section of the sync body. The declaration order is the packing priority: when a body would exceed the size
 * budget, the later parts wait for the next sync.
 */
enum Part
{
	LOCATION("location", 2),
	ACCOUNT("account", 2),
	EQUIPMENT("equipment", 1),
	INVENTORY("inventory", 1),
	SKILLS("skills", 2),
	DIARIES("diaries", 2),
	COMBAT_ACHIEVEMENTS("combat_achievements", 2),
	QUESTS("quests", 2),
	GRAND_EXCHANGE("grand_exchange", 3),
	KILL_COUNTS("kill_counts", 3),
	STORAGE("storage", 3),
	BANK("bank", 1),
	COLLECTION_LOG("collection_log", 2),
	VARS("vars", 3);

	/** The newest schema this plugin speaks. */
	static final int LATEST_SCHEMA = 5;

	/**
	 * The first schema whose body may give a part read before the send its own time, in {@code captured}. An older
	 * site refuses the schema, the plugin steps down, and that site dates every part at {@code captured_at}.
	 */
	static final int PART_TIMES_SCHEMA = 5;

	/** The body key. */
	final String key;

	/** The lowest schema number that carries this part. */
	final int minSchema;

	Part(String key, int minSchema)
	{
		this.key = key;
		this.minSchema = minSchema;
	}
}

package com.osrsindex;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/**
 * When each part that is held between sends was read, so the site can date it by that time rather than by the
 * send. The bank counts from when it was last read while open. Item stores and kill counts are built from several
 * reads, and count from when they last changed. Every other part is read when the body is built, so it needs no time.
 */
final class PartTimes
{
	/**
	 * The parts kept in the RuneLite profile between sessions. Their times are kept there too, because a time lost
	 * on a restart would leave them dated by their next send, which is the mistake this class exists to avoid.
	 */
	static final Set<Part> SAVED = Collections.unmodifiableSet(EnumSet.of(Part.STORAGE, Part.KILL_COUNTS));

	private final Map<Part, Instant> times = new EnumMap<>(Part.class);

	/** The part was read, or changed, at this moment. Kept to the second, as the body sends it. */
	void mark(Part part, Instant at)
	{
		times.put(part, at.truncatedTo(ChronoUnit.SECONDS));
	}

	/** The time of each part marked so far. */
	Map<Part, Instant> asMap()
	{
		return Collections.unmodifiableMap(times);
	}

	void clear()
	{
		times.clear();
	}

	/** The {@link #SAVED} parts' times, for the profile: {@code {"storage": "2026-10-07T14:02:11Z"}}. */
	JsonObject toJson()
	{
		JsonObject out = new JsonObject();
		for (Part part : SAVED)
		{
			Instant time = times.get(part);
			if (time != null)
			{
				out.addProperty(part.key, time.toString());
			}
		}
		return out;
	}

	/**
	 * Replace the {@link #SAVED} parts' times with the profile's. The bank's time is left alone, since the bank can
	 * be read before the profile loads. A profile saved before the plugin kept times has none, and its stores and
	 * kill counts go out undated until they next change.
	 */
	void load(String saved)
	{
		for (Part part : SAVED)
		{
			times.remove(part);
		}
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		try
		{
			JsonElement parsed = new JsonParser().parse(saved);
			if (!parsed.isJsonObject())
			{
				return;
			}
			JsonObject object = parsed.getAsJsonObject();
			for (Part part : SAVED)
			{
				JsonElement value = object.get(part.key);
				if (value != null && value.isJsonPrimitive())
				{
					try
					{
						Instant at = Instant.parse(value.getAsString());
						// A time after now is from a damaged profile or a wrong clock: as good as none.
						if (!at.isAfter(Instant.now()))
						{
							mark(part, at);
						}
					}
					catch (DateTimeParseException ignored)
					{
						// A malformed time is as good as none.
					}
				}
			}
		}
		catch (RuntimeException ignored)
		{
			// A malformed profile value loads as empty.
		}
	}
}

package com.osrsindex;

/**
 * A pathing plugin a site destination can be handed to, over RuneLite's {@code PluginMessage} bus. Hub
 * plugins load in separate class loaders and cannot call one another, so a message is the only way in.
 *
 * <p>Shortest Path answers {@code <namespace>/path} with {@code data.target} a {@code WorldPoint}, and starts
 * from the player's tile when {@code data.start} is absent. Farm Route Planner took its own namespace in its
 * ADR-038, so a message to Shortest Path does not also reach it.
 */
enum PathingPlugin
{
	SHORTEST_PATH("shortestpath", "Shortest Path");

	/** The {@code PluginMessage} namespace the plugin listens on. */
	final String namespace;
	/** Its {@code @PluginDescriptor} name: what {@code Plugin.getName()} returns, and what the player sees. */
	final String displayName;

	PathingPlugin(String namespace, String displayName)
	{
		this.namespace = namespace;
		this.displayName = displayName;
	}
}

package com.osrsindex;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/**
 * Builds one sync body from the parts waiting to be sent. The server refuses a body over 131,072
 * bytes whole, and an absent part is left as it was, so a part that does not fit simply waits for
 * the next sync. A single part larger than the budget is still sent alone, because waiting would
 * never make it smaller. If the server refuses that lone part as too large, it is dropped until it
 * changes (see {@link #tooLargeAlone}).
 */
final class PayloadPacker
{
	/** The server's cap is 131,072 bytes; keep some room. */
	static final int DEFAULT_BUDGET_BYTES = 120_000;

	/** Halving stops here, so the small parts can still go out together. */
	static final int MIN_BUDGET_BYTES = 16_000;

	static final class Packed
	{
		final String json;
		final Set<Part> parts;

		Packed(String json, Set<Part> parts)
		{
			this.json = json;
			this.parts = Collections.unmodifiableSet(parts);
		}
	}

	private PayloadPacker()
	{
	}

	/**
	 * @param pending the parts to send and their values, any order
	 * @return the body and the parts it carries, or null when nothing the schema allows is pending
	 */
	static Packed pack(Gson gson, int schema, String character, String capturedAt,
		Map<Part, JsonElement> pending, int budgetBytes)
	{
		return pack(gson, schema, character, capturedAt, pending, Collections.emptyMap(), budgetBytes);
	}

	/**
	 * @param pending the parts to send and their values, any order
	 * @param partTimes when the parts held between sends were read ({@link PartTimes}). From
	 *     {@link Part#PART_TIMES_SCHEMA} on, the body dates each such part it carries in {@code captured}. The site
	 *     refuses a time later than {@code captured_at}, so a time not before it is left out, and the site then
	 *     dates that part at {@code captured_at}, as it does every part an older schema sends.
	 * @return the body and the parts it carries, or null when nothing the schema allows is pending
	 */
	static Packed pack(Gson gson, int schema, String character, String capturedAt,
		Map<Part, JsonElement> pending, Map<Part, Instant> partTimes, int budgetBytes)
	{
		JsonObject body = new JsonObject();
		body.addProperty("schema", schema);
		body.addProperty("character", character);
		body.addProperty("captured_at", capturedAt);
		// Added before the parts so it is counted against the budget with them, and removed below if it stays
		// empty: the site refuses an empty one.
		JsonObject captured = new JsonObject();
		Instant sentAt = schema >= Part.PART_TIMES_SCHEMA ? instant(capturedAt) : null;
		if (sentAt != null)
		{
			body.add("captured", captured);
		}

		EnumSet<Part> included = EnumSet.noneOf(Part.class);
		for (Part part : Part.values())
		{
			JsonElement value = pending.get(part);
			if (value == null || part.minSchema > schema)
			{
				continue;
			}
			body.add(part.key, value);
			Instant time = partTimes.get(part);
			if (sentAt != null && time != null && time.isBefore(sentAt))
			{
				captured.addProperty(part.key, time.truncatedTo(ChronoUnit.SECONDS).toString());
			}
			if (!included.isEmpty() && size(gson, body) > budgetBytes)
			{
				// A part that waits for the next sync takes its time with it: the site refuses a time for a part
				// the body does not carry.
				body.remove(part.key);
				captured.remove(part.key);
				continue;
			}
			included.add(part);
		}
		if (included.isEmpty())
		{
			return null;
		}
		if (sentAt != null && captured.size() == 0)
		{
			body.remove("captured");
		}
		return new Packed(gson.toJson(body), included);
	}

	/** The send time as an instant, or null when it does not parse, which leaves the body undated. */
	private static Instant instant(String capturedAt)
	{
		try
		{
			return Instant.parse(capturedAt);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	static int size(Gson gson, JsonObject body)
	{
		return gson.toJson(body).getBytes(StandardCharsets.UTF_8).length;
	}

	/**
	 * The part to drop after the server refused a body as too large. A body of one part was refused
	 * for that part's own size, and no budget makes a lone part smaller, so sending it again would only
	 * be refused again.
	 *
	 * @param parts the parts the refused body carried
	 * @return the body's only part, or null for a body of several parts, which {@link #halved} splits up
	 */
	static Part tooLargeAlone(Set<Part> parts)
	{
		return parts.size() == 1 ? parts.iterator().next() : null;
	}

	/**
	 * The budget after the server refused a body of several parts as too large: half, so fewer parts go
	 * together next time, but never below {@link #MIN_BUDGET_BYTES}.
	 */
	static int halved(int budgetBytes)
	{
		return Math.max(MIN_BUDGET_BYTES, budgetBytes / 2);
	}
}

package com.osrsindex;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import net.runelite.client.events.PluginMessage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * This plugin's membership of the plugin bus (docs/plugin-bus.md): it says {@code hello} at start-up and
 * {@code bye} at shutdown, answers {@code discover}, and keeps a table of the other members present.
 *
 * <p>The EventBus is synchronous, so {@link #refresh()} rebuilds the table completely before it returns.
 * Messages may arrive on any thread; the table is a concurrent map.
 */
final class PluginBus
{
	private static final Logger log = LoggerFactory.getLogger(PluginBus.class);

	static final String NAMESPACE = "osrsindex.bus";
	static final int BUS_VERSION = 1;

	static final String HELLO = "hello";
	static final String DISCOVER = "discover";
	static final String BYE = "bye";

	static final String PLUGIN = "plugin";
	static final String NAME = "name";
	static final String VERSION = "version";
	static final String BUS = "bus";
	static final String ACCEPTS = "accepts";
	static final String POSTS = "posts";
	static final String FROM = "from";

	/** One plugin on the bus, as its {@code hello} described it. */
	static final class Member
	{
		final String plugin;
		final String name;
		final String version;
		final int bus;
		final List<String> accepts;
		final List<String> posts;

		Member(String plugin, String name, String version, int bus, List<String> accepts, List<String> posts)
		{
			this.plugin = plugin;
			this.name = name;
			this.version = version;
			this.bus = bus;
			this.accepts = Collections.unmodifiableList(new ArrayList<>(accepts));
			this.posts = Collections.unmodifiableList(new ArrayList<>(posts));
		}
	}

	private final Consumer<PluginMessage> post;
	private final Member self;
	private final Map<String, Member> members = new ConcurrentHashMap<>();
	private final Set<String> warned = ConcurrentHashMap.newKeySet();
	private volatile boolean running;

	PluginBus(Consumer<PluginMessage> post, Member self)
	{
		this.post = post;
		this.self = self;
	}

	/** Say {@code hello}, so the members present learn of this one, then {@code discover} them. */
	void start()
	{
		members.clear();
		running = true;
		post.accept(hello());
		post.accept(discover());
	}

	/** Say {@code bye} and forget everyone. Messages after this are ignored. */
	void stop()
	{
		if (!running)
		{
			return;
		}
		running = false;
		members.clear();
		post.accept(message(BYE, Collections.singletonMap(PLUGIN, self.plugin)));
	}

	/** Forget everyone and ask again: drops a member that crashed without saying {@code bye}. */
	void refresh()
	{
		if (!running)
		{
			return;
		}
		members.clear();
		post.accept(discover());
	}

	/** The other members present, by plugin id. A snapshot: later messages do not change it. */
	Map<String, Member> members()
	{
		return Collections.unmodifiableMap(new HashMap<>(members));
	}

	/** Whether {@code plugin} is present and says it accepts the command {@code name}. */
	boolean accepts(String plugin, String name)
	{
		Member member = members.get(plugin);
		return member != null && member.accepts.contains(name);
	}

	/** How many distinct warnings were logged: each malformed sender is logged once. */
	int warningsLogged()
	{
		return warned.size();
	}

	void onPluginMessage(PluginMessage message)
	{
		if (!running || !NAMESPACE.equals(message.getNamespace()))
		{
			return;
		}
		// PluginMessage refuses null data, so no null check is needed here.
		Map<String, Object> data = message.getData();
		switch (String.valueOf(message.getName()))
		{
			case DISCOVER:
				Object from = data.get(FROM);
				if (!self.plugin.equals(from))
				{
					post.accept(hello());
				}
				return;
			case HELLO:
				onHello(data);
				return;
			case BYE:
				Object leaving = data.get(PLUGIN);
				if (leaving instanceof String)
				{
					members.remove(leaving);
				}
				else
				{
					warnOnce("bye:" + leaving, "Ignored a plugin bus bye without a plugin id");
				}
				return;
			default:
				// A name this version does not know: rule 6, ignore it.
		}
	}

	private void onHello(Map<String, Object> data)
	{
		Member member = parseHello(data);
		if (member == null)
		{
			Object plugin = data.get(PLUGIN);
			warnOnce("hello:" + plugin, "Ignored a malformed plugin bus hello from {}", plugin);
			return;
		}
		if (member.plugin.equals(self.plugin))
		{
			return;
		}
		if (member.bus != BUS_VERSION)
		{
			warnOnce("bus:" + member.plugin + ":" + member.bus,
				"Ignored {}: it speaks plugin bus {}, this plugin speaks {}", member.plugin, member.bus, BUS_VERSION);
			return;
		}
		members.put(member.plugin, member);
	}

	/** The member a {@code hello} describes, or null if a required key is missing or of the wrong type. */
	static Member parseHello(Map<String, Object> data)
	{
		if (data == null)
		{
			return null;
		}
		Object plugin = data.get(PLUGIN);
		Object name = data.get(NAME);
		Object version = data.get(VERSION);
		Object bus = data.get(BUS);
		List<String> accepts = strings(data.get(ACCEPTS));
		List<String> posts = strings(data.get(POSTS));
		if (!(plugin instanceof String) || ((String) plugin).isEmpty()
			|| !(name instanceof String) || !(version instanceof String) || !(bus instanceof Number)
			|| accepts == null || posts == null)
		{
			return null;
		}
		return new Member((String) plugin, (String) name, (String) version, ((Number) bus).intValue(), accepts,
			posts);
	}

	private static List<String> strings(Object value)
	{
		if (!(value instanceof List))
		{
			return null;
		}
		List<String> strings = new ArrayList<>();
		for (Object element : (List<?>) value)
		{
			if (!(element instanceof String))
			{
				return null;
			}
			strings.add((String) element);
		}
		return strings;
	}

	private PluginMessage hello()
	{
		Map<String, Object> data = new HashMap<>();
		data.put(PLUGIN, self.plugin);
		data.put(NAME, self.name);
		data.put(VERSION, self.version);
		data.put(BUS, self.bus);
		data.put(ACCEPTS, self.accepts);
		data.put(POSTS, self.posts);
		return message(HELLO, data);
	}

	private PluginMessage discover()
	{
		return message(DISCOVER, Collections.singletonMap(FROM, self.plugin));
	}

	private static PluginMessage message(String name, Map<String, Object> data)
	{
		return new PluginMessage(NAMESPACE, name, Collections.unmodifiableMap(new HashMap<>(data)));
	}

	private void warnOnce(String key, String format, Object... arguments)
	{
		if (warned.add(key))
		{
			log.warn(format, arguments);
		}
	}
}

package com.osrsindex;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.client.events.PluginMessage;

/**
 * Hands a guide's quest step to the Quest Helper plugin, which guides quests better than a guide's text can. Quest
 * Helper has no way in from another plugin yet, so this works with what it has: it starts its helper by itself
 * when the game says "You've started a new quest" (its "Auto start helper" setting, on by default), and the player
 * can start one from the Quest List. The panel says which, and what to click.
 *
 * <p><b>Follow with Quest Helper</b> also posts {@code questhelper}/{@code start}, the message proposed upstream in
 * https://github.com/Zoinkwiz/quest-helper/pull/2756, so the button starts the helper once Quest Helper reads it.
 * Until then nothing listens, and the manual way stays on screen.
 *
 * <p>Read only: this never changes Quest Helper's settings, reads nothing of it but its public name and config, and
 * never touches its panel or overlays.
 */
final class QuestHelperHandOff
{
	/** Quest Helper's {@code @PluginDescriptor} name. */
	static final String PLUGIN_NAME = "Quest Helper";
	static final String CONFIG_GROUP = "questhelper";
	/** Its "Auto start helper" setting. Absent means on, its default. */
	static final String AUTO_START_KEY = "autostartQuests";
	static final String NAMESPACE = "questhelper";
	static final String START = "start";
	/** Proposed in https://github.com/Zoinkwiz/quest-helper/pull/2846: the helper Quest Helper now shows, or none. */
	static final String SELECTED = "selected";
	static final String SOURCE = "OSRS Index";

	/**
	 * Quests in the game with no helper in Quest Helper (checked at its v4.18.0, commit 5f79193). A step for one is
	 * guided by this plugin, as if Quest Helper were off.
	 */
	static final Set<String> NO_HELPER = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		"Learning the Ropes",
		"Into the Tombs",
		"The Frozen Door",
		"A Ruff Situation")));

	/**
	 * Where Quest Helper's name is not the game's. Recipe for Disaster's parts are "RFD - ...", and two of them are
	 * named for where they fall in the quest. Shield of Arrav is split by gang ({@link #helperName}).
	 */
	private static final Map<String, String> RENAMED;

	static
	{
		Map<String, String> renamed = new LinkedHashMap<>();
		renamed.put("Recipe for Disaster - Another Cook's Quest", "RFD - Start");
		renamed.put("Recipe for Disaster - Mountain Dwarf", "RFD - Mountain Dwarf");
		renamed.put("Recipe for Disaster - Wartface & Bentnoze", "RFD - Wartface & Bentnoze");
		renamed.put("Recipe for Disaster - Pirate Pete", "RFD - Pirate Pete");
		renamed.put("Recipe for Disaster - Lumbridge Guide", "RFD - Lumbridge Guide");
		renamed.put("Recipe for Disaster - Evil Dave", "RFD - Evil Dave");
		renamed.put("Recipe for Disaster - King Awowogei", "RFD - King Awowogei");
		renamed.put("Recipe for Disaster - Sir Amik Varze", "RFD - Sir Amik Varze");
		renamed.put("Recipe for Disaster - Skrach Uglogwee", "RFD - Skrach Uglogwee");
		renamed.put("Recipe for Disaster - Culinaromancer", "RFD - Finale");
		RENAMED = Collections.unmodifiableMap(renamed);
	}

	/** The game's quest names ({@link Quest#getName()}), which a guide's {@code quests} uses. */
	private static final Set<String> GAME_QUESTS;

	static
	{
		Set<String> names = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			names.add(quest.getName());
		}
		GAME_QUESTS = Collections.unmodifiableSet(names);
	}

	static final String SHIELD_OF_ARRAV = "Shield of Arrav";
	static final String RECIPE_FOR_DISASTER = "Recipe for Disaster";

	/** Which Shield of Arrav gang the character joined, from the quest's two progress varps. */
	enum Gang
	{
		PHOENIX("Shield of Arrav - Phoenix Gang"),
		BLACK_ARM("Shield of Arrav - Black Arm Gang"),
		/** Not joined yet. Quest Helper picks a gang itself for the plain name. */
		UNKNOWN(SHIELD_OF_ARRAV);

		final String helperName;

		Gang(String helperName)
		{
			this.helperName = helperName;
		}

		/**
		 * The gang from {@code PHOENIXGANG} (varp 145, which also counts the quest's start) and {@code BLACKARMGANG}
		 * (varp 146). Quest Helper's Phoenix helper takes the player to Straven at 4, so 5 and on is in the gang. The
		 * Black Arm helper sends the player to Katrina from 1.
		 */
		static Gang of(int phoenixGang, int blackArmGang)
		{
			if (phoenixGang >= 5)
			{
				return PHOENIX;
			}
			return blackArmGang >= 1 ? BLACK_ARM : UNKNOWN;
		}
	}

	enum Stage
	{
		/** No quest, Quest Helper off or set aside, or no helper for the quest: this plugin guides the step. */
		OURS,
		/** Quest Helper will guide it; the quest has not started. The map point leads to the start. */
		BEFORE_START,
		/** The quest is under way, so Quest Helper guides it, and this plugin's point and arrow stand down. */
		STARTED,
		/** Every quest of the step is finished: the step is done. */
		FINISHED
	}

	final Stage stage;
	/** The game's name of the quest Quest Helper is for, or null. */
	final String quest;
	/** Quest Helper's name for it, or null. */
	final String helperName;
	final boolean autoStart;

	private QuestHelperHandOff(Stage stage, String quest, String helperName, boolean autoStart)
	{
		this.stage = stage;
		this.quest = quest;
		this.helperName = helperName;
		this.autoStart = autoStart;
	}

	static final QuestHelperHandOff OURS = new QuestHelperHandOff(Stage.OURS, null, null, false);

	/** Whether this plugin draws the step's map point and minimap arrow: always, except while Quest Helper has it. */
	boolean ownsThePlace()
	{
		return stage != Stage.STARTED;
	}

	/**
	 * The hand-off for {@code step}. {@code questHelperOn}: Quest Helper is running and the player left "Hand quest
	 * steps to Quest Helper" on. The first quest of the step not finished decides it.
	 */
	static QuestHelperHandOff of(Guide.Step step, boolean questHelperOn, boolean autoStart, Gang gang, GuideFacts facts)
	{
		if (!questHelperOn || step.quests.isEmpty())
		{
			return OURS;
		}
		for (String quest : step.quests)
		{
			QuestState state = facts.quest(quest);
			if (state == QuestState.FINISHED)
			{
				continue;
			}
			String helper = helperName(quest, gang);
			if (helper == null)
			{
				return OURS;
			}
			return new QuestHelperHandOff(state == QuestState.IN_PROGRESS ? Stage.STARTED : Stage.BEFORE_START, quest,
				helper, autoStart);
		}
		return new QuestHelperHandOff(Stage.FINISHED, null, null, autoStart);
	}

	/**
	 * Quest Helper's name for the game's quest, or null when it has no helper for it or the name is not one of the
	 * game's. Its names are the game's, apart from Recipe for Disaster's parts and Shield of Arrav's gangs. The whole
	 * of Recipe for Disaster goes as is: Quest Helper opens its first part.
	 */
	static String helperName(String gameQuest, Gang gang)
	{
		if (gameQuest == null || !GAME_QUESTS.contains(gameQuest) || NO_HELPER.contains(gameQuest))
		{
			return null;
		}
		if (SHIELD_OF_ARRAV.equals(gameQuest))
		{
			return (gang == null ? Gang.UNKNOWN : gang).helperName;
		}
		String renamed = RENAMED.get(gameQuest);
		return renamed != null ? renamed : gameQuest;
	}

	/** The name the quest has in the game's Quest List, where Quest Helper's right-click option is. */
	static String questListName(String gameQuest)
	{
		return gameQuest.startsWith(RECIPE_FOR_DISASTER + " - ") ? RECIPE_FOR_DISASTER : gameQuest;
	}

	/** The message Follow with Quest Helper posts. */
	static PluginMessage startMessage(String helperName)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("quest", helperName);
		data.put("source", SOURCE);
		return new PluginMessage(NAMESPACE, START, Collections.unmodifiableMap(data));
	}

	/** Quest Helper's {@code selected} message, as proposed: the helper it shows, or null when it shows none. */
	static String selected(PluginMessage message)
	{
		Object quest = message.getData() == null ? null : message.getData().get("quest");
		return quest instanceof String ? GuideParser.text((String) quest, GuideParser.MAX_TITLE) : null;
	}

	/** "Auto start helper" from Quest Helper's config, as stored: absent or anything but "false" is on. */
	static boolean autoStart(String stored)
	{
		return !"false".equalsIgnoreCase(stored == null ? "" : stored.trim());
	}

	/** What the panel says about the hand-off, as plain text, or null when this plugin guides the step. */
	String panelText()
	{
		if (stage != Stage.BEFORE_START && stage != Stage.STARTED)
		{
			return null;
		}
		String manual = "open the Quest List, right-click " + questListName(quest) + " and pick Start Quest Helper"
			+ (helperName.equals(questListName(quest)) ? "" : " for " + helperName) + ".";
		switch (stage)
		{
			case BEFORE_START:
				return autoStart
					? "Quest Helper guides this quest. It starts by itself when you start " + quest + ". To start it now, "
					+ manual
					: "Quest Helper guides this quest. To start it, " + manual;
			case STARTED:
				return "Quest Helper guides " + quest + " now. This guide moves on by itself when the quest is finished."
					+ " If Quest Helper is not showing it, " + manual;
			default:
				return null;
		}
	}
}

package com.osrsindex;

import java.time.Clock;
import java.time.Duration;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Predicate;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.util.Text;

/**
 * Hands a site destination to a pathing plugin, following what the contract says the plugin must do with
 * one. Every destination whose {@code id} can be acked is acked once, with what became of it, and the first
 * of these that applies decides the ack's {@code result}:
 * <ol>
 *   <li>a place outside the ranges is {@code invalid}; one with no usable {@code id} cannot be acked at
 *   all;</li>
 *   <li>an {@code id} already routed is {@code routed} again, but not posted twice, because the site may
 *   deliver a place again after a reconnect when the first ack was lost;</li>
 *   <li>a place past {@code expires_at}, allowing 30 seconds of clock skew, is {@code expired};</li>
 *   <li>with Shortest Path off, the player is told in chat and it is {@code no_pathing_plugin};</li>
 *   <li>otherwise one {@code PluginMessage} is posted, {@code <namespace>/path} with {@code data.target} a
 *   {@code WorldPoint} and no {@code start}, so the route begins at the player. The player is told in chat,
 *   with the label escaped, since RuneLite chat markup is the client's, and it is {@code routed}.</li>
 * </ol>
 *
 * <p>The caller sends the {@code ack} and shows the chat line. This class touches no socket and no
 * client state, so the rules are testable on their own. Run it on the client thread: Shortest Path
 * reads the message on the thread that posts it.
 */
final class RouteDispatcher
{
	static final int MAX_COORDINATE = 16_383;
	static final int MAX_PLANE = 3;
	static final int MAX_LABEL_CODE_POINTS = 100;
	static final int MAX_ID_LENGTH = 64;
	static final Duration CLOCK_SKEW = Duration.ofSeconds(30);
	/** Ids live 2 minutes on the site; this covers far more sends than fit in that window. */
	static final int REMEMBERED_IDS = 64;

	static final String PATH = "path";
	static final String TARGET = "target";

	/** What became of one destination, and the {@code result} its ack carries. */
	enum Kind
	{
		/** Posted to a pathing plugin. Ack it {@code routed} and show the chat line. */
		ROUTED("routed"),
		/**
		 * This id was routed before. Ack it {@code routed} again, since the first ack may be lost, but post
		 * nothing.
		 */
		ALREADY_ROUTED("routed"),
		/** It breaks the contract's ranges. Ack it {@code invalid} if its id can be acked, and post nothing. */
		INVALID("invalid"),
		/** Past {@code expires_at}, plus the skew. Ack it {@code expired}, and post nothing. */
		EXPIRED("expired"),
		/**
		 * Shortest Path is not on. Show the chat line and ack it {@code no_pathing_plugin}, so the site's map
		 * says why too. The id is not remembered, so a redelivery once Shortest Path is on still routes.
		 */
		NO_PATHING_PLUGIN("no_pathing_plugin");

		/** The ack's {@code result}, in the site contract's words. */
		final String ackResult;

		Kind(String ackResult)
		{
			this.ackResult = ackResult;
		}
	}

	static final class Result
	{
		final Kind kind;
		/** The plugin it went to, for {@link Kind#ROUTED} only. */
		final PathingPlugin plugin;
		/** The line for game chat, already escaped, or null for none. */
		final String chatMessage;
		/** The id to ack with {@code kind}'s result, or null when the id cannot be acked. */
		final String ackId;

		private Result(Kind kind, PathingPlugin plugin, String chatMessage, String ackId)
		{
			this.kind = kind;
			this.plugin = plugin;
			this.chatMessage = chatMessage;
			this.ackId = ackId;
		}
	}

	private final Consumer<PluginMessage> post;
	private final Predicate<PathingPlugin> active;
	private final Clock clock;
	private final Set<String> routedIds = Collections.newSetFromMap(new LinkedHashMap<String, Boolean>()
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest)
		{
			return size() > REMEMBERED_IDS;
		}
	});

	RouteDispatcher(Consumer<PluginMessage> post, Predicate<PathingPlugin> active, Clock clock)
	{
		this.post = post;
		this.active = active;
		this.clock = clock;
	}

	/**
	 * Whether a pathing plugin is running, by its {@code @PluginDescriptor} name. That name is the one
	 * thing another Hub plugin exposes without reflection.
	 */
	static Predicate<PathingPlugin> activeIn(PluginManager pluginManager)
	{
		return plugin ->
		{
			for (Plugin loaded : pluginManager.getPlugins())
			{
				if (plugin.displayName.equals(loaded.getName()) && pluginManager.isPluginActive(loaded))
				{
					return true;
				}
			}
			return false;
		};
	}

	synchronized Result dispatch(Destination destination, RouteWith routeWith)
	{
		if (!valid(destination))
		{
			// The site sends only places in range, so this is a frame this version cannot read. Acking it
			// stops the site sending it again, and lets the map say what to do.
			return new Result(Kind.INVALID, null, null, ackable(destination) ? destination.id : null);
		}
		if (routedIds.contains(destination.id))
		{
			return new Result(Kind.ALREADY_ROUTED, null, null, destination.id);
		}
		// The skew comes off now, not onto expires_at, which may be as late as Instant allows.
		if (clock.instant().minus(CLOCK_SKEW).isAfter(destination.expiresAt))
		{
			return new Result(Kind.EXPIRED, null, null, destination.id);
		}

		String label = chatSafe(destination.label);
		String place = (label.isEmpty() ? "a tile" : label) + " (" + destination.x + ", " + destination.y + ", "
			+ destination.plane + ")";
		PathingPlugin plugin = routeWith.choose(active);
		if (plugin == null)
		{
			return new Result(Kind.NO_PATHING_PLUGIN, null,
				"osrsindex.com sent " + place + ", but " + routeWith + " is not on.", destination.id);
		}

		Map<String, Object> data = new HashMap<>();
		data.put(TARGET, new WorldPoint(destination.x, destination.y, destination.plane));
		// Read-only, so a plugin that sees it first cannot change the target before the pathing plugin does.
		post.accept(new PluginMessage(plugin.namespace, PATH, Collections.unmodifiableMap(data)));
		routedIds.add(destination.id);
		return new Result(Kind.ROUTED, plugin,
			"osrsindex.com: routing to " + place + " with " + plugin.displayName + ".", destination.id);
	}

	static boolean valid(Destination destination)
	{
		if (!ackable(destination) || destination.label == null || destination.expiresAt == null)
		{
			return false;
		}
		int labelLength = destination.label.codePointCount(0, destination.label.length());
		return inRange(destination.x, MAX_COORDINATE)
			&& inRange(destination.y, MAX_COORDINATE)
			&& inRange(destination.plane, MAX_PLANE)
			&& labelLength >= 1
			&& labelLength <= MAX_LABEL_CODE_POINTS;
	}

	/**
	 * Whether the site can match an ack to this destination: an {@code id} of 1 to 64 characters. The site
	 * ignores an ack whose id is empty or longer, so a place without such an id is dropped unacked.
	 */
	static boolean ackable(Destination destination)
	{
		return destination != null && destination.id != null && !destination.id.isEmpty()
			&& destination.id.length() <= MAX_ID_LENGTH;
	}

	/**
	 * The label as chat can show it. {@code escapeJagex} turns {@code <}, {@code >} and {@code @} into
	 * their escapes, so the site's plain text cannot open a colour or image tag. Control characters are
	 * dropped: the site removes them, but a label reaches chat only through this.
	 */
	static String chatSafe(String label)
	{
		StringBuilder printable = new StringBuilder(label.length());
		label.codePoints()
			.filter(codePoint -> !Character.isISOControl(codePoint) && Character.getType(codePoint) != Character.FORMAT)
			.forEach(printable::appendCodePoint);
		return Text.escapeJagex(printable.toString());
	}

	private static boolean inRange(int value, int max)
	{
		return value >= 0 && value <= max;
	}
}

package com.osrsindex;

import java.util.function.Predicate;

/**
 * Which pathing plugin a site destination goes to. There is one choice: destinations always go to Shortest Path.
 * Farm Route Planner is on the plugin bus, but it is never handed a destination.
 */
enum RouteWith
{
	SHORTEST_PATH(PathingPlugin.SHORTEST_PATH);

	private final PathingPlugin plugin;

	RouteWith(PathingPlugin plugin)
	{
		this.plugin = plugin;
	}

	/** The plugin to use, or null when it is off. Nothing else is tried in its place. */
	PathingPlugin choose(Predicate<PathingPlugin> active)
	{
		return active.test(plugin) ? plugin : null;
	}

	@Override
	public String toString()
	{
		return plugin.displayName;
	}
}

package com.osrsindex;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * What osrsindex.com asks of this plugin, so the site can change it without a plugin release: timings and
 * limits, parts to pause, which vars to send, and a notice for the player (docs/site-config.md).
 *
 * <p>It is data only. Every field is optional, clamped to a safe range or ignored when unusable, and the site
 * can only narrow what the player chose: a part the player turned off stays off. {@link #DEFAULTS} is the
 * plugin's built-in behaviour, which is what a site without the config route gets.
 */
final class SiteConfig
{
	static final int DEFAULT_REFRESH_SECONDS = 3_600;
	static final int MIN_REFRESH_SECONDS = 300;
	static final int MAX_REFRESH_SECONDS = 86_400;

	/** The longest player-facing text the site may send, in code points. */
	static final int MAX_TEXT = 300;
	static final int MAX_NOTICE_ID = 64;

	static final int MAX_SITE_VARBITS = 4_000;
	static final int MAX_SITE_VARPS = 1_000;
	static final int MAX_VAR_ID = 65_535;
	/**
	 * The vars part's estimated size limit, counting each entry as its name plus 8 bytes. The built-in list is about
	 * 74,500 by that count. The site's entries stop where they would pass this, so the part stays under the site's
	 * 131,072-byte body cap even when values run long.
	 */
	static final int MAX_VARS_BYTES = 100_000;
	/** RuneLite's gameval names: capitals, digits and underscores, never a digit first, which the sync refuses. */
	private static final Pattern VAR_NAME = Pattern.compile("[A-Z_][A-Z0-9_]{0,79}");
	/**
	 * Names the vars part keeps for others, so a site var never takes one: the site's own {@code __SITE_} names, and
	 * the schema 4 Slayer text this plugin writes itself ({@code SLAYER_TASK_NAME}, {@code SLAYER_TASK_AREA}). The
	 * sync refuses the whole vars part over any of them.
	 */
	static final Pattern RESERVED_VAR = Pattern.compile("^__SITE_|^SLAYER_TASK_NAME$|^SLAYER_TASK_AREA$");
	/**
	 * The names scripts/generate_gamevars.py leaves out: never interface settings, the POH, leagues or debug. Keep it
	 * the same as the generator's {@code EXCLUDE}. The IDs of every name it matches are refused as well
	 * ({@link GameVars#EXCLUDED_VARBIT_IDS}), so the site cannot send one under another name.
	 */
	static final Pattern EXCLUDED_VAR = Pattern.compile("^LEAGUE|_LEAGUE|^POH_|SETTINGS|_TEMP$|_TMP$|DEBUG|TOGGLE|HIDE"
		+ "|FILTER|SELECTED|SCROLL|_MENU|_UI_|_INTERFACE|_TAB$|_TAB_"
		+ "|^OPTION_|QUESTLIST_|REQUESTEDQUANTITY|WORLDSWITCHER|COLOUR|_PROMPT|BANNED|BANKPIN|^ACCOUNT_|LOGIN"
		+ "|DISPLAYNAME|BOND|PURGEIGNORED|^CHAT_", Pattern.CASE_INSENSITIVE);

	static final SiteConfig DEFAULTS = new SiteConfig(0, DEFAULT_REFRESH_SECONDS, Part.LATEST_SCHEMA, Timing.DEFAULTS,
		EnumSet.noneOf(Part.class), true, Vars.BUILT_IN, null);

	/** The config's revision; a stored sync naming a higher {@code config_version} asks for it again. */
	final int version;
	final int refreshSeconds;
	/** The highest sync schema to send. */
	final int maxSchema;
	final Timing timing;
	/** Parts the site paused. Never more than a pause: a part the player turned off stays off. */
	final Set<Part> paused;
	/** False when the site paused the destinations socket. */
	final boolean destinations;
	final Vars vars;
	/** One line for the panel, or null. */
	final Notice notice;

	private SiteConfig(int version, int refreshSeconds, int maxSchema, Timing timing, Set<Part> paused,
		boolean destinations, Vars vars, Notice notice)
	{
		this.version = version;
		this.refreshSeconds = refreshSeconds;
		this.maxSchema = maxSchema;
		this.timing = timing;
		this.paused = Collections.unmodifiableSet(paused);
		this.destinations = destinations;
		this.vars = vars;
		this.notice = notice;
	}

	/** Whether the site lets {@code part} go out. The player's own setting is checked as well, elsewhere. */
	boolean allows(Part part)
	{
		return !paused.contains(part);
	}

	/** The largest body budget the site may set: under its own 131,072-byte cap. */
	static final int MAX_BUDGET_BYTES = 125_000;

	/** The waits and limits the site may tune, each clamped to a range the plugin trusts. */
	static final class Timing
	{
		static final Timing DEFAULTS = new Timing(SyncOutcome.FLOOR_SECONDS, SyncOutcome.DEFAULT_RETRY_SECONDS,
			SyncOutcome.ACCOUNT_FULL_RETRY_SECONDS, PayloadPacker.DEFAULT_BUDGET_BYTES, 5, 25,
			DestinationSocket.FIRST_RETRY_MILLIS, DestinationSocket.MAX_RETRY_MILLIS);

		final int syncFloorSeconds;
		final int retrySeconds;
		final int accountFullRetrySeconds;
		final int budgetBytes;
		final int pollTicks;
		final int pollVarsTicks;
		final long relayRetryMillis;
		final long relayRetryMaxMillis;

		Timing(int syncFloorSeconds, int retrySeconds, int accountFullRetrySeconds, int budgetBytes, int pollTicks,
			int pollVarsTicks, long relayRetryMillis, long relayRetryMaxMillis)
		{
			this.syncFloorSeconds = syncFloorSeconds;
			this.retrySeconds = retrySeconds;
			this.accountFullRetrySeconds = accountFullRetrySeconds;
			this.budgetBytes = budgetBytes;
			this.pollTicks = pollTicks;
			this.pollVarsTicks = pollVarsTicks;
			this.relayRetryMillis = relayRetryMillis;
			this.relayRetryMaxMillis = relayRetryMaxMillis;
		}

		static Timing of(JsonObject json)
		{
			if (json == null)
			{
				return DEFAULTS;
			}
			// Never quicker than the built-in waits where quicker would cost the site: the floor is its own per-token
			// limit, and every linked client reconnects to the relay at once after an outage.
			long relayFirst = number(json, "relay_retry_seconds", DEFAULTS.relayRetryMillis / 1_000, 15, 600);
			long relayMax = number(json, "relay_retry_max_seconds", Math.max(relayFirst, DEFAULTS.relayRetryMaxMillis / 1_000),
				Math.max(relayFirst, 60), 3_600);
			return new Timing(
				(int) number(json, "sync_floor_seconds", DEFAULTS.syncFloorSeconds, SyncOutcome.FLOOR_SECONDS, 3_600),
				(int) number(json, "retry_seconds", DEFAULTS.retrySeconds, 30, 3_600),
				(int) number(json, "account_full_retry_seconds", DEFAULTS.accountFullRetrySeconds, 60, 86_400),
				(int) number(json, "budget_bytes", DEFAULTS.budgetBytes, PayloadPacker.MIN_BUDGET_BYTES, MAX_BUDGET_BYTES),
				(int) number(json, "poll_ticks", DEFAULTS.pollTicks, 1, 100),
				(int) number(json, "poll_vars_ticks", DEFAULTS.pollVarsTicks, 5, 1_000),
				relayFirst * 1_000L,
				relayMax * 1_000L);
		}
	}

	/** The varbits and varps the vars part reads, by gameval name, as parallel arrays. */
	static final class Vars
	{
		static final Vars BUILT_IN = new Vars(GameVars.VARBIT_NAMES, GameVars.VARBIT_IDS, GameVars.VARP_NAMES,
			GameVars.VARP_IDS);

		final String[] varbitNames;
		final int[] varbitIds;
		final String[] varpNames;
		final int[] varpIds;

		private Vars(String[] varbitNames, int[] varbitIds, String[] varpNames, int[] varpIds)
		{
			this.varbitNames = varbitNames;
			this.varbitIds = varbitIds;
			this.varpNames = varpNames;
			this.varpIds = varpIds;
		}

		boolean sameAs(Vars other)
		{
			return other != null && Arrays.equals(varbitNames, other.varbitNames) && Arrays.equals(varbitIds, other.varbitIds)
				&& Arrays.equals(varpNames, other.varpNames) && Arrays.equals(varpIds, other.varpIds);
		}

		static Vars of(JsonObject json)
		{
			if (json == null)
			{
				return BUILT_IN;
			}
			boolean replace = "replace".equals(string(json, "mode"));
			Map<String, Integer> varbits = replace ? new LinkedHashMap<>() : map(GameVars.VARBIT_NAMES, GameVars.VARBIT_IDS);
			Map<String, Integer> varps = replace ? new LinkedHashMap<>() : map(GameVars.VARP_NAMES, GameVars.VARP_IDS);
			int[] size = {estimate(varbits) + estimate(varps)};
			addFrom(object(json, "varbits"), MAX_SITE_VARBITS, GameVars.EXCLUDED_VARBIT_IDS, GameVars.VARBIT_NAMES,
				GameVars.VARBIT_IDS, GameVars.MAX_KNOWN_VARBIT_ID, varbits, size);
			addFrom(object(json, "varps"), MAX_SITE_VARPS, GameVars.EXCLUDED_VARP_IDS, GameVars.VARP_NAMES,
				GameVars.VARP_IDS, GameVars.MAX_KNOWN_VARP_ID, varps, size);
			List<String> varbitNames = new ArrayList<>(varbits.keySet());
			List<String> varpNames = new ArrayList<>(varps.keySet());
			Vars vars = new Vars(varbitNames.toArray(new String[0]), ids(varbits), varpNames.toArray(new String[0]), ids(varps));
			return vars.sameAs(BUILT_IN) ? BUILT_IN : vars;
		}

		private static Map<String, Integer> map(String[] names, int[] ids)
		{
			Map<String, Integer> out = new LinkedHashMap<>();
			for (int i = 0; i < names.length; i++)
			{
				out.put(names[i], ids[i]);
			}
			return out;
		}

		/** The vars part's size by {@link #MAX_VARS_BYTES}'s count: each name plus 8 bytes. */
		private static int estimate(Map<String, Integer> entries)
		{
			int size = 0;
			for (String name : entries.keySet())
			{
				size += name.length() + 8;
			}
			return size;
		}

		/**
		 * The site's usable entries, at most {@code limit}, while the part stays within {@link #MAX_VARS_BYTES}: a
		 * name it may ask for, neither excluded nor reserved, and a whole ID in range that no excluded name has and
		 * that {@link #allowed} lets through.
		 */
		private static void addFrom(JsonObject site, int limit, int[] excludedIds, String[] knownNames, int[] knownIds,
			int maxKnownId, Map<String, Integer> into, int[] size)
		{
			if (site == null)
			{
				return;
			}
			int taken = 0;
			for (Map.Entry<String, JsonElement> entry : site.entrySet())
			{
				if (taken == limit)
				{
					break;
				}
				String name = entry.getKey();
				Integer id = wholeNumber(entry.getValue());
				if (!VAR_NAME.matcher(name).matches() || EXCLUDED_VAR.matcher(name).find() || RESERVED_VAR.matcher(name).find()
					|| id == null || id < 0 || id > MAX_VAR_ID || Arrays.binarySearch(excludedIds, id) >= 0
					|| !allowed(name, id, knownNames, knownIds, maxKnownId))
				{
					continue;
				}
				int grows = into.containsKey(name) ? 0 : name.length() + 8;
				if (size[0] + grows > MAX_VARS_BYTES)
				{
					break;
				}
				into.put(name, id);
				size[0] += grows;
				taken++;
			}
		}

		/**
		 * A var this plugin's game data names goes only under that name, and only when the built-in list has it: the
		 * site cannot read an account or settings value by giving its ID a progress name. A var newer than that data
		 * goes only under a progress name, so a new quest or minigame can still be added from the site.
		 */
		static boolean allowed(String name, int id, String[] knownNames, int[] knownIds, int maxKnownId)
		{
			if (id > maxKnownId)
			{
				return GameVars.PROGRESS_NAME.matcher(name).find();
			}
			// The IDs are sorted; one ID may carry more than one name, so look either side of the match.
			int at = Arrays.binarySearch(knownIds, id);
			if (at < 0)
			{
				return false;
			}
			int first = at;
			while (first > 0 && knownIds[first - 1] == id)
			{
				first--;
			}
			for (int i = first; i < knownIds.length && knownIds[i] == id; i++)
			{
				if (knownNames[i].equals(name))
				{
					return true;
				}
			}
			return false;
		}

		private static int[] ids(Map<String, Integer> entries)
		{
			int[] out = new int[entries.size()];
			int i = 0;
			for (int id : entries.values())
			{
				out[i++] = id;
			}
			return out;
		}
	}

	/** One line for the player. {@link #url} is on the plugin's own origin, or null. */
	static final class Notice
	{
		final String id;
		final String text;
		final String url;
		/** Also put it in game chat, once per id. */
		final boolean chat;

		Notice(String id, String text, String url, boolean chat)
		{
			this.id = id;
			this.text = text;
			this.url = url;
			this.chat = chat;
		}

		static Notice of(JsonObject json)
		{
			String text = playerText(string(json, "text"));
			if (text == null)
			{
				return null;
			}
			String id = playerText(string(json, "id"));
			id = id == null || id.length() > MAX_NOTICE_ID ? text : id;
			JsonElement chat = json.get("chat");
			return new Notice(id, text, siteUrl(string(json, "url")), chat != null && isBoolean(chat) && chat.getAsBoolean());
		}
	}

	/** The config in a 200's body, or the built-in values when it is not a JSON object. */
	static SiteConfig parse(String body)
	{
		SiteConfig config = parseOrNull(body);
		return config == null ? DEFAULTS : config;
	}

	/**
	 * The config in a 200's body, or null when it is not a JSON object: an HTML page from a proxy or a fallback route
	 * is no answer, and the config already in use stays.
	 */
	static SiteConfig parseOrNull(String body)
	{
		JsonObject json = null;
		try
		{
			JsonElement parsed = body == null ? null : new JsonParser().parse(body);
			json = parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
		}
		catch (RuntimeException ignored)
		{
			// Not JSON: the built-in values.
		}
		if (json == null)
		{
			return null;
		}
		JsonObject notice = object(json, "notice");
		JsonElement destinations = json.get("destinations");
		return new SiteConfig(
			(int) number(json, "version", 0, 0, Integer.MAX_VALUE),
			(int) number(json, "refresh_seconds", DEFAULT_REFRESH_SECONDS, MIN_REFRESH_SECONDS, MAX_REFRESH_SECONDS),
			(int) number(json, "max_schema", Part.LATEST_SCHEMA, 1, Part.LATEST_SCHEMA),
			Timing.of(object(json, "timing")),
			paused(object(json, "parts")),
			destinations == null || !isBoolean(destinations) || destinations.getAsBoolean(),
			Vars.of(object(json, "vars")),
			notice == null ? null : Notice.of(notice));
	}

	private static Set<Part> paused(JsonObject parts)
	{
		Set<Part> out = EnumSet.noneOf(Part.class);
		if (parts == null)
		{
			return out;
		}
		for (Part part : Part.values())
		{
			JsonElement value = parts.get(part.key);
			if (value != null && isBoolean(value) && !value.getAsBoolean())
			{
				out.add(part);
			}
		}
		return out;
	}

	/**
	 * Text the site wrote for the player, made safe to show: control characters dropped, runs of whitespace made
	 * one space, at most {@link #MAX_TEXT} code points. Null when nothing is left. Markup stays text: chat and the
	 * panel each escape it where they show it.
	 */
	static String playerText(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		StringBuilder out = new StringBuilder();
		int[] count = {0};
		raw.codePoints()
			.map(codePoint -> Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint) ? ' ' : codePoint)
			.filter(codePoint -> !Character.isISOControl(codePoint) && Character.getType(codePoint) != Character.FORMAT)
			.forEach(codePoint ->
			{
				boolean space = codePoint == ' ';
				if (count[0] < MAX_TEXT && !(space && (out.length() == 0 || out.charAt(out.length() - 1) == ' ')))
				{
					out.appendCodePoint(codePoint);
					count[0]++;
				}
			});
		String text = out.toString().trim();
		return text.isEmpty() ? null : text;
	}

	/** A player-facing string field of a response body, made safe ({@link #playerText}), or null. */
	static String playerMessage(JsonObject json)
	{
		return json == null ? null : playerText(string(json, "player_message"));
	}

	/** {@code url} when it is a page on the plugin's own origin, else null. */
	static String siteUrl(String url)
	{
		return url != null && url.startsWith(Endpoints.origin() + "/") && url.length() <= 2_000
			&& url.chars().noneMatch(c -> c <= ' ' || c == 0x7F) ? url : null;
	}

	// --- reading the body ----------------------------------------------------

	private static JsonObject object(JsonObject json, String key)
	{
		JsonElement value = json.get(key);
		return value != null && value.isJsonObject() ? value.getAsJsonObject() : null;
	}

	static String string(JsonObject json, String key)
	{
		JsonElement value = json.get(key);
		return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString() ? value.getAsString() : null;
	}

	private static boolean isBoolean(JsonElement value)
	{
		return value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean();
	}

	/** A number field clamped to {@code min}..{@code max}, or {@code fallback} when absent or not a number. */
	private static long number(JsonObject json, String key, long fallback, long min, long max)
	{
		JsonElement value = json.get(key);
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return fallback;
		}
		double number = value.getAsDouble();
		if (Double.isNaN(number))
		{
			return fallback;
		}
		return (long) Math.max(min, Math.min(max, number));
	}

	/** A JSON number with no fraction that fits an int, or null. */
	private static Integer wholeNumber(JsonElement value)
	{
		if (value == null || !value.isJsonPrimitive())
		{
			return null;
		}
		JsonPrimitive primitive = value.getAsJsonPrimitive();
		if (!primitive.isNumber())
		{
			return null;
		}
		double number = primitive.getAsDouble();
		return number == Math.rint(number) && number >= Integer.MIN_VALUE && number <= Integer.MAX_VALUE ? (int) number : null;
	}
}

package com.osrsindex;

import java.io.IOException;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Keeps this client's {@link SiteConfig} from osrsindex.com (docs/site-config.md). It asks only while the client is
 * linked and the plugin ticks it, which it does only while logged in: one {@code GET} with the token as a bearer
 * on the first tick, then every {@code refresh_seconds}, or sooner when a sync says the config changed.
 *
 * <p>An answer it cannot use never costs the plugin anything: a site without the route ({@code 404}) means the
 * built-in values, and an error, a body that is not a JSON object, or no answer keeps the config it already has.
 * A new or cleared token goes back to the built-in values at once, because the config may be the account's own.
 */
final class SiteConfigFetcher
{
	/** One {@code GET} with the token as a bearer, answered with its status (-1 for no response) and body. */
	interface Transport
	{
		void get(String url, String token, Handler handler);
	}

	interface Handler
	{
		void handle(int status, String body);
	}

	/** How long syncs wait, after the first ask for a token, for a config or a 404 when neither has come. */
	static final long FIRST_ANSWER_WAIT_MILLIS = 30_000;
	/** After an error, or no answer: keep what we have, and ask again in 5 minutes. */
	static final long RETRY_MILLIS = 300_000;
	/** A site without the route: ask again in an hour. */
	static final long NOT_SERVED_RETRY_MILLIS = 3_600_000;
	/** A sync's {@code config_version} asks again, but never sooner than this after the last ask. */
	static final long SOONEST_REFRESH_MILLIS = 60_000;
	/** The largest body read as a config, in bytes. */
	static final int MAX_BODY_BYTES = 2_000_000;

	private final Transport transport;
	private final LongSupplier clock;
	/** Gets each config the plugin should now use, on whichever thread answered. */
	private final Consumer<SiteConfig> onConfig;

	private String token = "";
	private SiteConfig current = SiteConfig.DEFAULTS;
	/** Bumped on every token change, so an answer for the old token is ignored. */
	private int generation;
	private boolean inFlight;
	private long nextAskAtMillis;
	private long lastAskAtMillis = Long.MIN_VALUE / 2;
	/** When the first ask for this token went out, or -1. */
	private long firstAskAtMillis = -1;
	/** A config or a 404 has come for this token: what the site wants is known. */
	private boolean settled;
	/** The highest {@code config_version} a sync named for this token, or -1. */
	private int namedVersion = -1;
	/** {@link #namedVersion} when the ask in flight went out, so a newer one named meanwhile is asked for after it. */
	private int namedVersionAtAsk = -1;

	SiteConfigFetcher(OkHttpClient http, Consumer<SiteConfig> onConfig)
	{
		this(okHttp(http), System::currentTimeMillis, onConfig);
	}

	SiteConfigFetcher(Transport transport, LongSupplier clock, Consumer<SiteConfig> onConfig)
	{
		this.transport = transport;
		this.clock = clock;
		this.onConfig = onConfig;
	}

	synchronized SiteConfig current()
	{
		return current;
	}

	/** Call it every game tick with the current token. It asks when an ask is due, and does nothing otherwise. */
	void tick(String newToken)
	{
		String next = newToken == null ? "" : newToken.trim();
		SiteConfig reset = null;
		int askGeneration;
		synchronized (this)
		{
			if (!next.equals(token))
			{
				token = next;
				generation++;
				inFlight = false;
				settled = false;
				firstAskAtMillis = -1;
				nextAskAtMillis = 0;
				lastAskAtMillis = Long.MIN_VALUE / 2;
				namedVersion = -1;
				namedVersionAtAsk = -1;
				if (current != SiteConfig.DEFAULTS)
				{
					current = SiteConfig.DEFAULTS;
					reset = current;
				}
			}
			long now = clock.getAsLong();
			boolean ask = Tokens.wellFormed(token) && !inFlight && now >= nextAskAtMillis;
			if (ask)
			{
				inFlight = true;
				lastAskAtMillis = now;
				namedVersionAtAsk = namedVersion;
				if (firstAskAtMillis < 0)
				{
					firstAskAtMillis = now;
				}
			}
			askGeneration = ask ? generation : -1;
		}
		if (reset != null)
		{
			onConfig.accept(reset);
		}
		if (askGeneration >= 0)
		{
			transport.get(Endpoints.pluginConfig(), next, (status, body) -> answer(askGeneration, status, body));
		}
	}

	/**
	 * A stored sync named {@code version} as the config the site serves now. A version higher than any named before,
	 * and than the config's, asks again soon. Repeating the same version asks nothing more, so a site whose syncs and
	 * config disagree costs one ask, not one a minute.
	 */
	synchronized void changed(int version)
	{
		if (version <= namedVersion)
		{
			return;
		}
		namedVersion = version;
		if (version > current.version && !inFlight)
		{
			nextAskAtMillis = Math.min(nextAskAtMillis, lastAskAtMillis + SOONEST_REFRESH_MILLIS);
		}
	}

	/**
	 * True while syncs for this token should wait for the config: asked, with no config or 404 yet, and not for long.
	 * An error ends the wait only when the time is up, so a paused part does not go out because one ask failed.
	 */
	synchronized boolean awaitingFirstAnswer()
	{
		return !settled && firstAskAtMillis >= 0 && clock.getAsLong() - firstAskAtMillis < FIRST_ANSWER_WAIT_MILLIS;
	}

	private void answer(int askGeneration, int status, String body)
	{
		SiteConfig use;
		synchronized (this)
		{
			if (askGeneration != generation)
			{
				return;
			}
			inFlight = false;
			long now = clock.getAsLong();
			SiteConfig served = status == 200 ? SiteConfig.parseOrNull(body) : null;
			if (served != null)
			{
				current = served;
				settled = true;
				nextAskAtMillis = now + current.refreshSeconds * 1_000L;
			}
			else if (status == 404)
			{
				current = SiteConfig.DEFAULTS;
				settled = true;
				nextAskAtMillis = now + NOT_SERVED_RETRY_MILLIS;
			}
			else
			{
				nextAskAtMillis = now + RETRY_MILLIS;
			}
			if (namedVersion > namedVersionAtAsk && namedVersion > current.version)
			{
				// A sync named a newer config while this ask was out, and this answer is older: ask once more soon.
				nextAskAtMillis = Math.min(nextAskAtMillis, lastAskAtMillis + SOONEST_REFRESH_MILLIS);
			}
			use = current;
		}
		onConfig.accept(use);
	}

	/** The transport the plugin uses: the {@code GET} through {@code http}, which names the plugin's version. */
	static Transport okHttp(OkHttpClient http)
	{
		return (url, token, handler) ->
		{
			Request request = new Request.Builder()
				.url(url)
				.header("Authorization", "Bearer " + token)
				.header("Accept", "application/json")
				// Always from the site: the shared client's disk cache keys by address, not by token.
				.cacheControl(CacheControl.FORCE_NETWORK)
				.get()
				.build();
			http.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					handler.handle(-1, "");
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					int status = response.code();
					String body;
					try (ResponseBody responseBody = response.body())
					{
						body = responseBody == null ? "" : bounded(responseBody);
					}
					catch (IOException e)
					{
						body = null;
					}
					if (body == null)
					{
						handler.handle(-1, "");
						return;
					}
					handler.handle(status, body);
				}
			});
		};
	}

	/**
	 * The body as text, or null when it is larger than {@link #MAX_BODY_BYTES}. A config is a few hundred kilobytes
	 * at most, so anything far larger is not one, and it is never read whole into memory.
	 */
	static String bounded(ResponseBody body) throws IOException
	{
		return SiteHttp.bounded(body, MAX_BODY_BYTES);
	}
}

package com.osrsindex;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

/**
 * The HTTP client for every request this plugin makes to osrsindex.com: the sync, link start, link poll and
 * the destinations socket's upgrade. Each one names this plugin's version in {@value #VERSION_HEADER}, so the
 * site can show which version each linked client runs and tell a player when an update is really needed.
 *
 * <p>The client is derived from RuneLite's shared one with {@code newBuilder()}, so it shares that client's
 * connection pool and threads. The shared client itself is never changed: other plugins use it, and the
 * header means something only to osrsindex.com.
 */
final class SiteHttp
{
	/**
	 * The header the site's plugin contract names. It is optional: a site that does not read it, or reads a
	 * value it cannot use, answers exactly as it would without it.
	 */
	static final String VERSION_HEADER = "X-OSRS-Index-Plugin";

	private SiteHttp()
	{
	}

	/**
	 * A client for osrsindex.com, derived from {@code shared}, that sends {@code version} on every request. It follows
	 * no redirect: a sync redirected elsewhere would arrive as a GET whose answer could read as stored, and every
	 * route the plugin uses answers where it is asked.
	 */
	static OkHttpClient derive(OkHttpClient shared, String version)
	{
		return shared.newBuilder()
			.followRedirects(false)
			.followSslRedirects(false)
			.addInterceptor(new VersionHeader(version))
			.build();
	}

	/** An answer's body as text, or null when it is over {@code maxBytes}: it is never read whole into memory. */
	static String bounded(ResponseBody body, long maxBytes) throws IOException
	{
		if (body.contentLength() > maxBytes)
		{
			return null;
		}
		BufferedSource source = body.source();
		if (source.request(maxBytes + 1L))
		{
			return null;
		}
		return source.getBuffer().readString(StandardCharsets.UTF_8);
	}

	/**
	 * Sets the version header on each request, replacing any value already there. An application
	 * interceptor, so it also runs for a WebSocket's upgrade request.
	 */
	static final class VersionHeader implements Interceptor
	{
		private final String version;

		VersionHeader(String version)
		{
			this.version = version;
		}

		@Override
		public Response intercept(Chain chain) throws IOException
		{
			return chain.proceed(chain.request().newBuilder().header(VERSION_HEADER, version).build());
		}
	}
}

package com.osrsindex;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.InventoryID;

/**
 * Item stores the client can read only while they are open or checked, as with the bank. The last
 * copy of each is kept in the RuneLite profile, so a sync always carries every store seen so far.
 */
final class StorageTracker
{
	/** Store key -> the container id it is read from. */
	static final Map<String, Integer> STORES = new LinkedHashMap<>();

	static
	{
		STORES.put("looting_bag", InventoryID.LOOTING_BAG);
		STORES.put("seed_vault", InventoryID.SEED_VAULT);
		STORES.put("group_storage", InventoryID.INV_GROUP_TEMP);
		STORES.put("quiver", InventoryID.DIZANAS_QUIVER_AMMO);
		STORES.put("poh_costumes", InventoryID.POH_COSTUMES);
		STORES.put("forestry_kit", InventoryID.FORESTRY_KIT);
		STORES.put("huntsmans_kit", InventoryID.HUNTSMANS_KIT);
	}

	private final Map<String, JsonArray> stores = new LinkedHashMap<>();

	/** The store key for a container id, or null when it is not one of ours. */
	static String keyFor(int containerId)
	{
		for (Map.Entry<String, Integer> entry : STORES.entrySet())
		{
			if (entry.getValue() == containerId)
			{
				return entry.getKey();
			}
		}
		return null;
	}

	/** Returns true when the store changed. */
	boolean put(String key, JsonArray items)
	{
		if (key == null || items == null || items.equals(stores.get(key)))
		{
			return false;
		}
		stores.put(key, items);
		return true;
	}

	int size()
	{
		return stores.size();
	}

	void clear()
	{
		stores.clear();
	}

	JsonObject toJson()
	{
		JsonObject out = new JsonObject();
		stores.forEach(out::add);
		return out;
	}

	void load(String saved)
	{
		stores.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		try
		{
			JsonElement parsed = new JsonParser().parse(saved);
			if (!parsed.isJsonObject())
			{
				return;
			}
			for (Map.Entry<String, JsonElement> entry : parsed.getAsJsonObject().entrySet())
			{
				if (STORES.containsKey(entry.getKey()) && entry.getValue().isJsonArray())
				{
					stores.put(entry.getKey(), items(entry.getValue().getAsJsonArray()));
				}
			}
		}
		catch (RuntimeException ignored)
		{
			// A malformed profile value loads as empty.
		}
	}

	/**
	 * A saved store's items as the reader writes them, and nothing else: an edited or damaged profile cannot put
	 * anything else into the sync.
	 */
	static JsonArray items(JsonArray saved)
	{
		JsonArray out = new JsonArray();
		for (JsonElement element : saved)
		{
			if (out.size() >= CharacterReader.MAX_BANK_ITEMS)
			{
				break;
			}
			if (!element.isJsonObject())
			{
				continue;
			}
			JsonObject item = element.getAsJsonObject();
			JsonElement id = item.get("id");
			JsonElement quantity = item.get("quantity");
			if (id == null || quantity == null || !id.isJsonPrimitive() || !quantity.isJsonPrimitive()
				|| !id.getAsJsonPrimitive().isNumber() || !quantity.getAsJsonPrimitive().isNumber())
			{
				continue;
			}
			double idValue = id.getAsDouble();
			double quantityValue = quantity.getAsDouble();
			if (idValue >= 0 && idValue <= CharacterReader.MAX_ITEM_ID && idValue == Math.rint(idValue)
				&& quantityValue > 0 && quantityValue <= Integer.MAX_VALUE && quantityValue == Math.rint(quantityValue))
			{
				out.add(CharacterReader.itemJson((int) idValue, (int) quantityValue));
			}
		}
		return out;
	}
}

package com.osrsindex;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.EnumSet;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * What one sync response means for the plugin, decided from the status, the reason code (and, for a
 * refusal, the part it names) and `Retry-After` alone. The waits are the site config's
 * ({@link SiteConfig.Timing}). The body may also carry a {@code player_message} to show in place of the
 * plugin's own line, and a stored sync a {@code config_version} (docs/site-config.md).
 */
final class SyncOutcome
{
	enum Kind
	{
		/** 200: the parts sent are stored. */
		STORED,
		/**
		 * 400 unsupported_schema, or unknown_field: the server predates this schema; step down one. A
		 * server from before schema 2 checks fields before the schema number, so it says unknown_field.
		 */
		OLD_SERVER,
		/**
		 * 400 invalid_captured: the site refused the times in {@code captured}, not the parts they date. Nothing
		 * was stored. Send the same parts again at once without times, which the site then dates at
		 * {@code captured_at}, rather than drop data over a timing fault.
		 */
		PART_TIMES_REFUSED,
		/**
		 * Any other 400, or 415: the body broke the contract. Drop the part the site refused, or every
		 * part sent when it does not say which, rather than loop ({@link #dropped}).
		 */
		REJECTED,
		/** 401: the token is missing, unknown or revoked; stop until it changes. */
		BAD_TOKEN,
		/**
		 * 413: the body was too large. Several parts shrink the budget; a lone part is dropped, since no
		 * budget makes it smaller. Either way, wait: the site checks size before its rate limit.
		 */
		TOO_LARGE,
		/**
		 * 409 too_many_characters: the account already tracks as many characters as the site allows,
		 * and this is a new one. Nothing was stored. Try again only rarely, in case the player frees a
		 * slot on the site.
		 */
		ACCOUNT_FULL,
		/** 429, 503, 5xx or no response: wait, then send the latest state. */
		RETRY,
	}

	/** One sync per token per 30 seconds; a second more keeps clear of the boundary. */
	static final int FLOOR_SECONDS = 31;
	static final int DEFAULT_RETRY_SECONDS = 60;
	/** After ACCOUNT_FULL: fifteen minutes, so a full account costs the site four requests an hour, not sixty. */
	static final int ACCOUNT_FULL_RETRY_SECONDS = 900;

	final Kind kind;
	final String code;
	final int waitSeconds;
	/** REJECTED only: the part the site said it refused, or null when it named none this plugin knows. */
	final Part refused;
	/** The site's text for the player about this answer, already made safe ({@link SiteConfig#playerText}), or null. */
	final String playerMessage;
	/** STORED only: the site config revision the site serves now, or -1 when it did not say. */
	final int configVersion;

	private SyncOutcome(Kind kind, String code, int waitSeconds, Part refused, String playerMessage, int configVersion)
	{
		this.kind = kind;
		this.code = code;
		this.waitSeconds = waitSeconds;
		this.refused = refused;
		this.playerMessage = playerMessage;
		this.configVersion = configVersion;
	}

	static SyncOutcome networkFailure()
	{
		return networkFailure(SiteConfig.Timing.DEFAULTS);
	}

	static SyncOutcome networkFailure(SiteConfig.Timing timing)
	{
		return new SyncOutcome(Kind.RETRY, "network", timing.retrySeconds, null, null, -1);
	}

	static SyncOutcome of(int status, String body, String retryAfter)
	{
		return of(status, body, retryAfter, SiteConfig.Timing.DEFAULTS);
	}

	static SyncOutcome of(int status, String body, String retryAfter, SiteConfig.Timing timing)
	{
		JsonObject json = object(body);
		String code = field(json, "code");
		String message = SiteConfig.playerMessage(json);
		if (status == 200)
		{
			return new SyncOutcome(Kind.STORED, "stored", timing.syncFloorSeconds, null, null, configVersion(json));
		}
		if (status == 400 && ("unsupported_schema".equals(code) || "unknown_field".equals(code)))
		{
			return new SyncOutcome(Kind.OLD_SERVER, code, 0, null, message, -1);
		}
		if (status == 400 && "invalid_captured".equals(code))
		{
			return new SyncOutcome(Kind.PART_TIMES_REFUSED, code, 0, null, message, -1);
		}
		if (status == 400 || status == 415)
		{
			Part refused = status == 400 ? refusedPart(code, field(json, "part")) : null;
			return new SyncOutcome(Kind.REJECTED, code, 0, refused, message, -1);
		}
		if (status == 401)
		{
			return new SyncOutcome(Kind.BAD_TOKEN, code, 0, null, message, -1);
		}
		if (status == 413)
		{
			// The site answers 413 before its rate limiter sees the request, so without a wait here the
			// same body would go out again on the next game tick. A longer Retry-After still counts.
			return new SyncOutcome(Kind.TOO_LARGE, code, Math.max(timing.syncFloorSeconds, seconds(retryAfter) + 1),
				null, message, -1);
		}
		if (status == 409 && "too_many_characters".equals(code))
		{
			return new SyncOutcome(Kind.ACCOUNT_FULL, code, timing.accountFullRetrySeconds, null, message, -1);
		}
		int wait = seconds(retryAfter);
		return new SyncOutcome(Kind.RETRY, code, wait > 0 ? wait + 1 : timing.retrySeconds, null, message, -1);
	}

	/**
	 * The parts of a refused body to stop sending until they change. When the site named the part it
	 * refused, and that part was in the body, only that one: the rest were not at fault, so they stay
	 * dirty and go out on the next send. Otherwise every part sent, since sending the same body again
	 * would only be refused again.
	 */
	Set<Part> dropped(Set<Part> sent)
	{
		if (refused != null && sent.contains(refused))
		{
			return EnumSet.of(refused);
		}
		return sent;
	}

	/** What every section's refusal code starts with: {@code invalid_bank}, {@code invalid_vars} and so on. */
	private static final String INVALID_PREFIX = "invalid_";

	/**
	 * The part a 400 refusal names, or null when it names none this plugin knows. A fault inside a part answers
	 * that part's own code, {@code invalid_} plus its body key, and a bad item is no exception: it answers the
	 * code of the container it sits in, such as {@code invalid_bank} or {@code invalid_storage}. The envelope's
	 * codes ({@code invalid_character}, {@code invalid_captured_at}, {@code invalid_json}) match no part.
	 *
	 * <p>An older site answered every item fault {@code invalid_item}, which names no part, so from that site a
	 * bad item still drops everything sent. A {@code part} field wins over the code. No site sends one now, but
	 * reading it costs nothing and lets a site name the part outright, so it stays.
	 */
	static Part refusedPart(String code, String part)
	{
		Part named = byKey(part);
		if (named == null && code.startsWith(INVALID_PREFIX))
		{
			named = byKey(code.substring(INVALID_PREFIX.length()));
		}
		return named;
	}

	private static Part byKey(String key)
	{
		for (Part part : Part.values())
		{
			if (part.key.equals(key))
			{
				return part;
			}
		}
		return null;
	}

	static String code(String body)
	{
		return field(body, "code");
	}

	/** A string field of a JSON object body, or "" when the body is not one or does not carry it. */
	static String field(String body, String name)
	{
		return field(object(body), name);
	}

	private static String field(JsonObject object, String name)
	{
		return object != null && object.has(name) && object.get(name).isJsonPrimitive() ? object.get(name).getAsString() : "";
	}

	/** The body as a JSON object, or null when it is not one. */
	private static JsonObject object(String body)
	{
		if (body == null || body.isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement parsed = new JsonParser().parse(body);
			return parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
		}
		catch (RuntimeException ignored)
		{
			// Not JSON: a proxy error page. The status alone decides.
			return null;
		}
	}

	/** A stored sync's {@code config_version}: a whole number of 0 or more, else -1. */
	private static int configVersion(JsonObject json)
	{
		JsonElement value = json == null ? null : json.get("config_version");
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return -1;
		}
		double number = value.getAsDouble();
		return number >= 0 && number <= Integer.MAX_VALUE && number == Math.rint(number) ? (int) number : -1;
	}

	static int seconds(String retryAfter)
	{
		if (retryAfter == null)
		{
			return 0;
		}
		try
		{
			return Math.max(0, Math.min(3_600, Integer.parseInt(retryAfter.trim())));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/**
	 * A refusal's code as chat and the log may show it: the site's codes are lower-case words joined by
	 * underscores, and anything else, which could carry chat markup or line breaks, shows as {@code unknown}.
	 */
	static String plainCode(String code)
	{
		return code != null && PLAIN_CODE.matcher(code).matches() ? code : "unknown";
	}

	private static final Pattern PLAIN_CODE = Pattern.compile("[a-z0-9_]{1,40}");
}

package com.osrsindex;

import java.io.IOException;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Revokes this client's token on osrsindex.com when the player unlinks it. Forgetting the token in the
 * plugin's settings is not enough on its own: on the site the token would stay live, keep counting toward
 * the account's 5 linked clients, and keep working from any copy, such as an old RuneLite profile.
 *
 * <p>The request is one {@code DELETE} to {@link Endpoints#revokeToken()}, with the token as a bearer and no
 * body. It is sent once and never retried. The site answers 204 when it revoked the token, and 401 when it
 * no longer knows it, for example because it was already revoked on the account page. Both mean the token
 * is gone. Any other answer, such as a 429, a 503, or a 404 from a site without the route, leaves the token
 * possibly live, and so does no answer at all. Either way the player is told to revoke the client on the
 * account page.
 *
 * <p>The plugin forgets the token itself whatever the answer, so unlinking works offline. The site limits
 * this route to 5 requests a minute per address, in a bucket of its own. Each Unlink sends one request,
 * and the button is gone once the token is cleared, so that limit is never close.
 */
final class TokenRevoker
{
	/** What the site's answer means for the token. */
	enum Result
	{
		/** 204 or 401: the token no longer works on the site. */
		CONFIRMED,
		/** Any other status: the site did not say the token is gone. */
		NOT_CONFIRMED,
		/** No response: offline, timed out, or the site could not be reached. */
		NO_RESPONSE,
	}

	/** One {@code DELETE} with the token as a bearer, answered with its status, or -1 for no response. */
	interface Transport
	{
		void delete(String url, String token, IntConsumer status);
	}

	/** What chat adds whenever the site did not confirm the revoke. */
	static final String REVOKE_ON_THE_SITE = "Revoke this client on your osrsindex.com account page to be sure.";

	private final Transport transport;

	TokenRevoker(OkHttpClient http)
	{
		this(okHttp(http));
	}

	TokenRevoker(Transport transport)
	{
		this.transport = transport;
	}

	/** Ask the site to revoke {@code token}, once. {@code done} gets the result on whichever thread answered. */
	void revoke(String token, Consumer<Result> done)
	{
		transport.delete(Endpoints.revokeToken(), token, status -> done.accept(result(status)));
	}

	static Result result(int status)
	{
		if (status == 204 || status == 401)
		{
			return Result.CONFIRMED;
		}
		return status < 0 ? Result.NO_RESPONSE : Result.NOT_CONFIRMED;
	}

	/** The chat line that says whether the site confirmed the revoke. */
	static String chatLine(Result result)
	{
		switch (result)
		{
			case CONFIRMED:
				return "osrsindex.com confirmed that this client's link is revoked.";
			case NO_RESPONSE:
				return "osrsindex.com could not be reached to revoke this client's link. " + REVOKE_ON_THE_SITE;
			case NOT_CONFIRMED:
			default:
				return "osrsindex.com did not confirm that this client's link is revoked. " + REVOKE_ON_THE_SITE;
		}
	}

	/** The transport the plugin uses: the {@code DELETE} through {@code http}. Only the status is read. */
	static Transport okHttp(OkHttpClient http)
	{
		return (url, token, status) ->
		{
			Request request = new Request.Builder()
				.url(url)
				.header("Authorization", "Bearer " + token)
				.delete()
				.build();
			http.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					status.accept(-1);
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					// Closing the response frees the connection; its body, if any, says nothing more.
					try (Response closing = response)
					{
						status.accept(closing.code());
					}
				}
			});
		};
	}
}

package com.osrsindex;

import java.util.regex.Pattern;

/**
 * The link token's form. A token goes into an {@code Authorization} header, and OkHttp refuses a header value with
 * any character outside printable ASCII by throwing an exception whose message holds the whole value. So no request
 * is ever built with a token that has not passed {@link #wellFormed}.
 */
final class Tokens
{
	static final String PREFIX = "osrsidx_";

	/** The site issues {@code osrsidx_} and 43 base64url characters; this allows some room either way. */
	private static final Pattern FORM = Pattern.compile("osrsidx_[A-Za-z0-9_-]{16,256}");

	/** Spaces of every kind, invisible format characters and control characters, which a copy and paste can carry. */
	private static final Pattern INVISIBLE = Pattern.compile("[\\p{Z}\\p{Cf}\\p{Cc}]");

	private Tokens()
	{
	}

	/** The token as set, with every space, invisible and control character removed; empty for none. */
	static String normalize(String raw)
	{
		return raw == null ? "" : INVISIBLE.matcher(raw).replaceAll("");
	}

	/** Whether {@code token} has the site's form, and so is safe to send. */
	static boolean wellFormed(String token)
	{
		return token != null && FORM.matcher(token).matches();
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * Linking with one click: the approval page the panel opens, and the early poll
 * when the player comes back from the browser, kept inside the site's 5-a-minute limit.
 */
public class AccountLinkerTest
{
	private static final String CODE = "KXQ4-7MNP";

	private long now = 1_000_000L;
	private final List<String> urls = new ArrayList<>();
	private final List<Long> requestTimes = new ArrayList<>();
	private final List<AccountLinker.Handler> pending = new ArrayList<>();
	private final List<AccountLinker.State> states = new ArrayList<>();
	private final List<String> tokens = new ArrayList<>();

	private final AccountLinker linker = new AccountLinker(
		(url, body, handler) ->
		{
			urls.add(url);
			requestTimes.add(now);
			pending.add(handler);
		},
		() -> now,
		new AccountLinker.Listener()
		{
			@Override
			public void stateChanged(AccountLinker.State state, String userCode)
			{
				states.add(state);
			}

			@Override
			public void linked(String token)
			{
				tokens.add(token);
			}
		});

	private static JsonObject started(String complete)
	{
		JsonObject json = new JsonObject();
		json.addProperty("device_code", "osrsidl_" + "a".repeat(43));
		json.addProperty("user_code", CODE);
		json.addProperty("verification_url", Endpoints.origin() + "/link");
		if (complete != null)
		{
			json.addProperty("verification_url_complete", complete);
		}
		json.addProperty("expires_in", 600);
		json.addProperty("interval", 15);
		return json;
	}

	private static JsonObject status(String status)
	{
		JsonObject json = new JsonObject();
		json.addProperty("status", status);
		return json;
	}

	/** Answer the oldest request. */
	private void answer(int status, JsonObject json)
	{
		pending.remove(0).handle(status, json);
	}

	@Test
	public void theSitesPlayerMessageForARefusedLinkIsKept()
	{
		linker.start("Zezima");
		JsonObject full = new JsonObject();
		full.addProperty("code", "too_many_tokens");
		full.addProperty("player_message", "You have 8 linked clients, the most allowed.\nRevoke one first.");
		answer(503, full);
		assertEquals("You have 8 linked clients, the most allowed. Revoke one first.", linker.playerMessage());

		linker.start("Zezima");
		assertNull("a new start forgets the last answer's message", linker.playerMessage());
		answer(429, new JsonObject());
		assertNull(linker.playerMessage());
	}

	@Test
	public void aCodeThatExpiresHereDropsTheSitesLastMessage()
	{
		startWaiting(null);
		now += 15_000;
		linker.tick();
		JsonObject busy = new JsonObject();
		busy.addProperty("player_message", "Linking is slow right now.");
		answer(503, busy);
		assertEquals("Linking is slow right now.", linker.playerMessage());

		now += 601_000;
		linker.tick();
		assertEquals(AccountLinker.State.EXPIRED, linker.state());
		assertNull(linker.playerMessage());
	}

	private void startWaiting(String complete)
	{
		linker.start("Zezima");
		answer(200, started(complete));
		assertEquals(AccountLinker.State.WAITING, linker.state());
	}

	@Test
	public void opensTheSitesCompleteAddressForTheCode()
	{
		String complete = Endpoints.origin() + "/link?code=" + CODE;
		startWaiting(complete);
		assertEquals(complete, linker.approvalUrl());
		assertEquals(CODE, linker.userCode());
	}

	@Test
	public void buildsTheAddressWhenASiteFromBefore741SendsNone()
	{
		startWaiting(null);
		assertEquals("https://osrsindex.com/link?code=KXQ4-7MNP", linker.approvalUrl());
	}

	@Test
	public void neverOpensAnAddressOnAnotherOrigin()
	{
		startWaiting("https://evil.example/link?code=" + CODE);
		assertEquals(Endpoints.linkApproval(CODE), linker.approvalUrl());
		startWaiting("https://osrsindex.com.evil.example/link");
		assertEquals(Endpoints.linkApproval(CODE), linker.approvalUrl());
	}

	@Test
	public void hasNoAddressUnlessACodeIsWaiting()
	{
		assertNull(linker.approvalUrl());
		linker.start("Zezima");
		assertNull(linker.approvalUrl());
		answer(429, null);
		assertEquals(AccountLinker.State.EXPIRED, linker.state());
		assertNull(linker.approvalUrl());
	}

	@Test
	public void pollsAtOnceWhenThePlayerComesBackAndLinks()
	{
		startWaiting(null);
		now += 8_000;
		linker.tick();
		assertEquals(1, urls.size()); // only the start: the first poll is due at 15 s
		linker.pollSoon();
		linker.tick();
		assertEquals(Endpoints.linkPoll(), urls.get(1));
		answer(200, status("pending"));
		assertTrue(tokens.isEmpty());

		JsonObject approved = status("approved");
		approved.addProperty("token", OsrsIndexPlugin.TOKEN_PREFIX + "b".repeat(43));
		now += 15_000;
		linker.tick();
		answer(200, approved);
		assertEquals(1, tokens.size());
		assertEquals(AccountLinker.State.IDLE, linker.state());
		assertNull(linker.approvalUrl());
	}

	@Test
	public void theEarlyPollWaitsFiveSecondsAfterTheLastRequest()
	{
		startWaiting(null);
		now += AccountLinker.EARLY_POLL_GAP_MILLIS - 1;
		linker.pollSoon();
		linker.tick();
		assertEquals(1, urls.size());
		now += 1;
		linker.pollSoon();
		linker.tick();
		assertEquals(2, urls.size());
	}

	@Test
	public void checkingTheCodeInTheClientDoesNotUseUpTheEarlyPoll()
	{
		// Switching back to compare the code must not spend the only early poll, or the link itself waits
		// out the 15 s interval. Every return polls, within the limit.
		startWaiting(null);
		now += 6_000; // back in RuneLite to compare the code
		linker.pollSoon();
		linker.tick();
		answer(200, status("pending"));

		JsonObject approved = status("approved");
		approved.addProperty("token", OsrsIndexPlugin.TOKEN_PREFIX + "c".repeat(43));
		now += 6_000; // approved in the browser, and back again
		linker.pollSoon();
		linker.tick();
		assertEquals(3, urls.size());
		answer(200, approved);
		assertEquals(1, tokens.size());
	}

	@Test
	public void earlyPollsLeaveTheScheduledOneASlot()
	{
		long start = now;
		startWaiting(null); // request 1, at 0 s
		for (int i = 1; i <= 3; i++) // returns at 5, 10 and 15 s
		{
			now = start + i * AccountLinker.EARLY_POLL_GAP_MILLIS;
			linker.pollSoon();
			linker.tick();
			while (!pending.isEmpty())
			{
				answer(200, status("pending"));
			}
		}
		// Early polls took 2 of the minute's 4, then stopped: the third return was dropped.
		assertEquals(AccountLinker.MAX_REQUESTS_PER_MINUTE - 1, urls.size());

		// The scheduled poll, 15 s after the last one (at 10 s), still gets the fourth slot.
		now = start + 25_000;
		linker.tick();
		assertEquals(AccountLinker.MAX_REQUESTS_PER_MINUTE, urls.size());
		answer(200, status("pending"));

		// The next is due at 40 s, but the minute is full until the start is 60 s old.
		now = start + 40_000;
		linker.tick();
		assertEquals(AccountLinker.MAX_REQUESTS_PER_MINUTE, urls.size());
		now = start + 60_000;
		linker.tick();
		assertEquals(AccountLinker.MAX_REQUESTS_PER_MINUTE + 1, urls.size());
	}

	@Test
	public void focusingOverAndOverNeverPassesFourRequestsAMinute()
	{
		// The site counts link requests per address, 5 a minute; the plugin keeps to 4. Focus the client
		// every second for the whole life of a code, and check every 60 s window.
		startWaiting(null);
		long end = now + 600_000;
		while (now < end)
		{
			now += 1_000;
			linker.pollSoon();
			linker.tick();
			while (!pending.isEmpty())
			{
				answer(200, status("pending"));
			}
		}
		for (long start : requestTimes)
		{
			long inWindow = requestTimes.stream().filter(t -> t >= start && t < start + 60_000).count();
			assertTrue("requests in the minute from " + start + ": " + inWindow,
				inWindow <= AccountLinker.MAX_REQUESTS_PER_MINUTE);
		}
	}

	@Test
	public void aCodeThatIsNotPlainLettersAndDigitsIsNeverShown()
	{
		for (String code : new String[]{"<html><img src='https://example.com/p.png'>", "<col=ff0000>KXQ4", "KXQ4 7MNP", ""})
		{
			linker.start("Zezima");
			JsonObject json = started(null);
			json.addProperty("user_code", code);
			answer(200, json);
			assertEquals(code, AccountLinker.State.UNAVAILABLE, linker.state());
		}
	}

	@Test
	public void aStartAnswerOfTheWrongShapeIsUnavailableAndLinkStillWorksAfter()
	{
		linker.start("Zezima");
		JsonObject json = started(null);
		json.add("expires_in", com.google.gson.JsonNull.INSTANCE);
		json.addProperty("interval", "soon");
		answer(200, json);
		assertEquals("missing numbers fall back to the defaults", AccountLinker.State.WAITING, linker.state());

		linker.cancel();
		linker.start("Zezima");
		JsonObject broken = started(null);
		broken.add("device_code", com.google.gson.JsonNull.INSTANCE);
		answer(200, broken);
		assertEquals(AccountLinker.State.UNAVAILABLE, linker.state());

		linker.start("Zezima");
		answer(200, started(null));
		assertEquals("Link works again after a bad answer", AccountLinker.State.WAITING, linker.state());
	}

	@Test
	public void anApprovedTokenThatCouldNotBeSentIsNeverKept()
	{
		startWaiting(null);
		now += 15_000;
		linker.tick();
		JsonObject approved = status("approved");
		approved.addProperty("token", OsrsIndexPlugin.TOKEN_PREFIX + "b".repeat(42) + " ");
		answer(200, approved);
		assertTrue(tokens.isEmpty());
		assertEquals(AccountLinker.State.UNAVAILABLE, linker.state());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class CharacterReaderTest
{
	/** Where the fake player stands as the client reports it, which inside an instance is the instance's copy. */
	private static final WorldPoint INSTANCE_COPY = new WorldPoint(9000, 9000, 0);

	/** Scene tile (50, 50): chunk (6, 6), tile (2, 2) inside it. */
	private static final LocalPoint SCENE_TILE = new LocalPoint(50 << 7, 50 << 7, -1);

	private final Map<String, Function<Object[], Object>> client = new HashMap<>();
	private final Map<String, Function<Object[], Object>> view = new HashMap<>();

	private final CharacterReader reader = new CharacterReader(fake(Client.class, client), null);

	/**
	 * A fake of a RuneLite interface: each named method gives its answer, and every other method
	 * returns null, false or 0.
	 */
	@SuppressWarnings("unchecked")
	private static <T> T fake(Class<T> type, Map<String, Function<Object[], Object>> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (proxy, method, args) ->
		{
			Function<Object[], Object> answer = answers.get(method.getName());
			if (answer != null)
			{
				return answer.apply(args);
			}
			Class<?> returns = method.getReturnType();
			if (returns == boolean.class)
			{
				return false;
			}
			if (returns == int.class)
			{
				return 0;
			}
			if (returns == long.class)
			{
				return 0L;
			}
			if (returns == String.class)
			{
				return type.getSimpleName();
			}
			return null;
		});
	}

	private void standOnSceneTile(boolean instance)
	{
		Map<String, Function<Object[], Object>> player = new HashMap<>();
		player.put("getWorldLocation", args -> INSTANCE_COPY);
		player.put("getLocalLocation", args -> SCENE_TILE);
		client.put("getLocalPlayer", args -> fake(Player.class, player));
		client.put("getWorld", args -> 302);

		// Template chunk (400, 400), plane 0, no rotation: the real tile is (3202, 3202).
		int[][][] chunks = new int[4][13][13];
		chunks[0][6][6] = 400 << 14 | 400 << 3;
		view.put("isInstance", args -> instance);
		view.put("getInstanceTemplateChunks", args -> chunks);
		WorldView worldView = fake(WorldView.class, view);
		client.put("getTopLevelWorldView", args -> worldView);
		client.put("getWorldView", args -> worldView);
	}

	@Test
	public void skillsSendsEveryRealSkillAndNoOverall()
	{
		client.put("getSkillExperience", args -> 1_000 + ((Skill) args[0]).ordinal());
		client.put("getRealSkillLevel", args -> 10);

		JsonObject skills = reader.skills();

		assertNotNull(skills);
		assertEquals(Skill.values().length, skills.size());
		for (Skill skill : Skill.values())
		{
			JsonObject value = skills.getAsJsonObject(skill.name().toLowerCase(Locale.ROOT));
			assertEquals(1_000 + skill.ordinal(), value.get("xp").getAsInt());
			assertEquals(10, value.get("level").getAsInt());
		}
		assertTrue(skills.has("sailing"));
		assertFalse(skills.has("overall"));
	}

	@Test
	public void skillsAreNullUntilTheStatsArrive()
	{
		assertNull(reader.skills());
	}

	@Test
	public void locationOutsideAnInstanceIsWhereTheClientSaysThePlayerIs()
	{
		standOnSceneTile(false);

		JsonObject location = reader.location();

		assertNotNull(location);
		assertEquals(9000, location.get("x").getAsInt());
		assertEquals(9000, location.get("y").getAsInt());
		assertEquals(0, location.get("plane").getAsInt());
		assertEquals(302, location.get("world").getAsInt());
	}

	@Test
	public void locationInsideAnInstanceIsTheRealTileTheInstanceCopies()
	{
		standOnSceneTile(true);

		JsonObject location = reader.location();

		assertNotNull(location);
		assertEquals(3202, location.get("x").getAsInt());
		assertEquals(3202, location.get("y").getAsInt());
		assertEquals(0, location.get("plane").getAsInt());
	}

	@Test
	public void locationWithNoWorldViewYetIsWhereTheClientSaysThePlayerIs()
	{
		standOnSceneTile(true);
		client.put("getTopLevelWorldView", args -> null);

		JsonObject location = reader.location();

		assertNotNull(location);
		assertEquals(9000, location.get("x").getAsInt());
	}

	@Test
	public void locationIsNullWithoutAPlayer()
	{
		assertNull(reader.location());
	}

	@Test
	public void varsReadTheBuiltInListUnlessTheSiteChoseOthers()
	{
		client.put("getVarbitValue", args -> (Integer) args[0] + 1);
		client.put("getVarpValue", args -> (Integer) args[0] + 2);

		JsonObject builtIn = reader.vars(3);
		assertEquals(GameVars.VARBIT_IDS.length + GameVars.VARP_IDS.length, builtIn.size());
		assertEquals(GameVars.VARBIT_IDS[0] + 1, builtIn.get(GameVars.VARBIT_NAMES[0]).getAsInt());

		SiteConfig.Vars site = SiteConfig.parse("{\"vars\":{\"mode\":\"replace\",\"varbits\":{\"NEW_QUEST\":20512},"
			+ "\"varps\":{\"NEW_MINIGAME_POINTS\":6100}}}").vars;
		JsonObject chosen = reader.vars(3, site);
		assertEquals(2, chosen.size());
		assertEquals(20_513, chosen.get("NEW_QUEST").getAsInt());
		assertEquals(6_102, chosen.get("NEW_MINIGAME_POINTS").getAsInt());
	}

	@Test
	public void aVarTheClientCannotReadIsLeftOutFromThenOn()
	{
		int[] reads = {0};
		client.put("getVarbitValue", args ->
		{
			reads[0]++;
			if ((Integer) args[0] == 60_000)
			{
				throw new IndexOutOfBoundsException("no such varbit");
			}
			return 1;
		});
		client.put("getVarpValue", args ->
		{
			throw new ArrayIndexOutOfBoundsException("no such varp");
		});
		SiteConfig.Vars site = SiteConfig.parse("{\"vars\":{\"mode\":\"replace\",\"varbits\":{\"BAD_QUEST\":60000,"
			+ "\"GOOD_QUEST\":30001},\"varps\":{\"ALSO_BAD_QUEST\":65000}}}").vars;

		JsonObject first = reader.vars(3, site);
		assertEquals(1, first.size());
		assertEquals(1, first.get("GOOD_QUEST").getAsInt());
		assertEquals(2, reads[0]);

		JsonObject second = reader.vars(3, site);
		assertEquals(1, second.size());
		assertEquals("the unreadable varbit is not tried again", 3, reads[0]);

		reader.forgetUnreadableVars();
		reader.vars(3, site);
		assertEquals("a new session tries it again", 5, reads[0]);
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import org.junit.Test;

public class CollectionLogTrackerTest
{
	@Test
	public void recordsObtainedItemsAndIgnoresUnobtainedOnes()
	{
		CollectionLogTracker tracker = new CollectionLogTracker();
		assertTrue(tracker.record(4151, 3));
		assertFalse(tracker.record(11286, 0));
		assertFalse(tracker.record(4151, 3));
		assertTrue(tracker.record(4151, 4));
		assertEquals(1, tracker.size());
	}

	@Test
	public void survivesARoundTripThroughTheProfile()
	{
		CollectionLogTracker tracker = new CollectionLogTracker();
		tracker.record(4151, 3);
		tracker.record(11286, 1);
		String saved = new Gson().toJson(tracker.toJson());

		CollectionLogTracker restored = new CollectionLogTracker();
		restored.load(saved);

		assertEquals(tracker.toJson(), restored.toJson());
	}

	@Test
	public void aMalformedSavedValueLoadsAsEmptyInsteadOfThrowing()
	{
		CollectionLogTracker tracker = new CollectionLogTracker();
		tracker.load("{not json");
		assertEquals(0, tracker.size());
		tracker.load("[{\"id\":\"x\"},{\"id\":4151,\"quantity\":2}]");
		assertEquals(1, tracker.size());
	}

	@Test
	public void stopsAtTheContractCap()
	{
		CollectionLogTracker tracker = new CollectionLogTracker();
		for (int id = 0; id < CollectionLogTracker.MAX_ITEMS + 10; id++)
		{
			tracker.record(id, 1);
		}
		assertEquals(CollectionLogTracker.MAX_ITEMS, tracker.size());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

/**
 * Every destination the socket delivers with an id the site can match ends in one {@code ack} frame on that
 * socket, carrying what became of it: {@code routed}, {@code no_pathing_plugin}, {@code expired} or
 * {@code invalid}. A routed one also goes to the pathing plugin, with a chat line. Wired as the plugin wires it.
 */
public class DestinationReceiverTest
{
	private static final Instant NOW = Instant.parse("2026-09-26T12:00:00Z");
	private static final String TOKEN = OsrsIndexPlugin.TOKEN_PREFIX + "abcdefghijabcdefghijabcdefghijabcdefghijabc";

	private final List<PluginMessage> posted = new ArrayList<>();
	private final List<String> chat = new ArrayList<>();
	private final List<String> sent = new ArrayList<>();
	private boolean shortestPathOn = true;
	private DestinationSocket.Events events;
	private DestinationSocket.Connection connection;
	private DestinationReceiver receiver;

	private final DestinationSocket socket = new DestinationSocket(
		(token, events) ->
		{
			this.events = events;
			connection = new DestinationSocket.Connection()
			{
				@Override
				public boolean send(String text)
				{
					return sent.add(text);
				}

				@Override
				public void close(int code, String reason)
				{
				}
			};
			return connection;
		},
		(task, delay) -> () -> { },
		new Random(1),
		destination -> receiver.accept(destination),
		status -> { });

	private void listen()
	{
		RouteDispatcher dispatcher = new RouteDispatcher(posted::add,
			plugin -> plugin == PathingPlugin.SHORTEST_PATH && shortestPathOn, Clock.fixed(NOW, ZoneOffset.UTC));
		// As the plugin wires it: always Shortest Path, never Farm Route Planner.
		receiver = new DestinationReceiver(dispatcher, () -> RouteWith.SHORTEST_PATH, chat::add, socket::ack);
		socket.update(true, TOKEN, true, true);
		events.opened(connection, DestinationSocket.SUBPROTOCOL);
		events.text(connection, "{\"type\":\"hello\",\"protocol\":1}");
	}

	private void deliver(String id, String label)
	{
		events.text(connection, "{\"type\":\"destination\",\"id\":\"" + id + "\",\"x\":3036,\"y\":3294,\"plane\":0,"
			+ "\"label\":\"" + label + "\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
	}

	private static String ack(String id, String result)
	{
		return "{\"type\":\"ack\",\"id\":\"" + id + "\",\"result\":\"" + result + "\"}";
	}

	@Test
	public void aRoutedDestinationGetsTheChatLineAndIsAckedRouted()
	{
		listen();
		deliver("d-1", "Sarah");
		deliver("d-2", "Tile 3100, 3650, 0");

		assertEquals(2, posted.size());
		assertEquals("shortestpath", posted.get(0).getNamespace());
		assertEquals("shortestpath", posted.get(1).getNamespace());
		assertEquals("path", posted.get(0).getName());
		assertEquals(new WorldPoint(3036, 3294, 0), posted.get(0).getData().get("target"));
		assertEquals("osrsindex.com: routing to Sarah (3036, 3294, 0) with Shortest Path.", chat.get(0));
		assertEquals(Arrays.asList(ack("d-1", "routed"), ack("d-2", "routed")), sent);
		assertEquals(2, chat.size());
	}

	@Test
	public void aRepeatedIdIsAckedRoutedAgainButRoutedOnce()
	{
		listen();
		deliver("d-1", "Sarah");
		deliver("d-1", "Sarah");
		assertEquals(1, posted.size());
		assertEquals(1, chat.size());
		assertEquals(Arrays.asList(ack("d-1", "routed"), ack("d-1", "routed")), sent);
	}

	@Test
	public void withShortestPathOffThePlayerIsToldAndItIsAckedNoPathingPlugin()
	{
		shortestPathOn = false;
		listen();
		deliver("d-1", "Sarah");
		assertTrue(posted.isEmpty());
		assertEquals(1, chat.size());
		assertEquals("osrsindex.com sent Sarah (3036, 3294, 0), but Shortest Path is not on.", chat.get(0));
		assertEquals(Collections.singletonList(ack("d-1", "no_pathing_plugin")), sent);
	}

	@Test
	public void onceShortestPathIsOnARedeliveredPlaceRoutesAndIsAckedRouted()
	{
		shortestPathOn = false;
		listen();
		deliver("d-1", "Sarah");
		shortestPathOn = true;
		deliver("d-1", "Sarah");
		assertEquals(1, posted.size());
		assertEquals(Arrays.asList(ack("d-1", "no_pathing_plugin"), ack("d-1", "routed")), sent);
	}

	@Test
	public void anExpiredPlaceIsAckedExpiredWithoutARouteOrAChatLine()
	{
		listen();
		// 31 s past expiry by the client's clock: one second beyond the allowed skew.
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-1\",\"x\":3036,\"y\":3294,\"plane\":0,"
			+ "\"label\":\"Sarah\",\"expires_at\":\"2026-09-26T11:59:29Z\"}");
		assertTrue(posted.isEmpty());
		assertTrue(chat.isEmpty());
		assertEquals(Collections.singletonList(ack("d-1", "expired")), sent);
	}

	@Test
	public void anOutOfRangePlaceIsAckedInvalidWithoutARouteOrAChatLine()
	{
		listen();
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-1\",\"x\":16384,\"y\":3294,\"plane\":0,"
			+ "\"label\":\"Sarah\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-2\",\"x\":3036,\"y\":3294,\"plane\":4,"
			+ "\"label\":\"Sarah\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		assertTrue(posted.isEmpty());
		assertTrue(chat.isEmpty());
		assertEquals(Arrays.asList(ack("d-1", "invalid"), ack("d-2", "invalid")), sent);
	}

	@Test
	public void aPlaceThisVersionCannotReadIsAckedInvalid()
	{
		listen();
		// A coordinate as text, a fractional one, an unreadable time, and no label: each still has an id.
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-1\",\"x\":\"3036\",\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-2\",\"x\":1.5,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-3\",\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"yesterday\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d-4\",\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		assertTrue(posted.isEmpty());
		assertTrue(chat.isEmpty());
		assertEquals(Arrays.asList(ack("d-1", "invalid"), ack("d-2", "invalid"), ack("d-3", "invalid"),
			ack("d-4", "invalid")), sent);
	}

	@Test
	public void aPlaceWithNoIdTheSiteCanMatchIsDroppedUnacked()
	{
		listen();
		String tooLong = repeat('a', RouteDispatcher.MAX_ID_LENGTH + 1);
		events.text(connection, "{\"type\":\"destination\",\"x\":3036,\"y\":3294,\"plane\":0,"
			+ "\"label\":\"Sarah\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":7,\"x\":3036,\"y\":3294,\"plane\":0,"
			+ "\"label\":\"Sarah\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		deliver("", "Sarah");
		deliver(tooLong, "Sarah");
		assertTrue(posted.isEmpty());
		assertTrue(chat.isEmpty());
		assertTrue(sent.isEmpty());

		// 64 characters is the longest id the site matches.
		String longest = repeat('a', RouteDispatcher.MAX_ID_LENGTH);
		deliver(longest, "Sarah");
		assertEquals(Collections.singletonList(ack(longest, "routed")), sent);
	}

	@Test
	public void eachOutcomeIsAckedOnceAndEveryAckFitsTheSitesFrameLimit()
	{
		listen();
		String id = repeat('a', RouteDispatcher.MAX_ID_LENGTH);
		deliver(id, "Sarah");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"e\",\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T11:00:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"i\",\"x\":-1,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		shortestPathOn = false;
		deliver("n", "Sarah");

		assertEquals(Arrays.asList(ack(id, "routed"), ack("e", "expired"), ack("i", "invalid"),
			ack("n", "no_pathing_plugin")), sent);
		for (String frame : sent)
		{
			assertTrue(frame.getBytes(StandardCharsets.UTF_8).length <= 1_024);
		}
	}

	private static String repeat(char c, int n)
	{
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < n; i++)
		{
			builder.append(c);
		}
		return builder.toString();
	}

	@Test
	public void theLabelIsEscapedForChat()
	{
		listen();
		deliver("d-1", "<col=ff0000>Bank");
		assertTrue(chat.get(0).contains("<lt>col=ff0000<gt>Bank"));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;

/**
 * The destinations socket's state machine, against a fake connection and a fake
 * scheduler: when it opens, when it closes, when it comes back, and what it does with each frame.
 */
public class DestinationSocketTest
{
	private static final String TOKEN = OsrsIndexPlugin.TOKEN_PREFIX + repeat('a', 43);
	private static final String OTHER_TOKEN = OsrsIndexPlugin.TOKEN_PREFIX + repeat('b', 43);
	/** The relay's first frame on every socket. */
	private static final String HELLO = "{\"type\":\"hello\",\"protocol\":1}";

	private final List<FakeConnection> opened = new ArrayList<>();
	private final List<Scheduled> scheduled = new ArrayList<>();
	private final List<Destination> received = new ArrayList<>();
	private final List<DestinationSocket.Status> statuses = new ArrayList<>();
	private DestinationSocket.Events events;

	private final DestinationSocket socket = new DestinationSocket(
		(token, events) ->
		{
			this.events = events;
			FakeConnection connection = new FakeConnection(token);
			opened.add(connection);
			return connection;
		},
		(task, delayMillis) ->
		{
			Scheduled entry = new Scheduled(task, delayMillis);
			scheduled.add(entry);
			return () -> entry.cancelled = true;
		},
		new Random(7),
		received::add,
		statuses::add);

	private static final class FakeConnection implements DestinationSocket.Connection
	{
		final String token;
		final List<String> sent = new ArrayList<>();
		Integer closedWith;

		FakeConnection(String token)
		{
			this.token = token;
		}

		@Override
		public boolean send(String text)
		{
			sent.add(text);
			return true;
		}

		@Override
		public void close(int code, String reason)
		{
			closedWith = code;
		}
	}

	private static final class Scheduled
	{
		final Runnable task;
		final long delayMillis;
		boolean cancelled;

		Scheduled(Runnable task, long delayMillis)
		{
			this.task = task;
			this.delayMillis = delayMillis;
		}
	}

	private static String repeat(char c, int n)
	{
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < n; i++)
		{
			builder.append(c);
		}
		return builder.toString();
	}

	/** Open and accept a socket for TOKEN. */
	private FakeConnection listening()
	{
		socket.update(true, TOKEN, true, true);
		FakeConnection connection = last();
		events.opened(connection, DestinationSocket.SUBPROTOCOL);
		events.text(connection, "{\"type\":\"hello\",\"protocol\":1}");
		assertEquals(DestinationSocket.Status.LISTENING, socket.status());
		return connection;
	}

	private FakeConnection last()
	{
		return opened.get(opened.size() - 1);
	}

	private Scheduled pendingRetry()
	{
		Scheduled retry = null;
		for (Scheduled entry : scheduled)
		{
			if (!entry.cancelled)
			{
				retry = entry;
			}
		}
		return retry;
	}

	// --- criterion 2: off by default, and nothing opens without every condition --------------------

	@Test
	public void opensNoSocketWhileReceiveDestinationsIsOff()
	{
		socket.update(false, TOKEN, true, true);
		assertTrue(opened.isEmpty());
		assertEquals(DestinationSocket.Status.OFF, socket.status());
	}

	@Test
	public void opensNoSocketWithoutATokenOrWhileLoggedOut()
	{
		socket.update(true, "", true, true);
		socket.update(true, "not-one-of-ours", true, true);
		socket.update(true, TOKEN, false, true);
		assertTrue(opened.isEmpty());
		assertFalse(DestinationSocket.shouldListen(true, null, true));
	}

	@Test
	public void theSettingDefaultsToOn()
	{
		// A linked, logged-in client listens unless turned off.
		// Every setting is a default method, so this is exactly what a new install reads.
		OsrsIndexConfig defaults = new OsrsIndexConfig()
		{
		};
		assertTrue(defaults.receiveDestinations());
	}

	@Test
	public void everySettingHasATypeRuneLitesConfigProxyCanReach()
	{
		// A package-private enum as a setting's type throws IllegalAccessError inside the client.
		for (java.lang.reflect.Method method : OsrsIndexConfig.class.getDeclaredMethods())
		{
			Class<?> type = method.getReturnType();
			assertTrue(method.getName() + " returns " + type, type.isPrimitive()
				|| java.lang.reflect.Modifier.isPublic(type.getModifiers()));
		}
	}

	@Test
	public void opensOneSocketWithTheTokenWhenOptedInLinkedAndLoggedIn()
	{
		socket.update(true, TOKEN, true, true);
		socket.update(true, TOKEN, true, false);
		assertEquals(1, opened.size());
		assertEquals(TOKEN, opened.get(0).token);
		assertEquals(DestinationSocket.Status.CONNECTING, socket.status());
	}

	// --- criterion 4: unlink, revoke, logout and opt-out each close it; only a fresh link reopens ------

	@Test
	public void unlinkingClosesTheSocket()
	{
		FakeConnection connection = listening();
		socket.update(true, "", true, false);
		assertEquals(Integer.valueOf(DestinationSocket.CLOSE_NORMAL), connection.closedWith);
		assertEquals(DestinationSocket.Status.OFF, socket.status());
		assertNull(pendingRetry());
	}

	@Test
	public void loggingOutClosesTheSocket()
	{
		FakeConnection connection = listening();
		socket.update(true, TOKEN, false, false);
		assertEquals(Integer.valueOf(DestinationSocket.CLOSE_NORMAL), connection.closedWith);
		assertEquals(DestinationSocket.Status.OFF, socket.status());
	}

	@Test
	public void optingOutClosesTheSocket()
	{
		FakeConnection connection = listening();
		socket.update(false, TOKEN, true, false);
		assertEquals(Integer.valueOf(DestinationSocket.CLOSE_NORMAL), connection.closedWith);
		assertEquals(DestinationSocket.Status.OFF, socket.status());
	}

	@Test
	public void aRevokedTokenStaysClosedUntilAFreshLink()
	{
		FakeConnection connection = listening();
		events.closed(connection, DestinationSocket.CLOSE_REVOKED);

		assertEquals(DestinationSocket.Status.REVOKED, socket.status());
		assertNull(pendingRetry());
		// Logging in again, or toggling the setting, is not a new link.
		socket.update(true, TOKEN, false, false);
		socket.update(true, TOKEN, true, true);
		socket.update(false, TOKEN, true, true);
		socket.update(true, TOKEN, true, true);
		assertEquals(1, opened.size());
		assertEquals(DestinationSocket.Status.REVOKED, socket.status());

		socket.update(true, OTHER_TOKEN, true, true);
		assertEquals(2, opened.size());
		assertEquals(OTHER_TOKEN, last().token);
	}

	@Test
	public void aRefusedUpgradeWith401IsARevokedLink()
	{
		socket.update(true, TOKEN, true, true);
		events.failed(last(), 401, -1);
		assertEquals(DestinationSocket.Status.REVOKED, socket.status());
		assertNull(pendingRetry());
		socket.update(true, TOKEN, true, true);
		assertEquals(1, opened.size());
	}

	@Test
	public void aReplacedSocketStopsUntilThePlayerActs()
	{
		FakeConnection connection = listening();
		events.closed(connection, DestinationSocket.CLOSE_REPLACED);
		assertEquals(DestinationSocket.Status.REPLACED, socket.status());
		assertNull(pendingRetry());

		// A region load is not the player acting.
		socket.update(true, TOKEN, true, false);
		assertEquals(1, opened.size());

		socket.update(true, TOKEN, true, true);
		assertEquals(2, opened.size());
	}

	// --- reconnecting -----------------------------------------------------------------------------

	@Test
	public void anyOtherCloseReconnectsAfterABackoff()
	{
		for (int code : new int[]{1001, 1006, 1009, 1011, 1012, 4429})
		{
			FakeConnection connection = listening();
			events.closed(connection, code);
			Scheduled retry = pendingRetry();
			assertNotNull("close " + code + " schedules a retry", retry);
			assertEquals(DestinationSocket.Status.RETRYING, socket.status());
			int before = opened.size();
			retry.task.run();
			assertEquals(before + 1, opened.size());
			events.opened(last(), DestinationSocket.SUBPROTOCOL);
			// Reset for the next code.
			socket.update(false, TOKEN, true, false);
			scheduled.clear();
		}
	}

	@Test
	public void aNetworkFailureRetriesAndHonoursRetryAfter()
	{
		socket.update(true, TOKEN, true, true);
		events.failed(last(), 429, 90);
		assertTrue(pendingRetry().delayMillis >= 90_000);

		pendingRetry().task.run();
		events.failed(last(), 0, -1);
		assertNotNull(pendingRetry());
	}

	@Test
	public void theBackoffDoublesFrom15SecondsTo5MinutesWithin20Percent()
	{
		Random random = new Random(1);
		long[] bases = {15_000, 30_000, 60_000, 120_000, 240_000, 300_000, 300_000};
		for (int failures = 0; failures < bases.length; failures++)
		{
			for (int sample = 0; sample < 50; sample++)
			{
				long delay = DestinationSocket.retryDelayMillis(failures, -1, random);
				assertTrue(delay >= Math.round(bases[failures] * 0.8));
				assertTrue(delay <= Math.round(bases[failures] * 1.2));
			}
		}
		assertTrue(DestinationSocket.retryDelayMillis(0, 600, random) >= 600_000);
	}

	@Test
	public void theSiteConfigSetsTheBackoffsFirstAndLongestWait()
	{
		Random random = new Random(2);
		long[] bases = {30_000, 60_000, 120_000, 120_000};
		for (int failures = 0; failures < bases.length; failures++)
		{
			long delay = DestinationSocket.retryDelayMillis(failures, -1, random, 30_000, 120_000);
			assertTrue(delay >= Math.round(bases[failures] * 0.8));
			assertTrue(delay <= Math.round(bases[failures] * 1.2));
		}
	}

	@Test
	public void aSuccessfulOpenResetsTheBackoff()
	{
		socket.update(true, TOKEN, true, true);
		events.failed(last(), 0, -1);
		pendingRetry().task.run();
		events.failed(last(), 0, -1);
		long second = pendingRetry().delayMillis;
		assertTrue(second >= 24_000);

		pendingRetry().task.run();
		events.opened(last(), DestinationSocket.SUBPROTOCOL);
		// The relay's hello, not the upgrade alone, makes an open successful.
		events.text(last(), HELLO);
		events.closed(last(), 1006);
		assertTrue(pendingRetry().delayMillis <= 18_000);
	}

	@Test
	public void aRelayThatDoesNotEchoTheSubprotocolIsClosedAndRetried()
	{
		socket.update(true, TOKEN, true, true);
		FakeConnection connection = last();
		events.opened(connection, null);
		assertEquals(Integer.valueOf(DestinationSocket.CLOSE_NORMAL), connection.closedWith);
		assertNotNull(pendingRetry());
		assertFalse(socket.status() == DestinationSocket.Status.LISTENING);
	}

	@Test
	public void eventsFromAReplacedConnectionAreIgnored()
	{
		FakeConnection stale = listening();
		socket.update(true, OTHER_TOKEN, true, true);
		FakeConnection current = last();
		events.opened(current, DestinationSocket.SUBPROTOCOL);
		events.text(current, HELLO);

		events.closed(stale, DestinationSocket.CLOSE_REVOKED);
		events.text(stale, destinationFrame("stale"));
		assertEquals(DestinationSocket.Status.LISTENING, socket.status());
		assertTrue(received.isEmpty());
	}

	// --- the relay's hello ------------------------------------------------------------------------

	/** Open a socket for TOKEN and complete the upgrade, but without the relay's hello yet. */
	private FakeConnection upgraded()
	{
		socket.update(true, TOKEN, true, true);
		FakeConnection connection = last();
		events.opened(connection, DestinationSocket.SUBPROTOCOL);
		return connection;
	}

	private Scheduled lastScheduled()
	{
		return scheduled.get(scheduled.size() - 1);
	}

	@Test
	public void aHelloStartsListeningAndAPlaceRightBehindItIsHandedOn()
	{
		FakeConnection connection = upgraded();
		Scheduled deadline = lastScheduled();
		assertEquals(DestinationSocket.HELLO_TIMEOUT_MILLIS, deadline.delayMillis);
		// The upgrade alone is not listening: the relay has not answered yet.
		assertEquals(DestinationSocket.Status.CONNECTING, socket.status());

		// The site sends a waiting place straight after the hello, so both can arrive together.
		events.text(connection, HELLO);
		events.text(connection, destinationFrame("d-1"));
		assertEquals(DestinationSocket.Status.LISTENING, socket.status());
		assertTrue(deadline.cancelled);
		assertEquals(1, received.size());
		assertEquals("d-1", received.get(0).id);

		// A deadline that fires anyway, its cancel having lost the race with the hello, changes nothing.
		deadline.task.run();
		assertNull(connection.closedWith);
		assertEquals(DestinationSocket.Status.LISTENING, socket.status());
	}

	@Test
	public void aHelloOfAnotherProtocolIsClosedAndRetried()
	{
		for (String hello : new String[]{"{\"type\":\"hello\",\"protocol\":2}", "{\"type\":\"hello\"}"})
		{
			FakeConnection connection = upgraded();
			Scheduled deadline = lastScheduled();
			events.text(connection, hello);

			assertEquals(hello, Integer.valueOf(DestinationSocket.CLOSE_NORMAL), connection.closedWith);
			assertEquals(hello, DestinationSocket.Status.RETRYING, socket.status());
			assertTrue(hello, deadline.cancelled);
			assertNotNull(hello, pendingRetry());
			// Whatever the refused socket sends next is not acted on.
			events.text(connection, HELLO);
			events.text(connection, destinationFrame("late"));
			assertEquals(hello, DestinationSocket.Status.RETRYING, socket.status());
			assertTrue(hello, received.isEmpty());

			// Reset for the next frame.
			socket.update(false, TOKEN, true, false);
			scheduled.clear();
		}
		assertTrue(DestinationSocket.isAnyHello("{\"type\":\"hello\",\"protocol\":2}"));
		assertFalse(DestinationSocket.isAnyHello(destinationFrame("d")));
	}

	@Test
	public void noHelloWithin10SecondsIsClosedAndRetried()
	{
		FakeConnection connection = upgraded();
		lastScheduled().task.run();

		assertEquals(Integer.valueOf(DestinationSocket.CLOSE_NORMAL), connection.closedWith);
		assertEquals(DestinationSocket.Status.RETRYING, socket.status());
		Scheduled retry = pendingRetry();
		assertNotNull(retry);
		// A hello that comes too late is not listened to.
		events.text(connection, HELLO);
		assertEquals(DestinationSocket.Status.RETRYING, socket.status());

		// A relay that keeps upgrading without a hello is backed off further each time.
		retry.task.run();
		events.opened(last(), DestinationSocket.SUBPROTOCOL);
		lastScheduled().task.run();
		assertEquals(Integer.valueOf(DestinationSocket.CLOSE_NORMAL), last().closedWith);
		assertTrue(pendingRetry().delayMillis >= 24_000);
	}

	@Test
	public void aPlaceBeforeTheHelloIsNotHandedOn()
	{
		FakeConnection connection = upgraded();
		events.text(connection, destinationFrame("early"));
		events.text(connection, "{\"type\":\"news\"}");
		assertTrue(received.isEmpty());
		assertNull(connection.closedWith);
		assertEquals(DestinationSocket.Status.CONNECTING, socket.status());

		events.text(connection, HELLO);
		assertEquals(DestinationSocket.Status.LISTENING, socket.status());
	}

	@Test
	public void theHelloDeadlineGoesWithItsSocket()
	{
		FakeConnection dropped = upgraded();
		Scheduled deadline = lastScheduled();
		events.closed(dropped, 1006);
		assertTrue(deadline.cancelled);
		Scheduled retry = pendingRetry();

		// Firing late, it neither closes the next socket nor schedules another retry.
		retry.task.run();
		FakeConnection next = last();
		events.opened(next, DestinationSocket.SUBPROTOCOL);
		int before = scheduled.size();
		deadline.task.run();
		assertNull(next.closedWith);
		assertEquals(before, scheduled.size());

		// Logging out before the hello cancels the new socket's deadline too.
		Scheduled nextDeadline = lastScheduled();
		socket.update(true, TOKEN, false, false);
		assertTrue(nextDeadline.cancelled);
		assertEquals(DestinationSocket.Status.OFF, socket.status());
	}

	// --- frames -----------------------------------------------------------------------------------

	private static String destinationFrame(String id)
	{
		return "{\"type\":\"destination\",\"id\":\"" + id + "\",\"x\":3036,\"y\":3294,\"plane\":0,"
			+ "\"label\":\"Sarah\",\"expires_at\":\"2026-09-26T12:02:00.000Z\",\"future\":true}";
	}

	@Test
	public void aDestinationFrameIsHandedOn()
	{
		FakeConnection connection = listening();
		events.text(connection, destinationFrame("d-1"));
		assertEquals(1, received.size());
		Destination destination = received.get(0);
		assertEquals("d-1", destination.id);
		assertEquals(3036, destination.x);
		assertEquals(3294, destination.y);
		assertEquals(0, destination.plane);
		assertEquals("Sarah", destination.label);
		assertEquals(Instant.parse("2026-09-26T12:02:00Z"), destination.expiresAt);
	}

	@Test
	public void unknownFramesAndDestinationsWithoutAStringIdAreIgnored()
	{
		FakeConnection connection = listening();
		events.text(connection, "{\"type\":\"news\",\"id\":\"x\"}");
		events.text(connection, "not json");
		events.text(connection, "[1,2]");
		events.text(connection, "{\"type\":\"destination\",\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":7,\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		assertTrue(received.isEmpty());
		assertTrue(DestinationSocket.isHello("{\"type\":\"hello\",\"protocol\":1}"));
		assertFalse(DestinationSocket.isHello("{\"type\":\"hello\",\"protocol\":2}"));
	}

	@Test
	public void aMalformedDestinationWithAnIdIsHandedOnAsInvalidSoItCanBeAcked()
	{
		FakeConnection connection = listening();
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d\",\"x\":\"3036\",\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d\",\"x\":1,\"y\":1.5,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d\",\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"label\":\"a\",\"expires_at\":\"yesterday\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d\",\"x\":1,\"y\":1,"
			+ "\"label\":\"a\",\"expires_at\":\"2026-09-26T12:02:00Z\"}");
		events.text(connection, "{\"type\":\"destination\",\"id\":\"d\",\"x\":1,\"y\":1,\"plane\":0,"
			+ "\"label\":7,\"expires_at\":\"2026-09-26T12:02:00Z\"}");

		assertEquals(5, received.size());
		assertEquals(DestinationSocket.UNREADABLE, received.get(0).x);
		assertEquals(DestinationSocket.UNREADABLE, received.get(1).y);
		assertNull(received.get(2).expiresAt);
		assertEquals(DestinationSocket.UNREADABLE, received.get(3).plane);
		assertNull(received.get(4).label);
		for (Destination destination : received)
		{
			assertEquals("d", destination.id);
			assertFalse(RouteDispatcher.valid(destination));
			assertTrue(RouteDispatcher.ackable(destination));
		}
	}

	@Test
	public void anAckIsOneSmallFrameWithItsResultAndOnlyWhileListening()
	{
		assertFalse(socket.ack("d-0", "routed"));
		FakeConnection connection = listening();
		assertTrue(socket.ack("d-1", "routed"));
		assertEquals("{\"type\":\"ack\",\"id\":\"d-1\",\"result\":\"routed\"}", connection.sent.get(0));
		assertTrue(socket.ack(repeat('a', RouteDispatcher.MAX_ID_LENGTH), "no_pathing_plugin"));
		assertTrue(connection.sent.get(1).getBytes(java.nio.charset.StandardCharsets.UTF_8).length <= 1_024);

		socket.update(false, TOKEN, true, false);
		assertFalse(socket.ack("d-2", "routed"));
	}

	@Test
	public void shutdownClosesAndCancelsTheRetry()
	{
		socket.update(true, TOKEN, true, true);
		events.failed(last(), 0, -1);
		Scheduled retry = pendingRetry();
		socket.stop();
		assertTrue(retry.cancelled);
		assertEquals(DestinationSocket.Status.OFF, socket.status());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * The condition kinds that let the site describe a new kind of step without a plugin update: game variables, items
 * held, and what happens in the game (an area reached, a talk, a kill). Each is parsed, checked or seen, and an
 * unknown kind stays harmless.
 */
public class GuideConditionKindsTest
{
	private static Guide.Requirement parse(String json)
	{
		return GuideParser.requirement(new JsonParser().parse(json).getAsJsonObject());
	}

	private static Guide.Step step(String title, List<Guide.Requirement> completes)
	{
		return new Guide.Step("s", title, -1, null, null, Collections.<String>emptyList(), null, null,
			Collections.<String>emptySet(), Collections.<String>emptyList(), Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Place>emptyList(), Collections.<Guide.Item>emptyList(), Collections.<Guide.Collect>emptyList(),
			Collections.<Guide.Requirement>emptyList(), completes, null);
	}

	@Test
	public void eachKindIsRead()
	{
		Guide.Requirement varbit = parse("{\"kind\":\"varbit\",\"id\":4458,\"value\":1,\"op\":\">=\",\"label\":\"Easy Varrock diary\"}");
		assertEquals(Guide.Requirement.Kind.VARBIT, varbit.kind);
		assertEquals(4458, varbit.varId);
		assertEquals(">=", varbit.op);
		assertEquals(1, varbit.value);
		assertEquals("Easy Varrock diary", varbit.label);

		Guide.Requirement varp = parse("{\"kind\":\"varp\",\"id\":29,\"value\":5}");
		assertEquals(Guide.Requirement.Kind.VARP, varp.kind);
		assertEquals("the comparison defaults to at least", ">=", varp.op);
		assertNull(varp.label);

		Guide.Requirement items = parse("{\"kind\":\"items\",\"where\":\"carried\",\"items\":[{\"name\":\"Bucket\",\"id\":1925}]}");
		assertEquals(Guide.Requirement.Kind.ITEMS, items.kind);
		assertEquals("carried", items.op);
		assertEquals(1925, items.items.get(0).id);
		assertEquals("owned by default", "owned", parse("{\"kind\":\"items\",\"items\":[{\"name\":\"Pot\"}]}").op);

		Guide.Requirement area = parse("{\"kind\":\"area\",\"x\":3093,\"y\":3244,\"plane\":0,\"radius\":3,\"label\":\"Draynor\"}");
		assertEquals(Guide.Requirement.Kind.AREA, area.kind);
		assertEquals(3093, area.place.x);
		assertEquals(3, area.value);
		assertEquals("Draynor", area.label);
		assertEquals("the reach defaults to the signs' tiles", GuideSigns.REACH_TILES,
			parse("{\"kind\":\"area\",\"x\":1,\"y\":2}").value);

		Guide.Requirement talk = parse("{\"kind\":\"talk\",\"npc\":\"Mining Instructor\"}");
		assertEquals(Guide.Requirement.Kind.TALK, talk.kind);
		assertEquals("Mining Instructor", talk.npc);

		Guide.Requirement kill = parse("{\"kind\":\"kill\",\"npc\":\"Cow\",\"count\":5}");
		assertEquals(Guide.Requirement.Kind.KILL, kill.kind);
		assertEquals(5, kill.value);
	}

	@Test
	public void aKindThatCannotBeReadIsUnknownAndHarmless()
	{
		for (String json : new String[]{
			"{\"kind\":\"varbit\",\"id\":4458,\"value\":1,\"op\":\"~\"}",
			"{\"kind\":\"varbit\",\"value\":1}",
			"{\"kind\":\"varp\",\"id\":-1,\"value\":1}",
			"{\"kind\":\"items\",\"items\":[]}",
			"{\"kind\":\"items\",\"where\":\"nearby\",\"items\":[{\"name\":\"Pot\"}]}",
			"{\"kind\":\"area\",\"label\":\"Nowhere\"}",
			"{\"kind\":\"talk\"}",
			"{\"kind\":\"a_kind_from_a_later_site\"}"})
		{
			Guide.Requirement requirement = parse(json);
			assertEquals(json, Guide.Requirement.Kind.UNKNOWN, requirement.kind);
			assertEquals(json, GuideRules.Met.UNKNOWN, GuideRules.requirement(requirement, GuideFacts.UNKNOWN));
		}
	}

	@Test
	public void aGameVariableIsComparedAsTheSiteSays()
	{
		Guide.Requirement atLeast = parse("{\"kind\":\"varbit\",\"id\":100,\"value\":3}");
		assertEquals("not read yet", GuideRules.Met.UNKNOWN, GuideRules.requirement(atLeast, GuideFacts.UNKNOWN));
		assertEquals(GuideRules.Met.MISSING, GuideRules.requirement(atLeast, new GuideFacts.Builder().varbit(100, 2).build()));
		assertEquals(GuideRules.Met.MET, GuideRules.requirement(atLeast, new GuideFacts.Builder().varbit(100, 3).build()));
		assertEquals("a varp is read from varps, not varbits", GuideRules.Met.UNKNOWN,
			GuideRules.requirement(parse("{\"kind\":\"varp\",\"id\":100,\"value\":3}"), new GuideFacts.Builder().varbit(100, 9).build()));
		assertTrue(GuideRules.compare(5, "==", 5));
		assertTrue(GuideRules.compare(4, "!=", 5));
		assertTrue(GuideRules.compare(6, ">", 5));
		assertTrue(GuideRules.compare(5, "<=", 5));
		assertTrue(GuideRules.compare(4, "<", 5));
		assertFalse(GuideRules.compare(5, "<", 5));
	}

	@Test
	public void itemsAreCarriedOrOwned()
	{
		Guide.Requirement owned = parse("{\"kind\":\"items\",\"items\":[{\"name\":\"Bucket\",\"id\":1925,\"qty\":2}]}");
		Guide.Requirement carried = parse("{\"kind\":\"items\",\"where\":\"carried\",\"items\":[{\"name\":\"Bucket\",\"id\":1925}]}");
		Map<Integer, Integer> one = new HashMap<>();
		one.put(1925, 1);
		GuideFacts unseen = new GuideFacts.Builder().carried(one).build();
		assertEquals(GuideRules.Met.MET, GuideRules.requirement(carried, unseen));
		assertEquals("one carried, the bank unseen", GuideRules.Met.UNKNOWN, GuideRules.requirement(owned, unseen));
		GuideFacts banked = new GuideFacts.Builder().carried(one).banked(one).build();
		assertEquals("one carried and one banked", GuideRules.Met.MET, GuideRules.requirement(owned, banked));
		GuideFacts none = new GuideFacts.Builder().carried(Collections.<Integer, Integer>emptyMap())
			.banked(Collections.<Integer, Integer>emptyMap()).build();
		assertEquals(GuideRules.Met.MISSING, GuideRules.requirement(owned, none));
		assertEquals(GuideRules.Met.MISSING, GuideRules.requirement(carried, none));
	}

	@Test
	public void aStateTicksTheStepAndSomethingThatHappensIsLeftToTheTracker()
	{
		Guide.Step diary = step("Finish the easy Varrock diary",
			Collections.singletonList(parse("{\"kind\":\"varbit\",\"id\":4458,\"value\":1}")));
		assertTrue(GuideRules.checkable(diary));
		assertFalse(GuideRules.completed(diary, new GuideFacts.Builder().varbit(4458, 0).build()));
		assertTrue(GuideRules.completed(diary, new GuideFacts.Builder().varbit(4458, 1).build()));

		Guide.Step talkWithState = step("Speak to the guide", java.util.Arrays.asList(
			parse("{\"kind\":\"talk\",\"npc\":\"Gielinor Guide\"}"), parse("{\"kind\":\"varp\",\"id\":281,\"value\":3}")));
		assertTrue("it has a state to check", GuideRules.checkable(talkWithState));
		assertFalse("the talk has to happen", GuideRules.completed(talkWithState, new GuideFacts.Builder().varp(281, 9).build()));
		assertTrue(GuideRules.statesMet(talkWithState, new GuideFacts.Builder().varp(281, 3).build()));
		assertFalse(GuideRules.statesMet(talkWithState, new GuideFacts.Builder().varp(281, 1).build()));

		Guide.Step onlyTalk = step("Anything", Collections.singletonList(parse("{\"kind\":\"talk\",\"npc\":\"Hans\"}")));
		assertFalse("nothing to read at any time", GuideRules.checkable(onlyTalk));
		assertTrue(GuideRules.statesMet(onlyTalk, GuideFacts.UNKNOWN));

		Guide.Step unknown = step("Anything", Collections.singletonList(parse("{\"kind\":\"a_kind_from_a_later_site\"}")));
		assertFalse("a kind this version does not know is not checkable, so it never sits behind the player",
			GuideRules.checkable(unknown));
		assertFalse(GuideRules.completed(unknown, GuideFacts.UNKNOWN));
	}

	@Test
	public void whatTheSiteSaysHappensWinsOverTheTitle()
	{
		GuideSigns talk = GuideSigns.of(step("Kill a goblin", Collections.singletonList(parse("{\"kind\":\"talk\",\"npc\":\"Hans\"}"))));
		assertTrue("the site's talk, not the title's kill", talk.talkedTo("Hans"));
		assertFalse(talk.isKill("Goblin"));

		GuideSigns kill = GuideSigns.of(step("Anything", Collections.singletonList(parse("{\"kind\":\"kill\",\"npc\":\"Cow\",\"count\":3}"))));
		assertTrue(kill.isKill("Cow"));
		assertEquals(3, kill.kills);

		GuideSigns area = GuideSigns.of(step("Anything",
			Collections.singletonList(parse("{\"kind\":\"area\",\"x\":3000,\"y\":3000,\"radius\":2}"))));
		assertTrue(area.reached(3002, 2998, 0));
		assertFalse("the site's radius, not the default", area.reached(3003, 3000, 0));

		assertTrue("a varbit is a state, no sign", GuideSigns.of(step("Talk to Hans",
			Collections.singletonList(parse("{\"kind\":\"varbit\",\"id\":1,\"value\":1}")))).none());
	}

	@Test
	public void aLongShoppingListIsKeptWholeAndTheStepBoxCountsTheRest()
	{
		JsonObject guide = new JsonParser().parse(GuideFixtures.read(GuideFixtures.GUIDE)).getAsJsonObject();
		com.google.gson.JsonArray bring = new com.google.gson.JsonArray();
		for (int i = 0; i < 108; i++)
		{
			JsonObject item = new JsonObject();
			item.addProperty("name", "Item " + i);
			item.addProperty("id", 1000 + i);
			bring.add(item);
		}
		guide.getAsJsonArray("sections").get(0).getAsJsonObject().getAsJsonArray("steps").get(0).getAsJsonObject()
			.add("bring", bring);
		Guide parsed = GuideParser.guide(guide.toString()).value;
		assertEquals("the quest route's largest stock-up, 108 items, is kept whole", 108,
			parsed.step("cooks-assistant").bring.size());

		java.util.List<String> missing = new java.util.ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			missing.add("Item " + i);
		}
		java.util.List<String> lines = GuideStepOverlay.bringLines(missing);
		assertEquals(GuideStepOverlay.MAX_BRING_LINES + 1, lines.size());
		assertEquals("Bring: Item 0", lines.get(0));
		assertEquals("Bring: and 4 more, in the panel", lines.get(lines.size() - 1));
		assertEquals("one more than fits is listed, not counted", GuideStepOverlay.MAX_BRING_LINES + 1,
			GuideStepOverlay.bringLines(missing.subList(0, GuideStepOverlay.MAX_BRING_LINES + 1)).size());
	}

	@Test
	public void theVariablesToReadAreTheOnesTheGuideNames()
	{
		JsonObject guide = new JsonParser().parse(GuideFixtures.read(GuideFixtures.GUIDE)).getAsJsonObject();
		guide.getAsJsonArray("sections").get(0).getAsJsonObject().getAsJsonArray("steps").get(0).getAsJsonObject()
			.add("completes", new JsonParser().parse("[{\"kind\":\"varbit\",\"id\":4458,\"value\":1},"
				+ "{\"kind\":\"varp\",\"id\":29,\"value\":2}]"));
		Guide parsed = GuideParser.guide(guide.toString()).value;
		assertEquals(Collections.singleton(4458), GuideRules.varbits(parsed));
		assertEquals(Collections.singleton(29), GuideRules.varps(parsed));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * Guide requests: only when asked, the list kept an hour, a guide kept until its revision changes,
 * {@code If-None-Match} on a refresh, and what each answer means. A recording transport stands in for the network.
 */
public class GuideFetcherTest
{
	private final long[] now = {1_000_000L};
	private final List<String[]> asked = new ArrayList<>();
	private final List<GuideFetcher.Handler> pending = new ArrayList<>();
	private final GuideFetcher fetcher = new GuideFetcher((url, etag, handler) ->
	{
		asked.add(new String[]{url, etag});
		pending.add(handler);
	}, () -> now[0]);

	private final List<GuideFetcher.Answer<Guide.Listing>> listings = new ArrayList<>();
	private final List<GuideFetcher.Answer<Guide>> guides = new ArrayList<>();

	private void answer(int status, String body, String etag)
	{
		pending.remove(0).handle(status, body, etag);
	}

	@Test
	public void nothingIsAskedUntilThePlayerOpensGuides()
	{
		assertTrue(asked.isEmpty());
		fetcher.listing(listings::add);
		assertEquals(1, asked.size());
		assertEquals(Endpoints.guides(), asked.get(0)[0]);
		assertNull(asked.get(0)[1]);
	}

	@Test
	public void theListIsKeptForAnHourThenAskedAgainWithItsEtag()
	{
		fetcher.listing(listings::add);
		answer(200, GuideFixtures.read(GuideFixtures.LISTING), "\"list-1\"");
		assertSame(GuideFetcher.Status.OK, listings.get(0).status);
		assertEquals(2, listings.get(0).value.guides.size());

		now[0] += GuideFetcher.LIST_MAX_AGE_MILLIS - 1;
		fetcher.listing(listings::add);
		assertEquals("answered from memory", 1, asked.size());
		assertSame(listings.get(0).value, listings.get(1).value);

		now[0] += 1;
		fetcher.listing(listings::add);
		assertEquals(2, asked.size());
		assertEquals("\"list-1\"", asked.get(1)[1]);
		answer(304, "", null);
		assertSame("unchanged", listings.get(0).value, listings.get(2).value);
	}

	@Test
	public void twoOpensWhileAskingShareOneRequest()
	{
		fetcher.listing(listings::add);
		fetcher.listing(listings::add);
		assertEquals(1, asked.size());
		answer(200, GuideFixtures.read(GuideFixtures.LISTING), null);
		assertEquals(2, listings.size());
	}

	@Test
	public void aSiteWithoutTheRoutesIsNotServed()
	{
		fetcher.listing(listings::add);
		answer(404, "<html>", null);
		assertSame(GuideFetcher.Status.NOT_SERVED, listings.get(0).status);
		now[0] += 60_000;
		fetcher.listing(listings::add);
		assertEquals("not asked again at once", 1, asked.size());
		fetcher.forgetFailures();
		fetcher.listing(listings::add);
		assertEquals("Try again asks", 2, asked.size());
	}

	@Test
	public void anUnknownVersionAsksForAnUpdate()
	{
		fetcher.listing(listings::add);
		answer(200, "{\"version\":2,\"guides\":[]}", null);
		assertSame(GuideFetcher.Status.UPDATE_PLUGIN, listings.get(0).status);
		assertNull(listings.get(0).value);
	}

	@Test
	public void aFailedRefreshKeepsTheListItHas()
	{
		fetcher.listing(listings::add);
		answer(200, GuideFixtures.read(GuideFixtures.LISTING), "\"e\"");
		now[0] += GuideFetcher.LIST_MAX_AGE_MILLIS;
		fetcher.listing(listings::add);
		answer(503, "", null);
		assertSame(GuideFetcher.Status.OK, listings.get(1).status);
		assertSame(listings.get(0).value, listings.get(1).value);
		fetcher.listing(listings::add);
		assertEquals("asked again on the next open, after a short wait", 2, asked.size());
		now[0] += GuideFetcher.RETRY_MILLIS;
		fetcher.listing(listings::add);
		assertEquals(3, asked.size());
	}

	@Test
	public void aGuideIsKeptUntilItsRevisionChanges()
	{
		fetcher.guide("beginner", "3f2a9c1e", guides::add);
		assertEquals(Endpoints.guide("beginner"), asked.get(0)[0]);
		answer(200, GuideFixtures.read(GuideFixtures.GUIDE), "\"g-1\"");
		assertSame(GuideFetcher.Status.OK, guides.get(0).status);

		fetcher.guide("beginner", "3f2a9c1e", guides::add);
		fetcher.guide("beginner", null, guides::add);
		assertEquals("the same revision, from memory", 1, asked.size());

		fetcher.guide("beginner", "new-revision", guides::add);
		assertEquals(2, asked.size());
		assertEquals("\"g-1\"", asked.get(1)[1]);
		answer(304, "", null);
		assertSame(guides.get(0).value, guides.get(3).value);
	}

	@Test
	public void aGuideTheSiteNoLongerOffersOrThatIsNotTheOneAskedFor()
	{
		fetcher.guide("gone", null, guides::add);
		answer(404, "{\"code\":\"unknown_guide\"}", null);
		assertSame(GuideFetcher.Status.NOT_SERVED, guides.get(0).status);

		fetcher.guide("other", null, guides::add);
		answer(200, GuideFixtures.read(GuideFixtures.GUIDE), null);
		assertSame("the body is another guide", GuideFetcher.Status.FAILED, guides.get(1).status);

		fetcher.guide("other", null, guides::add);
		assertEquals("a failure is not asked again at once", 2, asked.size());
		assertSame(GuideFetcher.Status.FAILED, guides.get(2).status);
		fetcher.forgetFailures();
		fetcher.guide("other", null, guides::add);
		assertEquals(3, asked.size());
	}

	@Test
	public void theRequestCarriesNoTokenAndAsksForJson()
	{
		okhttp3.Request request = GuideFetcher.request(Endpoints.guide("beginner"), "\"g-1\"");
		assertNull(request.header("Authorization"));
		assertEquals("application/json", request.header("Accept"));
		assertEquals("\"g-1\"", request.header("If-None-Match"));
		assertNull(GuideFetcher.request(Endpoints.guides(), null).header("If-None-Match"));
		assertEquals("GET", request.method());
	}
}

package com.osrsindex;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;

/**
 * The guide bodies the tests read, in src/test/resources: shaped like the site's guide routes (docs/guides.md),
 * with fields from a later site mixed in. The text is sample text, not a real guide's.
 */
final class GuideFixtures
{
	static final String GUIDE = "guide-fixture.json";
	static final String LISTING = "guides-fixture.json";

	private GuideFixtures()
	{
	}

	static String read(String name)
	{
		try (InputStream in = GuideFixtures.class.getResourceAsStream(name))
		{
			if (in == null)
			{
				throw new IllegalStateException("no fixture " + name);
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	static Guide guide()
	{
		return GuideParser.guide(read(GUIDE)).value;
	}

	static Guide.Listing listing()
	{
		return GuideParser.listing(read(LISTING)).value;
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Reading the site's guide routes: every field of the fixture, fields from a later site ignored, an unknown
 * {@code version} refused as "update the plugin", and anything unsafe or unusable dropped.
 */
public class GuideParserTest
{
	@Test
	public void theGuideReadsInTheSitesOrder()
	{
		GuideParser.Result<Guide> result = GuideParser.guide(GuideFixtures.read(GuideFixtures.GUIDE));
		assertEquals(GuideParser.Problem.NONE, result.problem);
		Guide guide = result.value;
		assertEquals("beginner", guide.id);
		assertEquals("Beginner walkthrough", guide.title);
		assertEquals("Sample attribution line.", guide.attribution);
		assertEquals("3f2a9c1e", guide.revision);
		assertNull("null modes: any account type", guide.modes);
		assertEquals(2, guide.sections.size());
		assertEquals("Lumbridge", guide.sections.get(0).title);
		assertEquals(Arrays.asList("cooks-assistant", "sheep-shearer", "mining-instructor", "cooking-10", "risky-step"),
			ids(guide));
	}

	@Test
	public void aStepCarriesEveryField()
	{
		Guide.Step step = GuideFixtures.guide().step("cooks-assistant");
		assertEquals("Cook's Assistant", step.title);
		assertEquals(10, step.minutes);
		assertEquals("https://osrsindex.com/guides/beginner/cooks-assistant", step.url);
		assertEquals("Help the Lumbridge cook bake a cake.", step.text);
		assertEquals(2, step.how.size());
		assertEquals("The dairy cow is north of the castle.", step.tip);
		assertEquals("Fill the bucket yourself at the dairy cow.", step.ironman);
		assertEquals(Collections.singleton("solo"), step.tags);
		assertEquals(Collections.singletonList("Cook's Assistant"), step.quests);

		assertEquals(2, step.places.size());
		Guide.Place kitchen = step.places.get(0);
		assertTrue(kitchen.hasPoint());
		assertEquals(3208, kitchen.x);
		assertEquals(3214, kitchen.y);
		assertEquals(0, kitchen.plane);
		assertFalse("a place with only a label", step.places.get(1).hasPoint());
		assertEquals("Anvils", step.places.get(1).label);
		assertEquals(kitchen, step.point());

		assertEquals("teleport", step.travel.get(0).by);
		assertEquals(1925, step.bring.get(0).id);
		assertEquals("an item without an id is shown by name", -1, step.bring.get(1).id);
		assertEquals("Egg", step.collect.get(0).item.name);
		assertEquals(Collections.singletonList("Cook's Assistant"), step.collect.get(0).forQuests);
		assertEquals("Chicken farm", step.collect.get(0).from);

		Guide.Requirement cooking = step.requires.get(0);
		assertEquals(Guide.Requirement.Kind.SKILL, cooking.kind);
		assertEquals("cooking", cooking.skill);
		assertEquals(1, cooking.level);
		assertTrue(cooking.boostable);
		assertEquals(Guide.Requirement.Kind.QUEST, step.completes.get(0).kind);
		assertEquals("Cook's Assistant", step.completes.get(0).quest);

		assertEquals(300, step.rewards.xp.get(0).amount);
		assertEquals(1, step.rewards.questPoints);
		assertEquals(Collections.singletonList("Use of the cook's range."), step.rewards.unlocks);
	}

	@Test
	public void everyRequirementKindAndOneFromALaterSite()
	{
		Guide.Step step = GuideFixtures.guide().step("cooking-10");
		assertEquals(Guide.Requirement.Kind.QUEST, step.requires.get(0).kind);
		assertEquals(Guide.Requirement.Kind.QUEST_POINTS, step.requires.get(1).kind);
		assertEquals(1, step.requires.get(1).points);
		assertEquals(Guide.Requirement.Kind.MODE, step.requires.get(2).kind);
		assertEquals(Arrays.asList("ironman", "hardcore_ironman"), step.requires.get(2).modes);
		assertEquals("kept, so the step is never ticked on a guess", Guide.Requirement.Kind.UNKNOWN,
			step.requires.get(3).kind);
		assertEquals(10, step.completes.get(0).level);
		assertFalse(step.completes.get(0).boostable);
	}

	@Test
	public void anUnknownVersionAsksForAnUpdateAndShowsNothing()
	{
		String later = GuideFixtures.read(GuideFixtures.GUIDE).replace("\"version\": 1", "\"version\": 2");
		GuideParser.Result<Guide> result = GuideParser.guide(later);
		assertEquals(GuideParser.Problem.UPDATE_PLUGIN, result.problem);
		assertNull(result.value);
		String listing = GuideFixtures.read(GuideFixtures.LISTING).replace("\"version\": 1", "\"version\": 7");
		assertEquals(GuideParser.Problem.UPDATE_PLUGIN, GuideParser.listing(listing).problem);
		assertEquals(GuideParser.Problem.UPDATE_PLUGIN, GuideParser.guide("{\"version\":\"1\"}").problem);
	}

	@Test
	public void notAGuideIsUnreadable()
	{
		assertEquals(GuideParser.Problem.UNREADABLE, GuideParser.guide("<html>Not found</html>").problem);
		assertEquals(GuideParser.Problem.UNREADABLE, GuideParser.guide("[]").problem);
		assertEquals(GuideParser.Problem.UNREADABLE, GuideParser.guide(null).problem);
		assertEquals("no version", GuideParser.Problem.UNREADABLE,
			GuideParser.guide("{\"id\":\"a\",\"title\":\"A\",\"sections\":[]}").problem);
		assertEquals("an id that is not a slug", GuideParser.Problem.UNREADABLE,
			GuideParser.guide("{\"version\":1,\"id\":\"../x\",\"title\":\"A\",\"sections\":[]}").problem);
		assertEquals(GuideParser.Problem.UNREADABLE, GuideParser.listing("{\"version\":1}").problem);
	}

	@Test
	public void stepsWithoutAnIdOrWithOneAlreadyUsedAreLeftOut()
	{
		String body = "{\"version\":1,\"id\":\"g\",\"title\":\"G\",\"sections\":["
			+ "{\"id\":\"s\",\"title\":\"S\",\"steps\":[{\"title\":\"no id\"},{\"id\":\"a\",\"title\":\"First\"},"
			+ "{\"id\":\"a\",\"title\":\"Again\"},\"not an object\",{\"id\":\"b\"}]},"
			+ "{\"id\":\"empty\",\"title\":\"Empty\",\"steps\":[]}]}";
		Guide guide = GuideParser.guide(body).value;
		assertEquals(Arrays.asList("a", "b"), ids(guide));
		assertEquals("First", guide.step("a").title);
		assertEquals("a step without a title shows its id", "b", guide.step("b").title);
		assertEquals("a section with no steps is left out", 1, guide.sections.size());
	}

	@Test
	public void unsafeOrUnusableFieldsAreDropped()
	{
		String body = "{\"version\":1,\"id\":\"g\",\"title\":\"G\",\"sections\":[{\"id\":\"s\",\"title\":\"S\",\"steps\":["
			+ "{\"id\":\"a\",\"title\":\"T\\u0007itle\",\"url\":\"https://example.com/phish\",\"text\":\"  two\\n\\nlines  \","
			+ "\"places\":[{\"label\":\"Off the map\",\"x\":20000,\"y\":3200,\"plane\":0},"
			+ "{\"label\":\"High\",\"x\":3200,\"y\":3200,\"plane\":4},{\"label\":\"Surface\",\"x\":3200,\"y\":3200},"
			+ "{\"x\":1,\"y\":1}],"
			+ "\"bring\":[{\"name\":\"Zero\",\"id\":0},{\"name\":\"Huge\",\"id\":99999999},{\"id\":5}],"
			+ "\"requires\":[{\"kind\":\"skill\",\"skill\":\"cooking\",\"level\":150},{\"kind\":\"mode\",\"modes\":[]}]}]}]}";
		Guide.Step step = GuideParser.guide(body).value.step("a");
		assertEquals("control characters dropped", "Title", step.title);
		assertNull("a link off the site is dropped", step.url);
		assertEquals("whitespace made one space", "two lines", step.text);
		assertEquals("a place without a label says nothing", 3, step.places.size());
		assertFalse("off the map: label only", step.places.get(0).hasPoint());
		assertFalse("no such plane: label only", step.places.get(1).hasPoint());
		assertTrue("no plane is the surface", step.places.get(2).hasPoint());
		assertEquals(0, step.places.get(2).plane);
		assertEquals(2, step.bring.size());
		assertEquals(-1, step.bring.get(0).id);
		assertEquals(-1, step.bring.get(1).id);
		assertEquals(Guide.Requirement.Kind.UNKNOWN, step.requires.get(0).kind);
		assertEquals(Guide.Requirement.Kind.UNKNOWN, step.requires.get(1).kind);
	}

	@Test
	public void theListReadsEveryGuideItCanUse()
	{
		Guide.Listing listing = GuideFixtures.listing();
		assertEquals(2, listing.guides.size());
		Guide.Summary beginner = listing.find("beginner");
		assertEquals("Beginner walkthrough", beginner.title);
		assertEquals("free", beginner.membership);
		assertNull(beginner.modes);
		assertEquals(5, beginner.steps);
		assertEquals(540, beginner.minutes);
		assertEquals("3f2a9c1e", beginner.revision);
		assertEquals(Arrays.asList("ironman", "hardcore_ironman"), listing.find("ironman").modes);

		String body = "{\"version\":1,\"guides\":[{\"id\":\"Bad Id\",\"title\":\"x\"},{\"id\":\"a\"},"
			+ "{\"id\":\"b\",\"title\":\"B\"},{\"id\":\"b\",\"title\":\"Again\"}]}";
		Guide.Listing filtered = GuideParser.listing(body).value;
		assertEquals(1, filtered.guides.size());
		assertEquals("B", filtered.guides.get(0).title);
		assertNull("no revision given", filtered.guides.get(0).revision);
	}

	private static List<String> ids(Guide guide)
	{
		List<String> out = new ArrayList<>();
		for (Guide.Step step : guide.steps)
		{
			out.add(step.id);
		}
		return out;
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Progress as the RuneLite profile keeps it: marks round-trip, and a damaged value starts afresh, never fails. */
public class GuideProgressTest
{
	@Test
	public void marksRoundTripThroughTheProfile()
	{
		GuideProgress progress = new GuideProgress();
		assertTrue(progress.set("a", GuideProgress.Mark.DONE));
		assertTrue(progress.set("b", GuideProgress.Mark.SKIPPED));
		assertFalse("the same mark again changes nothing", progress.set("a", GuideProgress.Mark.DONE));
		String saved = progress.toJson().toString();
		assertEquals("{\"a\":\"done\",\"b\":\"skipped\"}", saved);

		GuideProgress loaded = GuideProgress.load(saved);
		assertSame(GuideProgress.Mark.DONE, loaded.mark("a"));
		assertSame(GuideProgress.Mark.SKIPPED, loaded.mark("b"));
		assertNull(loaded.mark("c"));
	}

	@Test
	public void notDoneAndTheStartStepRoundTripToo()
	{
		GuideProgress progress = new GuideProgress();
		progress.set("mining-instructor", GuideProgress.Mark.OPEN);
		assertTrue(progress.start("cooking-10"));
		assertFalse("the same start again changes nothing", progress.start("cooking-10"));
		String saved = progress.toJson().toString();
		assertEquals("{\"mining-instructor\":\"open\",\"@start\":\"cooking-10\"}", saved);

		GuideProgress loaded = GuideProgress.load(saved);
		assertSame(GuideProgress.Mark.OPEN, loaded.mark("mining-instructor"));
		assertEquals("cooking-10", loaded.start());
		assertEquals("the start is not a mark", 1, loaded.size());
		assertEquals("cooking-10", loaded.copy().start());
		assertTrue(loaded.start(null));
		assertNull(loaded.start());
	}

	@Test
	public void reopeningClearsTheMark()
	{
		GuideProgress progress = new GuideProgress();
		progress.set("a", GuideProgress.Mark.DONE);
		assertTrue(progress.set("a", null));
		assertNull(progress.mark("a"));
		assertFalse(progress.set("a", null));
	}

	@Test
	public void aDamagedValueStartsAfresh()
	{
		assertEquals(0, GuideProgress.load(null).size());
		assertEquals(0, GuideProgress.load("").size());
		assertEquals(0, GuideProgress.load("not json {").size());
		assertEquals(0, GuideProgress.load("[1,2]").size());
		GuideProgress partly = GuideProgress.load("{\"a\":\"done\",\"b\":\"half\",\"c\":7,\"d\":\"skipped\"}");
		assertEquals(2, partly.size());
		assertSame(GuideProgress.Mark.SKIPPED, partly.mark("d"));
	}

	@Test
	public void aCopyIsItsOwn()
	{
		GuideProgress progress = new GuideProgress();
		progress.set("a", GuideProgress.Mark.DONE);
		GuideProgress copy = progress.copy();
		progress.set("a", null);
		assertSame(GuideProgress.Mark.DONE, copy.mark("a"));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;

/**
 * The guide rules: requirements met, missing or unknown; each {@code completes} kind; the step status; the
 * "N/total" count with skipped steps left out; the current step; and items carried, banked or missing.
 */
public class GuideRulesTest
{
	private final Guide guide = GuideFixtures.guide();

	private static GuideFacts.Builder character()
	{
		GuideFacts.Builder builder = new GuideFacts.Builder()
			.questPoints(0)
			.accountType("normal");
		for (Skill skill : Skill.values())
		{
			builder.level(skill, 1, 1);
		}
		return builder;
	}

	private static Guide.Requirement skill(String skill, int level, boolean boostable)
	{
		return new Guide.Requirement(Guide.Requirement.Kind.SKILL, skill, level, boostable, null, 0,
			Collections.<String>emptyList());
	}

	private static Guide.Requirement quest(String quest)
	{
		return new Guide.Requirement(Guide.Requirement.Kind.QUEST, null, 0, false, quest, 0, Collections.<String>emptyList());
	}

	private static Guide.Requirement questPoints(int points)
	{
		return new Guide.Requirement(Guide.Requirement.Kind.QUEST_POINTS, null, 0, false, null, points,
			Collections.<String>emptyList());
	}

	private static Guide.Requirement mode(String... modes)
	{
		return new Guide.Requirement(Guide.Requirement.Kind.MODE, null, 0, false, null, 0, Arrays.asList(modes));
	}

	@Test
	public void aSkillUsesTheRealLevelAndABoostableOneIsMetWithinFive()
	{
		GuideFacts facts = character().level(Skill.COOKING, 40, 45).build();
		assertEquals(GuideRules.Met.MET, GuideRules.requirement(skill("cooking", 40, false), facts));
		assertEquals("a boost shown on the stats does not count unless boostable", GuideRules.Met.MISSING,
			GuideRules.requirement(skill("cooking", 41, false), facts));
		assertEquals(GuideRules.Met.BOOST, GuideRules.requirement(skill("cooking", 45, true), facts));
		assertTrue(GuideRules.Met.BOOST.met());
		assertEquals(GuideRules.Met.MISSING, GuideRules.requirement(skill("cooking", 46, true), facts));
		assertEquals("a skill the game does not have", GuideRules.Met.UNKNOWN,
			GuideRules.requirement(skill("sorcery", 1, false), facts));
		assertEquals(GuideRules.Met.MET,
			GuideRules.requirement(skill("runecrafting", 1, false), character().build()));
	}

	@Test
	public void questQuestPointsAndAccountType()
	{
		GuideFacts facts = character().quest("Cook's Assistant", QuestState.FINISHED)
			.quest("Sheep Shearer", QuestState.IN_PROGRESS).questPoints(12).accountType("hardcore_ironman").build();
		assertEquals(GuideRules.Met.MET, GuideRules.requirement(quest("Cook's Assistant"), facts));
		assertEquals("started is not finished", GuideRules.Met.MISSING, GuideRules.requirement(quest("Sheep Shearer"), facts));
		assertEquals("not read", GuideRules.Met.UNKNOWN, GuideRules.requirement(quest("Dragon Slayer I"), facts));
		assertEquals(GuideRules.Met.MET, GuideRules.requirement(questPoints(12), facts));
		assertEquals(GuideRules.Met.MISSING, GuideRules.requirement(questPoints(13), facts));
		assertEquals(GuideRules.Met.MET, GuideRules.requirement(mode("ironman", "hardcore_ironman"), facts));
		assertEquals(GuideRules.Met.MISSING, GuideRules.requirement(mode("ironman"), facts));
		assertTrue(facts.ironman());
		assertFalse(character().build().ironman());
	}

	@Test
	public void loggedOutEverythingIsUnknown()
	{
		GuideFacts unknown = GuideFacts.UNKNOWN;
		assertEquals(GuideRules.Met.UNKNOWN, GuideRules.requirement(skill("cooking", 1, false), unknown));
		assertEquals(GuideRules.Met.UNKNOWN, GuideRules.requirement(quest("Cook's Assistant"), unknown));
		assertEquals(GuideRules.Met.UNKNOWN, GuideRules.requirement(questPoints(0), unknown));
		assertEquals(GuideRules.Met.UNKNOWN, GuideRules.requirement(mode("normal"), unknown));
		for (Guide.Step step : guide.steps)
		{
			assertFalse(step.id, GuideRules.completed(step, unknown));
		}
	}

	@Test
	public void eachCompletesKindTicksTheStep()
	{
		Guide.Step quest = guide.step("cooks-assistant");
		assertFalse(GuideRules.completed(quest, character().quest("Cook's Assistant", QuestState.IN_PROGRESS).build()));
		assertTrue(GuideRules.completed(quest, character().quest("Cook's Assistant", QuestState.FINISHED).build()));

		Guide.Step level = guide.step("cooking-10");
		assertFalse(GuideRules.completed(level, character().level(Skill.COOKING, 9, 12).build()));
		assertTrue(GuideRules.completed(level, character().level(Skill.COOKING, 10, 10).build()));

		Guide.Step points = stepCompleting(questPoints(32));
		assertFalse(GuideRules.completed(points, character().questPoints(31).build()));
		assertTrue(GuideRules.completed(points, character().questPoints(32).build()));

		Guide.Step account = stepCompleting(mode("ironman"));
		assertFalse(GuideRules.completed(account, character().build()));
		assertTrue(GuideRules.completed(account, character().accountType("ironman").build()));

		Guide.Step both = stepCompleting(questPoints(1), skill("attack", 5, false));
		assertFalse("every entry must be met", GuideRules.completed(both, character().questPoints(1).build()));
		assertFalse("a boostable entry still needs the real level to finish a step",
			GuideRules.completed(stepCompleting(skill("attack", 5, true)), character().level(Skill.ATTACK, 4, 4).build()));
		assertFalse("a kind this version does not know never ticks",
			GuideRules.completed(stepCompleting(new Guide.Requirement(Guide.Requirement.Kind.UNKNOWN, null, 0, false, null, 0,
				Collections.<String>emptyList())), character().build()));
		assertFalse("nothing to complete: only the player ticks it", GuideRules.completed(guide.step("risky-step"),
			character().build()));
	}

	@Test
	public void aQuestStepWithoutCompletesIsDoneWhenItsQuestsAreFinished()
	{
		Guide.Step step = guide.step("sheep-shearer");
		assertTrue(step.completes.isEmpty());
		assertFalse(GuideRules.completed(step, character().quest("Sheep Shearer", QuestState.IN_PROGRESS).build()));
		assertTrue(GuideRules.completed(step, character().quest("Sheep Shearer", QuestState.FINISHED).build()));
	}

	@Test
	public void skippedWinsThenDoneThenOpen()
	{
		Guide.Step step = guide.step("cooks-assistant");
		GuideFacts finished = character().quest("Cook's Assistant", QuestState.FINISHED).build();
		GuideProgress progress = new GuideProgress();
		assertEquals(GuideRules.Status.OPEN, GuideRules.status(step, progress, character().build()));
		assertEquals("ticked by the character", GuideRules.Status.DONE, GuideRules.status(step, progress, finished));
		progress.set(step.id, GuideProgress.Mark.DONE);
		assertEquals(GuideRules.Status.DONE, GuideRules.status(step, progress, GuideFacts.UNKNOWN));
		progress.set(step.id, GuideProgress.Mark.SKIPPED);
		assertEquals(GuideRules.Status.SKIPPED, GuideRules.status(step, progress, finished));
	}

	@Test
	public void theCountLeavesSkippedStepsOutAndTheCurrentStepIsTheFirstOpenOneAfterThePlayersPlace()
	{
		GuideProgress progress = new GuideProgress();
		GuideRules.Count fresh = GuideRules.count(guide, progress, character().build());
		assertEquals("0/5", fresh.toString());
		assertEquals("a new player starts at the first step", "cooks-assistant", fresh.current.id);

		progress.set("cooks-assistant", GuideProgress.Mark.DONE);
		progress.set("sheep-shearer", GuideProgress.Mark.SKIPPED);
		GuideRules.Count count = GuideRules.count(guide, progress, character().level(Skill.COOKING, 10, 10).build());
		assertEquals("done, ticked, and the Mining Instructor passed, out of the four not skipped", "3/4", count.toString());
		assertEquals("risky-step", count.current.id);

		for (Guide.Step step : guide.steps)
		{
			progress.set(step.id, GuideProgress.Mark.DONE);
		}
		GuideRules.Count complete = GuideRules.count(guide, progress, character().build());
		assertEquals("5/5", complete.toString());
		assertNull(complete.current);
	}

	private static Guide.Step step(String id, List<String> quests, List<Guide.Collect> collect)
	{
		return new Guide.Step(id, id, -1, null, null, Collections.<String>emptyList(), null, null,
			Collections.<String>emptySet(), quests, Collections.<Guide.Place>emptyList(), Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Item>emptyList(), collect, Collections.<Guide.Requirement>emptyList(),
			Collections.<Guide.Requirement>emptyList(), null);
	}

	private static Guide.Step questStep(String id, String quest)
	{
		return step(id, Collections.singletonList(quest), Collections.<Guide.Collect>emptyList());
	}

	private static Guide.Step plainStep(String id)
	{
		return step(id, Collections.<String>emptyList(), Collections.<Guide.Collect>emptyList());
	}

	/** Two sections: five quests and a walk, then two quests around a walk. */
	private static Guide route()
	{
		return new Guide("route", "Route", null, null, "r", null, Arrays.asList(
			new Guide.Section("a", "A", null, Arrays.asList(questStep("a1", "Q1"), questStep("a2", "Q2"), plainStep("a3"),
				questStep("a4", "Q3"), questStep("a5", "Q4"), questStep("a6", "Q5"))),
			new Guide.Section("b", "B", null, Arrays.asList(questStep("b1", "Q6"), plainStep("b2"),
				questStep("b3", "Q7")))));
	}

	@Test
	public void theFirstSectionNotMostlyDoneIsWhereThePlayerIs()
	{
		Guide route = route();
		// Four of the first section's five quests, and one far ahead, out of the guide's order.
		GuideFacts facts = character().quest("Q1", QuestState.FINISHED).quest("Q2", QuestState.FINISHED)
			.quest("Q3", QuestState.FINISHED).quest("Q4", QuestState.NOT_STARTED).quest("Q5", QuestState.FINISHED)
			.quest("Q6", QuestState.NOT_STARTED).quest("Q7", QuestState.FINISHED).build();
		GuideRules.Standing standing = GuideRules.standing(route, new GuideProgress(), facts);
		assertEquals("nothing to check, and the player is past it", GuideRules.Status.PASSED, standing.of(route.step("a3")));
		assertEquals("a quest the player never did", GuideRules.Status.BEHIND, standing.of(route.step("a5")));
		assertEquals("b1", standing.count.current.id);
		assertEquals("after the player's place, a walk is still to do", GuideRules.Status.OPEN, standing.of(route.step("b2")));
		assertEquals("a quest done far ahead stays done, and does not move the place", GuideRules.Status.DONE,
			standing.of(route.step("b3")));
		assertEquals("6/9", standing.count.toString());
		assertEquals(Collections.singletonList(route.step("a5")), standing.behind);

		GuideProgress notDone = new GuideProgress();
		notDone.set("a3", GuideProgress.Mark.OPEN);
		GuideRules.Standing said = GuideRules.standing(route, notDone, facts);
		assertEquals("the player said not done", GuideRules.Status.BEHIND, said.of(route.step("a3")));
		assertEquals("5/9", said.count.toString());
	}

	@Test
	public void aDoneStepFarAheadDoesNotMoveThePlayersPlace()
	{
		GuideProgress progress = new GuideProgress();
		progress.set("risky-step", GuideProgress.Mark.DONE);
		GuideRules.Standing standing = GuideRules.standing(guide, progress, character().build());
		assertEquals("cooks-assistant", standing.count.current.id);
		assertTrue(standing.behind.isEmpty());
		assertEquals(GuideRules.Status.OPEN, standing.of(guide.step("mining-instructor")));
		assertEquals(GuideRules.Status.DONE, standing.of(guide.step("risky-step")));
		assertEquals("1/5", standing.count.toString());
	}

	@Test
	public void aPickUpStepIsDoneOnceItsQuestsAreFinishedOrItsUntradeableItemIsOwned()
	{
		Guide.Step fetch = step("fetch", Collections.<String>emptyList(), Collections.singletonList(
			new Guide.Collect(new Guide.Item("Rope", 954, 1), Collections.singletonList("Q9"), "General store")));
		assertFalse(GuideRules.completed(fetch, character().quest("Q9", QuestState.IN_PROGRESS).build()));
		assertTrue("fetched and used", GuideRules.completed(fetch, character().quest("Q9", QuestState.FINISHED).build()));
		assertTrue("its quests are read", GuideRules.quests(fetch).contains("Q9"));

		Map<Integer, Integer> amulet = new HashMap<>();
		amulet.put(552, 1);
		Guide.Step bound = step("bound", Collections.<String>emptyList(), Collections.singletonList(
			new Guide.Collect(new Guide.Item("Ghostspeak amulet", 552, 1, true), Collections.<String>emptyList(), null)));
		assertTrue("an untradeable item only this step gives", GuideRules.completed(bound,
			character().carried(amulet).build()));
		assertTrue("banked counts once the bank is seen", GuideRules.completed(bound,
			character().carried(Collections.<Integer, Integer>emptyMap()).banked(amulet).build()));
		assertFalse(GuideRules.completed(bound, character().carried(Collections.<Integer, Integer>emptyMap()).build()));

		Map<Integer, Integer> rope = new HashMap<>();
		rope.put(954, 1);
		assertFalse("a tradeable item proves nothing", GuideRules.completed(fetch, character().carried(rope).build()));
	}

	@Test
	public void startHereMovesThePlayersPlaceToTheStepBefore()
	{
		GuideProgress progress = new GuideProgress();
		progress.start("cooking-10");
		GuideRules.Standing standing = GuideRules.standing(guide, progress, character().build());
		assertEquals("cooking-10", standing.count.current.id);
		assertEquals(GuideRules.Status.PASSED, standing.of(guide.step("mining-instructor")));
		assertEquals(GuideRules.Status.BEHIND, standing.of(guide.step("cooks-assistant")));
		assertEquals("1/5", standing.count.toString());

		progress.set("risky-step", GuideProgress.Mark.DONE);
		assertEquals("a step done far ahead leaves the start where it is", "cooking-10",
			GuideRules.count(guide, progress, character().build()).current.id);
	}

	@Test
	public void aNewPlayerHasNothingBehind()
	{
		GuideRules.Standing standing = GuideRules.standing(guide, new GuideProgress(), character().build());
		assertTrue(standing.behind.isEmpty());
		for (Guide.Step step : guide.steps)
		{
			assertEquals(GuideRules.Status.OPEN, standing.of(step));
		}
	}

	@Test
	public void marksForStepsTheGuideNoLongerHasAreKeptButNotCounted()
	{
		GuideProgress progress = new GuideProgress();
		progress.set("a-step-the-site-removed", GuideProgress.Mark.DONE);
		progress.set("cooks-assistant", GuideProgress.Mark.DONE);
		assertEquals("1/5", GuideRules.count(guide, progress, character().build()).toString());
		assertSame(GuideProgress.Mark.DONE, GuideProgress.load(progress.toJson().toString()).mark("a-step-the-site-removed"));
	}

	@Test
	public void tickingStoresDoneStepsAndLeavesSkippedOnesSkipped()
	{
		GuideProgress progress = new GuideProgress();
		progress.set("cooking-10", GuideProgress.Mark.SKIPPED);
		GuideFacts facts = character().quest("Cook's Assistant", QuestState.FINISHED).level(Skill.COOKING, 20, 20).build();
		assertTrue(GuideRules.tickCompleted(guide, progress, facts));
		assertSame(GuideProgress.Mark.DONE, progress.mark("cooks-assistant"));
		assertSame(GuideProgress.Mark.SKIPPED, progress.mark("cooking-10"));
		assertFalse("nothing more to tick", GuideRules.tickCompleted(guide, progress, facts));
	}

	@Test
	public void anItemIsCarriedBankedMissingOrUnchecked()
	{
		Guide.Item bucket = new Guide.Item("Bucket", 1925, 2);
		Map<Integer, Integer> one = new HashMap<>();
		one.put(1925, 1);
		Map<Integer, Integer> two = new HashMap<>();
		two.put(1925, 2);
		assertEquals(GuideRules.Have.CARRIED, GuideRules.item(bucket, character().carried(two).build()));
		assertEquals("the bank was not open since login", GuideRules.Have.BANK_UNSEEN,
			GuideRules.item(bucket, character().carried(one).build()));
		assertEquals("one carried and one banked", GuideRules.Have.BANKED,
			GuideRules.item(bucket, character().carried(one).banked(one).build()));
		assertEquals(GuideRules.Have.MISSING, GuideRules.item(bucket, character().banked(one).build()));
		assertEquals(GuideRules.Have.NO_ID, GuideRules.item(new Guide.Item("Pot", -1, 1), character().build()));
	}

	@Test
	public void theQuestsToReadAreEveryOneTheGuideNames()
	{
		assertEquals(new LinkedHashSet<>(Arrays.asList("Cook's Assistant", "Sheep Shearer")), GuideRules.quests(guide));
	}

	private static Guide.Step stepCompleting(Guide.Requirement... completes)
	{
		return new Guide.Step("s", "S", -1, null, null, Collections.<String>emptyList(), null, null,
			Collections.<String>emptySet(), Collections.<String>emptyList(), Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Place>emptyList(), Collections.<Guide.Item>emptyList(), Collections.<Guide.Collect>emptyList(),
			Collections.<Guide.Requirement>emptyList(), Arrays.asList(completes), null);
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** What the game can show that a step without {@code completes} or quests is done, and item ids filled by name. */
public class GuideSignsTest
{
	private final Guide guide = GuideFixtures.guide();

	private static Guide.Step step(String title, List<Guide.Place> places, List<Guide.Item> bring)
	{
		return new Guide.Step("s", title, -1, null, null, Collections.<String>emptyList(), null, null,
			Collections.<String>emptySet(), Collections.<String>emptyList(), places, Collections.<Guide.Place>emptyList(),
			bring, Collections.<Guide.Collect>emptyList(), Collections.<Guide.Requirement>emptyList(),
			Collections.<Guide.Requirement>emptyList(), null);
	}

	@Test
	public void aStepTheSiteDescribesOrAQuestStepHasNoSigns()
	{
		assertTrue("completes and quests tick it already", GuideSigns.of(guide.step("cooks-assistant")).none());
		assertTrue("a quest step", GuideSigns.of(guide.step("sheep-shearer")).none());
		assertTrue("completes: a level", GuideSigns.of(guide.step("cooking-10")).none());
		assertTrue("no verb the signs know", GuideSigns.of(step("Learn to fish", Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Item>emptyList())).none());
	}

	@Test
	public void meetingSomeoneIsTalkingToThem()
	{
		GuideSigns signs = GuideSigns.of(guide.step("mining-instructor"));
		assertTrue(signs.talkedTo("Mining Instructor"));
		assertTrue("a dialogue's name can carry colour tags", signs.talkedTo("<col=ffff00>Mining Instructor</col>"));
		assertFalse(signs.talkedTo("Mining tutor"));
		assertFalse(signs.talkedTo(null));
		assertFalse("talking is not killing", signs.isKill("Mining Instructor"));
	}

	@Test
	public void killingWhatTheStepNames()
	{
		GuideSigns goblin = GuideSigns.of(guide.step("risky-step"));
		assertTrue(goblin.isKill("Goblin"));
		assertEquals(1, goblin.kills);
		assertFalse(goblin.isKill("Man"));

		GuideSigns cows = GuideSigns.of(step("Kill 5 cows", Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Item>emptyList()));
		assertTrue(cows.isKill("Cow"));
		assertEquals(5, cows.kills);
	}

	@Test
	public void reachingThePlaceTheStepSendsYouTo()
	{
		GuideSigns signs = GuideSigns.of(step("Go to Draynor Village",
			Collections.singletonList(new Guide.Place("Draynor Village", null, 3093, 3244, 0)),
			Collections.<Guide.Item>emptyList()));
		assertTrue(signs.reached(3093, 3244, 0));
		assertTrue(signs.reached(3093 + GuideSigns.REACH_TILES, 3244 - GuideSigns.REACH_TILES, 0));
		assertFalse(signs.reached(3093 + GuideSigns.REACH_TILES + 1, 3244, 0));
		assertFalse("another plane", signs.reached(3093, 3244, 1));
		assertTrue("a place with no tile cannot be reached", GuideSigns.of(step("Go to the Mining Instructor",
			Collections.singletonList(new Guide.Place("Mining Instructor", null, -1, -1, -1)),
			Collections.<Guide.Item>emptyList())).none());
	}

	@Test
	public void gettingItemsIsHoldingThemAll()
	{
		GuideSigns signs = GuideSigns.of(step("Buy a hammer and a chisel", Collections.<Guide.Place>emptyList(),
			java.util.Arrays.asList(new Guide.Item("Hammer", 2347, 1), new Guide.Item("Chisel", 1755, 1))));
		Map<Integer, Integer> carried = new HashMap<>();
		carried.put(2347, 1);
		assertFalse("one of two", signs.held(new GuideFacts.Builder().carried(carried).build()));
		carried.put(1755, 1);
		assertTrue(signs.held(new GuideFacts.Builder().carried(carried).build()));
		assertFalse("nothing read yet", signs.held(GuideFacts.UNKNOWN));
		assertTrue("an item with no id cannot be held, so the step is ticked by hand", GuideSigns.of(step("Buy a pot",
			Collections.<Guide.Place>emptyList(), Collections.singletonList(new Guide.Item("Pot", -1, 1)))).none());
	}

	@Test
	public void namesMeetTheGamesNames()
	{
		assertEquals("mining instructor", GuideSigns.name("the Mining Instructor"));
		assertEquals("goblin", GuideSigns.name("Goblins"));
		assertEquals("goblin", GuideSigns.name("a goblin"));
		assertEquals("cow", GuideSigns.name("5 cows"));
		assertEquals("boss", GuideSigns.name("Boss"));
		assertEquals("witch", GuideSigns.name("Witches"));
		assertEquals("cook", GuideSigns.name("<col=ffff00>Cook</col>"));
	}

	@Test
	public void itemIdsTheSiteLeftOutAreFilledByName()
	{
		Guide filled = guide.withItemIds(name -> name.equals("Pot") ? 1931 : name.equals("Bucket") ? 9999 : -1);
		Guide.Step step = filled.step("cooks-assistant");
		assertEquals("the site's id is kept", 1925, step.bring.get(0).id);
		assertEquals(1931, step.bring.get(1).id);
		assertEquals("Pot", step.bring.get(1).name);
		assertEquals(1944, step.collect.get(0).item.id);
		assertEquals("progress keys and revision are untouched", guide.revision, filled.revision);
		assertEquals(guide.steps.size(), filled.steps.size());
		assertSame("nothing to fill: the same guide", guide, guide.withItemIds(name -> -1));
		assertNull(guide.step("missing"));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import org.junit.Test;

/** The words the Guides view and chat use for a guide, a step, its items, requirements and rewards. */
public class GuideTextTest
{
	private final Guide guide = GuideFixtures.guide();

	@Test
	public void aGuideInTheList()
	{
		assertEquals("5 steps, about 9 h, free to play.", GuidesPanel.about(GuideFixtures.listing().find("beginner")));
		assertEquals("120 steps, about 50 h, members.", GuidesPanel.about(GuideFixtures.listing().find("ironman")));
		assertEquals("45 min", GuidesPanel.duration(45));
	}

	@Test
	public void aStepsLengthAndTags()
	{
		assertEquals("About 10 min. Solo.", GuidesPanel.stepAbout(guide.step("cooks-assistant")));
		assertEquals("Risky: you can die.", GuidesPanel.stepAbout(guide.step("risky-step")));
		assertEquals("Optional, a tag from a later site.", GuidesPanel.stepAbout(guide.step("mining-instructor")));
	}

	@Test
	public void itemsAndRequirements()
	{
		Guide.Step step = guide.step("cooks-assistant");
		assertEquals("Bucket", GuidesPanel.itemText(step.bring.get(0)));
		assertEquals("Bucket x3", GuidesPanel.itemText(new Guide.Item("Bucket", 1925, 3)));
		assertEquals(": in your bank", GuidesPanel.haveText(GuideRules.Have.BANKED, true));
		assertEquals("logged out, nothing is checked", "", GuidesPanel.haveText(GuideRules.Have.MISSING, false));
		assertEquals("Egg for Cook's Assistant, from Chicken farm", GuidesPanel.collectText(step.collect.get(0)));
		assertEquals("Cooking 1 (boostable): met", GuidesPanel.requirementText(step.requires.get(0), GuideRules.Met.MET));

		Guide.Step level = guide.step("cooking-10");
		assertEquals("Quest: Cook's Assistant: not yet",
			GuidesPanel.requirementText(level.requires.get(0), GuideRules.Met.MISSING));
		assertEquals("1 quest point", GuidesPanel.requirementText(level.requires.get(1), GuideRules.Met.UNKNOWN));
		assertEquals("Account: Ironman or Hardcore ironman",
			GuidesPanel.requirementText(level.requires.get(2), GuideRules.Met.UNKNOWN));
		assertEquals("A requirement this version of the plugin cannot check. See it on osrsindex.com.",
			GuidesPanel.requirementText(level.requires.get(3), GuideRules.Met.UNKNOWN));
	}

	@Test
	public void rewards()
	{
		assertEquals("300 Cooking xp, 1 quest point. Unlocks: Use of the cook's range.",
			GuidesPanel.rewardsText(guide.step("cooks-assistant").rewards));
		assertEquals("12,500 coins", GuidesPanel.rewardsText(new Guide.Rewards(Collections.<Guide.Xp>emptyList(), 0, 12_500,
			Collections.<Guide.Item>emptyList(), Collections.<String>emptyList())));
	}

	@Test
	public void theStepBoxCutsLongTextAtAWord()
	{
		Guide.Step step = guide.step("cooks-assistant");
		assertEquals("Help the Lumbridge cook bake a cake.", GuideStepOverlay.text(step, false));
		assertEquals("Fill the bucket yourself at the dairy cow.", GuideStepOverlay.text(step, true));
		assertEquals("no Ironman text: the step's own", "Shear sheep and spin the wool.",
			GuideStepOverlay.text(guide.step("sheep-shearer"), true));

		String words = "word ".repeat(100).trim();
		Guide.Step longStep = new Guide.Step("l", "L", -1, null, words, Collections.<String>emptyList(), null, null,
			Collections.<String>emptySet(), Collections.<String>emptyList(), Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Place>emptyList(), Collections.<Guide.Item>emptyList(), Collections.<Guide.Collect>emptyList(),
			Collections.<Guide.Requirement>emptyList(), Collections.<Guide.Requirement>emptyList(), null);
		String cut = GuideStepOverlay.text(longStep, false);
		assertTrue(cut, cut.length() <= GuideStepOverlay.MAX_TEXT + 3);
		assertTrue(cut, cut.endsWith("word..."));
	}

	@Test
	public void walkThereSaysWhatBecameOfThePlace()
	{
		Guide.Place kitchen = guide.step("cooks-assistant").point();
		assertEquals("Routing to Lumbridge Castle kitchen (3208, 3214, 0) with Shortest Path.",
			GuideTracker.walkLine(RouteDispatcher.Kind.ROUTED, kitchen));
		assertEquals("Shortest Path is not on, so the way to Lumbridge Castle kitchen (3208, 3214, 0) cannot be drawn."
			+ " Install or turn it on, then click Walk there again.",
			GuideTracker.walkLine(RouteDispatcher.Kind.NO_PATHING_PLUGIN, kitchen));
		assertEquals("a label cannot open chat markup", "Routing to a<lt>col=ff0000<gt>b (1, 2, 0) with Shortest Path.",
			GuideTracker.walkLine(RouteDispatcher.Kind.ROUTED, new Guide.Place("a<col=ff0000>b", null, 1, 2, 0)));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import java.time.Clock;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.Before;
import org.junit.Test;

/**
 * The guide tracker end to end, with the client, RuneLite and the network faked: nothing is fetched until the
 * player opens the tab, marks are kept per character, the guide moves on by itself, and the markers follow the
 * current step and stand aside while Quest Helper guides a quest.
 */
public class GuideTrackerTest
{
	private static final WorldPoint KITCHEN = new WorldPoint(3208, 3214, 0);
	private static final WorldPoint FRED = new WorldPoint(3190, 3273, 0);

	private final Map<String, Function<Object[], Object>> client = new HashMap<>();
	private final Map<String, Object> settings = new HashMap<>();
	private final Map<String, String> profile = new HashMap<>();
	private final Map<Quest, QuestState> quests = new HashMap<>();
	private final Map<Integer, Integer> varps = new HashMap<>();
	private final List<PluginMessage> posted = new ArrayList<>();
	private final List<String> chat = new ArrayList<>();
	private final List<String> asked = new ArrayList<>();
	private final List<GuideFetcher.Handler> pending = new ArrayList<>();
	private final long[] now = {1_000_000L};
	private boolean questHelperRunning;
	private String autoStart;
	private boolean shortestPathOn = true;

	private GuideTracker.Overlays overlays;
	private GuideTracker tracker;

	@SuppressWarnings("unchecked")
	private static <T> T fake(Class<T> type, Map<String, Function<Object[], Object>> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (proxy, method, args) ->
		{
			Function<Object[], Object> answer = answers.get(method.getName());
			if (answer != null)
			{
				return answer.apply(args);
			}
			Class<?> returns = method.getReturnType();
			if (returns == boolean.class)
			{
				return false;
			}
			if (returns == int.class)
			{
				return 0;
			}
			if (returns == long.class)
			{
				return 0L;
			}
			return null;
		});
	}

	@Before
	public void setUp()
	{
		client.put("getRealSkillLevel", args -> args[0] == Skill.HITPOINTS ? 10 : 1);
		client.put("getBoostedSkillLevel", args -> args[0] == Skill.HITPOINTS ? 10 : 1);
		client.put("getVarpValue", args -> varps.getOrDefault((Integer) args[0], 0));
		Client fakeClient = fake(Client.class, client);

		OsrsIndexConfig config = (OsrsIndexConfig) Proxy.newProxyInstance(OsrsIndexConfig.class.getClassLoader(),
			new Class<?>[]{OsrsIndexConfig.class}, (proxy, method, args) ->
				method.getReturnType() == boolean.class ? settings.getOrDefault(method.getName(), true) : null);

		ClientThread immediate = new ClientThread()
		{
			@Override
			public void invoke(Runnable runnable)
			{
				runnable.run();
			}

			@Override
			public void invokeLater(Runnable runnable)
			{
				runnable.run();
			}
		};

		GuideTracker.Host host = new GuideTracker.Host()
		{
			@Override
			public String profile(String key)
			{
				return profile.get(key);
			}

			@Override
			public void saveProfile(String key, String value)
			{
				profile.put(key, value);
			}

			@Override
			public boolean questHelperRunning()
			{
				return questHelperRunning;
			}

			@Override
			public String questHelperAutoStart()
			{
				return autoStart;
			}

			@Override
			public QuestState questState(Quest quest)
			{
				return quests.getOrDefault(quest, QuestState.NOT_STARTED);
			}

			@Override
			public void post(PluginMessage message)
			{
				posted.add(message);
			}

			@Override
			public void chat(String message)
			{
				chat.add(message);
			}
		};

		GuideFetcher fetcher = new GuideFetcher((url, etag, handler) ->
		{
			asked.add(url);
			pending.add(handler);
		}, () -> now[0]);
		RouteDispatcher dispatcher = new RouteDispatcher(posted::add, plugin -> shortestPathOn, Clock.systemUTC());
		overlays = new GuideTracker.Overlays(new GuideMinimapOverlay(fakeClient), new GuideTileOverlay(fakeClient),
			new GuideStepOverlay());
		tracker = new GuideTracker(fakeClient, immediate, host, config, fetcher, dispatcher, new WorldMapPointManager(), overlays,
			new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB));
	}

	private void answer(String body)
	{
		pending.remove(0).handle(200, body, null);
	}

	private void answer(int status)
	{
		pending.remove(0).handle(status, "", null);
	}

	/** Logged in, the Guides tab opened and the fixture guide opened from the list. */
	private void followTheFixture()
	{
		tracker.loggedIn();
		tracker.opened();
		answer(GuideFixtures.read(GuideFixtures.LISTING));
		tracker.openGuide("beginner");
		answer(GuideFixtures.read(GuideFixtures.GUIDE));
	}

	private WorldPoint mapPoint()
	{
		WorldMapPoint point = tracker.mapPoint();
		return point == null ? null : point.getWorldPoint();
	}

	@Test
	public void nothingIsFetchedUntilThePlayerOpensTheTab()
	{
		profile.put(GuideTracker.FOLLOWED_KEY, "beginner");
		tracker.loggedIn();
		tracker.tick();
		assertTrue("not at login, even with a guide followed", asked.isEmpty());

		tracker.opened();
		assertEquals(List.of(Endpoints.guides()), asked);
		answer(GuideFixtures.read(GuideFixtures.LISTING));
		assertEquals("the followed guide comes back once the list says it is offered", Endpoints.guide("beginner"),
			asked.get(1));
		answer(GuideFixtures.read(GuideFixtures.GUIDE));
		GuidesPanel.View view = tracker.lastView();
		assertTrue(view.guideOpen);
		assertSame(GuidesPanel.Load.OK, view.guideLoad);
		assertEquals("beginner", view.guide.id);
	}

	@Test
	public void showGuidesOffFetchesNothing()
	{
		settings.put("showGuides", false);
		tracker.opened();
		assertTrue(asked.isEmpty());
	}

	@Test
	public void openingAGuideFollowsItAndPointsAtItsCurrentStep()
	{
		followTheFixture();
		assertEquals("beginner", profile.get(GuideTracker.FOLLOWED_KEY));
		assertEquals(KITCHEN, mapPoint());
		assertEquals("Cook's Assistant", tracker.mapPoint().getName());
		assertEquals(KITCHEN, overlays.minimap.target());
		assertEquals(KITCHEN, overlays.tile.target());
		GuideStepOverlay.Box box = overlays.step.shown();
		assertEquals("Beginner walkthrough", box.guide);
		assertEquals("0/5", box.count);
		assertEquals("Cook's Assistant", box.step);
		assertEquals("Help the Lumbridge cook bake a cake.", box.text);
		assertEquals("Lumbridge Castle kitchen", box.where);
		assertEquals("the bucket: not carried, bank not seen", List.of("Bucket"), box.missing);
		assertNull("Quest Helper is not running", box.questHelper);
	}

	@Test
	public void marksAreKeptAndTheGuideMovesOn()
	{
		followTheFixture();
		tracker.markStep("cooks-assistant", GuideProgress.Mark.DONE);
		assertEquals("{\"cooks-assistant\":\"done\"}", profile.get(GuideTracker.PROGRESS_KEY_PREFIX + "beginner"));
		assertEquals(FRED, mapPoint());
		assertEquals("1/5", overlays.step.shown().count);

		tracker.markStep("sheep-shearer", GuideProgress.Mark.SKIPPED);
		assertNull("the next step has only a label", mapPoint());
		assertNull(overlays.minimap.target());
		assertEquals("Mining Instructor", overlays.step.shown().where);
		assertEquals("1/4", overlays.step.shown().count);

		tracker.markStep("sheep-shearer", null);
		tracker.markStep("cooks-assistant", null);
		assertEquals(KITCHEN, mapPoint());
		assertEquals("{}", profile.get(GuideTracker.PROGRESS_KEY_PREFIX + "beginner"));
	}

	@Test
	public void marksArePerCharacterAndNeedALogin()
	{
		profile.put(GuideTracker.PROGRESS_KEY_PREFIX + "beginner", "{\"cooks-assistant\":\"done\"}");
		followTheFixture();
		assertEquals(FRED, mapPoint());

		tracker.loggedOut();
		assertNull("logged out, nothing points anywhere", mapPoint());
		assertNull(overlays.minimap.target());
		assertNull(overlays.step.shown());
		tracker.markStep("sheep-shearer", GuideProgress.Mark.DONE);
		assertEquals("no mark without a character", "{\"cooks-assistant\":\"done\"}",
			profile.get(GuideTracker.PROGRESS_KEY_PREFIX + "beginner"));
		assertFalse(tracker.lastView().loggedIn);

		// Another character: its own marks, here none.
		profile.remove(GuideTracker.PROGRESS_KEY_PREFIX + "beginner");
		tracker.loggedIn();
		assertEquals(KITCHEN, mapPoint());
	}

