		tracker.markStep("cooks-assistant", GuideProgress.Mark.DONE);
		tracker.markStep("sheep-shearer", GuideProgress.Mark.SKIPPED);
		assertEquals("Meet the Mining Instructor", overlays.step.shown().step);
