/**
 * Draws the README's panel images from the plugin's own {@link OsrsIndexPanel}, in RuneLite's look, with a sample
 * character and code, so no image carries anyone's account: {@code gradlew panelImages}. Each image is the panel at
 * the sidebar's width, doubled pixel for pixel so it stays sharp.
 */
public class PanelImages
{
	private static final String CHARACTER = "Zezima";
	private static final String CODE = "KXQ4-7MNP";
	private static final GuidesPanel.Actions NO_GUIDE_ACTIONS = new GuidesPanel.Actions()
	{
		@Override
		public void retryGuides()
		{
		}

		@Override
		public void openGuide(String guideId)
		{
		}

		@Override
		public void showGuideList()
		{
		}

		@Override
		public void markStep(String stepId, GuideProgress.Mark mark)
		{
		}

		@Override
		public void walkTo(String stepId)
		{
		}

		@Override
		public void followWithQuestHelper(String stepId)
		{
		}

		@Override
		public void startHere(String stepId)
		{
		}
	};

	public static void main(String[] args) throws Exception
	{
		File out = new File(args.length > 0 ? args[0] : "images");
		if (!out.isDirectory() && !out.mkdirs())
		{
			throw new IOException("Cannot make " + out);
		}
		SwingUtilities.invokeAndWait(RuneLiteLAF::setup);

		draw(out, "panel-not-linked", panel ->
		{
			panel.showNotLinked(null);
			panel.showDestinations(OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.OFF, true, false, true,
				false));
		});
		draw(out, "panel-link-code", panel ->
		{
			panel.showCode(CODE);
			panel.showDestinations(OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.OFF, true, false, true,
				false));
		});
		draw(out, "panel-linked", panel ->
		{
			panel.showLinked(CHARACTER, "Last sync at 14:02: location, skills and bank.");
			panel.showDestinations(OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.LISTENING, true, true,
				true, false));
		});
		draw(out, "panel-notice", panel ->
		{
			panel.showNotice(new SiteConfig.Notice("maintenance", "osrsindex.com is down for maintenance on"
				+ " 20 October from 18:00 to 19:00 UTC.", "https://osrsindex.com/", false));
			panel.showLinked(CHARACTER, OsrsIndexPlugin.waitLine(java.time.LocalTime.of(18, 4),
				"osrsindex.com is down for maintenance until 19:00 UTC."));
			panel.showDestinations(OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.RETRYING, true, true,
				true, false));
		});
		draw(out, "panel-guides", (panel, guides) ->
		{
			panel.selectGuidesTab();
			guides.show(new GuidesPanel.View(GuidesPanel.Load.OK, GuideFixtures.listing(), false, GuidesPanel.Load.NONE,
				null, new GuideProgress(), GuideFacts.UNKNOWN, true, false, true, QuestHelperHandOff.Gang.UNKNOWN, null));
		});
		draw(out, "panel-guide-step", (panel, guides) ->
		{
			panel.selectGuidesTab();
			Map<Integer, Integer> carried = new HashMap<>();
			carried.put(1925, 1);
			GuideFacts.Builder facts = new GuideFacts.Builder().questPoints(0).accountType("normal").carried(carried)
				.quest("Cook's Assistant", QuestState.NOT_STARTED).quest("Sheep Shearer", QuestState.NOT_STARTED);
			for (Skill skill : Skill.values())
			{
				facts.level(skill, skill == Skill.HITPOINTS ? 10 : 1, skill == Skill.HITPOINTS ? 10 : 1);
			}
			guides.show(new GuidesPanel.View(GuidesPanel.Load.OK, GuideFixtures.listing(), true, GuidesPanel.Load.OK,
				GuideFixtures.guide(), new GuideProgress(), facts.build(), true, true, true, QuestHelperHandOff.Gang.UNKNOWN,
				null));
		});
		draw(out, "panel-guide-progress", (panel, guides) ->
		{
			panel.selectGuidesTab();
			// An account that is not new: Cook's Assistant finished and 10 Cooking reached, Sheep Shearer never done, and
			// Start here on the goblin. The Mining Instructor, with nothing to check, is passed; Sheep Shearer is behind.
			GuideProgress progress = new GuideProgress();
			progress.start("risky-step");
			GuideFacts.Builder facts = new GuideFacts.Builder().questPoints(1).accountType("ironman")
				.carried(Collections.<Integer, Integer>emptyMap()).banked(Collections.singletonMap(1925, 1))
				.quest("Cook's Assistant", QuestState.FINISHED)
				.quest("Sheep Shearer", QuestState.NOT_STARTED);
			for (Skill skill : Skill.values())
			{
				int level = skill == Skill.HITPOINTS || skill == Skill.COOKING ? 10 : 1;
				facts.level(skill, level, level);
			}
			guides.show(new GuidesPanel.View(GuidesPanel.Load.OK, GuideFixtures.listing(), true, GuidesPanel.Load.OK,
				GuideFixtures.guide(), progress, facts.build(), true, false, true, QuestHelperHandOff.Gang.UNKNOWN, null));
			guides.openStep("cooks-assistant");
			guides.openStep("mining-instructor");
		});
		drawStepBox(out);
		System.exit(0);
	}

	/** The step box the plugin draws on the game screen, over a plain background, doubled like the panels. */
	private static void drawStepBox(File out) throws IOException
	{
		GuideStepOverlay overlay = new GuideStepOverlay();
		overlay.show(new GuideStepOverlay.Box("Beginner walkthrough", "0/5", "Cook's Assistant",
			"Help the Lumbridge cook bake a cake.", "Lumbridge Castle kitchen", Collections.singletonList("Bucket"),
			"Quest Helper takes over when you start Cook's Assistant."));
		// Drawn on a large canvas, then cut out with a margin. A panel sizes itself from the frame before, as it does
		// in the client every frame, so the first frame only measures.
		BufferedImage canvas = new BufferedImage(600, 600, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = canvas.createGraphics();
		g.setFont(FontManager.getRunescapeFont());
		overlay.render(g);
		g.setColor(new Color(0x3E, 0x35, 0x29));
		g.fillRect(0, 0, canvas.getWidth(), canvas.getHeight());
		g.translate(8, 8);
		Dimension size = overlay.render(g);
		g.dispose();
		BufferedImage flat = canvas.getSubimage(0, 0, size.width + 16, size.height + 16);
		BufferedImage doubled = new BufferedImage(flat.getWidth() * 2, flat.getHeight() * 2, BufferedImage.TYPE_INT_RGB);
		Graphics2D big = doubled.createGraphics();
		big.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		big.drawImage(flat, 0, 0, doubled.getWidth(), doubled.getHeight(), null);
		big.dispose();
		File file = new File(out, "step-box.png");
		ImageIO.write(doubled, "png", file);
		System.out.println("wrote " + file.getPath() + " (" + doubled.getWidth() + "x" + doubled.getHeight() + ")");
	}

	private interface State
	{
		void apply(OsrsIndexPanel panel);
	}

	private interface GuidesState
	{
		void apply(OsrsIndexPanel panel, GuidesPanel guides);
	}

	private static void draw(File out, String name, State state) throws Exception
	{
		draw(out, name, (GuidesState) (panel, guides) -> state.apply(panel));
	}

	private static void draw(File out, String name, GuidesState state) throws Exception
	{
		OsrsIndexPanel[] holder = new OsrsIndexPanel[1];
		GuidesPanel[] guides = new GuidesPanel[1];
		JFrame[] frame = new JFrame[1];
		SwingUtilities.invokeAndWait(() ->
		{
			guides[0] = new GuidesPanel(NO_GUIDE_ACTIONS);
			holder[0] = new OsrsIndexPanel(new OsrsIndexPanel.Actions()
			{
				@Override
				public void guidesOpened()
				{
				}

				@Override
				public void linkWithBrowser()
				{
				}

				@Override
				public void requestNewCode()
				{
				}

				@Override
				public void unlink()
				{
				}

				@Override
				public void openMapHere()
				{
				}
			}, guides[0]);
		});
		// The panel's own updates go through invokeLater; queue them, then let them run.
		state.apply(holder[0], guides[0]);
		SwingUtilities.invokeAndWait(() ->
		{
		});
		BufferedImage[] image = new BufferedImage[1];
		SwingUtilities.invokeAndWait(() ->
		{
			OsrsIndexPanel panel = holder[0];
			// Never shown: packing gives the components a peer, so they lay out and paint as in the client.
			frame[0] = new JFrame();
			frame[0].add(panel);
			panel.setSize(new Dimension(PluginPanel.PANEL_WIDTH, 10));
			int height = panel.getPreferredSize().height;
			panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, height));
			frame[0].pack();
			layout(panel);
			BufferedImage flat = new BufferedImage(PluginPanel.PANEL_WIDTH, height, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = flat.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			panel.paint(g);
			g.dispose();
			BufferedImage doubled = new BufferedImage(flat.getWidth() * 2, flat.getHeight() * 2, BufferedImage.TYPE_INT_RGB);
			Graphics2D big = doubled.createGraphics();
			big.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			big.drawImage(flat, 0, 0, doubled.getWidth(), doubled.getHeight(), null);
			big.dispose();
			image[0] = doubled;
			frame[0].dispose();
		});
		File file = new File(out, name + ".png");
		ImageIO.write(image[0], "png", file);
		System.out.println("wrote " + file.getPath() + " (" + image[0].getWidth() + "x" + image[0].getHeight() + ")");
	}

	private static void layout(Component component)
	{
		component.doLayout();
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				layout(child);
			}
		}
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.time.Instant;
import org.junit.Test;

public class PartTimesTest
{
	private static final Instant BANK_AT = Instant.parse("2026-10-07T14:02:11Z");
	private static final Instant STORAGE_AT = Instant.parse("2026-10-07T13:00:00Z");
	private static final Instant KILLS_AT = Instant.parse("2026-10-07T14:40:00Z");

	@Test
	public void keepsEachTimeToTheSecond()
	{
		PartTimes times = new PartTimes();
		times.mark(Part.BANK, Instant.parse("2026-10-07T14:02:11.875Z"));

		assertEquals(BANK_AT, times.asMap().get(Part.BANK));
	}

	@Test
	public void aLaterMarkReplacesTheEarlierOne()
	{
		PartTimes times = new PartTimes();
		times.mark(Part.KILL_COUNTS, STORAGE_AT);
		times.mark(Part.KILL_COUNTS, KILLS_AT);

		assertEquals(KILLS_AT, times.asMap().get(Part.KILL_COUNTS));
	}

	@Test
	public void theProfileKeepsOnlyThePartsItKeeps()
	{
		// The bank is not kept in the profile, so neither is its time.
		PartTimes times = new PartTimes();
		times.mark(Part.BANK, BANK_AT);
		times.mark(Part.STORAGE, STORAGE_AT);
		times.mark(Part.KILL_COUNTS, KILLS_AT);

		JsonObject saved = times.toJson();

		assertEquals(2, saved.size());
		assertEquals("2026-10-07T13:00:00Z", saved.get("storage").getAsString());
		assertEquals("2026-10-07T14:40:00Z", saved.get("kill_counts").getAsString());
		assertFalse(saved.has("bank"));
	}

	@Test
	public void aSavedProfileRestoresTheTimesAndLeavesTheBankAlone()
	{
		PartTimes before = new PartTimes();
		before.mark(Part.STORAGE, STORAGE_AT);
		before.mark(Part.KILL_COUNTS, KILLS_AT);
		String saved = before.toJson().toString();

		// The bank can be read before the profile loads at login.
		PartTimes after = new PartTimes();
		after.mark(Part.BANK, BANK_AT);
		after.mark(Part.STORAGE, Instant.parse("2026-10-01T00:00:00Z"));
		after.load(saved);

		assertEquals(STORAGE_AT, after.asMap().get(Part.STORAGE));
		assertEquals(KILLS_AT, after.asMap().get(Part.KILL_COUNTS));
		assertEquals(BANK_AT, after.asMap().get(Part.BANK));
	}

	@Test
	public void aProfileFromBeforeTimesLeavesTheSavedPartsUndated()
	{
		PartTimes times = new PartTimes();
		times.mark(Part.STORAGE, STORAGE_AT);
		times.load(null);

		assertNull(times.asMap().get(Part.STORAGE));
	}

	@Test
	public void aMalformedProfileValueLoadsWhatItCan()
	{
		PartTimes times = new PartTimes();
		times.load("{\"storage\":\"yesterday\",\"kill_counts\":\"2026-10-07T14:40:00Z\",\"bank\":\"2026-10-07T14:02:11Z\"}");

		assertNull(times.asMap().get(Part.STORAGE));
		assertEquals(KILLS_AT, times.asMap().get(Part.KILL_COUNTS));
		// Only the parts the profile keeps are read from it.
		assertNull(times.asMap().get(Part.BANK));

		times.load("not json");
		assertTrue(times.asMap().isEmpty());
		times.load("[1]");
		assertTrue(times.asMap().isEmpty());
	}

	@Test
	public void clearForgetsEveryTime()
	{
		PartTimes times = new PartTimes();
		times.mark(Part.BANK, BANK_AT);
		times.mark(Part.STORAGE, STORAGE_AT);
		times.clear();

		assertTrue(times.asMap().isEmpty());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import org.junit.Test;

public class PayloadPackerTest
{
	private static final Gson GSON = new Gson();

	private static JsonArray bank(int items)
	{
		JsonArray out = new JsonArray();
		for (int i = 0; i < items; i++)
		{
			out.add(CharacterReader.itemJson(1_000 + i, 1_000_000 + i));
		}
		return out;
	}

	private static JsonObject location()
	{
		JsonObject out = new JsonObject();
		out.addProperty("x", 3222);
		out.addProperty("y", 3218);
		out.addProperty("plane", 0);
		return out;
	}

	@Test
	public void carriesTheHeaderAndEveryPartThatFits()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.LOCATION, location());
		pending.put(Part.BANK, bank(3));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 2, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);

		JsonObject body = new JsonParser().parse(packed.json).getAsJsonObject();
		assertEquals(2, body.get("schema").getAsInt());
		assertEquals("Zezima", body.get("character").getAsString());
		assertEquals("2026-09-24T18:00:00Z", body.get("captured_at").getAsString());
		assertEquals(3222, body.getAsJsonObject("location").get("x").getAsInt());
		assertEquals(3, body.getAsJsonArray("bank").size());
		assertEquals(EnumSet.of(Part.LOCATION, Part.BANK), packed.parts);
	}

	@Test
	public void schemaOneDropsEverySection()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.LOCATION, location());
		pending.put(Part.BANK, bank(1));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 1, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);

		JsonObject body = new JsonParser().parse(packed.json).getAsJsonObject();
		assertFalse(body.has("location"));
		assertTrue(body.has("bank"));
		assertEquals(EnumSet.of(Part.BANK), packed.parts);
	}

	@Test
	public void nothingToSendUnderSchemaOneIsNull()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.SKILLS, new JsonObject());

		assertNull(PayloadPacker.pack(GSON, 1, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000));
	}

	@Test
	public void aPartThatWouldBreakTheBudgetWaitsForTheNextSync()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.BANK, bank(2_000));
		JsonObject log = new JsonObject();
		log.addProperty("obtained", 3_000);
		log.addProperty("total", 3_000);
		log.add("items", bank(3_000));
		pending.put(Part.COLLECTION_LOG, log);

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 2, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);

		assertEquals(EnumSet.of(Part.BANK), packed.parts);
		assertTrue(packed.json.getBytes(StandardCharsets.UTF_8).length <= 120_000);
	}

	@Test
	public void aSinglePartLargerThanTheBudgetIsStillSentAlone()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.BANK, bank(2_000));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 2, "Zezima", "2026-09-24T18:00:00Z", pending, 1_000);

		assertEquals(EnumSet.of(Part.BANK), packed.parts);
	}

	@Test
	public void inventoryKeepsEmptySlotsSoIndexesStaySlots()
	{
		JsonArray inventory = new JsonArray();
		inventory.add(CharacterReader.itemJson(995, 1_000));
		inventory.add(JsonNull.INSTANCE);
		inventory.add(CharacterReader.itemJson(385, 1));
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.INVENTORY, inventory);

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 2, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);

		JsonArray sent = new JsonParser().parse(packed.json).getAsJsonObject().getAsJsonArray("inventory");
		assertEquals(3, sent.size());
		assertTrue(sent.get(1).isJsonNull());
	}

	@Test
	public void schemaTwoHoldsBackTheSchemaThreeParts()
	{
		JsonObject vars = new JsonObject();
		vars.addProperty("SLAYER_POINTS", 420);
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.VARS, vars);
		pending.put(Part.LOCATION, location());

		PayloadPacker.Packed two = PayloadPacker.pack(GSON, 2, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);
		PayloadPacker.Packed three = PayloadPacker.pack(GSON, 3, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);

		assertEquals(EnumSet.of(Part.LOCATION), two.parts);
		assertEquals(EnumSet.of(Part.LOCATION, Part.VARS), three.parts);
	}

	@Test
	public void theFullVarAllowlistFitsInOneSyncOnItsOwn()
	{
		JsonObject vars = new JsonObject();
		for (String name : GameVars.VARBIT_NAMES)
		{
			vars.addProperty(name, 2_147_483_647);
		}
		for (String name : GameVars.VARP_NAMES)
		{
			vars.addProperty(name, -2_147_483_648);
		}
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.VARS, vars);

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 3, "Zezima", "2026-09-24T18:00:00Z", pending, 120_000);

		assertTrue(packed.json.getBytes(StandardCharsets.UTF_8).length <= 131_072);
		assertEquals(GameVars.VARBIT_NAMES.length, GameVars.VARBIT_IDS.length);
		assertEquals(GameVars.VARP_NAMES.length, GameVars.VARP_IDS.length);
	}

	// --- part times (schema 5) ------------------------------------------------

	private static final String SENT_AT = "2026-10-07T15:00:00Z";

	private static JsonObject killCounts()
	{
		JsonObject out = new JsonObject();
		out.addProperty("Vorkath", 1234);
		return out;
	}

	@Test
	public void schemaFiveDatesThePartsReadBeforeTheSend()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.LOCATION, location());
		pending.put(Part.BANK, bank(3));
		pending.put(Part.KILL_COUNTS, killCounts());
		Map<Part, Instant> times = new EnumMap<>(Part.class);
		times.put(Part.BANK, Instant.parse("2026-10-07T14:02:11Z"));
		times.put(Part.KILL_COUNTS, Instant.parse("2026-10-07T14:40:00Z"));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 5, "Zezima", SENT_AT, pending, times, 120_000);

		JsonObject body = new JsonParser().parse(packed.json).getAsJsonObject();
		assertEquals(5, body.get("schema").getAsInt());
		assertEquals(SENT_AT, body.get("captured_at").getAsString());
		JsonObject captured = body.getAsJsonObject("captured");
		assertEquals(2, captured.size());
		assertEquals("2026-10-07T14:02:11Z", captured.get("bank").getAsString());
		assertEquals("2026-10-07T14:40:00Z", captured.get("kill_counts").getAsString());
		// Location is read at the send, so captured_at dates it.
		assertFalse(captured.has("location"));
		assertEquals(EnumSet.of(Part.LOCATION, Part.KILL_COUNTS, Part.BANK), packed.parts);
	}

	@Test
	public void anOlderSchemaSendsTheSamePartsUndated()
	{
		// After the site answers schema 5 with unsupported_schema, the plugin steps down and drops the times.
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.BANK, bank(3));
		pending.put(Part.KILL_COUNTS, killCounts());
		Map<Part, Instant> times = new EnumMap<>(Part.class);
		times.put(Part.BANK, Instant.parse("2026-10-07T14:02:11Z"));
		times.put(Part.KILL_COUNTS, Instant.parse("2026-10-07T14:40:00Z"));

		for (int schema = 1; schema < Part.PART_TIMES_SCHEMA; schema++)
		{
			PayloadPacker.Packed packed = PayloadPacker.pack(GSON, schema, "Zezima", SENT_AT, pending, times, 120_000);

			JsonObject body = new JsonParser().parse(packed.json).getAsJsonObject();
			assertEquals(schema, body.get("schema").getAsInt());
			assertFalse("schema " + schema, body.has("captured"));
			assertEquals(schema >= 3 ? EnumSet.of(Part.KILL_COUNTS, Part.BANK) : EnumSet.of(Part.BANK), packed.parts);
		}
	}

	@Test
	public void aBodyWithNothingToDateCarriesNoCapturedField()
	{
		// The site refuses an empty captured, so none is sent.
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.LOCATION, location());
		Map<Part, Instant> times = new EnumMap<>(Part.class);
		times.put(Part.BANK, Instant.parse("2026-10-07T14:02:11Z"));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 5, "Zezima", SENT_AT, pending, times, 120_000);

		assertFalse(new JsonParser().parse(packed.json).getAsJsonObject().has("captured"));
		PayloadPacker.Packed undated = PayloadPacker.pack(GSON, 5, "Zezima", SENT_AT, pending, 120_000);
		assertFalse(new JsonParser().parse(undated.json).getAsJsonObject().has("captured"));
	}

	@Test
	public void aTimeNotBeforeTheSendIsLeftOut()
	{
		// The site refuses a part time later than captured_at; one equal to it says nothing captured_at does not.
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.BANK, bank(3));
		pending.put(Part.KILL_COUNTS, killCounts());
		Map<Part, Instant> times = new EnumMap<>(Part.class);
		times.put(Part.BANK, Instant.parse(SENT_AT));
		times.put(Part.KILL_COUNTS, Instant.parse("2026-10-07T15:00:01Z"));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 5, "Zezima", SENT_AT, pending, times, 120_000);

		assertFalse(new JsonParser().parse(packed.json).getAsJsonObject().has("captured"));
		assertEquals(EnumSet.of(Part.KILL_COUNTS, Part.BANK), packed.parts);
	}

	@Test
	public void aTimeIsSentToTheSecond()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.BANK, bank(1));
		Map<Part, Instant> times = new EnumMap<>(Part.class);
		times.put(Part.BANK, Instant.parse("2026-10-07T14:02:11.875Z"));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 5, "Zezima", SENT_AT, pending, times, 120_000);

		JsonObject captured = new JsonParser().parse(packed.json).getAsJsonObject().getAsJsonObject("captured");
		assertEquals("2026-10-07T14:02:11Z", captured.get("bank").getAsString());
	}

	@Test
	public void aPartThatWaitsForTheNextSyncTakesItsTimeWithIt()
	{
		// The site refuses a time for a part the body does not carry.
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		JsonObject stores = new JsonObject();
		stores.add("seed_vault", bank(2_000));
		pending.put(Part.STORAGE, stores);
		pending.put(Part.BANK, bank(2_000));
		Map<Part, Instant> times = new EnumMap<>(Part.class);
		times.put(Part.STORAGE, Instant.parse("2026-10-07T13:00:00Z"));
		times.put(Part.BANK, Instant.parse("2026-10-07T14:02:11Z"));

		PayloadPacker.Packed packed = PayloadPacker.pack(GSON, 5, "Zezima", SENT_AT, pending, times, 120_000);

		assertEquals(EnumSet.of(Part.STORAGE), packed.parts);
		JsonObject captured = new JsonParser().parse(packed.json).getAsJsonObject().getAsJsonObject("captured");
		assertEquals(1, captured.size());
		assertEquals("2026-10-07T13:00:00Z", captured.get("storage").getAsString());
		assertTrue(packed.json.getBytes(StandardCharsets.UTF_8).length <= 120_000);
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.After;
import org.junit.Test;

public class PluginBusTest
{
	private final List<Throwable> thrown = new ArrayList<>();
	private final EventBus eventBus = new EventBus(thrown::add);
	/** Every lifecycle message, in the order it was posted. */
	private final List<PluginMessage> seen = new ArrayList<>();

	{
		// A higher priority runs first, so a reply posted from inside a member is recorded after its cause.
		eventBus.register(PluginMessage.class, message ->
		{
			if (PluginBus.NAMESPACE.equals(message.getNamespace()))
			{
				seen.add(message);
			}
		}, 100);
	}

	@After
	public void nothingWasThrownIntoTheEventBus()
	{
		assertTrue("subscribers threw: " + thrown, thrown.isEmpty());
	}

	private PluginBus member(String id, String... accepts)
	{
		PluginBus bus = new PluginBus(eventBus::post, new PluginBus.Member(id, "Name of " + id, "1.2.3",
			PluginBus.BUS_VERSION, Arrays.asList(accepts), Collections.singletonList("news")));
		eventBus.register(PluginMessage.class, bus::onPluginMessage, 0);
		return bus;
	}

	private List<String> names()
	{
		return seen.stream().map(PluginMessage::getName).collect(Collectors.toList());
	}

	private void post(String name, Map<String, Object> data)
	{
		eventBus.post(new PluginMessage(PluginBus.NAMESPACE, name, data));
	}

	private static Map<String, Object> hello(String plugin, Object bus)
	{
		Map<String, Object> data = new HashMap<>();
		data.put(PluginBus.PLUGIN, plugin);
		data.put(PluginBus.NAME, "Other");
		data.put(PluginBus.VERSION, "9.9.9");
		data.put(PluginBus.BUS, bus);
		data.put(PluginBus.ACCEPTS, Collections.singletonList("path"));
		data.put(PluginBus.POSTS, Collections.emptyList());
		return data;
	}

	@Test
	public void startSaysHelloThenDiscovers()
	{
		member("osrsindex").start();

		assertEquals(Arrays.asList("hello", "discover"), names());
		Map<String, Object> hello = seen.get(0).getData();
		assertEquals("osrsindex", hello.get(PluginBus.PLUGIN));
		assertEquals("Name of osrsindex", hello.get(PluginBus.NAME));
		assertEquals("1.2.3", hello.get(PluginBus.VERSION));
		assertEquals(1, hello.get(PluginBus.BUS));
		assertEquals(Collections.emptyList(), hello.get(PluginBus.ACCEPTS));
		assertEquals(Collections.singletonList("news"), hello.get(PluginBus.POSTS));
		assertEquals("osrsindex", seen.get(1).getData().get(PluginBus.FROM));
	}

	@Test
	public void aDiscoverFromAnotherPluginGetsExactlyOneHello()
	{
		member("osrsindex").start();
		seen.clear();

		post(PluginBus.DISCOVER, Collections.singletonMap(PluginBus.FROM, "farmrouteplanner"));

		assertEquals(Arrays.asList("discover", "hello"), names());
		assertEquals("osrsindex", seen.get(1).getData().get(PluginBus.PLUGIN));
	}

	@Test
	public void anAnonymousDiscoverIsAnsweredToo()
	{
		member("osrsindex").start();
		seen.clear();

		post(PluginBus.DISCOVER, Collections.emptyMap());

		assertEquals(Arrays.asList("discover", "hello"), names());
	}

	@Test
	public void twoMembersFindEachOtherWhicheverStartsFirst()
	{
		PluginBus index = member("osrsindex");
		PluginBus farm = member("farmrouteplanner", "path", "clear");

		index.start();
		farm.start();

		assertEquals(Collections.singleton("farmrouteplanner"), index.members().keySet());
		assertEquals(Collections.singleton("osrsindex"), farm.members().keySet());
		assertTrue(index.accepts("farmrouteplanner", "path"));
		assertFalse(index.accepts("farmrouteplanner", "transports"));
		assertFalse(index.accepts("slayerrouteplanner", "path"));

		PluginBus.Member seenFarm = index.members().get("farmrouteplanner");
		assertEquals("Name of farmrouteplanner", seenFarm.name);
		assertEquals("1.2.3", seenFarm.version);
		assertEquals(Collections.singletonList("news"), seenFarm.posts);
	}

	@Test
	public void theOtherStartOrderGivesTheSameTables()
	{
		PluginBus index = member("osrsindex");
		PluginBus farm = member("farmrouteplanner", "path");

		farm.start();
		index.start();

		assertEquals(Collections.singleton("farmrouteplanner"), index.members().keySet());
		assertEquals(Collections.singleton("osrsindex"), farm.members().keySet());
	}

	@Test
	public void aHelloIsNeverAnsweredWithAHello()
	{
		member("osrsindex").start();
		seen.clear();

		post(PluginBus.HELLO, hello("farmrouteplanner", 1));

		assertEquals(Collections.singletonList("hello"), names());
	}

	@Test
	public void stopSaysByeAndTheOthersForgetIt()
	{
		PluginBus index = member("osrsindex");
		PluginBus farm = member("farmrouteplanner");
		index.start();
		farm.start();
		seen.clear();

		farm.stop();

		assertEquals(Collections.singletonList("bye"), names());
		assertEquals("farmrouteplanner", seen.get(0).getData().get(PluginBus.PLUGIN));
		assertTrue(index.members().isEmpty());
		assertTrue(farm.members().isEmpty());
	}

	@Test
	public void aStoppedMemberIgnoresEverything()
	{
		PluginBus index = member("osrsindex");
		index.start();
		index.stop();
		seen.clear();

		post(PluginBus.DISCOVER, Collections.singletonMap(PluginBus.FROM, "farmrouteplanner"));
		post(PluginBus.HELLO, hello("farmrouteplanner", 1));

		assertEquals(Arrays.asList("discover", "hello"), names());
		assertTrue(index.members().isEmpty());
	}

	@Test
	public void stoppingTwiceSaysByeOnce()
	{
		PluginBus index = member("osrsindex");
		index.start();
		seen.clear();

		index.stop();
		index.stop();

		assertEquals(Collections.singletonList("bye"), names());
	}

	@Test
	public void refreshDropsAMemberThatCrashedWithoutBye()
	{
		PluginBus index = member("osrsindex");
		PluginBus crashing = new PluginBus(eventBus::post, new PluginBus.Member("slayerrouteplanner", "Slayer",
			"0.1.0", 1, Collections.emptyList(), Collections.emptyList()));
		EventBus.Subscriber crashingSubscriber = eventBus.register(PluginMessage.class, crashing::onPluginMessage, 0);
		index.start();
		crashing.start();
		assertTrue(index.members().containsKey("slayerrouteplanner"));

		// A crash: it stops listening and never says bye.
		eventBus.unregister(crashingSubscriber);
		index.refresh();

		assertFalse(index.members().containsKey("slayerrouteplanner"));
	}

	@Test
	public void itNeverListsItself()
	{
		PluginBus index = member("osrsindex");
		index.start();
		post(PluginBus.HELLO, hello("osrsindex", 1));

		assertTrue(index.members().isEmpty());
	}

	@Test
	public void aHelloOnAnotherBusVersionIsIgnoredAndLoggedOnce()
	{
		PluginBus index = member("osrsindex");
		index.start();

		post(PluginBus.HELLO, hello("future", 2));
		post(PluginBus.HELLO, hello("future", 2));

		assertTrue(index.members().isEmpty());
		assertEquals(1, index.warningsLogged());
	}

	@Test
	public void malformedLifecycleMessagesAreIgnoredLoggedOnceAndNeverThrown()
	{
		PluginBus index = member("osrsindex");
		index.start();

		Map<String, Object> noPlugin = hello("x", 1);
		noPlugin.remove(PluginBus.PLUGIN);
		Map<String, Object> busAsString = hello("stringbus", "1");
		Map<String, Object> badAccepts = hello("badaccepts", 1);
		badAccepts.put(PluginBus.ACCEPTS, Arrays.asList("path", 7));
		Map<String, Object> noPosts = hello("noposts", 1);
		noPosts.remove(PluginBus.POSTS);
		Map<String, Object> emptyPlugin = hello("", 1);

		for (int i = 0; i < 2; i++)
		{
			post(PluginBus.HELLO, noPlugin);
			post(PluginBus.HELLO, busAsString);
			post(PluginBus.HELLO, badAccepts);
			post(PluginBus.HELLO, noPosts);
			post(PluginBus.HELLO, emptyPlugin);
			post(PluginBus.HELLO, Collections.emptyMap());
			post(PluginBus.BYE, Collections.emptyMap());
		}

		assertTrue(index.members().isEmpty());
		// noPlugin and the empty hello share one key (no sender); the empty bye has its own. Each once.
		assertEquals(6, index.warningsLogged());
	}

	@Test
	public void unknownKeysAndUnknownNamesAreIgnored()
	{
		PluginBus index = member("osrsindex");
		index.start();

		Map<String, Object> withExtra = hello("farmrouteplanner", 1L);
		withExtra.put("colour", "green");
		post(PluginBus.HELLO, withExtra);
		post("ping", Collections.emptyMap());

		assertTrue(index.members().containsKey("farmrouteplanner"));
		assertEquals(0, index.warningsLogged());
	}

	@Test
	public void messagesOnOtherNamespacesAreNotTheBusBusiness()
	{
		PluginBus index = member("osrsindex");
		index.start();
		seen.clear();

		eventBus.post(new PluginMessage("farmrouteplanner", PluginBus.DISCOVER, Collections.emptyMap()));
		eventBus.post(new PluginMessage("osrsindex", PluginBus.HELLO, hello("sneaky", 1)));

		assertTrue(seen.isEmpty());
		assertTrue(index.members().isEmpty());
	}

	@Test
	public void theDataItPostsIsReadOnly()
	{
		member("osrsindex").start();

		for (PluginMessage message : seen)
		{
			try
			{
				message.getData().put("x", "y");
				fail(message.getName() + " data was writable");
			}
			catch (UnsupportedOperationException expected)
			{
				// Rule 4.
			}
		}
		try
		{
			@SuppressWarnings("unchecked")
			List<String> posts = (List<String>) seen.get(0).getData().get(PluginBus.POSTS);
			posts.add("x");
			fail("posts was writable");
		}
		catch (UnsupportedOperationException expected)
		{
			// Rule 4.
		}
	}

	@Test
	public void theMembersSnapshotDoesNotChangeUnderTheCaller()
	{
		PluginBus index = member("osrsindex");
		index.start();
		post(PluginBus.HELLO, hello("farmrouteplanner", 1));

		Map<String, PluginBus.Member> snapshot = index.members();
		post(PluginBus.BYE, Collections.singletonMap(PluginBus.PLUGIN, "farmrouteplanner"));

		assertTrue(snapshot.containsKey("farmrouteplanner"));
		assertNull(index.members().get("farmrouteplanner"));
	}

	@Test
	public void theVersionItsHelloCarriesMatchesTheReleaseVersion() throws Exception
	{
		// runelite-plugin.properties is the release version: the Plugin Hub reads it, and its standard build
		// replaces build.gradle. build.gradle, when it names a version, must agree.
		String properties = new String(Files.readAllBytes(Paths.get("runelite-plugin.properties")), StandardCharsets.UTF_8);
		Matcher release = Pattern.compile("(?m)^version=(\\S+)").matcher(properties);
		assertTrue(release.find());
		assertEquals(release.group(1), OsrsIndexPlugin.VERSION);

		String gradle = new String(Files.readAllBytes(Paths.get("build.gradle")), StandardCharsets.UTF_8);
		Matcher build = Pattern.compile("(?m)^version = '([^']+)'").matcher(gradle);
		if (build.find())
		{
			assertEquals(build.group(1), OsrsIndexPlugin.VERSION);
		}
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

/**
 * The hand-off to Quest Helper: its names for the game's quests, and what the plugin does on a quest step before
 * the quest starts, once it has started, once it is finished, and with Quest Helper off.
 */
public class QuestHelperHandOffTest
{
	/** Quest Helper's names that are not the game's (Zoinkwiz/quest-helper v4.18.0, QuestHelperQuest). */
	private static final Set<String> SPECIAL = new HashSet<>(Arrays.asList(
		"Shield of Arrav",
		"Recipe for Disaster - Another Cook's Quest",
		"Recipe for Disaster - Mountain Dwarf",
		"Recipe for Disaster - Wartface & Bentnoze",
		"Recipe for Disaster - Pirate Pete",
		"Recipe for Disaster - Lumbridge Guide",
		"Recipe for Disaster - Evil Dave",
		"Recipe for Disaster - King Awowogei",
		"Recipe for Disaster - Sir Amik Varze",
		"Recipe for Disaster - Skrach Uglogwee",
		"Recipe for Disaster - Culinaromancer"));

	@Test
	public void everyOtherQuestKeepsTheGamesName()
	{
		for (Quest quest : Quest.values())
		{
			String name = quest.getName();
			String helper = QuestHelperHandOff.helperName(name, QuestHelperHandOff.Gang.UNKNOWN);
			if (QuestHelperHandOff.NO_HELPER.contains(name))
			{
				assertNull(name, helper);
			}
			else if (!SPECIAL.contains(name))
			{
				assertEquals(name, name, helper);
			}
		}
	}

	@Test
	public void recipeForDisastersPartsAreQuestHelpersRfdNames()
	{
		assertEquals("RFD - Start", QuestHelperHandOff.helperName("Recipe for Disaster - Another Cook's Quest", null));
		assertEquals("RFD - Mountain Dwarf", QuestHelperHandOff.helperName("Recipe for Disaster - Mountain Dwarf", null));
		assertEquals("RFD - Wartface & Bentnoze",
			QuestHelperHandOff.helperName("Recipe for Disaster - Wartface & Bentnoze", null));
		assertEquals("RFD - Finale", QuestHelperHandOff.helperName("Recipe for Disaster - Culinaromancer", null));
		assertEquals("the whole quest: Quest Helper opens its first part", "Recipe for Disaster",
			QuestHelperHandOff.helperName("Recipe for Disaster", null));
		assertEquals("Recipe for Disaster", QuestHelperHandOff.questListName("Recipe for Disaster - Pirate Pete"));
		for (String name : SPECIAL)
		{
			assertTrue(name + " is a game quest", Arrays.stream(Quest.values()).anyMatch(q -> q.getName().equals(name)));
		}
	}

	@Test
	public void shieldOfArravGoesByTheGangThePlayerJoined()
	{
		assertEquals("Shield of Arrav - Phoenix Gang",
			QuestHelperHandOff.helperName("Shield of Arrav", QuestHelperHandOff.Gang.PHOENIX));
		assertEquals("Shield of Arrav - Black Arm Gang",
			QuestHelperHandOff.helperName("Shield of Arrav", QuestHelperHandOff.Gang.BLACK_ARM));
		assertEquals("not joined: the plain name", "Shield of Arrav",
			QuestHelperHandOff.helperName("Shield of Arrav", QuestHelperHandOff.Gang.UNKNOWN));

		assertSame(QuestHelperHandOff.Gang.UNKNOWN, QuestHelperHandOff.Gang.of(0, 0));
		assertSame("the start of the quest counts on the Phoenix varp", QuestHelperHandOff.Gang.UNKNOWN,
			QuestHelperHandOff.Gang.of(4, 0));
		assertSame(QuestHelperHandOff.Gang.PHOENIX, QuestHelperHandOff.Gang.of(8, 0));
		assertSame(QuestHelperHandOff.Gang.BLACK_ARM, QuestHelperHandOff.Gang.of(4, 1));
	}

	@Test
	public void noHelperOrNotAGameQuestIsOurs()
	{
		assertNull(QuestHelperHandOff.helperName("Learning the Ropes", null));
		assertNull(QuestHelperHandOff.helperName("Into the Tombs", null));
		assertNull(QuestHelperHandOff.helperName("The Frozen Door", null));
		assertNull(QuestHelperHandOff.helperName("Cooks Assistant", null));
		assertNull(QuestHelperHandOff.helperName(null, null));
	}

	@Test
	public void beforeTheQuestStartsQuestHelperGuidesItAndOurPointLeadsToTheStart()
	{
		Guide.Step step = questStep("Cook's Assistant");
		QuestHelperHandOff handOff = QuestHelperHandOff.of(step, true, true, QuestHelperHandOff.Gang.UNKNOWN,
			facts("Cook's Assistant", QuestState.NOT_STARTED));
		assertSame(QuestHelperHandOff.Stage.BEFORE_START, handOff.stage);
		assertEquals("Cook's Assistant", handOff.helperName);
		assertTrue(handOff.ownsThePlace());
		assertTrue(handOff.panelText().contains("starts by itself when you start Cook's Assistant"));
		assertTrue("the manual way stays on screen", handOff.panelText().contains("right-click Cook's Assistant"));

		QuestHelperHandOff manual = QuestHelperHandOff.of(step, true, false, QuestHelperHandOff.Gang.UNKNOWN,
			facts("Cook's Assistant", QuestState.NOT_STARTED));
		assertFalse(manual.panelText().contains("by itself"));
		assertTrue(manual.panelText().contains("open the Quest List, right-click Cook's Assistant and pick Start Quest"
			+ " Helper."));
		assertSame("not read yet counts as not started", QuestHelperHandOff.Stage.BEFORE_START,
			QuestHelperHandOff.of(step, true, true, QuestHelperHandOff.Gang.UNKNOWN, GuideFacts.UNKNOWN).stage);
	}

	@Test
	public void onceStartedOurPointAndArrowStandDown()
	{
		QuestHelperHandOff handOff = QuestHelperHandOff.of(questStep("Cook's Assistant"), true, true,
			QuestHelperHandOff.Gang.UNKNOWN, facts("Cook's Assistant", QuestState.IN_PROGRESS));
		assertSame(QuestHelperHandOff.Stage.STARTED, handOff.stage);
		assertFalse(handOff.ownsThePlace());
		assertTrue(handOff.panelText().contains("moves on by itself when the quest is finished"));
	}

	@Test
	public void finishedMeansTheStepIsDoneAndTheGuideMovesOn()
	{
		Guide.Step step = questStep("Cook's Assistant");
		GuideFacts finished = facts("Cook's Assistant", QuestState.FINISHED);
		assertSame(QuestHelperHandOff.Stage.FINISHED,
			QuestHelperHandOff.of(step, true, true, QuestHelperHandOff.Gang.UNKNOWN, finished).stage);
		assertTrue(GuideRules.completed(step, finished));
	}

	@Test
	public void withQuestHelperOffOrNoHelperTheStepIsOurs()
	{
		GuideFacts started = facts("Cook's Assistant", QuestState.IN_PROGRESS);
		QuestHelperHandOff off = QuestHelperHandOff.of(questStep("Cook's Assistant"), false, true,
			QuestHelperHandOff.Gang.UNKNOWN, started);
		assertSame(QuestHelperHandOff.Stage.OURS, off.stage);
		assertTrue("we keep pointing the way", off.ownsThePlace());
		assertNull(off.panelText());
		assertSame(QuestHelperHandOff.Stage.OURS, QuestHelperHandOff.of(questStep("Learning the Ropes"), true, true,
			QuestHelperHandOff.Gang.UNKNOWN, facts("Learning the Ropes", QuestState.IN_PROGRESS)).stage);
		assertSame("no quest", QuestHelperHandOff.Stage.OURS, QuestHelperHandOff.of(questStep(), true, true,
			QuestHelperHandOff.Gang.UNKNOWN, started).stage);
	}

	@Test
	public void aTwoQuestStepGoesOneQuestAtATime()
	{
		Guide.Step step = questStep("Imp Catcher", "Witch's Potion");
		GuideFacts first = new GuideFacts.Builder().quest("Imp Catcher", QuestState.FINISHED)
			.quest("Witch's Potion", QuestState.NOT_STARTED).build();
		QuestHelperHandOff handOff = QuestHelperHandOff.of(step, true, true, QuestHelperHandOff.Gang.UNKNOWN, first);
		assertSame(QuestHelperHandOff.Stage.BEFORE_START, handOff.stage);
		assertEquals("Witch's Potion", handOff.quest);
		assertFalse("one quest is not the step", GuideRules.completed(step, first));
	}

	@Test
	public void followWithQuestHelperPostsTheProposedStartMessage()
	{
		PluginMessage message = QuestHelperHandOff.startMessage("RFD - Mountain Dwarf");
		assertEquals("questhelper", message.getNamespace());
		assertEquals("start", message.getName());
		assertEquals("RFD - Mountain Dwarf", message.getData().get("quest"));
		assertEquals("OSRS Index", message.getData().get("source"));
		assertEquals(2, message.getData().size());
	}

	@Test
	public void questHelpersSelectedMessageAndAutoStartSetting()
	{
		assertEquals("Cook's Assistant", QuestHelperHandOff.selected(new PluginMessage("questhelper", "selected",
			Collections.<String, Object>singletonMap("quest", "Cook's Assistant"))));
		assertNull("cleared", QuestHelperHandOff.selected(new PluginMessage("questhelper", "selected",
			Collections.<String, Object>emptyMap())));
		assertTrue("absent is its default, on", QuestHelperHandOff.autoStart(null));
		assertTrue(QuestHelperHandOff.autoStart("true"));
		assertFalse(QuestHelperHandOff.autoStart("false"));
	}

	@Test
	public void theManualWayNamesTheGangOrPartOption()
	{
		QuestHelperHandOff handOff = QuestHelperHandOff.of(questStep("Recipe for Disaster - Mountain Dwarf"), true, false,
			QuestHelperHandOff.Gang.UNKNOWN, GuideFacts.UNKNOWN);
		assertTrue(handOff.panelText(), handOff.panelText().contains(
			"right-click Recipe for Disaster and pick Start Quest Helper for RFD - Mountain Dwarf."));
	}

	private static GuideFacts facts(String quest, QuestState state)
	{
		return new GuideFacts.Builder().quest(quest, state).build();
	}

	private static Guide.Step questStep(String... quests)
	{
		return new Guide.Step("q", "Quest", -1, null, null, Collections.<String>emptyList(), null, null,
			Collections.<String>emptySet(), Arrays.asList(quests), Collections.<Guide.Place>emptyList(),
			Collections.<Guide.Place>emptyList(), Collections.<Guide.Item>emptyList(), Collections.<Guide.Collect>emptyList(),
			Collections.<Guide.Requirement>emptyList(), Collections.<Guide.Requirement>emptyList(), null);
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

public class RouteDispatcherTest
{
	private static final Instant NOW = Instant.parse("2026-09-26T12:00:00Z");
	private static final Instant LATER = NOW.plusSeconds(120);

	private final List<PluginMessage> posted = new ArrayList<>();
	private final Set<PathingPlugin> active = EnumSet.allOf(PathingPlugin.class);
	private final RouteDispatcher dispatcher = new RouteDispatcher(
		posted::add, active::contains, Clock.fixed(NOW, ZoneOffset.UTC));

	private static Destination sarah(String id)
	{
		return new Destination(id, 3036, 3294, 0, "Sarah", LATER);
	}

	@Test
	public void aValidDestinationPostsExactlyOnePathMessageWithAWorldPointTarget()
	{
		RouteDispatcher.Result result = dispatcher.dispatch(sarah("a"), RouteWith.SHORTEST_PATH);

		assertEquals(RouteDispatcher.Kind.ROUTED, result.kind);
		assertEquals(PathingPlugin.SHORTEST_PATH, result.plugin);
		assertEquals("a", result.ackId);
		assertEquals("routed", result.kind.ackResult);
		assertEquals(1, posted.size());
		PluginMessage message = posted.get(0);
		assertEquals("shortestpath", message.getNamespace());
		assertEquals("path", message.getName());
		assertEquals(new WorldPoint(3036, 3294, 0), message.getData().get("target"));
		// No start: the route begins at the player.
		assertEquals(1, message.getData().size());
		assertEquals("osrsindex.com: routing to Sarah (3036, 3294, 0) with Shortest Path.",
			result.chatMessage);
	}

	@Test
	public void theEdgesOfTheMapAreValid()
	{
		assertEquals(RouteDispatcher.Kind.ROUTED,
			dispatcher.dispatch(new Destination("low", 0, 0, 0, "Corner", LATER), RouteWith.SHORTEST_PATH).kind);
		assertEquals(RouteDispatcher.Kind.ROUTED,
			dispatcher.dispatch(new Destination("high", 16_383, 16_383, 3, "Corner", LATER),
				RouteWith.SHORTEST_PATH).kind);
	}

	@Test
	public void anOutOfRangeTileIsAckedInvalidWithoutAMessage()
	{
		int[][] tiles = {{-1, 0, 0}, {16_384, 0, 0}, {0, -1, 0}, {0, 16_384, 0}, {0, 0, -1}, {0, 0, 4}};
		for (int[] tile : tiles)
		{
			RouteDispatcher.Result result = dispatcher.dispatch(
				new Destination("t", tile[0], tile[1], tile[2], "Bad", LATER), RouteWith.SHORTEST_PATH);
			assertEquals(RouteDispatcher.Kind.INVALID, result.kind);
			assertEquals("t", result.ackId);
			assertEquals("invalid", result.kind.ackResult);
			assertNull(result.chatMessage);
		}
		assertTrue(posted.isEmpty());
	}

	@Test
	public void aMissingOrOversizedLabelOrExpiryIsAckedInvalid()
	{
		String longLabel = new String(new char[RouteDispatcher.MAX_LABEL_CODE_POINTS + 1]).replace('\0', 'x');
		Destination[] bad = {
			new Destination("a", 1, 1, 0, null, LATER),
			new Destination("a", 1, 1, 0, "", LATER),
			new Destination("a", 1, 1, 0, longLabel, LATER),
			new Destination("a", 1, 1, 0, "Sarah", null),
		};
		for (Destination destination : bad)
		{
			RouteDispatcher.Result result = dispatcher.dispatch(destination, RouteWith.SHORTEST_PATH);
			assertEquals(RouteDispatcher.Kind.INVALID, result.kind);
			assertEquals("a", result.ackId);
		}
		assertTrue(posted.isEmpty());
	}

	@Test
	public void aPlaceWithNoIdTheSiteCanMatchIsDroppedUnacked()
	{
		String longId = new String(new char[RouteDispatcher.MAX_ID_LENGTH + 1]).replace('\0', 'a');
		Destination[] bad = {
			null,
			new Destination(null, 1, 1, 0, "Sarah", LATER),
			new Destination("", 1, 1, 0, "Sarah", LATER),
			new Destination(longId, 1, 1, 0, "Sarah", LATER),
			// Out of range as well: still no id to ack it by.
			new Destination(longId, 16_384, 1, 0, "Sarah", LATER),
		};
		for (Destination destination : bad)
		{
			RouteDispatcher.Result result = dispatcher.dispatch(destination, RouteWith.SHORTEST_PATH);
			assertEquals(RouteDispatcher.Kind.INVALID, result.kind);
			assertNull(result.ackId);
		}
		assertTrue(posted.isEmpty());

		String longest = longId.substring(1);
		assertEquals(longest, dispatcher.dispatch(new Destination(longest, 16_384, 1, 0, "Sarah", LATER),
			RouteWith.SHORTEST_PATH).ackId);
	}

	@Test
	public void theLabelLimitCountsCodePointsNotUtf16Units()
	{
		// 100 emoji are 200 UTF-16 units, and still within the site's 100 code points.
		String emoji = new String(Character.toChars(0x1F955));
		StringBuilder label = new StringBuilder();
		for (int i = 0; i < RouteDispatcher.MAX_LABEL_CODE_POINTS; i++)
		{
			label.append(emoji);
		}
		assertEquals(RouteDispatcher.Kind.ROUTED,
			dispatcher.dispatch(new Destination("e", 1, 1, 0, label.toString(), LATER), RouteWith.SHORTEST_PATH).kind);
	}

	@Test
	public void expiryAllowsThirtySecondsOfClockSkewAndNoMore()
	{
		Instant justInside = NOW.minus(RouteDispatcher.CLOCK_SKEW);
		Instant justOutside = justInside.minusSeconds(1);

		assertEquals(RouteDispatcher.Kind.ROUTED,
			dispatcher.dispatch(new Destination("in", 1, 1, 0, "In", justInside), RouteWith.SHORTEST_PATH).kind);
		RouteDispatcher.Result expired = dispatcher.dispatch(
			new Destination("out", 1, 1, 0, "Out", justOutside), RouteWith.SHORTEST_PATH);
		assertEquals(RouteDispatcher.Kind.EXPIRED, expired.kind);
		assertEquals("out", expired.ackId);
		assertEquals("expired", expired.kind.ackResult);
		assertNull(expired.chatMessage);
		assertEquals(1, posted.size());
	}

	@Test
	public void aRepeatedIdIsRoutedOnceButAckedRoutedAgain()
	{
		dispatcher.dispatch(sarah("same"), RouteWith.SHORTEST_PATH);
		RouteDispatcher.Result again = dispatcher.dispatch(sarah("same"), RouteWith.SHORTEST_PATH);

		assertEquals(RouteDispatcher.Kind.ALREADY_ROUTED, again.kind);
		assertEquals("same", again.ackId);
		assertEquals("routed", again.kind.ackResult);
		assertNull(again.chatMessage);
		assertEquals(1, posted.size());
	}

	@Test
	public void aRoutedIdIsAckedRoutedAgainEvenPastItsExpiry()
	{
		dispatcher.dispatch(sarah("late"), RouteWith.SHORTEST_PATH);
		// The routed check comes before expiry: a place routed once is never reported to the site as expired.
		RouteDispatcher.Result again = dispatcher.dispatch(
			new Destination("late", 3036, 3294, 0, "Sarah", NOW.minusSeconds(3_600)), RouteWith.SHORTEST_PATH);
		assertEquals(RouteDispatcher.Kind.ALREADY_ROUTED, again.kind);
		assertEquals("late", again.ackId);
		assertEquals(1, posted.size());
	}

	@Test
	public void eachKindAcksWithTheSiteContractsResult()
	{
		assertEquals("routed", RouteDispatcher.Kind.ROUTED.ackResult);
		assertEquals("routed", RouteDispatcher.Kind.ALREADY_ROUTED.ackResult);
		assertEquals("invalid", RouteDispatcher.Kind.INVALID.ackResult);
		assertEquals("expired", RouteDispatcher.Kind.EXPIRED.ackResult);
		assertEquals("no_pathing_plugin", RouteDispatcher.Kind.NO_PATHING_PLUGIN.ackResult);
	}

	@Test
	public void aPlaceThatFoundNoPluginIsNotRememberedSoARedeliveryRoutes()
	{
		active.clear();
		dispatcher.dispatch(sarah("a"), RouteWith.SHORTEST_PATH);
		active.add(PathingPlugin.SHORTEST_PATH);

		RouteDispatcher.Result result = dispatcher.dispatch(sarah("a"), RouteWith.SHORTEST_PATH);
		assertEquals(RouteDispatcher.Kind.ROUTED, result.kind);
		assertEquals(PathingPlugin.SHORTEST_PATH, result.plugin);
	}

	@Test
	public void withShortestPathOffItSaysSoAndAcksNoPathingPlugin()
	{
		active.remove(PathingPlugin.SHORTEST_PATH);
		RouteDispatcher.Result result = dispatcher.dispatch(sarah("a"), RouteWith.SHORTEST_PATH);

		assertEquals(RouteDispatcher.Kind.NO_PATHING_PLUGIN, result.kind);
		assertEquals("a", result.ackId);
		assertEquals("no_pathing_plugin", result.kind.ackResult);
		assertTrue(posted.isEmpty());
		assertEquals("osrsindex.com sent Sarah (3036, 3294, 0), but Shortest Path is not on.",
			result.chatMessage);
	}

	@Test
	public void theLabelCannotCarryChatMarkupOrControlCharacters()
	{
		RouteDispatcher.Result result = dispatcher.dispatch(
			new Destination("m", 1, 1, 0, "<col=ff0000>Sa\u0007rah</col>@red@", LATER), RouteWith.SHORTEST_PATH);

		assertFalse(result.chatMessage.contains("<col"));
		assertFalse(result.chatMessage.contains("\u0007"));
		assertTrue(result.chatMessage.startsWith(
			"osrsindex.com: routing to <lt>col=ff0000<gt>Sarah<lt>/col<gt><at>red<at> (1, 1, 0)"));
	}

	@Test
	public void aLabelOfOnlyControlCharactersReadsAsATile()
	{
		RouteDispatcher.Result result = dispatcher.dispatch(
			new Destination("c", 1, 2, 0, "\u0007\u0008", LATER), RouteWith.SHORTEST_PATH);
		assertEquals("osrsindex.com: routing to a tile (1, 2, 0) with Shortest Path.", result.chatMessage);
	}

	@Test
	public void rememberedIdsAreBoundedSoTheOldestIsForgotten()
	{
		for (int i = 0; i <= RouteDispatcher.REMEMBERED_IDS; i++)
		{
			dispatcher.dispatch(sarah("id-" + i), RouteWith.SHORTEST_PATH);
		}
		// id-0 was evicted by the 65th; id-64 is still remembered.
		assertEquals(RouteDispatcher.Kind.ROUTED, dispatcher.dispatch(sarah("id-0"), RouteWith.SHORTEST_PATH).kind);
		assertEquals(RouteDispatcher.Kind.ALREADY_ROUTED,
			dispatcher.dispatch(sarah("id-" + RouteDispatcher.REMEMBERED_IDS), RouteWith.SHORTEST_PATH).kind);
	}
}

