		SiteConfig.Vars vars = parse("{\"vars\":{\"varbits\":{\"QUEST_X\":" + excludedVarbit + ","
			+ "\"" + GameVars.VARBIT_NAMES[0] + "\":" + excludedVarbit + "},\"varps\":{\"QUEST_Y\":" + excludedVarp + "}}}").vars;
