package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;
import okhttp3.Interceptor;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.After;
import org.junit.Test;

/**
 * Every request to osrsindex.com names the plugin's version in {@code X-OSRS-Index-Plugin}: the sync, link
 * start, link poll, the destinations upgrade and the unlink revoke. Each test sends the plugin's own request through the client
 * the plugin uses. A last interceptor records the request and answers in place of the network, so nothing
 * leaves the machine.
 */
public class SiteHttpTest
{
	private static final String TOKEN = OsrsIndexPlugin.TOKEN_PREFIX + "a".repeat(43);
	private static final MediaType JSON = MediaType.parse("application/json");
	/** The form the site reads; anything else it ignores. Mirrors the site's plugin-version parser. */
	private static final Pattern SITE_VERSION =
		Pattern.compile("(0|[1-9]\\d{0,3})\\.(0|[1-9]\\d{0,3})\\.(0|[1-9]\\d{0,3})(-[0-9A-Za-z][0-9A-Za-z.-]*)?");

	private final OkHttpClient shared = new OkHttpClient();
	private final List<Request> seen = Collections.synchronizedList(new ArrayList<>());
	private final Semaphore arrived = new Semaphore(0);
	private final Deque<String> answers = new ArrayDeque<>();

	@After
	public void stopThreads()
	{
		shared.dispatcher().executorService().shutdown();
		shared.connectionPool().evictAll();
	}

	/** {@code client} plus a last interceptor that records each request and answers 200 with the next body. */
	private OkHttpClient recording(OkHttpClient client, String... bodies)
	{
		answers.addAll(Arrays.asList(bodies));
		Interceptor recorder = chain ->
		{
			Request request = chain.request();
			String body;
			synchronized (answers)
			{
				body = answers.isEmpty() ? "{}" : answers.removeFirst();
			}
			seen.add(request);
			arrived.release();
			return new Response.Builder()
				.request(request)
				.protocol(Protocol.HTTP_1_1)
				.code(200)
				.message("OK")
				.body(ResponseBody.create(JSON, body))
				.build();
		};
		return client.newBuilder().addInterceptor(recorder).build();
	}

	/** The client the plugin builds in startUp, recording. */
	private OkHttpClient site(String... bodies)
	{
		return recording(SiteHttp.derive(shared, OsrsIndexPlugin.VERSION), bodies);
	}

	private void awaitRequests(int count) throws InterruptedException
	{
		assertTrue("expected " + count + " request(s)", arrived.tryAcquire(count, 10, TimeUnit.SECONDS));
	}

	@Test
	public void theSyncNamesThePluginVersion() throws Exception
	{
		site().newCall(OsrsIndexPlugin.syncRequest(TOKEN, "{\"schema\":4}")).execute().close();

		Request request = seen.get(0);
		assertEquals(Endpoints.sync(), request.url().toString());
		assertEquals("Bearer " + TOKEN, request.header("Authorization"));
		assertEquals(OsrsIndexPlugin.VERSION, request.header(SiteHttp.VERSION_HEADER));
	}

	@Test
	public void theUnlinkRevokeNamesThePluginVersion() throws Exception
	{
		new TokenRevoker(site()).revoke(TOKEN, result ->
		{
		});
		awaitRequests(1);

		Request request = seen.get(0);
		assertEquals("DELETE", request.method());
		assertEquals(Endpoints.revokeToken(), request.url().toString());
		assertEquals("Bearer " + TOKEN, request.header("Authorization"));
		assertEquals(OsrsIndexPlugin.VERSION, request.header(SiteHttp.VERSION_HEADER));
	}

	@Test
	public void linkStartAndEveryPollNameThePluginVersion() throws Exception
	{
		String started = "{\"device_code\":\"osrsidl_" + "b".repeat(43) + "\",\"user_code\":\"KXQ4-7MNP\","
			+ "\"expires_in\":600,\"interval\":15}";
		long[] now = {1_000_000L};
		Semaphore waiting = new Semaphore(0);
		AccountLinker linker = new AccountLinker(AccountLinker.okHttp(site(started, "{\"status\":\"pending\"}"), new Gson()),
			() -> now[0], new AccountLinker.Listener()
			{
				@Override
				public void stateChanged(AccountLinker.State state, String userCode)
				{
					if (state == AccountLinker.State.WAITING)
					{
						waiting.release();
					}
				}

				@Override
				public void linked(String token)
				{
				}
			});

		linker.start("Zezima");
		assertTrue("the start answer arrives", waiting.tryAcquire(10, TimeUnit.SECONDS));
		now[0] += 15_000L;
		linker.tick();
		awaitRequests(2);

		assertEquals(Endpoints.linkStart(), seen.get(0).url().toString());
		assertEquals(Endpoints.linkPoll(), seen.get(1).url().toString());
		for (Request request : seen)
		{
			assertEquals(OsrsIndexPlugin.VERSION, request.header(SiteHttp.VERSION_HEADER));
		}
	}

	@Test
	public void theDestinationsUpgradeNamesThePluginVersion() throws Exception
	{
		Semaphore refused = new Semaphore(0);
		new OkHttpConnector(site(), Endpoints::destinations).open(TOKEN, new DestinationSocket.Events()
		{
			@Override
			public void opened(DestinationSocket.Connection connection, String protocol)
			{
			}

			@Override
			public void text(DestinationSocket.Connection connection, String text)
			{
			}

			@Override
			public void closed(DestinationSocket.Connection connection, int code)
			{
			}

			@Override
			public void failed(DestinationSocket.Connection connection, int httpStatus, long retryAfterSeconds)
			{
				// The recorder answers 200, not 101, so OkHttp refuses the upgrade; the request is what counts.
				refused.release();
			}
		});
		awaitRequests(1);
		assertTrue("the refused upgrade is reported", refused.tryAcquire(10, TimeUnit.SECONDS));

		Request request = seen.get(0);
		assertEquals("websocket", request.header("Upgrade"));
		assertEquals("Bearer " + TOKEN, request.header("Authorization"));
		assertEquals(DestinationSocket.SUBPROTOCOL, request.header("Sec-WebSocket-Protocol"));
		assertEquals(OsrsIndexPlugin.VERSION, request.header(SiteHttp.VERSION_HEADER));
	}

	@Test
	public void guideRequestsNameThePluginVersionAndCarryNoToken() throws Exception
	{
		GuideFetcher fetcher = new GuideFetcher(site("{\"version\":1,\"guides\":[]}", "{}"));
		fetcher.listing(answer ->
		{
		});
		fetcher.guide("beginner", null, answer ->
		{
		});
		awaitRequests(2);

		List<String> urls = new ArrayList<>();
		for (Request request : seen)
		{
			urls.add(request.url().toString());
			assertEquals("GET", request.method());
			assertNull(request.header("Authorization"));
			assertEquals(OsrsIndexPlugin.VERSION, request.header(SiteHttp.VERSION_HEADER));
		}
		assertTrue(urls.contains(Endpoints.guides()));
		assertTrue(urls.contains(Endpoints.guide("beginner")));
	}

	@Test
	public void theSharedClientIsLeftAsItWasAndItsPoolIsShared() throws Exception
	{
		OkHttpClient site = SiteHttp.derive(shared, OsrsIndexPlugin.VERSION);
		assertTrue(shared.interceptors().isEmpty());
		assertEquals(1, site.interceptors().size());
		assertSame(shared.dispatcher(), site.dispatcher());
		assertSame(shared.connectionPool(), site.connectionPool());

		// Another plugin's request through the shared client carries no version header.
		recording(shared).newCall(new Request.Builder().url("https://example.com/").build()).execute().close();
		assertNull(seen.get(0).header(SiteHttp.VERSION_HEADER));
	}

	@Test
	public void theHeaderReplacesAnyValueAlreadyOnTheRequest() throws Exception
	{
		Request request = OsrsIndexPlugin.syncRequest(TOKEN, "{}").newBuilder()
			.header(SiteHttp.VERSION_HEADER, "9.9.9")
			.build();
		site().newCall(request).execute().close();
		assertEquals(Collections.singletonList(OsrsIndexPlugin.VERSION), seen.get(0).headers(SiteHttp.VERSION_HEADER));
	}

	@Test
	public void theVersionHasTheFormTheSiteReads()
	{
		// The site ignores a value outside this form, or over 32 characters, so a release must keep to it.
		assertTrue(OsrsIndexPlugin.VERSION, SITE_VERSION.matcher(OsrsIndexPlugin.VERSION).matches());
		assertTrue(OsrsIndexPlugin.VERSION.length() <= 32);
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.time.LocalTime;
import java.util.EnumSet;
import org.junit.Test;

/**
 * Where the panel's buttons send the browser, and what the panel says about the last sync.
 */
public class SiteLinksTest
{
	@Test
	public void theSitesPagesAreOnItsOwnOrigin()
	{
		assertEquals("https://osrsindex.com/tracker", Endpoints.tracker());
		assertEquals("https://osrsindex.com/account#runelite", Endpoints.account());
		assertEquals("https://osrsindex.com/map?x=3222&y=3218&plane=0", Endpoints.map(3222, 3218, 0));
		assertEquals("https://osrsindex.com/map", Endpoints.map());
		assertEquals("https://osrsindex.com/link?code=KXQ4-7MNP", Endpoints.linkApproval("KXQ4-7MNP"));
	}

	@Test
	public void myCharacterOpensTheLoggedInCharacter()
	{
		String tracker = "https://osrsindex.com/tracker";
		assertEquals(tracker + "?character=Zezima", Endpoints.tracker("Zezima"));
		assertEquals(tracker + "?character=Iron%20Man", Endpoints.tracker("Iron Man"));
		assertEquals(tracker + "?character=Lil_Jim-2", Endpoints.tracker("Lil_Jim-2"));
	}

	@Test
	public void aHardSpaceInTheNameIsSentAsTheSpaceTheSiteStores()
	{
		// The game writes the space in a player's name as U+00A0; the site stores a plain space.
		assertEquals("https://osrsindex.com/tracker?character=Iron%20Man", Endpoints.tracker("Iron\u00A0Man"));
		assertEquals("https://osrsindex.com/tracker?character=A%20B%20C", Endpoints.tracker("\u00A0A\u00A0B C\u00A0"));
	}

	@Test
	public void withNoCharacterMyCharacterOpensThePlainPage()
	{
		assertEquals("https://osrsindex.com/tracker", Endpoints.tracker(null));
		assertEquals("https://osrsindex.com/tracker", Endpoints.tracker(""));
		assertEquals("https://osrsindex.com/tracker", Endpoints.tracker(" \u00A0"));
	}

	@Test
	public void theLastSyncLineListsWhatWasStoredInTheContractsOrder()
	{
		LocalTime at = LocalTime.of(14, 2);
		assertEquals("Last sync at 14:02: location, skills and bank.",
			OsrsIndexPlugin.syncSummary(at, EnumSet.of(Part.BANK, Part.SKILLS, Part.LOCATION)));
		assertEquals("Last sync at 14:02: combat achievements.",
			OsrsIndexPlugin.syncSummary(at, EnumSet.of(Part.COMBAT_ACHIEVEMENTS)));
		assertEquals("Last sync at 14:02.", OsrsIndexPlugin.syncSummary(at, EnumSet.noneOf(Part.class)));
	}

	@Test
	public void anUnlinkedClientIsToldHowToLinkAndThatNothingIsSent()
	{
		assertTrue(OsrsIndexPlugin.LINK_HINT.contains("nothing is sent"));
		assertTrue(OsrsIndexPlugin.LINK_HINT.contains("Link with osrsindex.com"));
	}

	@Test
	public void aWaitTheSiteExplainedSaysWhenAndWhy()
	{
		assertEquals("Not synced at 14:02: Back at 19:00 UTC.",
			OsrsIndexPlugin.waitLine(LocalTime.of(14, 2), "Back at 19:00 UTC."));
	}

	@Test
	public void thePanelSaysWhenTheSiteHasPausedDestinations()
	{
		assertEquals("Not listening: osrsindex.com has paused destinations for now.",
			OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.OFF, true, true, true, true));
		assertEquals("the player's own setting is named first",
			"Not listening: \"Receive destinations\" is off in this plugin's settings.",
			OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.OFF, false, true, true, true));
		assertEquals("Not listening.",
			OsrsIndexPlugin.destinationStatusText(DestinationSocket.Status.OFF, true, true, true, false));
	}

	@Test
	public void aCharacterNameIsTextInThePanel()
	{
		assertEquals("A&lt;b&gt;&amp;c", OsrsIndexPanel.escape("A<b>&c"));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import org.junit.Test;

public class SlayerAssignmentTest
{
	@Test
	public void schemaFourCarriesNamedCurrentTaskAndOptionalArea()
	{
		JsonObject vars = new JsonObject();
		vars.addProperty("SLAYER_COUNT", 72);
		CharacterReader.addSlayerAssignment(vars, 4, 72, "Cave krakens", "Kraken Cove");
		assertEquals("Cave krakens", vars.get("SLAYER_TASK_NAME").getAsString());
		assertEquals("Kraken Cove", vars.get("SLAYER_TASK_AREA").getAsString());
	}

	@Test
	public void schemaFiveStillCarriesTheNamedTask()
	{
		JsonObject vars = new JsonObject();
		vars.addProperty("SLAYER_COUNT", 72);
		CharacterReader.addSlayerAssignment(vars, Part.LATEST_SCHEMA, 72, "Cave krakens", "Kraken Cove");
		assertEquals(5, Part.LATEST_SCHEMA);
		assertEquals("Cave krakens", vars.get("SLAYER_TASK_NAME").getAsString());
		assertEquals("Kraken Cove", vars.get("SLAYER_TASK_AREA").getAsString());
	}

	@Test
	public void schemaThreeDowngradeKeepsOnlyNumericGamevals()
	{
		JsonObject vars = new JsonObject();
		vars.addProperty("SLAYER_COUNT", 72);
		CharacterReader.addSlayerAssignment(vars, 3, 72, "Cave krakens", "Kraken Cove");
		assertEquals(1, vars.size());
		assertFalse(vars.has("SLAYER_TASK_NAME"));
	}

	@Test
	public void zeroOrUnresolvedTaskNeverCreatesStaleAssignment()
	{
		JsonObject vars = new JsonObject();
		CharacterReader.addSlayerAssignment(vars, 4, 0, "Cave krakens", "Kraken Cove");
		CharacterReader.addSlayerAssignment(vars, 4, 20, null, "Kraken Cove");
		CharacterReader.addSlayerAssignment(vars, 4, 20, "Cave\nkrakens", "Kraken Cove");
		assertFalse(vars.has("SLAYER_TASK_NAME"));
		CharacterReader.addSlayerAssignment(vars, 4, 20, "Cave krakens", "Area\nunknown");
		assertTrue(vars.has("SLAYER_TASK_NAME"));
		assertFalse(vars.has("SLAYER_TASK_AREA"));
	}

	@Test
	public void hardSpaceAtEitherEndIsStrippedAndTheTaskKept()
	{
		assertKept("\u00A0Cave krakens", "Kraken Cove\u00A0");
		assertKept("Cave krakens\u00A0", "\u00A0Kraken Cove");
		assertKept("\u00A0\u00A0Cave krakens\u00A0", "\u00A0Kraken Cove\u00A0\u00A0");
	}

	@Test
	public void byteOrderMarkAtEitherEndIsStrippedAndTheTaskKept()
	{
		assertKept("\uFEFFCave krakens", "Kraken Cove\uFEFF");
		assertKept("Cave krakens\uFEFF", "\uFEFFKraken Cove");
		assertKept("\uFEFF\u00A0Cave krakens \uFEFF", "\u3000Kraken Cove\u2028");
	}

	@Test
	public void hardSpaceInsideANameBecomesAPlainSpace()
	{
		assertKept("Cave\u00A0krakens", "Kraken\u00A0Cove");
	}

	@Test
	public void eightyCharactersAreCountedAfterTheEndsAreStripped()
	{
		String eighty = "k".repeat(80);
		JsonObject vars = new JsonObject();
		CharacterReader.addSlayerAssignment(vars, 4, 20, eighty + "\u00A0", null);
		assertEquals(eighty, vars.get("SLAYER_TASK_NAME").getAsString());

		JsonObject tooLong = new JsonObject();
		CharacterReader.addSlayerAssignment(tooLong, 4, 20, "\u00A0" + eighty + "k", null);
		assertFalse(tooLong.has("SLAYER_TASK_NAME"));
	}

	@Test
	public void nameOfOnlyTrimmedCharactersIsDropped()
	{
		JsonObject vars = new JsonObject();
		CharacterReader.addSlayerAssignment(vars, 4, 20, "\u00A0\uFEFF ", "Kraken Cove");
		assertFalse(vars.has("SLAYER_TASK_NAME"));
		assertFalse(vars.has("SLAYER_TASK_AREA"));
	}

	@Test
	public void validSlayerTextRefusesHardSpaceAndByteOrderMarkAtEitherEnd()
	{
		assertTrue(CharacterReader.validSlayerText("Cave krakens"));
		assertFalse(CharacterReader.validSlayerText("\u00A0Cave krakens"));
		assertFalse(CharacterReader.validSlayerText("Cave krakens\u00A0"));
		assertFalse(CharacterReader.validSlayerText("\uFEFFCave krakens"));
		assertFalse(CharacterReader.validSlayerText("Cave krakens\uFEFF"));
		// Inside a name neither is trimmed, and neither is a control character, so the site takes it as it is.
		assertTrue(CharacterReader.validSlayerText("Cave\u00A0krakens"));
		assertTrue(CharacterReader.validSlayerText("Cave\uFEFFkrakens"));
	}

	/**
	 * Every UTF-16 code unit against ECMAScript's own definition, written independently of the plugin's list:
	 * WhiteSpace is tab, vertical tab, form feed, U+FEFF and any space separator (Zs), and LineTerminator is line
	 * feed, carriage return, U+2028 and U+2029. Characters outside the set, such as U+200B and U+180E, stay valid
	 * at the ends because the site's trim() keeps them too.
	 */
	@Test
	public void trimmedSetIsExactlyJavaScriptTrim()
	{
		for (int code = 0; code <= 0xffff; code++)
		{
			char c = (char) code;
			boolean script = code == 0x09 || code == 0x0b || code == 0x0c || code == 0xfeff
				|| Character.getType(c) == Character.SPACE_SEPARATOR
				|| code == 0x0a || code == 0x0d || code == 0x2028 || code == 0x2029;
			assertEquals(String.format("U+%04X", code), script, CharacterReader.isScriptTrimmed(c));
			if (script)
			{
				assertFalse(String.format("U+%04X first", code), CharacterReader.validSlayerText(c + "Cave krakens"));
				assertFalse(String.format("U+%04X last", code), CharacterReader.validSlayerText("Cave krakens" + c));
			}
		}
		assertTrue(CharacterReader.validSlayerText("\u200BCave krakens\u200B"));
		assertTrue(CharacterReader.validSlayerText("\u180ECave krakens\u180E"));
	}

	@Test
	public void scriptTrimStripsBothEndsOnly()
	{
		assertEquals("Cave krakens", CharacterReader.scriptTrim("\t\u2003Cave krakens\r\n\u205F"));
		assertEquals("a\u3000b", CharacterReader.scriptTrim("\u3000a\u3000b\u3000"));
		assertEquals("", CharacterReader.scriptTrim("\u1680\u202F\u2029"));
		assertEquals("", CharacterReader.scriptTrim(""));
		assertNull(CharacterReader.normaliseSlayerText(null));
	}

	private static void assertKept(String name, String area)
	{
		JsonObject vars = new JsonObject();
		CharacterReader.addSlayerAssignment(vars, 4, 20, name, area);
		assertEquals("Cave krakens", vars.get("SLAYER_TASK_NAME").getAsString());
		assertEquals("Kraken Cove", vars.get("SLAYER_TASK_AREA").getAsString());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.DBTableID;
import org.junit.Test;

public class SlayerTaskLookupTest
{
	private static final int KRAKEN_TASK_ID = 53;
	private static final int KRAKEN_TASK_ROW = 1_053;
	private static final int ZULRAH_BOSS_ID = 18;
	private static final int ZULRAH_SUBLIST_ROW = 2_018;
	private static final int ZULRAH_TASK_ROW = 1_201;
	private static final int KRAKEN_COVE_AREA_ID = 27;
	private static final int KRAKEN_COVE_AREA_ROW = 3_027;

	/** DB rows and fields held in maps, keyed the way the client looks them up. Unknown keys answer empty. */
	private static final class FakeTables implements CharacterReader.DbTables
	{
		final Map<String, List<Integer>> rows = new HashMap<>();
		final Map<String, Object[]> fields = new HashMap<>();

		FakeTables row(int table, int column, Object value, Integer row)
		{
			rows.put(table + "/" + column + "/" + value, Collections.singletonList(row));
			return this;
		}

		FakeTables field(int row, int column, Object[] values)
		{
			fields.put(row + "/" + column, values);
			return this;
		}

		@Override
		public List<Integer> rowsByValue(int table, int column, int tupleIndex, Object value)
		{
			return rows.getOrDefault(table + "/" + column + "/" + value, Collections.emptyList());
		}

		@Override
		public Object[] field(int row, int column, int tupleIndex)
		{
			return fields.getOrDefault(row + "/" + column, new Object[0]);
		}
	}

	/** A boss task wired through the sublist; the test then breaks one link of the chain. */
	private static FakeTables bossTables(Object[] sublistTaskField)
	{
		return new FakeTables()
			.row(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, ZULRAH_BOSS_ID,
				ZULRAH_SUBLIST_ROW)
			.field(ZULRAH_SUBLIST_ROW, DBTableID.SlayerTaskSublist.COL_TASK, sublistTaskField)
			.field(ZULRAH_TASK_ROW, DBTableID.SlayerTask.COL_NAME_UPPERCASE, new Object[]{"Zulrah"});
	}

	private static FakeTables regularTables(Object[] nameField)
	{
		return new FakeTables()
			.row(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, KRAKEN_TASK_ID, KRAKEN_TASK_ROW)
			.field(KRAKEN_TASK_ROW, DBTableID.SlayerTask.COL_NAME_UPPERCASE, nameField);
	}

	@Test
	public void regularTaskIsNamedFromTheSlayerTaskTable()
	{
		assertEquals("Cave krakens",
			CharacterReader.slayerTaskName(regularTables(new Object[]{"Cave krakens"}), KRAKEN_TASK_ID, 0));
	}

	@Test
	public void bossTaskIsNamedThroughTheSublist()
	{
		assertEquals("Zulrah", CharacterReader.slayerTaskName(bossTables(new Object[]{ZULRAH_TASK_ROW}),
			CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID));
	}

	@Test
	public void bossTaskWithAnEmptySublistFieldStaysUnnamed()
	{
		assertNull(CharacterReader.slayerTaskName(bossTables(new Object[0]),
			CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID));
		assertNull(CharacterReader.slayerTaskName(bossTables(null), CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID));
	}

	@Test
	public void bossTaskWithASublistFieldOfAnotherTypeStaysUnnamed()
	{
		assertNull(CharacterReader.slayerTaskName(bossTables(new Object[]{"1201"}),
			CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID));
		assertNull(CharacterReader.slayerTaskName(bossTables(new Object[]{null}),
			CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID));
	}

	@Test
	public void bossTaskWithAMissingRowStaysUnnamed()
	{
		// No sublist row for this boss.
		assertNull(CharacterReader.slayerTaskName(bossTables(new Object[]{ZULRAH_TASK_ROW}),
			CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID + 1));
		// The sublist points at a task row that has no name.
		assertNull(CharacterReader.slayerTaskName(bossTables(new Object[]{ZULRAH_TASK_ROW + 1}),
			CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID));
	}

	@Test
	public void regularTaskWithAMissingRowOrMistypedNameStaysUnnamed()
	{
		assertNull(CharacterReader.slayerTaskName(regularTables(new Object[]{"Cave krakens"}), KRAKEN_TASK_ID + 1, 0));
		assertNull(CharacterReader.slayerTaskName(regularTables(new Object[0]), KRAKEN_TASK_ID, 0));
		assertNull(CharacterReader.slayerTaskName(regularTables(new Object[]{42}), KRAKEN_TASK_ID, 0));
	}

	@Test
	public void aNullRowOrRowListCountsAsMissing()
	{
		FakeTables tables = new FakeTables();
		tables.rows.put(DBTableID.SlayerTask.ID + "/" + DBTableID.SlayerTask.COL_ID + "/" + KRAKEN_TASK_ID,
			new ArrayList<>(Arrays.asList((Integer) null)));
		assertNull(CharacterReader.slayerTaskName(tables, KRAKEN_TASK_ID, 0));
		tables.rows.put(DBTableID.SlayerTask.ID + "/" + DBTableID.SlayerTask.COL_ID + "/" + KRAKEN_TASK_ID, null);
		assertNull(CharacterReader.slayerTaskName(tables, KRAKEN_TASK_ID, 0));
	}

	@Test
	public void areaIsNamedOnlyWhenItsRowAndFieldAreSound()
	{
		FakeTables tables = new FakeTables()
			.row(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, KRAKEN_COVE_AREA_ID, KRAKEN_COVE_AREA_ROW)
			.field(KRAKEN_COVE_AREA_ROW, DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, new Object[]{"Kraken Cove"});
		assertEquals("Kraken Cove", CharacterReader.slayerAreaName(tables, KRAKEN_COVE_AREA_ID));
		assertNull(CharacterReader.slayerAreaName(tables, 0));
		assertNull(CharacterReader.slayerAreaName(tables, KRAKEN_COVE_AREA_ID + 1));
		tables.field(KRAKEN_COVE_AREA_ROW, DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, new Object[]{7});
		assertNull(CharacterReader.slayerAreaName(tables, KRAKEN_COVE_AREA_ID));
	}

	@Test
	public void aLookupThatThrowsLeavesTheTaskUnnamedAndReportsTheFailure()
	{
		CharacterReader.DbTables broken = new CharacterReader.DbTables()
		{
			@Override
			public List<Integer> rowsByValue(int table, int column, int tupleIndex, Object value)
			{
				throw new IllegalStateException("table reshaped");
			}

			@Override
			public Object[] field(int row, int column, int tupleIndex)
			{
				throw new IllegalStateException("table reshaped");
			}
		};
		List<RuntimeException> failures = new ArrayList<>();
		assertNull(CharacterReader.guardSlayerLookup(
			() -> CharacterReader.slayerTaskName(broken, CharacterReader.BOSS_TASK_ID, ZULRAH_BOSS_ID), failures::add));
		assertNull(CharacterReader.guardSlayerLookup(
			() -> CharacterReader.slayerAreaName(broken, KRAKEN_COVE_AREA_ID), failures::add));
		assertEquals(2, failures.size());
		assertTrue(failures.get(0) instanceof IllegalStateException);
	}

	@Test
	public void aLookupThatSucceedsPassesItsValueThroughTheGuard()
	{
		List<RuntimeException> failures = new ArrayList<>();
		String name = "Cave krakens";
		assertSame(name, CharacterReader.guardSlayerLookup(() -> name, failures::add));
		assertNull(CharacterReader.guardSlayerLookup(() -> null, failures::add));
		assertTrue(failures.isEmpty());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import net.runelite.api.gameval.InventoryID;
import org.junit.Test;

public class StorageTrackerTest
{
	private static JsonArray items(int... idQuantityPairs)
	{
		JsonArray out = new JsonArray();
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			out.add(CharacterReader.itemJson(idQuantityPairs[i], idQuantityPairs[i + 1]));
		}
		return out;
	}

	@Test
	public void mapsContainersToStoreKeys()
	{
		assertEquals("looting_bag", StorageTracker.keyFor(InventoryID.LOOTING_BAG));
		assertEquals("group_storage", StorageTracker.keyFor(InventoryID.INV_GROUP_TEMP));
		assertNull(StorageTracker.keyFor(InventoryID.BANK));
	}

	@Test
	public void onlyAChangedStoreCounts()
	{
		StorageTracker tracker = new StorageTracker();
		assertTrue(tracker.put("seed_vault", items(5295, 10)));
		assertFalse(tracker.put("seed_vault", items(5295, 10)));
		assertTrue(tracker.put("seed_vault", items(5295, 11)));
	}

	@Test
	public void survivesARoundTripAndDropsUnknownStores()
	{
		StorageTracker tracker = new StorageTracker();
		tracker.put("looting_bag", items(995, 5_000));
		com.google.gson.JsonObject withJunk = tracker.toJson();
		withJunk.add("not_a_store", new JsonArray());
		String saved = new Gson().toJson(withJunk);

		StorageTracker restored = new StorageTracker();
		restored.load(saved);

		assertEquals(tracker.toJson(), restored.toJson());
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class SyncOutcomeTest
{
	@Test
	public void storedWaitsOutTheFloor()
	{
		SyncOutcome outcome = SyncOutcome.of(200, "{\"stored\":[\"bank\"]}", null);
		assertEquals(SyncOutcome.Kind.STORED, outcome.kind);
		assertEquals(SyncOutcome.FLOOR_SECONDS, outcome.waitSeconds);
	}

	@Test
	public void unsupportedSchemaMeansAnOlderServer()
	{
		assertEquals(SyncOutcome.Kind.OLD_SERVER,
			SyncOutcome.of(400, "{\"code\":\"unsupported_schema\",\"message\":\"…\"}", null).kind);
	}

	@Test
	public void unknownFieldAlsoMeansAnOlderServer()
	{
		// A schema 1 server checks fields before the schema number, so a schema 2 body gets unknown_field.
		assertEquals(SyncOutcome.Kind.OLD_SERVER,
			SyncOutcome.of(400, "{\"code\":\"unknown_field\"}", null).kind);
	}

	@Test
	public void refusedPartTimesAreTheirOwnOutcome()
	{
		// captured is not a body part, so the times alone are at fault: nothing is dropped, nothing waits.
		SyncOutcome outcome = SyncOutcome.of(400, "{\"code\":\"invalid_captured\",\"message\":\"…\"}", null);
		assertEquals(SyncOutcome.Kind.PART_TIMES_REFUSED, outcome.kind);
		assertEquals("invalid_captured", outcome.code);
		assertEquals(0, outcome.waitSeconds);
		assertNull(outcome.refused);
		// The envelope's own time is a different code, and still a refusal of the body.
		assertEquals(SyncOutcome.Kind.REJECTED, SyncOutcome.of(400, "{\"code\":\"invalid_captured_at\"}", null).kind);
		// Only a 400 carries a reason code the plugin reads.
		assertEquals(SyncOutcome.Kind.REJECTED, SyncOutcome.of(415, "{\"code\":\"invalid_captured\"}", null).kind);
	}

	@Test
	public void anyOtherContractBreakIsRejectedWithItsCode()
	{
		SyncOutcome outcome = SyncOutcome.of(400, "{\"code\":\"invalid_location\"}", null);
		assertEquals(SyncOutcome.Kind.REJECTED, outcome.kind);
		assertEquals("invalid_location", outcome.code);
	}

	@Test
	public void eachSectionCodeNamesItsPart()
	{
		// The site's own codes, written out rather than built from Part.key, so a renamed key fails here. A bad
		// item answers its container's code too: equipment, inventory, bank, collection log or storage.
		Map<Part, String> codes = new EnumMap<>(Part.class);
		codes.put(Part.LOCATION, "invalid_location");
		codes.put(Part.ACCOUNT, "invalid_account");
		codes.put(Part.EQUIPMENT, "invalid_equipment");
		codes.put(Part.INVENTORY, "invalid_inventory");
		codes.put(Part.SKILLS, "invalid_skills");
		codes.put(Part.DIARIES, "invalid_diaries");
		codes.put(Part.COMBAT_ACHIEVEMENTS, "invalid_combat_achievements");
		codes.put(Part.QUESTS, "invalid_quests");
		codes.put(Part.GRAND_EXCHANGE, "invalid_grand_exchange");
		codes.put(Part.KILL_COUNTS, "invalid_kill_counts");
		codes.put(Part.STORAGE, "invalid_storage");
		codes.put(Part.BANK, "invalid_bank");
		codes.put(Part.COLLECTION_LOG, "invalid_collection_log");
		codes.put(Part.VARS, "invalid_vars");
		assertEquals(EnumSet.allOf(Part.class), codes.keySet());

		for (Map.Entry<Part, String> entry : codes.entrySet())
		{
			SyncOutcome outcome = SyncOutcome.of(400, "{\"code\":\"" + entry.getValue() + "\",\"message\":\"…\"}", null);
			assertEquals(entry.getValue(), SyncOutcome.Kind.REJECTED, outcome.kind);
			assertEquals(entry.getValue(), entry.getKey(), outcome.refused);
		}
	}

	@Test
	public void anOlderSitesInvalidItemNamesNone()
	{
		// A site from before item faults took their container's code: invalid_item, from any item container,
		// and the code alone does not say which. It can still answer, so it is still read.
		SyncOutcome outcome = SyncOutcome.of(400, "{\"code\":\"invalid_item\",\"message\":\"…\"}", null);
		assertEquals(SyncOutcome.Kind.REJECTED, outcome.kind);
		assertNull(outcome.refused);
	}

	@Test
	public void aPartFieldNamesTheContainer()
	{
		// No site sends part now. One that does names the part outright, whatever the code.
		for (Part part : EnumSet.of(Part.EQUIPMENT, Part.INVENTORY, Part.BANK, Part.COLLECTION_LOG, Part.STORAGE))
		{
			SyncOutcome outcome = SyncOutcome.of(400,
				"{\"code\":\"invalid_item\",\"message\":\"…\",\"part\":\"" + part.key + "\"}", null);
			assertEquals(part.key, SyncOutcome.Kind.REJECTED, outcome.kind);
			assertEquals(part.key, part, outcome.refused);
		}
	}

	@Test
	public void aPartFieldWinsOverTheCodeUnlessItNamesNoKnownPart()
	{
		assertEquals(Part.STORAGE,
			SyncOutcome.of(400, "{\"code\":\"invalid_bank\",\"part\":\"storage\"}", null).refused);
		assertEquals(Part.VARS,
			SyncOutcome.of(400, "{\"code\":\"invalid_vars\",\"part\":\"a_later_part\"}", null).refused);
		assertNull(SyncOutcome.of(400, "{\"code\":\"invalid_item\",\"part\":\"a_later_part\"}", null).refused);
		assertNull(SyncOutcome.of(400, "{\"code\":\"invalid_item\",\"part\":[\"bank\"]}", null).refused);
	}

	@Test
	public void codesThatNameNoPartNameNone()
	{
		String[] codes = {"invalid_json", "not_an_object", "invalid_character", "invalid_captured_at", "no_containers",
			"invalid_something_new", "a_future_code"};
		for (String code : codes)
		{
			SyncOutcome outcome = SyncOutcome.of(400, "{\"code\":\"" + code + "\"}", null);
			assertEquals(code, SyncOutcome.Kind.REJECTED, outcome.kind);
			assertNull(code, outcome.refused);
		}
		assertNull(SyncOutcome.of(400, "<html>bad request</html>", null).refused);
		// Only a 400 names a part: a 415 is about the request, not one part of the body.
		assertNull(SyncOutcome.of(415, "{\"code\":\"invalid_bank\",\"part\":\"bank\"}", null).refused);
		// At schema 1 an older server's codes fall through to a refusal of everything sent.
		assertNull(SyncOutcome.of(400, "{\"code\":\"unknown_field\"}", null).refused);
	}

	@Test
	public void aNamedRefusalDropsOnlyThatPart()
	{
		Set<Part> sent = EnumSet.of(Part.LOCATION, Part.QUESTS, Part.BANK, Part.VARS);
		SyncOutcome outcome = SyncOutcome.of(400, "{\"code\":\"invalid_vars\"}", null);
		assertEquals(EnumSet.of(Part.VARS), outcome.dropped(sent));

		// A bad bank item answers the bank's own code, so only the bank waits.
		SyncOutcome item = SyncOutcome.of(400, "{\"code\":\"invalid_bank\"}", null);
		assertEquals(EnumSet.of(Part.BANK), item.dropped(sent));

		SyncOutcome named = SyncOutcome.of(400, "{\"code\":\"invalid_item\",\"part\":\"bank\"}", null);
		assertEquals(EnumSet.of(Part.BANK), named.dropped(sent));
	}

	@Test
	public void aRefusalThatNamesNoPartDropsEverythingSent()
	{
		Set<Part> sent = EnumSet.of(Part.LOCATION, Part.QUESTS, Part.BANK, Part.VARS);
		// An older site's invalid_item names no part.
		assertEquals(sent, SyncOutcome.of(400, "{\"code\":\"invalid_item\"}", null).dropped(sent));
		assertEquals(sent, SyncOutcome.of(400, "{\"code\":\"a_future_code\"}", null).dropped(sent));
		assertEquals(sent, SyncOutcome.of(415, "{\"code\":\"unsupported_media_type\"}", null).dropped(sent));
	}

	@Test
	public void aRefusalOfAPartThatWasNotSentDropsEverythingSent()
	{
		// Dropping nothing would send the same body again, and have it refused again.
		Set<Part> sent = EnumSet.of(Part.LOCATION, Part.QUESTS);
		assertEquals(sent, SyncOutcome.of(400, "{\"code\":\"invalid_bank\"}", null).dropped(sent));
	}

	@Test
	public void unauthorizedStopsUntilTheTokenChanges()
	{
		assertEquals(SyncOutcome.Kind.BAD_TOKEN, SyncOutcome.of(401, "{\"code\":\"unauthorized\"}", null).kind);
	}

	@Test
	public void tooLargeShrinksTheBudget()
	{
		assertEquals(SyncOutcome.Kind.TOO_LARGE, SyncOutcome.of(413, "{\"code\":\"too_large\"}", null).kind);
	}

	@Test
	public void aFullAccountWaitsFifteenMinutesInsteadOfRetryingEveryMinute()
	{
		SyncOutcome outcome = SyncOutcome.of(409, "{\"code\":\"too_many_characters\",\"message\":\"…\"}", null);
		assertEquals(SyncOutcome.Kind.ACCOUNT_FULL, outcome.kind);
		assertEquals(SyncOutcome.ACCOUNT_FULL_RETRY_SECONDS, outcome.waitSeconds);
		assertEquals("too_many_characters", outcome.code);
	}

	@Test
	public void anyOther409IsAnOrdinaryRetry()
	{
		assertEquals(SyncOutcome.Kind.RETRY, SyncOutcome.of(409, "{\"code\":\"something_else\"}", null).kind);
		assertEquals(SyncOutcome.Kind.RETRY, SyncOutcome.of(409, "<html>conflict</html>", null).kind);
	}

	@Test
	public void tooFrequentHonoursRetryAfter()
	{
		SyncOutcome outcome = SyncOutcome.of(429, "{\"code\":\"too_frequent\"}", "17");
		assertEquals(SyncOutcome.Kind.RETRY, outcome.kind);
		assertEquals(18, outcome.waitSeconds);
	}

	@Test
	public void aServerErrorPageWithoutRetryAfterWaitsTheDefault()
	{
		SyncOutcome outcome = SyncOutcome.of(502, "<html>bad gateway</html>", null);
		assertEquals(SyncOutcome.Kind.RETRY, outcome.kind);
		assertEquals(SyncOutcome.DEFAULT_RETRY_SECONDS, outcome.waitSeconds);
	}

	// --- the site config and player messages (docs/site-config.md) ----------

	private static final SiteConfig.Timing TUNED = SiteConfig.parse("{\"timing\":{\"sync_floor_seconds\":45,"
		+ "\"retry_seconds\":120,\"account_full_retry_seconds\":3600}}").timing;

	@Test
	public void theWaitsAreTheSiteConfigs()
	{
		assertEquals(45, SyncOutcome.of(200, "{}", null, TUNED).waitSeconds);
		assertEquals(120, SyncOutcome.of(503, "", null, TUNED).waitSeconds);
		assertEquals(120, SyncOutcome.networkFailure(TUNED).waitSeconds);
		assertEquals(3_600, SyncOutcome.of(409, "{\"code\":\"too_many_characters\"}", null, TUNED).waitSeconds);
		assertEquals("a 413 waits at least the floor", 45, SyncOutcome.of(413, "", null, TUNED).waitSeconds);
		assertEquals("Retry-After still wins", 18, SyncOutcome.of(429, "", "17", TUNED).waitSeconds);
	}

	@Test
	public void aPlayerMessageIsKeptMadeSafeAndTheDeveloperMessageNever()
	{
		SyncOutcome refused = SyncOutcome.of(400, "{\"code\":\"invalid_bank\",\"message\":\"bank[3].qty < 0\","
			+ "\"player_message\":\"  Your bank could not be read.\\nTry opening it again.  \"}", null);
		assertEquals("Your bank could not be read. Try opening it again.", refused.playerMessage);
		assertNull(SyncOutcome.of(400, "{\"code\":\"invalid_bank\",\"message\":\"bank[3].qty < 0\"}", null).playerMessage);
		assertNull(SyncOutcome.of(400, "{\"code\":\"invalid_bank\",\"player_message\":7}", null).playerMessage);
		assertNull(SyncOutcome.of(503, "<html>down</html>", null).playerMessage);
		assertEquals("Back at 19:00 UTC.",
			SyncOutcome.of(503, "{\"code\":\"maintenance\",\"player_message\":\"Back at 19:00 UTC.\"}", null).playerMessage);
	}

	@Test
	public void aStoredSyncMayNameTheConfigVersion()
	{
		assertEquals(8, SyncOutcome.of(200, "{\"stored\":[\"bank\"],\"config_version\":8}", null).configVersion);
		assertEquals(-1, SyncOutcome.of(200, "{\"stored\":[\"bank\"]}", null).configVersion);
		assertEquals(-1, SyncOutcome.of(200, "{\"config_version\":\"8\"}", null).configVersion);
		assertEquals(-1, SyncOutcome.of(200, "{\"config_version\":-2}", null).configVersion);
		assertEquals(-1, SyncOutcome.of(200, "{\"config_version\":1.5}", null).configVersion);
		assertEquals(-1, SyncOutcome.of(200, "", null).configVersion);
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.function.IntConsumer;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

/**
 * Unlink revoking the token on the site: what each answer means and what chat says, with a fake transport,
 * and the request itself, through an OkHttp client that never reaches the network.
 */
public class TokenRevokerTest
{
	private static final String TOKEN = OsrsIndexPlugin.TOKEN_PREFIX + "a".repeat(43);

	private final List<String> urls = new ArrayList<>();
	private final List<String> tokens = new ArrayList<>();
	private final List<IntConsumer> pending = new ArrayList<>();
	private final List<TokenRevoker.Result> results = new ArrayList<>();

	private final TokenRevoker revoker = new TokenRevoker((url, token, status) ->
	{
		urls.add(url);
		tokens.add(token);
		pending.add(status);
	});

	/** Revoke, answer with {@code status}, and return what came of it. */
	private TokenRevoker.Result revokeAnswering(int status)
	{
		revoker.revoke(TOKEN, results::add);
		pending.remove(0).accept(status);
		return results.get(results.size() - 1);
	}

	@Test
	public void sendsTheTokenToTheSitesRevokeRouteOnce()
	{
		revoker.revoke(TOKEN, results::add);
		assertEquals(List.of("https://osrsindex.com/api/v1/tracker/token"), urls);
		assertEquals(List.of(TOKEN), tokens);
		assertTrue("nothing is decided before the site answers", results.isEmpty());
	}

	@Test
	public void aRevokeTheSiteConfirmedSaysSo()
	{
		assertEquals(TokenRevoker.Result.CONFIRMED, revokeAnswering(204));
		assertEquals("osrsindex.com confirmed that this client's link is revoked.",
			TokenRevoker.chatLine(TokenRevoker.Result.CONFIRMED));
	}

	@Test
	public void aTokenTheSiteNoLongerKnowsIsAlsoConfirmed()
	{
		// 401: unknown, or already revoked on the account page. Either way it no longer works.
		assertEquals(TokenRevoker.Result.CONFIRMED, revokeAnswering(401));
	}

	@Test
	public void anyOtherAnswerIsNotConfirmedAndIsNeverRetried()
	{
		// 404 is a site without the route; 429 its per-address limit; 503 no tracker storage.
		for (int status : new int[]{404, 405, 429, 500, 503, 200, 400})
		{
			assertEquals("status " + status, TokenRevoker.Result.NOT_CONFIRMED, revokeAnswering(status));
		}
		assertEquals("one request per revoke, none sent again", 7, urls.size());
		assertTrue(pending.isEmpty());
	}

	@Test
	public void noResponseIsNotConfirmedEither()
	{
		assertEquals(TokenRevoker.Result.NO_RESPONSE, revokeAnswering(-1));
		assertEquals(1, urls.size());
	}

	@Test
	public void chatTellsThePlayerToRevokeOnTheSiteWhenItWasNotConfirmed()
	{
		String advice = "Revoke this client on your osrsindex.com account page to be sure.";
		assertEquals("osrsindex.com did not confirm that this client's link is revoked. " + advice,
			TokenRevoker.chatLine(TokenRevoker.Result.NOT_CONFIRMED));
		assertEquals("osrsindex.com could not be reached to revoke this client's link. " + advice,
			TokenRevoker.chatLine(TokenRevoker.Result.NO_RESPONSE));
	}

	@Test
	public void theRequestIsADeleteWithTheBearerTokenAndNoBody() throws Exception
	{
		BlockingQueue<Request> sent = new ArrayBlockingQueue<>(1);
		OkHttpClient http = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				sent.add(chain.request());
				return answer(chain.request(), 204);
			})
			.build();
		BlockingQueue<TokenRevoker.Result> answered = new ArrayBlockingQueue<>(1);

		new TokenRevoker(http).revoke(TOKEN, answered::add);

		assertEquals(TokenRevoker.Result.CONFIRMED, answered.poll(10, TimeUnit.SECONDS));
		Request request = sent.poll(10, TimeUnit.SECONDS);
		assertNotNull(request);
		assertEquals("DELETE", request.method());
		assertEquals("https://osrsindex.com/api/v1/tracker/token", request.url().toString());
		assertEquals("Bearer " + TOKEN, request.header("Authorization"));
		assertTrue("no body", request.body() == null || request.body().contentLength() == 0);
	}

	@Test
	public void aRequestThatNeverGetsAnAnswerIsNoResponse() throws Exception
	{
		OkHttpClient http = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				throw new IOException("offline");
			})
			.build();
		BlockingQueue<TokenRevoker.Result> answered = new ArrayBlockingQueue<>(1);

		new TokenRevoker(http).revoke(TOKEN, answered::add);

		assertEquals(TokenRevoker.Result.NO_RESPONSE, answered.poll(10, TimeUnit.SECONDS));
	}

	@Test
	public void aRefusalThroughOkHttpIsNotConfirmed() throws Exception
	{
		OkHttpClient http = new OkHttpClient.Builder()
			.addInterceptor(chain -> answer(chain.request(), 429))
			.build();
		BlockingQueue<TokenRevoker.Result> answered = new ArrayBlockingQueue<>(1);

		new TokenRevoker(http).revoke(TOKEN, answered::add);

		assertEquals(TokenRevoker.Result.NOT_CONFIRMED, answered.poll(10, TimeUnit.SECONDS));
	}

	private static Response answer(Request request, int code)
	{
		String body = code == 204 ? "" : "{\"code\":\"rate_limited\"}";
		return new Response.Builder()
			.request(request)
			.protocol(Protocol.HTTP_1_1)
			.code(code)
			.message("test")
			.body(ResponseBody.create(MediaType.parse("application/json"), body))
			.build();
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** The link token's form: nothing goes into a request header that OkHttp would refuse, and log, there. */
public class TokensTest
{
	private static final String TOKEN = "osrsidx_" + "Ab9-_".repeat(8) + "xyz";

	@Test
	public void theSitesFormIsWellFormed()
	{
		assertTrue(Tokens.wellFormed(TOKEN));
	}

	@Test
	public void aPasteKeepsNoSpaceOrInvisibleCharacter()
	{
		assertEquals(TOKEN, Tokens.normalize(" \t" + TOKEN + " ​﻿\n"));
		assertTrue(Tokens.wellFormed(Tokens.normalize(" " + TOKEN + " ")));
		assertEquals("", Tokens.normalize(null));
	}

	@Test
	public void anythingElseIsNeverSent()
	{
		assertFalse(Tokens.wellFormed(null));
		assertFalse(Tokens.wellFormed(""));
		assertFalse(Tokens.wellFormed("osrsidx_"));
		assertFalse(Tokens.wellFormed("osrsidx_short"));
		assertFalse(Tokens.wellFormed("Bearer " + TOKEN));
		assertFalse(Tokens.wellFormed(TOKEN + "é"));
		assertFalse(Tokens.wellFormed(TOKEN.replace('A', 'Ä')));
		assertFalse(Tokens.wellFormed("osrsidx_" + "a".repeat(257)));
	}
}

package com.osrsindex;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.LocalTime;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import org.junit.Test;

/**
 * What the plugin does after the site answers 413: a body of one part drops that part, a body of
 * several parts halves the budget, and either way the next send waits.
 */
public class TooLargeTest
{
	private static final Gson GSON = new Gson();

	private static JsonArray items(int count)
	{
		JsonArray out = new JsonArray();
		for (int i = 0; i < count; i++)
		{
			out.add(CharacterReader.itemJson(1_000 + i, 1_000_000 + i));
		}
		return out;
	}

	private static JsonObject vars(int count)
	{
		JsonObject out = new JsonObject();
		for (int i = 0; i < count; i++)
		{
			out.addProperty("VAR_" + i, 2_147_483_647);
		}
		return out;
	}

	private static PayloadPacker.Packed pack(Map<Part, JsonElement> pending, int budgetBytes)
	{
		return PayloadPacker.pack(GSON, 3, "Zezima", "2026-10-07T18:00:00Z", pending, budgetBytes);
	}

	@Test
	public void aTooLargeBodyWaitsOutTheFloorBeforeTheNextSend()
	{
		SyncOutcome outcome = SyncOutcome.of(413, "{\"code\":\"too_large\"}", null);
		assertEquals(SyncOutcome.Kind.TOO_LARGE, outcome.kind);
		assertEquals(SyncOutcome.FLOOR_SECONDS, outcome.waitSeconds);

		// A proxy's own 413 page carries no code, and still waits.
		SyncOutcome proxy = SyncOutcome.of(413, "<html>413 Request Entity Too Large</html>", null);
		assertEquals(SyncOutcome.Kind.TOO_LARGE, proxy.kind);
		assertEquals(SyncOutcome.FLOOR_SECONDS, proxy.waitSeconds);
	}

	@Test
	public void aLongerRetryAfterOnA413IsHonouredButNeverAShorterOne()
	{
		assertEquals(121, SyncOutcome.of(413, "{\"code\":\"too_large\"}", "120").waitSeconds);
		assertEquals(SyncOutcome.FLOOR_SECONDS, SyncOutcome.of(413, "{\"code\":\"too_large\"}", "5").waitSeconds);
		assertEquals(SyncOutcome.FLOOR_SECONDS, SyncOutcome.of(413, "{\"code\":\"too_large\"}", "0").waitSeconds);
	}

	@Test
	public void aLonePartOverTheBudgetIsTheOneDroppedAfterA413()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.VARS, vars(2_000));

		// Sent alone because waiting would never make it smaller...
		PayloadPacker.Packed packed = pack(pending, 1_000);
		assertEquals(EnumSet.of(Part.VARS), packed.parts);

		// ...so when the site refuses it, no smaller budget can help: that part is dropped.
		assertEquals(Part.VARS, PayloadPacker.tooLargeAlone(packed.parts));
	}

	@Test
	public void severalPartsRefusedAsTooLargeDropNothingAndHalveTheBudget()
	{
		Map<Part, JsonElement> pending = new EnumMap<>(Part.class);
		pending.put(Part.BANK, items(1_500));
		JsonObject log = new JsonObject();
		log.addProperty("obtained", 1_000);
		log.addProperty("total", 1_699);
		log.add("items", items(1_000));
		pending.put(Part.COLLECTION_LOG, log);

		PayloadPacker.Packed packed = pack(pending, PayloadPacker.DEFAULT_BUDGET_BYTES);
		assertEquals(EnumSet.of(Part.BANK, Part.COLLECTION_LOG), packed.parts);
		assertNull(PayloadPacker.tooLargeAlone(packed.parts));

		int budget = PayloadPacker.halved(PayloadPacker.DEFAULT_BUDGET_BYTES);
		assertEquals(60_000, budget);
		// At half the budget the two go separately, and the later one waits for the next sync.
		assertEquals(EnumSet.of(Part.BANK), pack(pending, budget).parts);
	}

	@Test
	public void theBudgetHalvesDownToItsFloorAndStaysThere()
	{
		assertEquals(30_000, PayloadPacker.halved(60_000));
		assertEquals(PayloadPacker.MIN_BUDGET_BYTES, PayloadPacker.halved(30_000));
		assertEquals(PayloadPacker.MIN_BUDGET_BYTES, PayloadPacker.halved(PayloadPacker.MIN_BUDGET_BYTES));
	}

	@Test
	public void thePanelLineNamesThePartThatWasTooLarge()
	{
		assertEquals("Not synced at 14:02: collection log was too large for the site. It is sent again when it changes.",
			OsrsIndexPlugin.tooLargeLine(LocalTime.of(14, 2), Part.COLLECTION_LOG));
		assertEquals("Not synced at 09:30: vars was too large for the site. It is sent again when it changes.",
			OsrsIndexPlugin.tooLargeLine(LocalTime.of(9, 30), Part.VARS));
	}
